#[derive(Clone, Debug, PartialEq, Eq)]
pub enum M4RuntimeFailureClass {
    InvalidRequest,
    CapabilityDenied,
    NotFound,
    Conflict,
    Unprocessable,
    Unavailable,
    Integrity,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum LocalRuntimeError {
    Io(String),
    Serde(String),
    Storage(String),
    WorkspaceConflict {
        root: PathBuf,
    },
    UnknownScenario {
        scenario_id: String,
    },
    RunNotFound {
        run_id: String,
    },
    ProgramNotFound {
        program_id: String,
    },
    InferenceProviderNotFound {
        provider_id: String,
    },
    InferenceTurnNotFound {
        turn_result_id: String,
    },
    TurnPackageNotFound {
        turn_package_id: String,
    },
    ParsedTurnResultNotFound {
        parsed_result_id: String,
    },
    ToolExecutionNotFound {
        tool_execution_id: String,
    },
    InvalidOperation {
        run_id: String,
        reason: String,
    },
    InvalidProgramOperation {
        program_id: String,
        reason: String,
    },
    InvalidInferenceOperation {
        identifier: String,
        reason: String,
    },
    InvalidTurnPackageOperation {
        identifier: String,
        reason: String,
    },
    InferenceExecutionFailed {
        identifier: String,
        reason: String,
    },
    M1Reference(String),
    M2Runtime(String),
    M3Runtime(String),
    M4Runtime {
        class: M4RuntimeFailureClass,
        reason: String,
    },
    HistoricalPhase04TruthUnavailable {
        decision: crate::execution::NorthStarClosureDecision,
    },
}

impl Display for LocalRuntimeError {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Io(reason) => write!(f, "local runtime I/O error: {reason}"),
            Self::Serde(reason) => write!(f, "local runtime serialization error: {reason}"),
            Self::Storage(reason) => write!(f, "local runtime storage error: {reason}"),
            Self::WorkspaceConflict { root } => write!(
                f,
                "local runtime workspace '{}' already has a live owner",
                root.display()
            ),
            Self::UnknownScenario { scenario_id } => {
                write!(f, "unknown local runtime scenario '{scenario_id}'")
            }
            Self::RunNotFound { run_id } => write!(f, "local runtime run '{run_id}' was not found"),
            Self::ProgramNotFound { program_id } => {
                write!(f, "local runtime program '{program_id}' was not found")
            }
            Self::InferenceProviderNotFound { provider_id } => {
                write!(
                    f,
                    "local runtime inference provider '{provider_id}' was not found"
                )
            }
            Self::InferenceTurnNotFound { turn_result_id } => {
                write!(
                    f,
                    "local runtime inference turn '{turn_result_id}' was not found"
                )
            }
            Self::TurnPackageNotFound { turn_package_id } => {
                write!(
                    f,
                    "local runtime turn package '{turn_package_id}' was not found"
                )
            }
            Self::ParsedTurnResultNotFound { parsed_result_id } => {
                write!(
                    f,
                    "local runtime parsed turn result '{parsed_result_id}' was not found"
                )
            }
            Self::ToolExecutionNotFound { tool_execution_id } => {
                write!(
                    f,
                    "local runtime tool execution '{tool_execution_id}' was not found"
                )
            }
            Self::InvalidOperation { run_id, reason } => {
                write!(f, "run '{run_id}' cannot perform that operation: {reason}")
            }
            Self::InvalidProgramOperation { program_id, reason } => {
                write!(
                    f,
                    "program '{program_id}' cannot perform that operation: {reason}"
                )
            }
            Self::InvalidInferenceOperation { identifier, reason } => {
                write!(
                    f,
                    "inference operation '{identifier}' cannot proceed: {reason}"
                )
            }
            Self::InvalidTurnPackageOperation { identifier, reason } => {
                write!(
                    f,
                    "turn package operation '{identifier}' cannot proceed: {reason}"
                )
            }
            Self::InferenceExecutionFailed { identifier, reason } => {
                write!(f, "inference execution '{identifier}' failed: {reason}")
            }
            Self::M1Reference(reason) => write!(f, "M1 reference lifecycle error: {reason}"),
            Self::M2Runtime(reason) => write!(f, "M2 durable runtime error: {reason}"),
            Self::M3Runtime(reason) => write!(f, "M3 capability runtime error: {reason}"),
            Self::M4Runtime { reason, .. } => {
                write!(f, "M4 worker runtime error: {reason}")
            }
            Self::HistoricalPhase04TruthUnavailable { decision } => write!(
                f,
                "local runtime storage error: active historical Phase 04 truth requires lineage decision Closed, found {decision:?}"
            ),
        }
    }
}

impl Error for LocalRuntimeError {}

impl From<std::io::Error> for LocalRuntimeError {
    fn from(value: std::io::Error) -> Self {
        Self::Io(value.to_string())
    }
}

impl From<serde_json::Error> for LocalRuntimeError {
    fn from(value: serde_json::Error) -> Self {
        Self::Serde(value.to_string())
    }
}

impl From<crate::execution::StorageError> for LocalRuntimeError {
    fn from(value: crate::execution::StorageError) -> Self {
        Self::Storage(value.to_string())
    }
}

impl From<ReferenceLifecycleError> for LocalRuntimeError {
    fn from(value: ReferenceLifecycleError) -> Self {
        Self::M1Reference(value.to_string())
    }
}

impl From<M2RuntimeError> for LocalRuntimeError {
    fn from(value: M2RuntimeError) -> Self {
        Self::M2Runtime(value.to_string())
    }
}

impl From<M3RuntimeError> for LocalRuntimeError {
    fn from(value: M3RuntimeError) -> Self {
        Self::M3Runtime(value.to_string())
    }
}

impl From<M4RuntimeError> for LocalRuntimeError {
    fn from(value: M4RuntimeError) -> Self {
        let class = classify_m4_runtime_error(&value);
        Self::M4Runtime {
            class,
            reason: value.to_string(),
        }
    }
}

fn classify_m4_runtime_error(error: &M4RuntimeError) -> M4RuntimeFailureClass {
    match error {
        M4RuntimeError::InvalidConfig(_)
        | M4RuntimeError::Serialization(_)
        | M4RuntimeError::UnsafePath(_) => M4RuntimeFailureClass::InvalidRequest,
        M4RuntimeError::NotFound(_) => M4RuntimeFailureClass::NotFound,
        M4RuntimeError::Conflict(_) => M4RuntimeFailureClass::Conflict,
        M4RuntimeError::Integrity(_) | M4RuntimeError::Artifact(_) => {
            M4RuntimeFailureClass::Integrity
        }
        M4RuntimeError::CapabilityFailure(_) => M4RuntimeFailureClass::Unprocessable,
        M4RuntimeError::Worker(error) => classify_worker_runtime_error(error),
        M4RuntimeError::M3(error) => classify_m3_runtime_error(error),
        M4RuntimeError::Io { .. } | M4RuntimeError::LockPoisoned => {
            M4RuntimeFailureClass::Unavailable
        }
    }
}

fn classify_worker_runtime_error(
    error: &crate::worker_runtime::WorkerRuntimeError,
) -> M4RuntimeFailureClass {
    use crate::worker_runtime::WorkerRuntimeError;

    match error {
        WorkerRuntimeError::InvalidRegistration(_)
        | WorkerRuntimeError::InvalidRequest(_)
        | WorkerRuntimeError::Serialization(_) => M4RuntimeFailureClass::InvalidRequest,
        WorkerRuntimeError::NotFound(_) => M4RuntimeFailureClass::NotFound,
        WorkerRuntimeError::Conflict(_) => M4RuntimeFailureClass::Conflict,
        WorkerRuntimeError::CapabilityDenied(_) => M4RuntimeFailureClass::CapabilityDenied,
        WorkerRuntimeError::BudgetExceeded(_)
        | WorkerRuntimeError::DeadlineExceeded(_)
        | WorkerRuntimeError::NoEligibleWorker(_)
        | WorkerRuntimeError::ExecutionFailed(_) => M4RuntimeFailureClass::Unprocessable,
        WorkerRuntimeError::Integrity(_) => M4RuntimeFailureClass::Integrity,
        WorkerRuntimeError::Io { .. } | WorkerRuntimeError::LockPoisoned => {
            M4RuntimeFailureClass::Unavailable
        }
    }
}

fn classify_m3_runtime_error(error: &M3RuntimeError) -> M4RuntimeFailureClass {
    use crate::capability_services::{CapabilityHostError, ServiceFailureKind};

    match error {
        M3RuntimeError::InvalidConfig(_)
        | M3RuntimeError::InvalidSchedule(_)
        | M3RuntimeError::InvalidOperationsInspection(_)
        | M3RuntimeError::InvalidEvidenceBundle(_)
        | M3RuntimeError::Serialization(_)
        | M3RuntimeError::UnsafePath { .. } => M4RuntimeFailureClass::InvalidRequest,
        M3RuntimeError::TerminalCapability(failure) => match failure.kind {
            ServiceFailureKind::ScopeDenied | ServiceFailureKind::ApprovalBlocked => {
                M4RuntimeFailureClass::CapabilityDenied
            }
            ServiceFailureKind::Unavailable => M4RuntimeFailureClass::Unavailable,
            ServiceFailureKind::Failed
            | ServiceFailureKind::TimedOut
            | ServiceFailureKind::Cancelled
            | ServiceFailureKind::Unsupported
            | ServiceFailureKind::ResourceExhausted => M4RuntimeFailureClass::Unprocessable,
        },
        M3RuntimeError::Capability(error) => match error {
            CapabilityHostError::Serialization(_)
            | CapabilityHostError::InvalidConfiguration(_)
            | CapabilityHostError::InvalidRequest(_)
            | CapabilityHostError::InvalidField { .. }
            | CapabilityHostError::UnsafePath { .. }
            | CapabilityHostError::RequestTooLarge { .. } => M4RuntimeFailureClass::InvalidRequest,
            CapabilityHostError::UnknownService { .. }
            | CapabilityHostError::ReceiptNotFound { .. } => M4RuntimeFailureClass::NotFound,
            CapabilityHostError::ConfigurationMismatch { .. }
            | CapabilityHostError::IdempotencyConflict { .. }
            | CapabilityHostError::InvocationIdConflict { .. }
            | CapabilityHostError::InvocationInFlight { .. } => M4RuntimeFailureClass::Conflict,
            CapabilityHostError::JournalFull { .. } => M4RuntimeFailureClass::Unprocessable,
            CapabilityHostError::Io { .. } | CapabilityHostError::StateLockPoisoned => {
                M4RuntimeFailureClass::Unavailable
            }
            CapabilityHostError::CorruptState(_) => M4RuntimeFailureClass::Integrity,
        },
        M3RuntimeError::ScheduleNotFound { .. } => M4RuntimeFailureClass::NotFound,
        M3RuntimeError::Conflict(_)
        | M3RuntimeError::ImmutableConflict { .. }
        | M3RuntimeError::ScheduleConflict { .. } => M4RuntimeFailureClass::Conflict,
        M3RuntimeError::ResourceBoundExceeded { .. } => M4RuntimeFailureClass::Unprocessable,
        M3RuntimeError::Io { .. } => M4RuntimeFailureClass::Unavailable,
        M3RuntimeError::CorruptState(_) => M4RuntimeFailureClass::Integrity,
        M3RuntimeError::M2(_) | M3RuntimeError::Candidate(_) | M3RuntimeError::Deployment(_) => {
            M4RuntimeFailureClass::Unavailable
        }
        M3RuntimeError::Artifact(_) => M4RuntimeFailureClass::Integrity,
    }
}

