    pub async fn recursive_factory_health_view(
        &self,
    ) -> Result<RecursiveFactoryHealthView, LocalRuntimeError> {
        let store = self.llm_interface_store()?;
        let cycles = store.list_model_driven_factory_cycle_records()?;
        let produced_workers = store
            .list_worker_specialization_cards()?
            .into_iter()
            .filter(|card| card.production_program_instance_ref.is_some())
            .collect::<Vec<_>>();
        let mut adopted_count = 0usize;
        let mut refused_count = 0usize;
        let mut rolled_back_count = 0usize;
        let mut paused_count = 0usize;
        let mut approval_incident_count = 0usize;
        let mut quarantine_incident_count = 0usize;
        let mut denial_incident_count = 0usize;
        let mut failure_incident_count = 0usize;
        let mut max_generation_depth = 0usize;
        for cycle in &cycles {
            match cycle.outcome {
                crate::execution::RecursiveCycleOutcome::Adopted => adopted_count += 1,
                crate::execution::RecursiveCycleOutcome::Refused => refused_count += 1,
                crate::execution::RecursiveCycleOutcome::RolledBack => rolled_back_count += 1,
                crate::execution::RecursiveCycleOutcome::Paused => paused_count += 1,
                crate::execution::RecursiveCycleOutcome::ApprovalBlocked => {
                    approval_incident_count += 1
                }
                crate::execution::RecursiveCycleOutcome::Quarantined => {
                    quarantine_incident_count += 1
                }
                crate::execution::RecursiveCycleOutcome::Denied => denial_incident_count += 1,
                crate::execution::RecursiveCycleOutcome::Failed => failure_incident_count += 1,
                crate::execution::RecursiveCycleOutcome::WorkerDispatched
                | crate::execution::RecursiveCycleOutcome::CycleRecorded => {}
            }
            if let Some(tick_id) = &cycle.tick_receipt_ref {
                if let Some(receipt) = self
                    .factory_program_tick_receipts
                    .read()
                    .unwrap()
                    .iter()
                    .find(|receipt| &receipt.tick_id == tick_id)
                {
                    max_generation_depth = max_generation_depth.max(receipt.generation_depth);
                }
            }
        }
        let completed_cycle_decision_count = cycles
            .iter()
            .filter(|cycle| cycle.tick_receipt_ref.is_some())
            .count();
        let summary = if cycles.is_empty() {
            "No recursive factory cycles are recorded in the Wasm-Biotic runtime ledger."
                .to_string()
        } else {
            format!(
                "{} model-driven recursive cycle(s) now track {} completed cycle decision(s) and {} produced worker agent(s).",
                cycles.len(),
                completed_cycle_decision_count,
                produced_workers.len()
            )
        };
        Ok(RecursiveFactoryHealthView {
            summary,
            model_driven_cycle_count: cycles.len(),
            completed_cycle_decision_count,
            produced_worker_agent_count: produced_workers.len(),
            adopted_count,
            refused_count,
            rolled_back_count,
            paused_count,
            approval_incident_count,
            quarantine_incident_count,
            denial_incident_count,
            failure_incident_count,
            max_generation_depth,
        })
    }

    pub async fn drive_llm_factory_program(
        &self,
        instance_id: &str,
        request: DriveLlmFactoryProgramRequest,
    ) -> Result<FactoryProgramView, LocalRuntimeError> {
        request
            .validate()
            .map_err(|error| invalid_turn_package_operation(instance_id, error))?;
        let max_cycles = request.normalized_max_cycles();
        let store = self.llm_interface_store()?;
        for _ in 0..max_cycles {
            let instance = self
                .factory_program_instances
                .read()
                .unwrap()
                .iter()
                .find(|item| item.instance_id == instance_id)
                .cloned()
                .ok_or_else(|| LocalRuntimeError::ProgramNotFound {
                    program_id: instance_id.to_string(),
                })?;
            let spec = self
                .factory_program_specs
                .read()
                .unwrap()
                .iter()
                .find(|item| item.spec_id == instance.spec_id)
                .cloned()
                .ok_or_else(|| LocalRuntimeError::InvalidProgramOperation {
                    program_id: instance_id.to_string(),
                    reason: format!("missing program spec '{}'", instance.spec_id),
                })?;
            if instance.campaign_count >= spec.recursion_budget.max_campaigns
                || instance.generation_depth >= spec.recursion_budget.max_depth
                || matches!(
                    instance.program_state,
                    crate::execution::FactoryProgramState::Paused
                        | crate::execution::FactoryProgramState::Stopped
                        | crate::execution::FactoryProgramState::Completed
                )
            {
                break;
            }
            let profile_ref = spec.llm_driver_profile_ref.as_ref().ok_or_else(|| {
                LocalRuntimeError::InvalidProgramOperation {
                    program_id: instance_id.to_string(),
                    reason: "llm-driven execution requires `llm_driver_profile_ref`".to_string(),
                }
            })?;
            let profile = store.load_llm_factory_program_profile(profile_ref)?;
            if profile.response_schema_family
                != crate::execution::TurnResponseSchemaFamily::SupervisorTurnV1
            {
                return Err(LocalRuntimeError::InvalidProgramOperation {
                    program_id: instance_id.to_string(),
                    reason:
                        "llm factory driver profiles must use `SupervisorTurnV1` in Workstream F"
                            .to_string(),
                });
            }
            let campaign_number =
                self.next_llm_factory_campaign_number(&store, &instance.instance_id)?;
            let turn_request = self.build_llm_factory_turn_package_request(
                &instance,
                &spec,
                &profile,
                campaign_number,
            )?;
            let created = match profile.tool_catalog_ref.as_deref() {
                None => self.create_turn_package(turn_request).await?,
                Some(M1_REFERENCE_TOOL_CATALOG_ID) => {
                    self.create_m1_turn_package(turn_request).await?
                }
                Some(tool_catalog_ref)
                    if tool_catalog_ref
                        == self
                            .tool_catalog_bundle
                            .read()
                            .unwrap()
                            .catalog
                            .tool_catalog_id =>
                {
                    self.create_turn_package(turn_request).await?
                }
                Some(tool_catalog_ref) => {
                    return Err(LocalRuntimeError::InvalidProgramOperation {
                        program_id: instance_id.to_string(),
                        reason: format!(
                            "llm driver profile references unknown tool catalog '{tool_catalog_ref}'"
                        ),
                    });
                }
            };
            let parsed = self
                .execute_turn_package(ExecuteTurnPackageRequest {
                    turn_package_id: created.turn_package.turn_package_id.clone(),
                    provider_ref: request.provider_ref.clone(),
                    model_ref: request.model_ref.clone(),
                    generation_policy: request.generation_policy.clone(),
                })
                .await?;
            let authority_decision = parsed
                .governance
                .as_ref()
                .map(|governance| governance.authority_decision.decision)
                .unwrap_or(crate::execution::ModelAuthorityDecisionKind::Allow);
            if authority_decision != crate::execution::ModelAuthorityDecisionKind::Allow {
                break;
            }
            self.execute_parsed_turn_tools(&parsed.parsed_result.parsed_turn_result_id)
                .await?;
            let cycle_id = model_factory_cycle_id(&parsed.parsed_result.parsed_turn_result_id);
            let cycle = store.load_model_driven_factory_cycle_record(&cycle_id)?;
            let Some(tick_id) = &cycle.tick_receipt_ref else {
                break;
            };
            let tick_receipt = self
                .factory_program_tick_receipts
                .read()
                .unwrap()
                .iter()
                .find(|receipt| &receipt.tick_id == tick_id)
                .cloned()
                .ok_or_else(|| LocalRuntimeError::InvalidProgramOperation {
                    program_id: instance_id.to_string(),
                    reason: format!("missing tick receipt '{}'", tick_id),
                })?;
            if tick_receipt.stop_condition.decision
                != crate::execution::StopConditionDecision::Continue
            {
                break;
            }
            if tick_receipt.campaign_count >= spec.recursion_budget.max_campaigns
                || tick_receipt.generation_depth >= spec.recursion_budget.max_depth
            {
                break;
            }
        }
        self.factory_program_view(instance_id).await
    }

    async fn build_recursive_factory_program_view(
        &self,
        spec: &crate::execution::FactoryProgramSpec,
        instance: &crate::execution::FactoryProgramInstance,
        receipts: &[crate::execution::FactoryProgramTickReceipt],
    ) -> Result<FactoryProgramView, LocalRuntimeError> {
        let store = self.llm_interface_store()?;
        let mut view = build_factory_program_view(spec, instance, receipts)?;
        view.llm_driver_profile = spec
            .llm_driver_profile_ref
            .as_ref()
            .and_then(|profile_ref| store.load_llm_factory_program_profile(profile_ref).ok())
            .map(|profile| build_llm_factory_program_profile_view(&profile));

        let mut cycles = store
            .list_model_driven_factory_cycle_records()?
            .into_iter()
            .filter(|cycle| cycle.program_instance_ref == instance.instance_id)
            .collect::<Vec<_>>();
        cycles.sort_by(|left, right| {
            left.campaign_number
                .cmp(&right.campaign_number)
                .then_with(|| {
                    run_timestamp(&left.created_at).cmp(&run_timestamp(&right.created_at))
                })
                .then_with(|| {
                    left.model_factory_cycle_id
                        .cmp(&right.model_factory_cycle_id)
                })
        });
        view.model_factory_cycles = cycles
            .iter()
            .map(build_model_driven_factory_cycle_view)
            .collect();

        let mut produced_workers = store
            .list_worker_specialization_cards()?
            .into_iter()
            .filter(|card| {
                card.production_program_instance_ref.as_deref()
                    == Some(instance.instance_id.as_str())
            })
            .collect::<Vec<_>>();
        produced_workers.sort_by(|left, right| left.worker_card_id.cmp(&right.worker_card_id));
        view.produced_worker_agents = produced_workers
            .iter()
            .map(build_produced_worker_agent_view)
            .collect();

        let lineage_id = recursive_lineage_execution_id(&instance.instance_id);
        view.recursive_lineage_execution = store
            .load_recursive_lineage_execution_record(&lineage_id)
            .ok()
            .map(|lineage| build_recursive_lineage_execution_view(&lineage));

        let statement_id = architectural_dependency_statement_id(&instance.instance_id);
        view.architectural_dependency_statement = store
            .load_architectural_dependency_statement(&statement_id)
            .ok()
            .map(|statement| build_architectural_dependency_statement_view(&statement));

        let dossier_id = recursion_closure_dossier_id(&instance.instance_id);
        view.recursion_closure_dossier = store
            .load_interface_native_recursion_closure_dossier(&dossier_id)
            .ok()
            .map(|dossier| build_recursion_closure_dossier_view(&dossier));
        Ok(view)
    }

    fn next_llm_factory_campaign_number(
        &self,
        store: &DurableArtifactStore,
        instance_id: &str,
    ) -> Result<usize, LocalRuntimeError> {
        let next = store
            .list_model_driven_factory_cycle_records()?
            .into_iter()
            .filter(|cycle| cycle.program_instance_ref == instance_id)
            .map(|cycle| cycle.campaign_number)
            .max()
            .unwrap_or(0)
            + 1;
        Ok(next)
    }

    fn build_llm_factory_turn_package_request(
        &self,
        instance: &crate::execution::FactoryProgramInstance,
        spec: &crate::execution::FactoryProgramSpec,
        profile: &crate::execution::LlmFactoryProgramProfile,
        campaign_number: usize,
    ) -> Result<CreateTurnPackageRequest, LocalRuntimeError> {
        let program_key = stable_short_token(&instance.instance_id);
        let default_campaign_ref = format!("campaign:{program_key}:{campaign_number}");
        let default_epoch_ref = format!("epoch:{program_key}:{campaign_number}");
        let task_ref = format!("factory-program-task:{program_key}:{campaign_number}");
        let turn_package_id = format!(
            "llm-factory-turn-package:{}:{}",
            program_key, campaign_number
        );
        let session_ref = format!("llm-factory-session:{}:{}", program_key, campaign_number);
        let turn_ref = format!("llm-factory-turn:{}:{}", program_key, campaign_number);
        let replacements = factory_template_replacements(
            spec,
            instance,
            &program_key,
            campaign_number,
            &default_campaign_ref,
            &default_epoch_ref,
            &task_ref,
        );
        let continuity_entries = self.build_llm_factory_continuity_entries(instance, spec);
        let capability_envelope =
            render_factory_profile_capability_envelope(&profile.capability_envelope, &replacements);
        Ok(CreateTurnPackageRequest {
            turn_package_id: turn_package_id.clone(),
            program_ref: instance.recurring_program_ref.clone(),
            session_ref,
            turn_ref,
            envelope_ref: capability_envelope.envelope_id.clone(),
            role: crate::execution::TurnPackageRole::Supervisor,
            system_frame_ref: format!("system-frame:{}", sanitize_id(&turn_package_id)),
            system_frame_text: render_factory_profile_template(
                &profile.system_frame_text,
                &replacements,
            ),
            program_frame_ref: format!("program-frame:{}", sanitize_id(&turn_package_id)),
            program_frame_text: render_factory_profile_template(
                &profile.program_frame_template,
                &replacements,
            ),
            capability_frame_ref: format!("capability-frame:{}", sanitize_id(&turn_package_id)),
            capability_frame_text: render_factory_profile_template(
                &profile.capability_frame_text,
                &replacements,
            ),
            agenda_ref: format!("agenda:{}", sanitize_id(&turn_package_id)),
            agenda_text: render_factory_profile_template(&profile.agenda_template, &replacements),
            continuity_entries,
            tool_execution_context: CreateTurnPackageToolExecutionContext {
                tool_execution_context_id: format!(
                    "tool-context:{}",
                    sanitize_id(&turn_package_id)
                ),
                capability_envelope,
                campaign_ref: Some(
                    profile
                        .default_campaign_ref
                        .as_deref()
                        .map(|value| render_factory_profile_template(value, &replacements))
                        .unwrap_or(default_campaign_ref),
                ),
                epoch_ref: Some(
                    profile
                        .default_epoch_ref
                        .as_deref()
                        .map(|value| render_factory_profile_template(value, &replacements))
                        .unwrap_or(default_epoch_ref),
                ),
                task_ref: Some(task_ref),
                pointer_index_ref: profile
                    .default_pointer_index_ref
                    .as_deref()
                    .map(|value| render_factory_profile_template(value, &replacements)),
                factory_program_instance_ref: Some(instance.instance_id.clone()),
                workspace_scope_ref: profile
                    .default_workspace_scope_ref
                    .as_deref()
                    .map(|value| render_factory_profile_template(value, &replacements)),
                ecology_snapshot_ref: profile
                    .default_ecology_snapshot_ref
                    .as_deref()
                    .map(|value| render_factory_profile_template(value, &replacements)),
            },
            response_schema_family: crate::execution::TurnResponseSchemaFamily::SupervisorTurnV1,
            context_budget: CreateTurnPackageContextBudget {
                context_budget_id: format!("context-budget:{}", sanitize_id(&turn_package_id)),
                max_rendered_prompt_chars: profile.max_rendered_prompt_chars,
                max_continuity_entries: profile.max_continuity_entries,
            },
        })
    }

    fn build_llm_factory_continuity_entries(
        &self,
        instance: &crate::execution::FactoryProgramInstance,
        spec: &crate::execution::FactoryProgramSpec,
    ) -> Vec<crate::execution::TurnContinuityEntry> {
        let mut entries = vec![
            crate::execution::TurnContinuityEntry {
                entry_ref: format!(
                    "continuity:{}:root-factory",
                    sanitize_id(&instance.instance_id)
                ),
                text: format!(
                    "Root factory `{}` remains the stable lineage anchor.",
                    spec.root_factory_ref
                ),
                priority: crate::execution::ContinuityEntryPriority::Critical,
            },
            crate::execution::TurnContinuityEntry {
                entry_ref: format!(
                    "continuity:{}:current-factory",
                    sanitize_id(&instance.instance_id)
                ),
                text: format!(
                    "Current incumbent factory is `{}` at generation depth {} after {} recorded campaign(s).",
                    instance.current_factory_ref,
                    instance.generation_depth,
                    instance.campaign_count
                ),
                priority: crate::execution::ContinuityEntryPriority::Critical,
            },
        ];
        if let Some(latest_tick_id) = &instance.latest_tick_id {
            entries.push(crate::execution::TurnContinuityEntry {
                entry_ref: format!(
                    "continuity:{}:latest-tick",
                    sanitize_id(&instance.instance_id)
                ),
                text: format!(
                    "Latest governed cycle receipt is `{}` and must bound the next recursive step.",
                    latest_tick_id
                ),
                priority: crate::execution::ContinuityEntryPriority::Supporting,
            });
        }
        entries
    }

    async fn reconcile_recursive_factory_artifacts_for_turn(
        &self,
        store: &DurableArtifactStore,
        parsed_result_id: &str,
    ) -> Result<(), LocalRuntimeError> {
        let parsed_result = store.load_parsed_turn_result(parsed_result_id)?;
        let turn_package = store.load_turn_package(&parsed_result.turn_package_ref)?;
        let context =
            store.load_tool_execution_context_record(&turn_package.tool_execution_context_ref)?;
        let Some(program_instance_ref) = context.factory_program_instance_ref.as_deref() else {
            return Ok(());
        };

        let authority_decision = self.authority_decision_for_turn_result(parsed_result_id)?;
        let campaign_number =
            self.current_model_cycle_campaign_number(store, program_instance_ref, &parsed_result)?;
        let cycle_id = model_factory_cycle_id(parsed_result_id);
        let lineage_id = recursive_lineage_execution_id(program_instance_ref);

        let turn_grounding = store
            .list_turn_grounding_packets()?
            .into_iter()
            .find(|packet| packet.turn_package_ref == turn_package.turn_package_id);
        let continuity_bundle_ref = turn_grounding
            .as_ref()
            .map(|packet| packet.continuity_bundle_ref.clone());
        let turn_grounding_ref = turn_grounding
            .as_ref()
            .map(|packet| packet.turn_grounding_packet_id.clone());

        let approvals = store
            .list_model_approval_request_records()?
            .into_iter()
            .filter(|approval| approval.turn_result_ref == parsed_result.parsed_turn_result_id)
            .collect::<Vec<_>>();
        let quarantines = store
            .list_model_output_quarantine_records()?
            .into_iter()
            .filter(|quarantine| {
                quarantine.affected_turn_result_ref == parsed_result.parsed_turn_result_id
            })
            .collect::<Vec<_>>();
        let checkpoints = store
            .list_turn_checkpoint_records()?
            .into_iter()
            .filter(|checkpoint| checkpoint.turn_result_ref == parsed_result.parsed_turn_result_id)
            .collect::<Vec<_>>();
        let pending_actions = store
            .list_pending_governed_turn_action_records()?
            .into_iter()
            .filter(|action| action.turn_result_ref == parsed_result.parsed_turn_result_id)
            .collect::<Vec<_>>();
        let tool_executions = parsed_result
            .tool_execution_refs
            .iter()
            .map(|record_ref| store.load_tool_execution_record(record_ref))
            .collect::<Result<Vec<_>, _>>()?;

        let mut worker_card_refs = Vec::new();
        let mut worker_dispatch_refs = Vec::new();
        let mut worker_result_refs = Vec::new();
        let mut proving_refs = Vec::new();
        let mut observation_refs = Vec::new();
        let mut comparison_refs = Vec::new();
        let mut tick_receipt_ref = None;
        let mut candidate_factory_ref = None;
        let mut resulting_factory_ref = None;

        for execution in &tool_executions {
            let payload = parse_optional_json_object(execution.result_payload_json.as_deref())?;
            let intent = store
                .load_parsed_tool_call_intent_record(&execution.parsed_tool_call_intent_ref)?;
            let arguments = parse_json_object(&intent.arguments_json)?;
            match execution.tool_id.as_str() {
                "ecology.dispatch_worker" => {
                    let dispatch_id = json_string_field(payload.as_ref(), "dispatch_id")
                        .unwrap_or_else(|| execution.tool_execution_id.clone());
                    let worker_id = json_string_field(payload.as_ref(), "worker_id")
                        .or_else(|| json_string_field(Some(&arguments), "worker_id"))
                        .unwrap_or_else(|| format!("worker:{}", sanitize_id(&dispatch_id)));
                    let task_kind = json_string_field(Some(&arguments), "task_kind");
                    let requested_capabilities =
                        capability_requests_from_json(&arguments, "requested_capabilities")?;
                    let card = self.materialize_produced_worker_agent_card(
                        store,
                        program_instance_ref,
                        campaign_number,
                        &cycle_id,
                        &lineage_id,
                        &turn_package,
                        &parsed_result,
                        &worker_id,
                        task_kind.as_deref(),
                        &requested_capabilities,
                    )?;
                    worker_card_refs.push(card.worker_card_id.clone());
                    worker_dispatch_refs.push(dispatch_id);
                }
                "ecology.collect_results" => {
                    if let Some(dispatch_id) = json_string_field(payload.as_ref(), "dispatch_id") {
                        worker_dispatch_refs.push(dispatch_id);
                    }
                    if let Some(result_ref) = json_string_field(payload.as_ref(), "result_ref") {
                        worker_result_refs.push(result_ref);
                    }
                }
                "validation.run_proving" => {
                    if let Some(proving_ref) = json_string_field(payload.as_ref(), "proving_run_id")
                    {
                        proving_refs.push(proving_ref);
                    }
                    if candidate_factory_ref.is_none() {
                        candidate_factory_ref =
                            json_string_field(payload.as_ref(), "candidate_factory_ref");
                    }
                }
                "validation.record_observation" => {
                    if let Some(observation_ref) =
                        json_string_field(payload.as_ref(), "observation_id")
                    {
                        observation_refs.push(observation_ref);
                    }
                }
                "validation.compare_candidate" => {
                    if let Some(comparison_ref) =
                        json_string_field(payload.as_ref(), "comparison_id")
                    {
                        comparison_refs.push(comparison_ref);
                    }
                    if candidate_factory_ref.is_none() {
                        candidate_factory_ref =
                            json_string_field(payload.as_ref(), "candidate_factory_ref").or_else(
                                || json_string_field(Some(&arguments), "candidate_factory_ref"),
                            );
                    }
                }
                "program.submit_cycle_decision" => {
                    tick_receipt_ref = json_string_field(payload.as_ref(), "tick_id");
                    candidate_factory_ref =
                        json_string_field(Some(&arguments), "candidate_factory_ref")
                            .or(candidate_factory_ref);
                    resulting_factory_ref =
                        json_string_field(payload.as_ref(), "resulting_factory_ref")
                            .or(resulting_factory_ref);
                    proving_refs.extend(json_string_array_field(Some(&arguments), "proving_refs"));
                    observation_refs.extend(json_string_array_field(
                        Some(&arguments),
                        "observation_refs",
                    ));
                    comparison_refs
                        .extend(json_string_array_field(Some(&arguments), "comparison_refs"));
                }
                _ => {}
            }
        }

        let tick_receipt = tick_receipt_ref.as_ref().and_then(|tick_id| {
            self.factory_program_tick_receipts
                .read()
                .unwrap()
                .iter()
                .find(|receipt| &receipt.tick_id == tick_id)
                .cloned()
        });
        if let Some(receipt) = &tick_receipt {
            candidate_factory_ref = Some(receipt.candidate_factory_ref.clone());
            resulting_factory_ref = Some(receipt.resulting_factory_ref.clone());
            proving_refs.extend(receipt.generation_agenda.proving_refs.clone());
            observation_refs.extend(receipt.generation_agenda.observation_refs.clone());
            comparison_refs.extend(receipt.lineage_health.comparison_refs.clone());
        }

        let outcome = determine_recursive_cycle_outcome(
            authority_decision.decision,
            &pending_actions,
            !tool_executions.is_empty(),
            !worker_dispatch_refs.is_empty() || !worker_result_refs.is_empty(),
            tick_receipt.as_ref(),
        );

        let cycle = crate::execution::ModelDrivenFactoryCycleRecord {
            model_factory_cycle_id: cycle_id.clone(),
            program_instance_ref: program_instance_ref.to_string(),
            campaign_number,
            turn_package_ref: turn_package.turn_package_id.clone(),
            parsed_turn_result_ref: parsed_result.parsed_turn_result_id.clone(),
            inference_turn_result_ref: parsed_result.inference_turn_result_ref.clone(),
            authority_decision_ref: authority_decision.authority_decision_id.clone(),
            continuity_bundle_ref,
            turn_grounding_ref,
            tool_execution_receipt_refs: unique_strings(
                parsed_result.tool_execution_receipt_refs.clone(),
            ),
            tool_execution_refs: unique_strings(parsed_result.tool_execution_refs.clone()),
            worker_card_refs: unique_strings(worker_card_refs),
            worker_dispatch_refs: unique_strings(worker_dispatch_refs),
            worker_result_refs: unique_strings(worker_result_refs),
            proving_refs: unique_strings(proving_refs),
            observation_refs: unique_strings(observation_refs),
            comparison_refs: unique_strings(comparison_refs),
            tick_receipt_ref: tick_receipt_ref.clone(),
            candidate_factory_ref,
            resulting_factory_ref,
            approval_request_refs: unique_strings(
                approvals
                    .iter()
                    .map(|approval| approval.model_approval_request_id.clone()),
            ),
            quarantine_refs: unique_strings(
                quarantines
                    .iter()
                    .map(|quarantine| quarantine.model_quarantine_id.clone()),
            ),
            checkpoint_refs: unique_strings(
                checkpoints
                    .iter()
                    .map(|checkpoint| checkpoint.turn_checkpoint_id.clone()),
            ),
            pending_action_refs: unique_strings(
                pending_actions
                    .iter()
                    .map(|action| action.pending_governed_turn_action_id.clone()),
            ),
            outcome,
            created_at: parsed_result.created_at.clone(),
        };
        store.persist_model_driven_factory_cycle_record(&cycle)?;

        let mut cycles = store
            .list_model_driven_factory_cycle_records()?
            .into_iter()
            .filter(|record| record.program_instance_ref == program_instance_ref)
            .collect::<Vec<_>>();
        cycles.sort_by(|left, right| {
            left.campaign_number
                .cmp(&right.campaign_number)
                .then_with(|| {
                    left.model_factory_cycle_id
                        .cmp(&right.model_factory_cycle_id)
                })
        });
        let current_instance = self
            .factory_program_instances
            .read()
            .unwrap()
            .iter()
            .find(|instance| instance.instance_id == program_instance_ref)
            .cloned()
            .ok_or_else(|| LocalRuntimeError::ProgramNotFound {
                program_id: program_instance_ref.to_string(),
            })?;
        let existing_lineage = store
            .load_recursive_lineage_execution_record(&lineage_id)
            .ok();
        let lineage = crate::execution::RecursiveLineageExecutionRecord {
            recursive_lineage_execution_id: lineage_id.clone(),
            program_instance_ref: program_instance_ref.to_string(),
            cycle_refs: cycles
                .iter()
                .map(|record| record.model_factory_cycle_id.clone())
                .collect(),
            model_turn_refs: unique_strings(cycles.iter().flat_map(|record| {
                [
                    record.turn_package_ref.clone(),
                    record.parsed_turn_result_ref.clone(),
                ]
            })),
            produced_worker_refs: unique_strings(
                cycles
                    .iter()
                    .flat_map(|record| record.worker_card_refs.clone()),
            ),
            adopted_factory_refs: unique_strings(cycles.iter().filter_map(|record| {
                (record.outcome == crate::execution::RecursiveCycleOutcome::Adopted)
                    .then(|| record.resulting_factory_ref.clone())
                    .flatten()
            })),
            continuity_refs: unique_strings(cycles.iter().flat_map(|record| {
                record
                    .continuity_bundle_ref
                    .iter()
                    .cloned()
                    .chain(record.turn_grounding_ref.iter().cloned())
            })),
            governance_refs: unique_strings(cycles.iter().flat_map(|record| {
                std::iter::once(record.authority_decision_ref.clone())
                    .chain(record.approval_request_refs.clone())
                    .chain(record.quarantine_refs.clone())
                    .chain(record.checkpoint_refs.clone())
                    .chain(record.pending_action_refs.clone())
            })),
            latest_tick_ref: cycles
                .iter()
                .rev()
                .find_map(|record| record.tick_receipt_ref.clone()),
            current_depth: current_instance.generation_depth,
            campaign_count: cycles.len(),
            claim_posture: crate::execution::derive_recursion_claim_posture(&cycles),
            created_at: existing_lineage
                .as_ref()
                .map(|lineage| lineage.created_at.clone())
                .unwrap_or_else(current_timestamp),
            updated_at: current_timestamp(),
        };
        store.persist_recursive_lineage_execution_record(&lineage)?;

        let dependency_statement =
            build_architectural_dependency_statement(store, &lineage, &cycles)?;
        store.persist_architectural_dependency_statement(&dependency_statement)?;
        let closure_dossier = build_interface_native_recursion_closure_dossier(
            &lineage,
            &cycles,
            &dependency_statement,
        )?;
        store.persist_interface_native_recursion_closure_dossier(&closure_dossier)?;
        Ok(())
    }

    fn current_model_cycle_campaign_number(
        &self,
        store: &DurableArtifactStore,
        program_instance_ref: &str,
        parsed_result: &ParsedTurnResult,
    ) -> Result<usize, LocalRuntimeError> {
        if let Ok(existing) = store.load_model_driven_factory_cycle_record(&model_factory_cycle_id(
            &parsed_result.parsed_turn_result_id,
        )) {
            return Ok(existing.campaign_number);
        }
        self.next_llm_factory_campaign_number(store, program_instance_ref)
    }

    fn materialize_produced_worker_agent_card(
        &self,
        store: &DurableArtifactStore,
        program_instance_ref: &str,
        campaign_number: usize,
        cycle_id: &str,
        lineage_id: &str,
        turn_package: &TurnPackage,
        parsed_result: &ParsedTurnResult,
        worker_id: &str,
        task_kind: Option<&str>,
        requested_capabilities: &[crate::execution::CapabilityOperationRequest],
    ) -> Result<crate::execution::WorkerSpecializationCard, LocalRuntimeError> {
        let worker_card_id = produced_worker_card_id(program_instance_ref, worker_id);
        if let Ok(existing) = store.load_worker_specialization_card(&worker_card_id) {
            return Ok(existing);
        }
        let capability_worlds = requested_capabilities
            .iter()
            .map(|request| request.world.clone())
            .collect::<Vec<_>>();
        let role_kind = crate::execution::infer_worker_role_kind(task_kind, &capability_worlds);
        let world_refs = capability_worlds
            .iter()
            .map(capability_world_wire_value)
            .collect::<Vec<_>>();
        let routing_requirements = unique_strings(
            requested_capabilities
                .iter()
                .map(|request| request.resource_scope.clone()),
        );
        let card = crate::execution::WorkerSpecializationCard {
            worker_card_id,
            role_kind,
            world_refs,
            capability_ref: worker_role_capability(role_kind).to_string(),
            service_dependency_refs: worker_role_service_dependencies(role_kind),
            preferred_work_refs: worker_role_preferred_work(role_kind),
            ownership_scope: format!(
                "scope:produced-worker:{}:{}",
                sanitize_id(program_instance_ref),
                sanitize_id(worker_id)
            ),
            responsibility_boundary: format!(
                "Produced worker `{}` is bounded to model-requested task `{}`.",
                worker_id,
                task_kind.unwrap_or("bounded-task")
            ),
            routing_requirements: if routing_requirements.is_empty() {
                vec![format!("route:produced-worker:{}", sanitize_id(worker_id))]
            } else {
                routing_requirements
            },
            failure_budget_ref: format!(
                "failure-budget:produced-worker:{}:{}",
                sanitize_id(program_instance_ref),
                sanitize_id(worker_id)
            ),
            production_mode: Some(crate::execution::WorkerAgentProductionMode::ModelProduced),
            production_program_instance_ref: Some(program_instance_ref.to_string()),
            production_turn_package_ref: Some(turn_package.turn_package_id.clone()),
            production_parsed_turn_result_ref: Some(parsed_result.parsed_turn_result_id.clone()),
            production_cycle_ref: Some(cycle_id.to_string()),
            lineage_ref: Some(lineage_id.to_string()),
            production_summary: Some(format!(
                "Model-produced worker `{}` first appeared in campaign {}.",
                worker_id, campaign_number
            )),
        };
        store.persist_worker_specialization_card(&card)?;
        Ok(card)
    }

    fn llm_interface_store(&self) -> Result<DurableArtifactStore, LocalRuntimeError> {
        DurableArtifactStore::bootstrap(self.workspace.llm_interface_store_root())
            .map_err(Into::into)
    }

    fn tool_catalog_for_ref(
        &self,
        tool_catalog_ref: &str,
    ) -> Result<CanonicalToolCatalogBundle, LocalRuntimeError> {
        if self
            .tool_catalog_bundle
            .read()
            .unwrap()
            .catalog
            .tool_catalog_id
            == tool_catalog_ref
        {
            return Ok(self.tool_catalog_bundle.read().unwrap().clone());
        }
        if tool_catalog_ref == M1_REFERENCE_TOOL_CATALOG_ID {
            return Ok(self.m1_tool_catalog_bundle.read().unwrap().clone());
        }
        Err(LocalRuntimeError::InvalidTurnPackageOperation {
            identifier: tool_catalog_ref.to_string(),
            reason: "turn package references an unknown tool catalog".to_string(),
        })
    }

    pub async fn inference_provider_registry(
        &self,
    ) -> Result<InferenceProviderRegistryView, LocalRuntimeError> {
        let mut providers = self.inference_providers.read().unwrap().clone();
        providers.sort_by(|left, right| left.provider_id.cmp(&right.provider_id));
        let provider_views = providers
            .into_iter()
            .map(build_inference_provider_view)
            .collect::<Vec<_>>();
        let summary = if provider_views.is_empty() {
            "No inference providers are registered.".to_string()
        } else {
            format!(
                "{} inference provider(s) are registered in the Wasm-Biotic runtime boundary.",
                provider_views.len()
            )
        };
        Ok(InferenceProviderRegistryView {
            summary,
            providers: provider_views,
        })
    }

    pub async fn inference_provider_view(
        &self,
        provider_id: &str,
    ) -> Result<InferenceProviderView, LocalRuntimeError> {
        let provider = self
            .inference_providers
            .read()
            .unwrap()
            .iter()
            .find(|provider| provider.provider_id == provider_id)
            .cloned()
            .ok_or_else(|| LocalRuntimeError::InferenceProviderNotFound {
                provider_id: provider_id.to_string(),
            })?;
        Ok(build_inference_provider_view(provider))
    }

    pub async fn upsert_inference_provider(
        &self,
        provider: InferenceProviderRegistryEntry,
    ) -> Result<InferenceProviderView, LocalRuntimeError> {
        provider
            .validate()
            .map_err(|error| invalid_inference_operation(&provider.provider_id, error))?;
        let store = self.llm_interface_store()?;
        store.persist_inference_provider_registry_entry(&provider)?;
        let mut providers = self.inference_providers.write().unwrap();
        if let Some(entry) = providers
            .iter_mut()
            .find(|entry| entry.provider_id == provider.provider_id)
        {
            *entry = provider.clone();
        } else {
            providers.push(provider.clone());
        }
        providers.sort_by(|left, right| left.provider_id.cmp(&right.provider_id));
        Ok(build_inference_provider_view(provider))
    }

    pub async fn inference_turn_ledger(
        &self,
    ) -> Result<InferenceTurnLedgerView, LocalRuntimeError> {
        let store = self.llm_interface_store()?;
        let mut turn_results = self.inference_turn_results.read().unwrap().clone();
        turn_results.sort_by(|left, right| {
            run_timestamp(&right.created_at)
                .cmp(&run_timestamp(&left.created_at))
                .then_with(|| left.turn_result_id.cmp(&right.turn_result_id))
        });
        let mut turns = Vec::with_capacity(turn_results.len());
        for turn_result in turn_results {
            turns.push(load_inference_turn_view(&store, &turn_result)?);
        }
        let summary = if turns.is_empty() {
            "No inference turns have been executed yet.".to_string()
        } else {
            format!(
                "{} inference turn(s) are recorded in the Wasm-Biotic runtime ledger.",
                turns.len()
            )
        };
        Ok(InferenceTurnLedgerView { summary, turns })
    }

    pub async fn inference_turn_view(
        &self,
        turn_result_id: &str,
    ) -> Result<InferenceTurnView, LocalRuntimeError> {
        let turn_result = self
            .inference_turn_results
            .read()
            .unwrap()
            .iter()
            .find(|turn_result| turn_result.turn_result_id == turn_result_id)
            .cloned()
            .ok_or_else(|| LocalRuntimeError::InferenceTurnNotFound {
                turn_result_id: turn_result_id.to_string(),
            })?;
        let store = self.llm_interface_store()?;
        load_inference_turn_view(&store, &turn_result)
    }

    pub async fn create_inference_turn(
        &self,
        request: CreateInferenceTurnRequest,
    ) -> Result<InferenceTurnView, LocalRuntimeError> {
        request
            .validate()
            .map_err(|error| invalid_inference_operation(&request.turn_request_id, error))?;

        let provider = self
            .inference_providers
            .read()
            .unwrap()
            .iter()
            .find(|provider| provider.provider_id == request.provider_ref)
            .cloned()
            .ok_or_else(|| LocalRuntimeError::InvalidInferenceOperation {
                identifier: request.turn_request_id.clone(),
                reason: format!("missing provider '{}'", request.provider_ref),
            })?;

        let generation_policy = request.generation_policy.clone();
        generation_policy
            .validate()
            .map_err(|error| invalid_inference_operation(&request.turn_request_id, error))?;

        let turn_request = InferenceTurnRequest {
            turn_request_id: request.turn_request_id.clone(),
            provider_ref: request.provider_ref.clone(),
            model_ref: request.model_ref.clone(),
            rendered_prompt_ref: format!(
                "inference-rendered-prompt:{}",
                sanitize_id(&request.turn_request_id)
            ),
            tool_catalog_ref: format!(
                "inference-tool-catalog:{}",
                sanitize_id(&request.turn_request_id)
            ),
            response_schema_ref: format!(
                "inference-response-schema:{}",
                sanitize_id(&request.turn_request_id)
            ),
            generation_policy_ref: generation_policy.generation_policy_id.clone(),
        };
        turn_request
            .validate()
            .map_err(|error| invalid_inference_operation(&request.turn_request_id, error))?;

        let rendered_prompt = InferenceRenderedPromptRecord {
            rendered_prompt_id: turn_request.rendered_prompt_ref.clone(),
            turn_request_ref: turn_request.turn_request_id.clone(),
            prompt_text: request.rendered_prompt.clone(),
            created_at: current_timestamp(),
        };
        let tool_catalog = InferenceToolCatalogPayloadRecord {
            tool_catalog_id: turn_request.tool_catalog_ref.clone(),
            turn_request_ref: turn_request.turn_request_id.clone(),
            tool_catalog_json: request.tool_catalog_json.clone(),
            created_at: current_timestamp(),
        };
        let response_schema = InferenceResponseSchemaPayloadRecord {
            response_schema_id: turn_request.response_schema_ref.clone(),
            turn_request_ref: turn_request.turn_request_id.clone(),
            response_schema_json: request.response_schema_json.clone(),
            created_at: current_timestamp(),
        };

        let store = self.llm_interface_store()?;
        store.persist_inference_generation_policy(&generation_policy)?;
        store.persist_inference_turn_request(&turn_request)?;
        store.persist_inference_rendered_prompt_record(&rendered_prompt)?;
        store.persist_inference_tool_catalog_payload_record(&tool_catalog)?;
        store.persist_inference_response_schema_payload_record(&response_schema)?;

        let bundle = execute_inference_turn(
            &provider,
            &generation_policy,
            &turn_request,
            &rendered_prompt,
            &tool_catalog,
            &response_schema,
        )
        .await
        .map_err(|error| map_inference_execution_error(&request.turn_request_id, error))?;

        for request_body in &bundle.request_body_records {
            store.persist_inference_request_body_record(request_body)?;
        }
        for raw_output in &bundle.raw_output_records {
            store.persist_inference_raw_output_record(raw_output)?;
        }
        for attempt in &bundle.attempts {
            store.persist_inference_attempt_record(attempt)?;
        }
        store.persist_inference_usage_record(&bundle.usage_record)?;
        store.persist_inference_provider_outcome_record(&bundle.provider_outcome)?;
        if let Some(parsed_output) = &bundle.parsed_output {
            store.persist_inference_parsed_output_record(parsed_output)?;
        }
        if let Some(degradation_record) = &bundle.degradation_record {
            store.persist_provider_degradation_record(degradation_record)?;
        }
        store.persist_inference_turn_result(&bundle.turn_result)?;

        let mut turn_results = self.inference_turn_results.write().unwrap();
        if let Some(entry) = turn_results
            .iter_mut()
            .find(|entry| entry.turn_result_id == bundle.turn_result.turn_result_id)
        {
            *entry = bundle.turn_result.clone();
        } else {
            turn_results.push(bundle.turn_result.clone());
        }
        turn_results.sort_by(|left, right| {
            run_timestamp(&right.created_at)
                .cmp(&run_timestamp(&left.created_at))
                .then_with(|| left.turn_result_id.cmp(&right.turn_result_id))
        });

        load_inference_turn_view(&store, &bundle.turn_result)
    }

    pub async fn turn_package_ledger(&self) -> Result<TurnPackageLedgerView, LocalRuntimeError> {
        let store = self.llm_interface_store()?;
        let mut turn_packages = self.turn_packages.read().unwrap().clone();
        turn_packages.sort_by(|left, right| {
            run_timestamp(&right.created_at)
                .cmp(&run_timestamp(&left.created_at))
                .then_with(|| left.turn_package_id.cmp(&right.turn_package_id))
        });
        let turn_packages = turn_packages
            .iter()
            .map(|turn_package| load_turn_package_view(&store, turn_package))
            .collect::<Result<Vec<_>, _>>()?;
        let summary = if turn_packages.is_empty() {
            "No turn packages are recorded in the Wasm-Biotic runtime ledger.".to_string()
        } else {
            format!(
                "{} turn package(s) are recorded in the Wasm-Biotic runtime ledger.",
                turn_packages.len()
            )
        };
        Ok(TurnPackageLedgerView {
            summary,
            turn_packages,
        })
    }

