    async fn create_turn_package_for_catalog(
        &self,
        request: CreateTurnPackageRequest,
        requested_tool_catalog_ref: &str,
    ) -> Result<TurnPackageView, LocalRuntimeError> {
        request
            .validate()
            .map_err(|error| invalid_turn_package_operation(&request.turn_package_id, error))?;

        let timestamp = current_timestamp();
        let tool_catalog_ref = self
            .tool_catalog_for_ref(requested_tool_catalog_ref)?
            .catalog
            .tool_catalog_id;
        let tool_execution_context = ToolExecutionContextRecord {
            tool_execution_context_id: request
                .tool_execution_context
                .tool_execution_context_id
                .clone(),
            turn_package_ref: request.turn_package_id.clone(),
            capability_envelope: request.tool_execution_context.capability_envelope.clone(),
            campaign_ref: request.tool_execution_context.campaign_ref.clone(),
            epoch_ref: request.tool_execution_context.epoch_ref.clone(),
            task_ref: request.tool_execution_context.task_ref.clone(),
            pointer_index_ref: request.tool_execution_context.pointer_index_ref.clone(),
            factory_program_instance_ref: request
                .tool_execution_context
                .factory_program_instance_ref
                .clone(),
            workspace_scope_ref: request.tool_execution_context.workspace_scope_ref.clone(),
            ecology_snapshot_ref: request.tool_execution_context.ecology_snapshot_ref.clone(),
            created_at: timestamp.clone(),
        };
        let turn_package = TurnPackage {
            turn_package_id: request.turn_package_id.clone(),
            program_ref: request.program_ref.clone(),
            session_ref: request.session_ref.clone(),
            turn_ref: request.turn_ref.clone(),
            envelope_ref: request.envelope_ref.clone(),
            role: request.role,
            system_frame_ref: request.system_frame_ref.clone(),
            system_frame_text: request.system_frame_text.clone(),
            program_frame_ref: request.program_frame_ref.clone(),
            program_frame_text: request.program_frame_text.clone(),
            capability_frame_ref: request.capability_frame_ref.clone(),
            capability_frame_text: request.capability_frame_text.clone(),
            agenda_ref: request.agenda_ref.clone(),
            agenda_text: request.agenda_text.clone(),
            continuity_entries: request.continuity_entries.clone(),
            tool_catalog_ref,
            tool_execution_context_ref: tool_execution_context.tool_execution_context_id.clone(),
            response_schema_family: request.response_schema_family,
            context_budget: crate::execution::ContextBudgetRecord {
                context_budget_id: request.context_budget.context_budget_id.clone(),
                turn_package_ref: request.turn_package_id.clone(),
                max_rendered_prompt_chars: request.context_budget.max_rendered_prompt_chars,
                max_continuity_entries: request.context_budget.max_continuity_entries,
                created_at: timestamp.clone(),
            },
            created_at: timestamp,
        };
        turn_package.validate().map_err(|error| {
            invalid_turn_package_operation(&turn_package.turn_package_id, error)
        })?;

        let continuity_grounding = self
            .build_continuity_grounding_bundle(&turn_package, &tool_execution_context)
            .await?;
        let store = self.llm_interface_store()?;
        store.persist_context_budget_record(&turn_package.context_budget)?;
        store.persist_tool_execution_context_record(&tool_execution_context)?;
        store.persist_turn_package(&turn_package)?;
        persist_continuity_grounding_bundle(&store, &continuity_grounding)?;

        let mut turn_packages = self.turn_packages.write().unwrap();
        upsert_turn_package(&mut turn_packages, turn_package.clone());
        let mut tool_execution_contexts = self.tool_execution_contexts.write().unwrap();
        upsert_tool_execution_context(&mut tool_execution_contexts, tool_execution_context);
        load_turn_package_view(&store, &turn_package)
    }

