    pub async fn execute_turn_package(
        &self,
        request: ExecuteTurnPackageRequest,
    ) -> Result<ParsedTurnResultView, LocalRuntimeError> {
        request
            .validate()
            .map_err(|error| invalid_turn_package_operation(&request.turn_package_id, error))?;
        let turn_package = self
            .turn_packages
            .read()
            .unwrap()
            .iter()
            .find(|turn_package| turn_package.turn_package_id == request.turn_package_id)
            .cloned()
            .ok_or_else(|| LocalRuntimeError::TurnPackageNotFound {
                turn_package_id: request.turn_package_id.clone(),
            })?;
        let render_bundle = render_turn_package(&turn_package)
            .map_err(|error| invalid_turn_package_operation(&request.turn_package_id, error))?;
        let store = self.llm_interface_store()?;
        persist_turn_render_bundle(&store, &render_bundle)?;
        let tool_catalog_bundle = self.tool_catalog_for_ref(&turn_package.tool_catalog_ref)?;

        let low_level_request = CreateInferenceTurnRequest {
            turn_request_id: format!(
                "turn-package-execution:{}:{}",
                sanitize_id(&turn_package.turn_package_id),
                current_timestamp()
            ),
            provider_ref: request.provider_ref.clone(),
            model_ref: request.model_ref.clone(),
            generation_policy: request.generation_policy.clone(),
            rendered_prompt: render_bundle.rendering.rendered_prompt_text.clone(),
            tool_catalog_json: render_tool_catalog_json_for_role(
                &tool_catalog_bundle,
                turn_package.role,
            )
            .map_err(|error| LocalRuntimeError::InferenceExecutionFailed {
                identifier: request.turn_package_id.clone(),
                reason: error.to_string(),
            })?,
            response_schema_json: render_bundle.response_schema.response_schema_json.clone(),
        };
        let inference_turn = self.create_inference_turn(low_level_request).await?;
        let parsed_bundle = parse_turn_package_output(
            &turn_package,
            &inference_turn.turn_result,
            inference_turn.parsed_output.as_ref(),
        )
        .map_err(|error| invalid_turn_package_operation(&request.turn_package_id, error))?;
        let context =
            store.load_tool_execution_context_record(&turn_package.tool_execution_context_ref)?;
        let mut governance_artifacts = build_turn_governance_artifacts(
            &tool_catalog_bundle,
            &turn_package,
            &parsed_bundle,
            &context,
        )?;
        persist_parsed_turn_bundle(&store, &parsed_bundle)?;
        self.apply_turn_governance_runtime_grounding(
            &turn_package,
            &context,
            &mut governance_artifacts,
        )
        .await?;
        persist_turn_governance_artifacts(&store, &governance_artifacts)?;

        {
            let mut parsed_turn_results = self.parsed_turn_results.write().unwrap();
            upsert_parsed_turn_result(
                &mut parsed_turn_results,
                parsed_bundle.parsed_result.clone(),
            );
        }
        {
            let mut policies = self.delegation_policies.write().unwrap();
            upsert_model_delegation_policy_record(
                &mut policies,
                governance_artifacts.bundle.delegation_policy.clone(),
            );
        }
        {
            let mut decisions = self.authority_decisions.write().unwrap();
            upsert_model_authority_decision(
                &mut decisions,
                governance_artifacts.bundle.authority_decision.clone(),
            );
        }
        {
            let mut approvals = self.model_approval_requests.write().unwrap();
            for approval in &governance_artifacts.bundle.approvals {
                upsert_model_approval_request_record(&mut approvals, approval.clone());
            }
        }
        {
            let mut quarantines = self.model_output_quarantines.write().unwrap();
            for quarantine in &governance_artifacts.bundle.quarantines {
                upsert_model_output_quarantine_record(&mut quarantines, quarantine.clone());
            }
        }
        {
            let mut checkpoints = self.turn_checkpoint_records.write().unwrap();
            for checkpoint in &governance_artifacts.bundle.checkpoints {
                upsert_turn_checkpoint_record(&mut checkpoints, checkpoint.clone());
            }
        }
        {
            let mut pending_actions = self.pending_governed_turn_actions.write().unwrap();
            for action in &governance_artifacts.bundle.pending_actions {
                upsert_pending_governed_turn_action_record(&mut pending_actions, action.clone());
            }
        }
        self.reconcile_recursive_factory_artifacts_for_turn(
            &store,
            &parsed_bundle.parsed_result.parsed_turn_result_id,
        )
        .await?;
        load_parsed_turn_result_view(&store, &parsed_bundle.parsed_result)
    }

