    pub async fn governance_health_view(&self) -> Result<GovernanceHealthView, LocalRuntimeError> {
        let parsed_turn_results = self.parsed_turn_results.read().unwrap().clone();
        let authority_decisions = self.authority_decisions.read().unwrap().clone();
        let parse_repair_event_count = parsed_turn_results
            .iter()
            .map(|result| result.repair_refs.len())
            .sum::<usize>();
        let mut allow_count = 0usize;
        let mut approval_block_count = 0usize;
        let mut deny_count = 0usize;
        let mut quarantine_count = 0usize;
        let mut fail_count = 0usize;
        for decision in &authority_decisions {
            match decision.decision {
                ModelAuthorityDecisionKind::Allow => allow_count += 1,
                ModelAuthorityDecisionKind::ApprovalBlock => approval_block_count += 1,
                ModelAuthorityDecisionKind::Deny => deny_count += 1,
                ModelAuthorityDecisionKind::Quarantine => quarantine_count += 1,
                ModelAuthorityDecisionKind::Fail => fail_count += 1,
            }
        }
        let approval_interrupt_count = self.model_approval_requests.read().unwrap().len();
        let quarantine_record_count = self.model_output_quarantines.read().unwrap().len();
        let total_turns = parsed_turn_results.len();
        let summary = if total_turns == 0 {
            "No governed LLM turns are available yet.".to_string()
        } else {
            format!(
                "{} governed turn(s) now account for {} approval interrupt(s), {} quarantine record(s), and {} parse repair event(s).",
                total_turns,
                approval_interrupt_count,
                quarantine_record_count,
                parse_repair_event_count
            )
        };
        Ok(GovernanceHealthView {
            summary,
            total_turns,
            allow_count,
            approval_block_count,
            deny_count,
            quarantine_count,
            fail_count,
            approval_interrupt_count,
            quarantine_record_count,
            parse_repair_event_count,
        })
    }

