    async fn build_continuity_grounding_bundle(
        &self,
        turn_package: &TurnPackage,
        context: &ToolExecutionContextRecord,
    ) -> Result<crate::execution::ContinuityGroundingBundle, LocalRuntimeError> {
        let mut pointer_index_refs = Vec::new();
        let mut transcript_slice_refs = Vec::new();
        let mut lineage_receipt_refs = Vec::new();
        let mut open_question_refs = Vec::new();
        let mut missing_evidence_refs = Vec::new();
        let mut open_question_notes = Vec::new();
        let mut selection_diagnostics = Vec::new();
        let mut retrieval_traces = Vec::new();
        let mut contradiction_carry_forwards = Vec::new();

        let runtime_state = self
            .match_runtime_state_for_turn_context(turn_package, context)
            .await;
        if let Some(runtime_state) = &runtime_state {
            selection_diagnostics.push(format!(
                "matched runtime state session `{}` for turn grounding",
                runtime_state.session.header.session_id
            ));
        } else {
            open_question_refs.push(format!(
                "open-question:{}:runtime-state",
                sanitize_id(&turn_package.turn_package_id)
            ));
            missing_evidence_refs.push(turn_package.session_ref.clone());
            open_question_notes.push(format!(
                "No replayable runtime state matched session `{}` and the supplied continuity context.",
                turn_package.session_ref
            ));
        }

        if let Some(runtime_state) = &runtime_state {
            if let Some(pointer_index_ref) = context.pointer_index_ref.as_deref() {
                if let Some(pointer_index) = runtime_state
                    .memory_store
                    .load_pointer_index(pointer_index_ref)
                {
                    pointer_index_refs.push(pointer_index.index_id.clone());
                    let mut bundle_classes = Vec::new();
                    for entry_ref in &pointer_index.entry_refs {
                        if let Some(bundle) = runtime_state.memory_store.topic_bundle(entry_ref) {
                            if !bundle_classes.contains(&bundle.bundle_class) {
                                bundle_classes.push(bundle.bundle_class);
                            }
                        }
                    }
                    if bundle_classes.is_empty() {
                        bundle_classes.push(TopicBundleClass::CampaignOperatingNotes);
                    }
                    let max_trace_count = turn_package
                        .context_budget
                        .max_continuity_entries
                        .max(1)
                        .min(bundle_classes.len());
                    for bundle_class in bundle_classes.into_iter().take(max_trace_count) {
                        let trace = crate::execution::execute_memory_retrieval_protocol(
                            &runtime_state.memory_store,
                            &crate::execution::MemoryRetrievalRequest {
                                retrieval_request_id: format!(
                                    "turn-grounding:{}:{}",
                                    sanitize_id(&turn_package.turn_package_id),
                                    topic_bundle_class_label(bundle_class)
                                ),
                                shell_session_id: turn_package.session_ref.clone(),
                                shell_turn_id: turn_package.turn_ref.clone(),
                                pointer_index_ref: pointer_index.index_id.clone(),
                                bundle_class,
                                transcript_query: crate::execution::TranscriptSliceQuery {
                                    campaign_id: context.campaign_ref.clone().or_else(|| {
                                        Some(runtime_state.session.header.campaign_id.clone())
                                    }),
                                    epoch_id: context.epoch_ref.clone().or_else(|| {
                                        Some(runtime_state.session.header.epoch_id.clone())
                                    }),
                                    session_id: Some(turn_package.session_ref.clone()),
                                    task_id: context
                                        .task_ref
                                        .clone()
                                        .or_else(|| Some(runtime_state.root_task.task_id.clone())),
                                    artifact_ref: None,
                                    search_term: None,
                                },
                                max_bundle_refs: turn_package
                                    .context_budget
                                    .max_continuity_entries
                                    .max(1),
                            },
                        )
                        .map_err(|error| {
                            LocalRuntimeError::InvalidTurnPackageOperation {
                                identifier: turn_package.turn_package_id.clone(),
                                reason: error.to_string(),
                            }
                        })?;
                        transcript_slice_refs.extend(trace.transcript_slice_refs.iter().cloned());
                        retrieval_traces.push(trace);
                    }
                    transcript_slice_refs = unique_strings(transcript_slice_refs);
                    selection_diagnostics.push(format!(
                        "retrieved {} continuity trace(s) from pointer index `{}`",
                        retrieval_traces.len(),
                        pointer_index.index_id
                    ));
                    if transcript_slice_refs.is_empty() {
                        open_question_refs.push(format!(
                            "open-question:{}:transcript-slices",
                            sanitize_id(&turn_package.turn_package_id)
                        ));
                        missing_evidence_refs.push(pointer_index.index_id.clone());
                        open_question_notes.push(format!(
                            "No transcript slices were retrieved for pointer index `{}` under the turn grounding query.",
                            pointer_index.index_id
                        ));
                    }
                    for contradiction_ref in &pointer_index.contested_refs {
                        let Some(contradiction) = runtime_state
                            .memory_store
                            .contradiction_records
                            .iter()
                            .find(|record| record.contradiction_id == *contradiction_ref)
                        else {
                            continue;
                        };
                        if matches!(
                            contradiction.resolution_state,
                            crate::execution::ContradictionResolutionState::Resolved
                                | crate::execution::ContradictionResolutionState::Retired
                        ) {
                            continue;
                        }
                        contradiction_carry_forwards.push(ContradictionCarryForwardRecord {
                            contradiction_carry_forward_id: format!(
                                "contradiction-carry-forward:{}:{}",
                                sanitize_id(&turn_package.turn_package_id),
                                sanitize_id(&contradiction.contradiction_id)
                            ),
                            turn_package_ref: turn_package.turn_package_id.clone(),
                            contradiction_ref: contradiction.contradiction_id.clone(),
                            claim_refs: contradiction.claim_refs.clone(),
                            resolution_state: contradiction.resolution_state,
                            resolution_path: contradiction.resolution_path.clone(),
                            created_at: turn_package.created_at.clone(),
                        });
                    }
                    if contradiction_carry_forwards.is_empty() {
                        selection_diagnostics.push(format!(
                            "no unresolved contradictions were carried forward from pointer index `{}`",
                            pointer_index.index_id
                        ));
                    } else {
                        selection_diagnostics.push(format!(
                            "carried {} unresolved contradiction(s) from pointer index `{}`",
                            contradiction_carry_forwards.len(),
                            pointer_index.index_id
                        ));
                    }
                } else {
                    open_question_refs.push(format!(
                        "open-question:{}:pointer-index",
                        sanitize_id(&turn_package.turn_package_id)
                    ));
                    missing_evidence_refs.push(pointer_index_ref.to_string());
                    open_question_notes.push(format!(
                        "Pointer index `{}` was requested for grounding but was not present in the matched runtime state.",
                        pointer_index_ref
                    ));
                }
            } else {
                open_question_refs.push(format!(
                    "open-question:{}:pointer-index-context",
                    sanitize_id(&turn_package.turn_package_id)
                ));
                open_question_notes.push(
                    "No pointer index ref was supplied in the turn tool execution context."
                        .to_string(),
                );
            }
        }

        if let Some(factory_program_instance_ref) = context.factory_program_instance_ref.as_deref()
        {
            let program_lineage_receipts = self
                .factory_program_lineage_receipt_refs(factory_program_instance_ref)
                .await?;
            if program_lineage_receipts.is_empty() {
                open_question_refs.push(format!(
                    "open-question:{}:lineage-grounding",
                    sanitize_id(&turn_package.turn_package_id)
                ));
                missing_evidence_refs.push(factory_program_instance_ref.to_string());
                open_question_notes.push(format!(
                    "Factory program `{}` did not yield lineage receipts for recursive turn grounding.",
                    factory_program_instance_ref
                ));
            } else {
                lineage_receipt_refs = program_lineage_receipts;
                selection_diagnostics.push(format!(
                    "attached {} lineage receipt ref(s) from factory program `{}`",
                    lineage_receipt_refs.len(),
                    factory_program_instance_ref
                ));
            }
        }

        if selection_diagnostics.is_empty() {
            selection_diagnostics.push(
                "turn grounding captured only open questions because no evidence sources matched"
                    .to_string(),
            );
        }

        let open_question_ledger = if open_question_refs.is_empty() {
            None
        } else {
            Some(OpenQuestionLedger {
                open_question_ledger_id: format!(
                    "open-question-ledger:{}",
                    sanitize_id(&turn_package.turn_package_id)
                ),
                turn_package_ref: turn_package.turn_package_id.clone(),
                open_question_refs: unique_strings(open_question_refs),
                missing_evidence_refs: unique_strings(missing_evidence_refs),
                notes: open_question_notes,
                created_at: turn_package.created_at.clone(),
            })
        };
        let open_question_refs = open_question_ledger
            .as_ref()
            .map(|ledger| ledger.open_question_refs.clone())
            .unwrap_or_default();
        let contradiction_refs = contradiction_carry_forwards
            .iter()
            .map(|record| record.contradiction_ref.clone())
            .collect::<Vec<_>>();
        let continuity_bundle = ModelContinuityBundle {
            continuity_bundle_id: format!(
                "continuity-bundle:{}",
                sanitize_id(&turn_package.turn_package_id)
            ),
            turn_package_ref: turn_package.turn_package_id.clone(),
            session_ref: turn_package.session_ref.clone(),
            agenda_ref: turn_package.agenda_ref.clone(),
            pointer_index_refs: unique_strings(pointer_index_refs),
            transcript_slice_refs,
            lineage_receipt_refs: unique_strings(lineage_receipt_refs),
            contradiction_refs,
            open_question_refs,
            created_at: turn_package.created_at.clone(),
        };
        let turn_grounding_packet = TurnGroundingPacket {
            turn_grounding_packet_id: format!(
                "turn-grounding:{}",
                sanitize_id(&turn_package.turn_package_id)
            ),
            turn_package_ref: turn_package.turn_package_id.clone(),
            continuity_bundle_ref: continuity_bundle.continuity_bundle_id.clone(),
            open_question_ledger_ref: open_question_ledger
                .as_ref()
                .map(|ledger| ledger.open_question_ledger_id.clone()),
            contradiction_carry_forward_refs: contradiction_carry_forwards
                .iter()
                .map(|record| record.contradiction_carry_forward_id.clone())
                .collect(),
            retrieval_trace_refs: retrieval_traces
                .iter()
                .map(|trace| trace.trace_id.clone())
                .collect(),
            lineage_receipt_refs: continuity_bundle.lineage_receipt_refs.clone(),
            selection_diagnostics,
            created_at: turn_package.created_at.clone(),
        };
        let bundle = crate::execution::ContinuityGroundingBundle {
            continuity_bundle,
            turn_grounding_packet,
            retrieval_traces,
            open_question_ledger,
            contradiction_carry_forwards,
        };
        bundle
            .validate()
            .map_err(|error| LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: turn_package.turn_package_id.clone(),
                reason: error.to_string(),
            })?;
        Ok(bundle)
    }

    async fn match_runtime_state_for_turn_context(
        &self,
        turn_package: &TurnPackage,
        context: &ToolExecutionContextRecord,
    ) -> Option<ReplayableRuntimeState> {
        self.runs
            .read()
            .await
            .values()
            .filter_map(|record| {
                let mut score = 0usize;
                if record.runtime_state.session.header.session_id == turn_package.session_ref {
                    score += 8;
                }
                if context.campaign_ref.as_deref().is_some_and(|campaign_ref| {
                    campaign_ref == record.runtime_state.session.header.campaign_id
                }) {
                    score += 2;
                }
                if context.epoch_ref.as_deref().is_some_and(|epoch_ref| {
                    epoch_ref == record.runtime_state.session.header.epoch_id
                }) {
                    score += 2;
                }
                if context
                    .task_ref
                    .as_deref()
                    .is_some_and(|task_ref| task_ref == record.runtime_state.root_task.task_id)
                {
                    score += 2;
                }
                if context
                    .pointer_index_ref
                    .as_deref()
                    .is_some_and(|pointer_index_ref| {
                        record
                            .runtime_state
                            .memory_store
                            .load_pointer_index(pointer_index_ref)
                            .is_some()
                    })
                {
                    score += 6;
                }
                (score > 0).then(|| (score, record.runtime_state.clone()))
            })
            .max_by(|left, right| left.0.cmp(&right.0))
            .map(|(_, runtime_state)| runtime_state)
    }

    fn authority_decision_for_turn_result(
        &self,
        parsed_result_id: &str,
    ) -> Result<ModelAuthorityDecision, LocalRuntimeError> {
        self.authority_decisions
            .read()
            .unwrap()
            .iter()
            .find(|decision| decision.turn_result_ref == parsed_result_id)
            .cloned()
            .ok_or_else(|| LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: parsed_result_id.to_string(),
                reason: format!(
                    "no authority decision is recorded for parsed turn '{parsed_result_id}'"
                ),
            })
    }

    async fn apply_turn_governance_runtime_grounding(
        &self,
        turn_package: &TurnPackage,
        context: &ToolExecutionContextRecord,
        artifacts: &mut GovernedParsedTurnArtifacts,
    ) -> Result<(), LocalRuntimeError> {
        if artifacts.bundle.checkpoints.is_empty() {
            return Ok(());
        }
        let Some(run_id) = self
            .matching_run_id_for_turn_context(turn_package, context)
            .await
        else {
            return Ok(());
        };

        let checkpoint_id = artifacts.bundle.checkpoints[0].turn_checkpoint_id.clone();
        let pending_approval_refs = artifacts
            .bundle
            .approvals
            .iter()
            .map(|approval| approval.approval_request.approval_request_id.clone())
            .collect::<Vec<_>>();
        let decision_summary = artifacts.bundle.authority_decision.reason_summary.clone();
        let (persisted_record, checkpoint) = {
            let mut runs = self.runs.write().await;
            let Some(record) = runs.get_mut(&run_id) else {
                return Ok(());
            };
            let mut session = record.runtime_state.session.clone();
            let mut task = record.runtime_state.root_task.clone();
            let blocked_reason =
                BlockedReason::new(BlockedReasonKind::Governance, decision_summary);
            match artifacts.bundle.authority_decision.decision {
                ModelAuthorityDecisionKind::ApprovalBlock => {
                    session.state = ExecutionSessionState::AwaitingApproval;
                    session.pending_approval_refs = pending_approval_refs.clone();
                    session.blocked_reason = Some(blocked_reason.clone());
                    task.state = TaskState::BlockedOnApproval;
                    task.blocked_reason = Some(blocked_reason.clone());
                    record.metadata.status = LocalRunStatus::AwaitingApproval;
                }
                ModelAuthorityDecisionKind::Quarantine
                | ModelAuthorityDecisionKind::Deny
                | ModelAuthorityDecisionKind::Fail => {
                    session.state = ExecutionSessionState::Blocked;
                    session.pending_approval_refs.clear();
                    session.blocked_reason = Some(blocked_reason.clone());
                    task.state = TaskState::Paused;
                    task.blocked_reason = Some(blocked_reason.clone());
                    record.metadata.status = LocalRunStatus::Paused;
                }
                ModelAuthorityDecisionKind::Allow => return Ok(()),
            }
            let checkpoint = capture_checkpoint(
                &mut record.runtime_state.memory_store,
                &session,
                &task,
                &checkpoint_id,
                "LLM turn governance checkpoint captured",
            );
            session.latest_checkpoint_ref = Some(checkpoint.checkpoint_id.clone());
            record.runtime_state.session = session;
            record.runtime_state.root_task = task;
            record.runtime_state.latest_checkpoint = Some(checkpoint.clone());
            record.metadata.updated_at = current_timestamp();
            if artifacts.bundle.authority_decision.decision
                == ModelAuthorityDecisionKind::ApprovalBlock
            {
                for approval in &artifacts.bundle.approvals {
                    persist_approval_request_bundle(
                        &mut record.runtime_state.memory_store,
                        &approval.approval_request,
                        &checkpoint,
                    );
                }
            }
            for quarantine in &artifacts.bundle.quarantines {
                append_audit_artifact(
                    &mut record.runtime_state.memory_store,
                    &record.runtime_state.session,
                    Some(&record.runtime_state.root_task.task_id),
                    AuditRecordClass::GovernanceAuditRecord,
                    quarantine.quarantine_record.quarantine_id.clone(),
                    format!(
                        "model quarantine {} constrained parsed turn {}",
                        quarantine.model_quarantine_id, quarantine.affected_turn_result_ref
                    ),
                );
            }
            (record.clone(), checkpoint)
        };
        self.persist_record(&persisted_record)?;
        if let Some(turn_checkpoint) = artifacts.bundle.checkpoints.first_mut() {
            turn_checkpoint.runtime_checkpoint = Some(checkpoint);
        }
        Ok(())
    }

    async fn matching_run_id_for_turn_context(
        &self,
        turn_package: &TurnPackage,
        context: &ToolExecutionContextRecord,
    ) -> Option<String> {
        self.runs
            .read()
            .await
            .iter()
            .filter_map(|(run_id, record)| {
                let mut score = 0usize;
                if record.runtime_state.session.header.session_id == turn_package.session_ref {
                    score += 8;
                }
                if context.campaign_ref.as_deref().is_some_and(|campaign_ref| {
                    campaign_ref == record.runtime_state.session.header.campaign_id
                }) {
                    score += 2;
                }
                if context.epoch_ref.as_deref().is_some_and(|epoch_ref| {
                    epoch_ref == record.runtime_state.session.header.epoch_id
                }) {
                    score += 2;
                }
                if context
                    .task_ref
                    .as_deref()
                    .is_some_and(|task_ref| task_ref == record.runtime_state.root_task.task_id)
                {
                    score += 2;
                }
                if context
                    .pointer_index_ref
                    .as_deref()
                    .is_some_and(|pointer_index_ref| {
                        record
                            .runtime_state
                            .memory_store
                            .load_pointer_index(pointer_index_ref)
                            .is_some()
                    })
                {
                    score += 6;
                }
                (score > 0).then(|| (score, run_id.clone()))
            })
            .max_by(|left, right| left.0.cmp(&right.0))
            .map(|(_, run_id)| run_id)
    }

    async fn resolve_model_approval_action(
        &self,
        model_approval_request_id: &str,
        action: ModelApprovalResolutionAction,
    ) -> Result<TurnGovernanceView, LocalRuntimeError> {
        let store = self.llm_interface_store()?;
        let mut approval = store.load_model_approval_request_record(model_approval_request_id)?;
        if approval.resolution_action.is_some() {
            return Err(LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: model_approval_request_id.to_string(),
                reason: "model approval request has already been resolved".to_string(),
            });
        }
        let parsed_result = store.load_parsed_turn_result(&approval.turn_result_ref)?;
        let turn_package = store.load_turn_package(&parsed_result.turn_package_ref)?;
        let context =
            store.load_tool_execution_context_record(&turn_package.tool_execution_context_ref)?;
        let decision_status = match action {
            ModelApprovalResolutionAction::Grant => ApprovalDecisionStatus::Granted,
            ModelApprovalResolutionAction::Deny => ApprovalDecisionStatus::Denied,
            ModelApprovalResolutionAction::Expire => ApprovalDecisionStatus::Expired,
            ModelApprovalResolutionAction::Escalate => ApprovalDecisionStatus::Superseded,
        };
        let mut pending_action = approval
            .pending_action_ref
            .as_ref()
            .map(|pending_action_ref| {
                store.load_pending_governed_turn_action_record(pending_action_ref)
            })
            .transpose()?;
        let mut latest_receipt_ref = None;
        if let Some(record) = pending_action.as_mut() {
            if record.resolution_status != PendingGovernedTurnActionStatus::PendingApproval {
                return Err(LocalRuntimeError::InvalidTurnPackageOperation {
                    identifier: record.pending_governed_turn_action_id.clone(),
                    reason: "pending governed turn action has already been resolved".to_string(),
                });
            }
            match action {
                ModelApprovalResolutionAction::Grant => {
                    let receipt = self
                        .resume_pending_governed_turn_action(
                            &store,
                            &turn_package,
                            &parsed_result,
                            &context,
                            &approval,
                            record,
                        )
                        .await?;
                    latest_receipt_ref = Some(
                        receipt
                            .receipt
                            .parsed_turn_tool_execution_receipt_id
                            .clone(),
                    );
                    record.resolution_status = PendingGovernedTurnActionStatus::GrantedExecuted;
                    record.execution_receipt_ref = latest_receipt_ref.clone();
                    record.resolved_at = Some(current_timestamp());
                    record.notes.push(format!(
                        "approval {} released the stored tool batch",
                        approval.approval_request.approval_request_id
                    ));
                }
                ModelApprovalResolutionAction::Deny => {
                    record.resolution_status = PendingGovernedTurnActionStatus::Denied;
                    record.resolved_at = Some(current_timestamp());
                    record
                        .notes
                        .push("operator denied the stored governed turn action".to_string());
                }
                ModelApprovalResolutionAction::Expire => {
                    record.resolution_status = PendingGovernedTurnActionStatus::Expired;
                    record.resolved_at = Some(current_timestamp());
                    record
                        .notes
                        .push("approval window expired before execution".to_string());
                }
                ModelApprovalResolutionAction::Escalate => {
                    record.resolution_status = PendingGovernedTurnActionStatus::Escalated;
                    record.resolved_at = Some(current_timestamp());
                    record
                        .notes
                        .push("approval was escalated without resuming stored work".to_string());
                }
            }
            store.persist_pending_governed_turn_action_record(record)?;
            let mut pending_actions = self.pending_governed_turn_actions.write().unwrap();
            upsert_pending_governed_turn_action_record(&mut pending_actions, record.clone());
        }
        let approval_decision = ApprovalDecision {
            approval_request_id: approval.approval_request.approval_request_id.clone(),
            campaign_id: approval.approval_request.campaign_id.clone(),
            epoch_id: approval.approval_request.epoch_id.clone(),
            session_id: approval.approval_request.session_id.clone(),
            task_id: approval.approval_request.task_id.clone(),
            action_ref: approval.approval_request.action_ref.clone(),
            decision: decision_status.clone(),
            decided_by: "operator:llm-interface".to_string(),
            scope_ref: approval.approval_request.scope_ref.clone(),
            notes: Some(format!("resolved through {:?}", action)),
        };
        approval.approval_request.status = decision_status;
        approval.latest_decision = Some(approval_decision.clone());
        approval.resolution_action = Some(action);
        if let Some(receipt_ref) = latest_receipt_ref {
            approval
                .notes
                .push(format!("stored tool batch resumed through {}", receipt_ref));
        } else {
            approval
                .notes
                .push(format!("approval resolved through {:?}", action));
        }
        store.persist_model_approval_request_record(&approval)?;
        {
            let mut approvals = self.model_approval_requests.write().unwrap();
            upsert_model_approval_request_record(&mut approvals, approval.clone());
        }
        self.apply_model_approval_resolution_runtime_grounding(
            &turn_package,
            &context,
            &approval.approval_request,
            &approval_decision,
        )
        .await?;
        self.reconcile_recursive_factory_artifacts_for_turn(&store, &approval.turn_result_ref)
            .await?;
        self.turn_governance_view(&approval.turn_result_ref).await
    }

    async fn resume_pending_governed_turn_action(
        &self,
        store: &DurableArtifactStore,
        turn_package: &TurnPackage,
        parsed_result: &ParsedTurnResult,
        context: &ToolExecutionContextRecord,
        approval: &ModelApprovalRequestRecord,
        pending_action: &PendingGovernedTurnActionRecord,
    ) -> Result<ParsedTurnToolExecutionView, LocalRuntimeError> {
        let intents = pending_action
            .stored_tool_intent_refs
            .iter()
            .map(|record_ref| store.load_parsed_tool_call_intent_record(record_ref))
            .collect::<Result<Vec<_>, _>>()?;
        let tool_catalog_bundle = self.tool_catalog_for_ref(&turn_package.tool_catalog_ref)?;
        let mut executions = Vec::new();
        for intent in &intents {
            let execution = self
                .execute_approved_tool_intent(
                    store,
                    &tool_catalog_bundle,
                    turn_package,
                    parsed_result,
                    context,
                    intent,
                    &approval.approval_request,
                )
                .await?;
            executions.push(execution);
        }
        let receipt = ParsedTurnToolExecutionReceipt {
            parsed_turn_tool_execution_receipt_id: format!(
                "approved-turn-tool-execution-receipt:{}:{}",
                sanitize_id(&parsed_result.parsed_turn_result_id),
                current_timestamp()
            ),
            parsed_turn_result_ref: parsed_result.parsed_turn_result_id.clone(),
            attempted_tool_intent_refs: intents
                .iter()
                .map(|intent| intent.parsed_tool_call_intent_id.clone())
                .collect(),
            tool_execution_refs: executions
                .iter()
                .map(|execution| execution.execution.tool_execution_id.clone())
                .collect(),
            terminal_decision: ToolExecutionDecision::Allowed,
            stopped_after_tool_intent_ref: None,
            created_at: current_timestamp(),
        };
        for execution in &executions {
            store.persist_tool_execution_record(&execution.execution)?;
            if let Some(turn_memory_update) =
                build_verified_turn_memory_update(store, &execution.execution)?
            {
                store.persist_verified_turn_memory_update(&turn_memory_update)?;
            }
        }
        store.persist_parsed_turn_tool_execution_receipt(&receipt)?;
        let mut updated_result = parsed_result.clone();
        updated_result.tool_execution_refs.extend(
            executions
                .iter()
                .map(|execution| execution.execution.tool_execution_id.clone()),
        );
        updated_result
            .tool_execution_receipt_refs
            .push(receipt.parsed_turn_tool_execution_receipt_id.clone());
        store.persist_parsed_turn_result(&updated_result)?;
        {
            let mut parsed_turn_results = self.parsed_turn_results.write().unwrap();
            upsert_parsed_turn_result(&mut parsed_turn_results, updated_result);
        }
        {
            let mut tool_execution_records = self.tool_execution_records.write().unwrap();
            for execution in &executions {
                upsert_tool_execution_record(
                    &mut tool_execution_records,
                    execution.execution.clone(),
                );
            }
        }
        {
            let mut receipts = self.tool_execution_receipts.write().unwrap();
            upsert_parsed_turn_tool_execution_receipt(&mut receipts, receipt.clone());
        }
        load_parsed_turn_tool_execution_view(store, &receipt.parsed_turn_tool_execution_receipt_id)
    }

    async fn execute_approved_tool_intent(
        &self,
        store: &DurableArtifactStore,
        tool_catalog_bundle: &CanonicalToolCatalogBundle,
        turn_package: &TurnPackage,
        parsed_result: &ParsedTurnResult,
        context: &ToolExecutionContextRecord,
        intent: &ParsedToolCallIntentRecord,
        approval_request: &ApprovalRequest,
    ) -> Result<crate::execution::ToolExecutionBundle, LocalRuntimeError> {
        let definition = tool_catalog_bundle
            .definition(&intent.tool_id)
            .cloned()
            .ok_or_else(|| LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: intent.tool_id.clone(),
                reason: "approved resume referenced an undefined tool".to_string(),
            })?;
        let argument_schema = tool_catalog_bundle
            .argument_schema_for(&intent.tool_id)
            .cloned()
            .ok_or_else(|| LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: intent.tool_id.clone(),
                reason: "approved resume referenced a tool without an argument schema".to_string(),
            })?;
        let result_schema = tool_catalog_bundle
            .result_schema_for(&intent.tool_id)
            .cloned()
            .ok_or_else(|| LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: intent.tool_id.clone(),
                reason: "approved resume referenced a tool without a result schema".to_string(),
            })?;
        let exposure_decision = tool_catalog_bundle
            .exposure_for(&intent.tool_id)
            .cloned()
            .ok_or_else(|| LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: intent.tool_id.clone(),
                reason: "approved resume referenced a tool without an exposure decision"
                    .to_string(),
            })?;
        let legality = store.load_tool_call_legality_record(&format!(
            "tool-legality:{}",
            sanitize_id(&intent.parsed_tool_call_intent_id)
        ))?;
        if turn_package.tool_catalog_ref != tool_catalog_bundle.catalog.tool_catalog_id {
            return Err(LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: intent.parsed_tool_call_intent_id.clone(),
                reason: "approved resume catalog does not match the original turn package"
                    .to_string(),
            });
        }
        if legality.decision != ToolExecutionDecision::ApprovalBlocked
            || legality.parsed_tool_call_intent_ref != intent.parsed_tool_call_intent_id
            || legality.parsed_turn_result_ref != parsed_result.parsed_turn_result_id
            || legality.turn_package_ref != turn_package.turn_package_id
            || legality.tool_definition_ref != definition.tool_id
        {
            return Err(LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: intent.parsed_tool_call_intent_id.clone(),
                reason:
                    "approved resume is not bound to the original approval-blocked legality record"
                        .to_string(),
            });
        }
        crate::execution::tool_membrane::validate_json_against_schema(
            "arguments",
            &intent.arguments_json,
            &argument_schema.argument_schema_json,
        )
        .map_err(map_tool_membrane_runtime_error)?;
        let (_, effective_scope) =
            crate::execution::tool_membrane::resolve_effective_scope(&definition, context)
                .map_err(map_tool_membrane_runtime_error)?;
        if approval_request.status != ApprovalDecisionStatus::Requested
            || approval_request.action_ref != definition.tool_id
            || approval_request.scope_ref != effective_scope
        {
            return Err(LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: approval_request.approval_request_id.clone(),
                reason: "approval request is not bound to the resumed tool and effective scope"
                    .to_string(),
            });
        }
        let service_outcome = execute_allowed_tool_service(
            self,
            &definition,
            intent,
            turn_package,
            context,
            Some(approval_request),
        )
        .await
        .map_err(map_tool_membrane_runtime_error)?;
        service_outcome
            .validate()
            .map_err(map_tool_membrane_runtime_error)?;
        if service_outcome.decision != ToolExecutionDecision::Allowed {
            return Err(LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: intent.parsed_tool_call_intent_id.clone(),
                reason: format!(
                    "approved service returned {:?}; an approval grant cannot manufacture an allowed result",
                    service_outcome.decision
                ),
            });
        }
        let result_payload = service_outcome
            .result_payload_json
            .as_ref()
            .ok_or_else(|| LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: intent.parsed_tool_call_intent_id.clone(),
                reason: "approved service did not return a result payload".to_string(),
            })?;
        crate::execution::tool_membrane::validate_json_against_schema(
            "result",
            result_payload,
            &result_schema.result_schema_json,
        )
        .map_err(map_tool_membrane_runtime_error)?;
        let mut governance_refs = service_outcome.governance_refs.clone();
        governance_refs.push(approval_request.approval_request_id.clone());
        let execution = ToolExecutionRecord {
            tool_execution_id: format!(
                "tool-execution-approved:{}:{}",
                sanitize_id(&intent.parsed_tool_call_intent_id),
                current_timestamp()
            ),
            parsed_tool_call_intent_ref: intent.parsed_tool_call_intent_id.clone(),
            parsed_turn_result_ref: parsed_result.parsed_turn_result_id.clone(),
            tool_id: definition.tool_id.clone(),
            decision: ToolExecutionDecision::Allowed,
            legality_ref: legality.tool_legality_id.clone(),
            result_refs: service_outcome.result_refs.clone(),
            governance_refs: unique_strings(governance_refs),
            diagnostics: std::iter::once(format!(
                "executed after explicit approval {}",
                approval_request.approval_request_id
            ))
            .chain(service_outcome.diagnostics.iter().cloned())
            .collect(),
            result_payload_json: service_outcome.result_payload_json.clone(),
            governance_payload_json: service_outcome.governance_payload_json.clone(),
            created_at: current_timestamp(),
        };
        let bundle = crate::execution::ToolExecutionBundle {
            definition,
            argument_schema,
            result_schema,
            exposure_decision,
            legality,
            execution,
        };
        bundle.validate().map_err(map_tool_membrane_runtime_error)?;
        Ok(bundle)
    }

    async fn apply_model_approval_resolution_runtime_grounding(
        &self,
        turn_package: &TurnPackage,
        context: &ToolExecutionContextRecord,
        approval_request: &ApprovalRequest,
        approval_decision: &ApprovalDecision,
    ) -> Result<(), LocalRuntimeError> {
        let Some(run_id) = self
            .matching_run_id_for_turn_context(turn_package, context)
            .await
        else {
            return Ok(());
        };
        let persisted_record = {
            let mut runs = self.runs.write().await;
            let Some(record) = runs.get_mut(&run_id) else {
                return Ok(());
            };
            record
                .runtime_state
                .session
                .pending_approval_refs
                .retain(|candidate| candidate != &approval_request.approval_request_id);
            persist_approval_decision_bundle(
                &mut record.runtime_state.memory_store,
                approval_decision,
                &[AuditRecord::new(
                    format!(
                        "audit-llm-approval-resolution-{}",
                        approval_request.approval_request_id
                    ),
                    AuditRecordClass::GovernanceAuditRecord,
                    approval_request.campaign_id.clone(),
                    approval_request.epoch_id.clone(),
                    approval_request.session_id.clone(),
                    Some(approval_request.task_id.clone()),
                    approval_request.approval_request_id.clone(),
                    format!(
                        "LLM turn approval {} resolved as {:?}",
                        approval_request.approval_request_id, approval_decision.decision
                    ),
                )],
            );
            if record
                .runtime_state
                .session
                .pending_approval_refs
                .is_empty()
            {
                record.runtime_state.session.blocked_reason = None;
                record.runtime_state.root_task.blocked_reason = None;
                record.runtime_state.session.state = ExecutionSessionState::Ready;
                record.runtime_state.root_task.state = TaskState::Ready;
                record.metadata.status = LocalRunStatus::Paused;
            } else {
                let blocked_reason = BlockedReason::new(
                    BlockedReasonKind::Governance,
                    "additional approval boundaries remain pending",
                );
                record.runtime_state.session.state = ExecutionSessionState::AwaitingApproval;
                record.runtime_state.session.blocked_reason = Some(blocked_reason.clone());
                record.runtime_state.root_task.state = TaskState::BlockedOnApproval;
                record.runtime_state.root_task.blocked_reason = Some(blocked_reason);
                record.metadata.status = LocalRunStatus::AwaitingApproval;
            }
            record.metadata.updated_at = current_timestamp();
            record.clone()
        };
        self.persist_record(&persisted_record)?;
        Ok(())
    }

    async fn factory_program_lineage_receipt_refs(
        &self,
        factory_program_instance_ref: &str,
    ) -> Result<Vec<String>, LocalRuntimeError> {
        let Some(instance) = self
            .factory_program_instances
            .read()
            .unwrap()
            .iter()
            .find(|instance| instance.instance_id == factory_program_instance_ref)
            .cloned()
        else {
            return Ok(Vec::new());
        };
        let Some(spec) = self
            .factory_program_specs
            .read()
            .unwrap()
            .iter()
            .find(|spec| spec.spec_id == instance.spec_id)
            .cloned()
        else {
            return Ok(Vec::new());
        };
        let receipts = self
            .factory_program_tick_receipts
            .read()
            .unwrap()
            .iter()
            .filter(|receipt| receipt.instance_id == instance.instance_id)
            .cloned()
            .collect::<Vec<_>>();
        if receipts.is_empty() {
            return Ok(Vec::new());
        }
        let program_view = self
            .build_recursive_factory_program_view(&spec, &instance, &receipts)
            .await?;
        let mut refs = program_view
            .receipts
            .iter()
            .map(|receipt| receipt.tick_id.clone())
            .collect::<Vec<_>>();
        if let Some(lineage_ledger) = &program_view.lineage_ledger {
            refs.push(lineage_ledger.lineage_ledger_id.clone());
        }
        if let Some(regression_packet) = &program_view.regression_packet {
            refs.push(regression_packet.regression_packet_id.clone());
        }
        if let Some(longitudinal_lineage_dossier) = &program_view.longitudinal_lineage_dossier {
            refs.push(longitudinal_lineage_dossier.lineage_dossier_id.clone());
        }
        for cycle in &program_view.model_factory_cycles {
            refs.push(cycle.cycle.model_factory_cycle_id.clone());
        }
        if let Some(lineage) = &program_view.recursive_lineage_execution {
            refs.push(lineage.lineage.recursive_lineage_execution_id.clone());
        }
        if let Some(statement) = &program_view.architectural_dependency_statement {
            refs.push(
                statement
                    .statement
                    .architectural_dependency_statement_id
                    .clone(),
            );
        }
        if let Some(dossier) = &program_view.recursion_closure_dossier {
            refs.push(dossier.dossier.recursion_closure_dossier_id.clone());
        }
        Ok(unique_strings(refs))
    }

