    pub async fn tool_execution_ledger(
        &self,
    ) -> Result<ToolExecutionLedgerView, LocalRuntimeError> {
        let store = self.llm_interface_store()?;
        let mut tool_execution_records = self.tool_execution_records.read().unwrap().clone();
        tool_execution_records.sort_by(|left, right| {
            run_timestamp(&right.created_at)
                .cmp(&run_timestamp(&left.created_at))
                .then_with(|| left.tool_execution_id.cmp(&right.tool_execution_id))
        });
        let tool_executions = tool_execution_records
            .iter()
            .map(|record| load_tool_execution_view(&store, &record.tool_execution_id))
            .collect::<Result<Vec<_>, _>>()?;
        let summary = if tool_executions.is_empty() {
            "No tool executions are recorded in the Wasm-Biotic runtime ledger.".to_string()
        } else {
            format!(
                "{} tool execution(s) are recorded in the Wasm-Biotic runtime ledger.",
                tool_executions.len()
            )
        };
        Ok(ToolExecutionLedgerView {
            summary,
            tool_executions,
        })
    }

