    async fn execute_tool_service_shim(
        &self,
        definition: &ModelToolDefinition,
        legality: &ToolCallLegalityRecord,
        intent: &ParsedToolCallIntentRecord,
        turn_package: &TurnPackage,
        context: &ToolExecutionContextRecord,
    ) -> Result<crate::execution::ToolServiceExecutionOutcome, ToolMembraneError> {
        if legality.decision != ToolExecutionDecision::Allowed {
            return Ok(build_non_allowed_tool_outcome(
                legality,
                turn_package,
                context,
                definition,
            )?);
        }
        execute_allowed_tool_service(self, definition, intent, turn_package, context, None).await
    }

    async fn execute_program_inspect_tool(
        &self,
        definition: &ModelToolDefinition,
        context: &ToolExecutionContextRecord,
    ) -> Result<crate::execution::ToolServiceExecutionOutcome, ToolMembraneError> {
        let instance_id = context.factory_program_instance_ref.clone().ok_or(
            ToolMembraneError::MissingExecutionContextField {
                field: crate::execution::ToolContextField::FactoryProgramInstanceRef,
            },
        )?;
        let view = self
            .factory_program_view(&instance_id)
            .await
            .map_err(|error| ToolMembraneError::ServiceFailure {
                tool_id: definition.tool_id.clone(),
                reason: error.to_string(),
            })?;
        let payload = serde_json::json!({
            "program_ref": instance_id,
            "summary": view.summary,
            "result_ref": view.instance.instance_id,
        });
        Ok(successful_tool_outcome(
            payload
                .get("result_ref")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("factory-program"),
            payload.to_string(),
            Vec::new(),
        ))
    }

    async fn execute_program_lineage_health_tool(
        &self,
        definition: &ModelToolDefinition,
        context: &ToolExecutionContextRecord,
    ) -> Result<crate::execution::ToolServiceExecutionOutcome, ToolMembraneError> {
        let instance_id = context.factory_program_instance_ref.clone().ok_or(
            ToolMembraneError::MissingExecutionContextField {
                field: crate::execution::ToolContextField::FactoryProgramInstanceRef,
            },
        )?;
        let view = self
            .factory_program_view(&instance_id)
            .await
            .map_err(|error| ToolMembraneError::ServiceFailure {
                tool_id: definition.tool_id.clone(),
                reason: error.to_string(),
            })?;
        let payload = serde_json::json!({
            "program_ref": instance_id,
            "summary": view.summary,
            "result_ref": format!("lineage-health:{}", sanitize_id(&view.instance.instance_id)),
        });
        Ok(successful_tool_outcome(
            payload
                .get("result_ref")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("lineage-health"),
            payload.to_string(),
            Vec::new(),
        ))
    }

    async fn execute_program_submit_cycle_decision_tool(
        &self,
        definition: &ModelToolDefinition,
        arguments: &serde_json::Value,
        context: &ToolExecutionContextRecord,
    ) -> Result<crate::execution::ToolServiceExecutionOutcome, ToolMembraneError> {
        let instance_id = context.factory_program_instance_ref.clone().ok_or(
            ToolMembraneError::MissingExecutionContextField {
                field: crate::execution::ToolContextField::FactoryProgramInstanceRef,
            },
        )?;
        let tick = crate::execution::FactoryProgramTickRequest {
            candidate_factory_ref: required_argument_string(arguments, "candidate_factory_ref")?,
            proving_refs: required_argument_string_array(arguments, "proving_refs")?,
            observation_refs: required_argument_string_array(arguments, "observation_refs")?,
            comparison_refs: required_argument_string_array(arguments, "comparison_refs")?,
            risk_refs: required_argument_string_array(arguments, "risk_refs")?,
            trend_refs: required_argument_string_array(arguments, "trend_refs")?,
            rollback_refs: required_argument_string_array(arguments, "rollback_refs")?,
            adoption_result: adoption_window_result_from_args(arguments, "decision")?,
            operator_note: Some(required_argument_string(arguments, "operator_note")?),
        };
        let receipt = self
            .tick_factory_program(&instance_id, tick)
            .await
            .map_err(|error| ToolMembraneError::ServiceFailure {
                tool_id: definition.tool_id.clone(),
                reason: error.to_string(),
            })?;
        let payload = serde_json::json!({
            "tick_id": receipt.tick_id,
            "instance_id": receipt.instance_id,
            "resulting_factory_ref": receipt.resulting_factory_ref,
        });
        Ok(successful_tool_outcome(
            payload
                .get("tick_id")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("tick"),
            payload.to_string(),
            Vec::new(),
        ))
    }

    pub async fn list_runs(&self) -> Result<Vec<RunSummary>, LocalRuntimeError> {
        let runs = self.runs.read().await;
        let mut summaries = Vec::with_capacity(runs.len());
        for record in runs.values() {
            summaries.push(record.view_model(&self.workspace)?.summary);
        }
        summaries.sort_by(|left, right| {
            run_timestamp(&right.updated_at)
                .cmp(&run_timestamp(&left.updated_at))
                .then_with(|| left.run_id.cmp(&right.run_id))
        });
        Ok(summaries)
    }

