    pub async fn general_audience_home(
        &self,
    ) -> Result<GeneralAudienceHomeView, LocalRuntimeError> {
        let run_views = self.collect_run_views().await?;
        let sorted_runs = sorted_run_views(&run_views);
        let overview = build_system_overview(&run_views);
        let history = build_run_history_view(&run_views);
        let portfolio = build_factory_portfolio_view(&run_views);

        let runbook = self.operator_runbook.read().unwrap().clone();
        let factory_01_programs = self.factory_01_program_views().await?;
        let mut planning = build_planning_guidance_view(&run_views, &runbook);
        annotate_planning_guidance_with_factory_01(&mut planning, &factory_01_programs);

        let programs = self.factory_program_ledger().await?;
        let transition = self.v2_transition_workspace().await?;
        let convergence_transition = self.v2_convergence_transition_workspace().await?;
        let world_taxonomy = self.v2_world_taxonomy().await?;
        let service_handles = self.v2_service_contract_handles().await?;
        let service_attestation = self.v2_service_attestation().await?;
        let memory_closure = self.v2_memory_review_lineage_closure().await?;
        let topology = self.v2_coordination_topology_map().await?;
        let scheduler = self.v2_scheduler_queue_contracts().await?;
        let governance = self.v2_governance_release_gate().await?;
        let reviewable_generation = self
            .v2_operator_reviewable_native_service_generation()
            .await?;
        let challenger_comparison = self.v2_challenger_incumbent_generation_comparison().await?;
        let pressure = self.v2_capability_pressure_approval_load().await?;
        let recovery = self.v2_recovery_intervention_shared_resources().await?;
        let phase01 = self.remediation_phase_01_lifecycle_closure().await?;
        let phase02 = self.remediation_phase_02_service_ecology_closure().await?;
        let phase03 = self
            .remediation_phase_03_reproduction_ecosystem_closure()
            .await?;
        let phase04 = match self.remediation_phase_04_final_closure_rereview().await {
            Ok(phase04) => Some(phase04),
            Err(LocalRuntimeError::HistoricalPhase04TruthUnavailable { .. }) => None,
            Err(error) => return Err(error),
        };

        let active_run_ids = sorted_runs
            .iter()
            .filter(|view| is_active_status(&view.summary.status))
            .map(|view| view.summary.run_id.clone())
            .collect::<Vec<_>>();
        let factory_views = self.general_audience_factory_views(&active_run_ids).await?;
        let agent_views = self.general_audience_agent_views(&active_run_ids).await?;

        Ok(GeneralAudienceHomeView {
            introduction_paragraphs: general_audience_intro_paragraphs(),
            operational_north_star_decision: overview.operational_north_star_decision,
            status_authority_ref: overview.status_authority_ref.clone(),
            status_basis: overview.status_basis.clone(),
            operator_truth_surfaces: overview.operator_truth_surfaces.clone(),
            current_snapshot: build_general_audience_current_snapshot(&sorted_runs, &overview),
            active_capability_groups: build_general_audience_capability_groups(
                &overview.progress_tracker,
                &transition,
                &convergence_transition,
                &world_taxonomy,
                &service_handles,
                &service_attestation,
                &memory_closure,
                &topology,
                &scheduler,
                &governance,
                &reviewable_generation,
                &challenger_comparison,
                &pressure,
                &recovery,
                &phase01,
                &phase02,
                &phase03,
            ),
            in_flight_capabilities: build_general_audience_in_flight_capabilities(
                &sorted_runs,
                &planning,
                &programs,
                &factory_views,
                &agent_views,
            ),
            historical_timeline: build_general_audience_historical_timeline(
                &history,
                &portfolio,
                &overview.progress_tracker,
                &phase01,
                &phase02,
                &phase03,
                phase04.as_ref(),
            ),
            future_roadmap: build_general_audience_future_roadmap(
                &overview.progress_tracker,
                &planning,
                &transition,
                &convergence_transition,
                &phase01,
                &phase02,
                &phase03,
                phase04.as_ref(),
            ),
            recommended_actions: build_general_audience_recommended_actions(),
            advanced_actions: build_general_audience_advanced_actions(&sorted_runs, &programs),
        })
    }

