    async fn factory_01_program_views(&self) -> Result<Vec<FactoryProgramView>, LocalRuntimeError> {
        let Some(spec) = self
            .factory_program_specs
            .read()
            .unwrap()
            .iter()
            .find(|spec| spec.spec_id == FACTORY_01_SPEC_ID)
            .cloned()
        else {
            return Ok(Vec::new());
        };

        let mut instances = self
            .factory_program_instances
            .read()
            .unwrap()
            .iter()
            .filter(|instance| instance.spec_id == FACTORY_01_SPEC_ID)
            .cloned()
            .collect::<Vec<_>>();
        instances.sort_by(|left, right| {
            run_timestamp(&right.updated_at)
                .cmp(&run_timestamp(&left.updated_at))
                .then_with(|| left.instance_id.cmp(&right.instance_id))
        });

        let all_receipts = self.factory_program_tick_receipts.read().unwrap().clone();
        let mut programs = Vec::with_capacity(instances.len());
        for instance in instances {
            let receipts = all_receipts
                .iter()
                .filter(|receipt| receipt.instance_id == instance.instance_id)
                .cloned()
                .collect::<Vec<_>>();
            programs.push(
                self.build_recursive_factory_program_view(&spec, &instance, &receipts)
                    .await?,
            );
        }
        Ok(programs)
    }

