    pub async fn export_phase_b_factory_review_packet(
        &self,
        request: PhaseBFactoryReviewPacketExportRequest,
    ) -> Result<PhaseBFactoryReviewPacket, LocalRuntimeError> {
        let records = self.collect_run_records().await?;
        let packet =
            build_phase_b_factory_review_packet(&self.workspace, &records, &request, false)?;
        {
            let mut packets = self.phase_b_factory_review_packets.write().unwrap();
            packets.push(packet.clone());
            packets.sort_by(|left, right| {
                run_timestamp(&right.created_at)
                    .cmp(&run_timestamp(&left.created_at))
                    .then_with(|| left.packet_id.cmp(&right.packet_id))
            });
            self.persist_phase_b_factory_review_packets(&packets)?;
        }
        Ok(packet)
    }

