    pub async fn export_run(&self, run_id: &str) -> Result<PathBuf, LocalRuntimeError> {
        let runs = self.runs.read().await;
        let record = runs
            .get(run_id)
            .ok_or_else(|| LocalRuntimeError::RunNotFound {
                run_id: run_id.to_string(),
            })?;
        self.persist_record(record)?;
        let export_root = self.workspace.export_root(run_id);
        if export_root.exists() {
            fs::remove_dir_all(&export_root)?;
        }
        copy_dir_all(&self.workspace.bundle_root(run_id), &export_root)?;
        let summary = record.view_model(&self.workspace)?.summary;
        drop(runs);
        self.append_runbook_entry(build_runbook_entry(
            RunbookEntryKind::BundleExported,
            Some(summary.run_id.clone()),
            "Bundle exported",
            &format!(
                "A durable local bundle export was written for `{}`.",
                summary.title
            ),
            vec![summary.run_id, summary.campaign_id, summary.epoch_id],
            vec!["Use the exported bundle for offline review or durable archival.".to_string()],
        ))?;
        Ok(export_root)
    }

    async fn update_run<F>(
        &self,
        run_id: &str,
        mutate: F,
    ) -> Result<RunViewModel, LocalRuntimeError>
    where
        F: FnOnce(&mut LocalRunRecord) -> Result<(), LocalRuntimeError>,
    {
        let view = {
            let mut runs = self.runs.write().await;
            let record = runs
                .get_mut(run_id)
                .ok_or_else(|| LocalRuntimeError::RunNotFound {
                    run_id: run_id.to_string(),
                })?;
            mutate(record)?;
            self.persist_record(record)?;
            record.view_model(&self.workspace)?
        };
        let _ = self.updates.send(RunUpdate {
            run_id: run_id.to_string(),
            status: view.summary.status.clone(),
            summary: view.summary.clone(),
        });
        Ok(view)
    }

    fn persist_record(&self, record: &LocalRunRecord) -> Result<(), LocalRuntimeError> {
        let run_root = self.workspace.run_root(&record.metadata.run_id);
        fs::create_dir_all(&run_root)?;
        let store =
            DurableArtifactStore::bootstrap(self.workspace.store_root(&record.metadata.run_id))?;
        store.persist_runtime_state(&record.runtime_state)?;
        write_json(
            self.workspace.metadata_path(&record.metadata.run_id),
            &record.metadata,
        )?;
        let operator_runbook = self.operator_runbook.read().unwrap().clone();
        let operator_context_packages = self.operator_context_packages.read().unwrap().clone();
        let operator_review_packets = self.operator_review_packets.read().unwrap().clone();
        let v2_transition_packets = self.v2_transition_packets.read().unwrap().clone();
        let v2_next_line_handoff_packets =
            self.v2_next_line_handoff_packets.read().unwrap().clone();
        let v3_generation_artifacts = self.v3_generation_artifacts.read().unwrap().clone();
        let v3_self_production_evidence_packets = self
            .v3_self_production_evidence_packets
            .read()
            .unwrap()
            .clone();
        write_bundle(
            &self.workspace,
            record,
            &operator_runbook,
            &operator_context_packages,
            &operator_review_packets,
            &v2_transition_packets,
            &v2_next_line_handoff_packets,
            &v3_generation_artifacts,
            &v3_self_production_evidence_packets,
        )?;
        Ok(())
    }

    async fn collect_run_views(&self) -> Result<Vec<RunViewModel>, LocalRuntimeError> {
        let runs = self.runs.read().await;
        let mut run_views = Vec::with_capacity(runs.len());
        for record in runs.values() {
            run_views.push(record.view_model(&self.workspace)?);
        }
        Ok(run_views)
    }

    async fn collect_run_records(&self) -> Result<Vec<LocalRunRecord>, LocalRuntimeError> {
        let runs = self.runs.read().await;
        Ok(runs.values().cloned().collect())
    }

    fn append_runbook_entry(&self, entry: OperatorRunbookEntry) -> Result<(), LocalRuntimeError> {
        let mut runbook = self.operator_runbook.write().unwrap();
        runbook.push(entry);
        runbook.sort_by(|left, right| {
            run_timestamp(&right.created_at)
                .cmp(&run_timestamp(&left.created_at))
                .then_with(|| left.entry_id.cmp(&right.entry_id))
        });
        write_json(self.workspace.operator_runbook_path(), &*runbook)?;
        Ok(())
    }

