    pub async fn export_operator_context_package(
        &self,
        request: OperatorContextPackageExportRequest,
    ) -> Result<OperatorContextPackage, LocalRuntimeError> {
        let run_views = self.collect_run_views().await?;
        let runbook = self.operator_runbook.read().unwrap().clone();
        let selected_run = request
            .run_id
            .as_ref()
            .and_then(|run_id| run_views.iter().find(|view| view.summary.run_id == *run_id))
            .or_else(|| run_views.first());
        let package = build_operator_context_package(selected_run, &runbook, &request, false);
        {
            let mut packages = self.operator_context_packages.write().unwrap();
            packages.push(package.clone());
            packages.sort_by(|left, right| {
                run_timestamp(&right.created_at)
                    .cmp(&run_timestamp(&left.created_at))
                    .then_with(|| left.package_id.cmp(&right.package_id))
            });
            self.persist_operator_context_packages(&packages)?;
        }
        Ok(package)
    }

    pub async fn import_operator_context_package(
        &self,
        mut package: OperatorContextPackage,
    ) -> Result<OperatorContextPackage, LocalRuntimeError> {
        package.imported = true;
        if package.package_id.trim().is_empty() {
            package.package_id = format!("context-package:imported:{}", current_timestamp());
        }
        {
            let mut packages = self.operator_context_packages.write().unwrap();
            packages.retain(|existing| existing.package_id != package.package_id);
            packages.push(package.clone());
            packages.sort_by(|left, right| {
                run_timestamp(&right.created_at)
                    .cmp(&run_timestamp(&left.created_at))
                    .then_with(|| left.package_id.cmp(&right.package_id))
            });
            self.persist_operator_context_packages(&packages)?;
        }
        Ok(package)
    }

