pub async fn serve_local_console(
    service: Arc<LocalRuntimeService>,
    address: SocketAddr,
) -> Result<(), LocalRuntimeError> {
    let listener = tokio::net::TcpListener::bind(address)
        .await
        .map_err(|error| LocalRuntimeError::Io(error.to_string()))?;
    service.start_m2_supervisor()?;
    let server_result = axum::serve(listener, build_router(Arc::clone(&service)))
        .with_graceful_shutdown(async {
            let _ = tokio::signal::ctrl_c().await;
        })
        .await
        .map_err(|error| LocalRuntimeError::Io(error.to_string()));
    let supervisor_result = service.stop_m2_supervisor();
    server_result?;
    supervisor_result
}

pub fn default_console_address(port: u16) -> SocketAddr {
    SocketAddr::from(([127, 0, 0, 1], port))
}

