#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum M2ApprovalResolutionDecision {
    Grant,
    Deny,
    Expire,
    Escalate,
}

impl From<M2ApprovalResolutionDecision> for M2ApprovalResolutionKind {
    fn from(value: M2ApprovalResolutionDecision) -> Self {
        match value {
            M2ApprovalResolutionDecision::Grant => Self::Granted,
            M2ApprovalResolutionDecision::Deny => Self::Denied,
            M2ApprovalResolutionDecision::Expire => Self::Expired,
            M2ApprovalResolutionDecision::Escalate => Self::Escalated,
        }
    }
}

