async fn run_m4_reference_workflow_handler(
    State(service): State<Arc<LocalRuntimeService>>,
    request: Result<Json<M4ReferenceWorkflowRunRequest>, JsonRejection>,
) -> Result<Json<M4ReferenceWorkflowEvidence>, ApiError> {
    let request = parse_m4_json_request(request)?;
    Ok(Json(
        service
            .run_m4_reference_workflow(&request.request)
            .map_err(ApiError::from)?,
    ))
}

fn parse_m4_json_request<T>(request: Result<Json<T>, JsonRejection>) -> Result<T, ApiError> {
    request
        .map(|Json(request)| request)
        .map_err(|rejection| ApiError {
            status: StatusCode::BAD_REQUEST,
            message: format!("invalid M4 request JSON: {rejection}"),
        })
}

fn validate_m4_mutation_request(body: &Bytes) -> Result<(), ApiError> {
    if body.iter().all(|byte| byte.is_ascii_whitespace()) {
        return Ok(());
    }
    serde_json::from_slice::<M4MutationRequest>(body)
        .map(|_| ())
        .map_err(|error| ApiError {
            status: StatusCode::BAD_REQUEST,
            message: format!("invalid M4 mutation request: {error}"),
        })
}

