async fn start_run(
    State(service): State<Arc<LocalRuntimeService>>,
    Json(request): Json<StartRunRequest>,
) -> Result<Json<RunViewModel>, ApiError> {
    let profile = ScenarioLaunchProfile {
        template_id: request.template_id,
        pack_id: request.pack_id,
        composition_id: request.composition_id,
        run_set_id: request.run_set_id,
        hypothesis_id: request.hypothesis_id,
        review_packet_id: request.review_packet_id,
        regression_pack_id: request.regression_pack_id,
        operator_goal: request.operator_goal,
    };
    let run = if profile == ScenarioLaunchProfile::default() {
        service.start_run(&request.scenario_id).await
    } else {
        service
            .start_run_with_profile(&request.scenario_id, profile)
            .await
    };
    Ok(Json(run.map_err(ApiError::from)?))
}

