async fn stream_run_updates(
    State(service): State<Arc<LocalRuntimeService>>,
    AxumPath(run_id): AxumPath<String>,
) -> Result<Sse<impl tokio_stream::Stream<Item = Result<SseEvent, Infallible>>>, ApiError> {
    let initial = service.run_view(&run_id).await.map_err(ApiError::from)?;
    let initial_event = SseEvent::default()
        .event("update")
        .data(serde_json::to_string(&RunUpdate {
            run_id: initial.summary.run_id.clone(),
            status: initial.summary.status.clone(),
            summary: initial.summary.clone(),
        })?);
    let receiver = service.subscribe();
    let initial_stream = tokio_stream::iter(vec![Ok(initial_event)]);
    let update_stream = BroadcastStream::new(receiver).filter_map(move |message| match message {
        Ok(update) if update.run_id == run_id => serde_json::to_string(&update)
            .ok()
            .map(|json| Ok(SseEvent::default().event("update").data(json))),
        _ => None,
    });
    Ok(Sse::new(initial_stream.chain(update_stream)).keep_alive(KeepAlive::default()))
}

#[derive(Debug)]
struct ApiError {
    status: StatusCode,
    message: String,
}

impl From<LocalRuntimeError> for ApiError {
    fn from(value: LocalRuntimeError) -> Self {
        let status = match &value {
            LocalRuntimeError::UnknownScenario { .. } => StatusCode::NOT_FOUND,
            LocalRuntimeError::RunNotFound { .. } => StatusCode::NOT_FOUND,
            LocalRuntimeError::ProgramNotFound { .. } => StatusCode::NOT_FOUND,
            LocalRuntimeError::InferenceProviderNotFound { .. } => StatusCode::NOT_FOUND,
            LocalRuntimeError::InferenceTurnNotFound { .. } => StatusCode::NOT_FOUND,
            LocalRuntimeError::TurnPackageNotFound { .. } => StatusCode::NOT_FOUND,
            LocalRuntimeError::ParsedTurnResultNotFound { .. } => StatusCode::NOT_FOUND,
            LocalRuntimeError::ToolExecutionNotFound { .. } => StatusCode::NOT_FOUND,
            LocalRuntimeError::InvalidOperation { .. } => StatusCode::BAD_REQUEST,
            LocalRuntimeError::InvalidProgramOperation { .. } => StatusCode::BAD_REQUEST,
            LocalRuntimeError::InvalidInferenceOperation { .. } => StatusCode::BAD_REQUEST,
            LocalRuntimeError::InvalidTurnPackageOperation { .. } => StatusCode::BAD_REQUEST,
            LocalRuntimeError::InferenceExecutionFailed { .. } => StatusCode::INTERNAL_SERVER_ERROR,
            LocalRuntimeError::WorkspaceConflict { .. } => StatusCode::CONFLICT,
            LocalRuntimeError::M4Runtime { class, .. } => match class {
                M4RuntimeFailureClass::InvalidRequest => StatusCode::BAD_REQUEST,
                M4RuntimeFailureClass::CapabilityDenied => StatusCode::FORBIDDEN,
                M4RuntimeFailureClass::NotFound => StatusCode::NOT_FOUND,
                M4RuntimeFailureClass::Conflict => StatusCode::CONFLICT,
                M4RuntimeFailureClass::Unprocessable => StatusCode::UNPROCESSABLE_ENTITY,
                M4RuntimeFailureClass::Unavailable => StatusCode::SERVICE_UNAVAILABLE,
                M4RuntimeFailureClass::Integrity => StatusCode::INTERNAL_SERVER_ERROR,
            },
            _ => StatusCode::INTERNAL_SERVER_ERROR,
        };
        Self {
            status,
            message: value.to_string(),
        }
    }
}

impl From<serde_json::Error> for ApiError {
    fn from(value: serde_json::Error) -> Self {
        Self {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            message: value.to_string(),
        }
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> axum::response::Response {
        (
            self.status,
            [(header::CONTENT_TYPE, "text/plain; charset=utf-8")],
            self.message,
        )
            .into_response()
    }
}

fn acquire_local_runtime_owner_lock(
    workspace: &LocalRuntimeWorkspace,
) -> Result<File, LocalRuntimeError> {
    let root_metadata = fs::symlink_metadata(workspace.root())?;
    if root_metadata.file_type().is_symlink() || !root_metadata.is_dir() {
        return Err(LocalRuntimeError::Storage(format!(
            "local runtime workspace root '{}' must be a real directory",
            workspace.root().display()
        )));
    }
    let root = fs::canonicalize(workspace.root())?;
    let path = root.join(LOCAL_RUNTIME_OWNER_LOCK_FILE);
    match fs::symlink_metadata(&path) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => {
            return Err(LocalRuntimeError::Storage(format!(
                "local runtime owner lock '{}' must be a regular file",
                path.display()
            )));
        }
        Ok(_) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error.into()),
    }
    let file = OpenOptions::new()
        .create(true)
        .truncate(false)
        .read(true)
        .write(true)
        .open(&path)?;
    file.try_lock().map_err(|source| match source {
        std::fs::TryLockError::WouldBlock => LocalRuntimeError::WorkspaceConflict { root },
        std::fs::TryLockError::Error(source) => LocalRuntimeError::Io(source.to_string()),
    })?;
    Ok(file)
}

fn initialize_m1_reference_template(
    workspace: &LocalRuntimeWorkspace,
) -> Result<(), LocalRuntimeError> {
    let reference_root = workspace.m1_reference_root();
    let template_root = workspace.m1_reference_template_root();
    ensure_service_owned_directory(&reference_root, "M1 reference root")?;
    ensure_service_owned_directory(&template_root, "M1 reference template")?;
    ensure_frozen_m1_template_file(
        &template_root.join("component.wit"),
        M1_REFERENCE_COMPONENT_WIT,
    )?;
    ensure_frozen_m1_template_file(
        &template_root.join("component.wat"),
        M1_REFERENCE_COMPONENT_WAT,
    )?;
    Ok(())
}

fn ensure_service_owned_directory(path: &Path, label: &str) -> Result<(), LocalRuntimeError> {
    match fs::symlink_metadata(path) {
        Ok(metadata) if metadata.file_type().is_symlink() => {
            Err(LocalRuntimeError::InvalidInferenceOperation {
                identifier: path.display().to_string(),
                reason: format!("{label} must not be a symbolic link"),
            })
        }
        Ok(metadata) if !metadata.is_dir() => Err(LocalRuntimeError::InvalidInferenceOperation {
            identifier: path.display().to_string(),
            reason: format!("{label} must be a directory"),
        }),
        Ok(_) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            fs::create_dir(path)?;
            Ok(())
        }
        Err(error) => Err(error.into()),
    }
}

fn ensure_frozen_m1_template_file(
    path: &Path,
    expected_bytes: &[u8],
) -> Result<(), LocalRuntimeError> {
    match fs::symlink_metadata(path) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => {
            return Err(LocalRuntimeError::InvalidInferenceOperation {
                identifier: path.display().to_string(),
                reason: "frozen M1 template entry must be a regular file".to_string(),
            });
        }
        Ok(_) => {
            let actual = fs::read(path)?;
            if actual != expected_bytes {
                return Err(LocalRuntimeError::InvalidInferenceOperation {
                    identifier: path.display().to_string(),
                    reason: "frozen M1 template bytes differ from the tracked reference fixture"
                        .to_string(),
                });
            }
            return Ok(());
        }
        Err(error) if error.kind() != std::io::ErrorKind::NotFound => return Err(error.into()),
        Err(_) => {}
    }

    let temporary_path = path.with_extension(format!(
        "m1-template-tmp-{}-{}",
        std::process::id(),
        current_timestamp()
            .chars()
            .filter(|character| character.is_ascii_alphanumeric())
            .collect::<String>()
    ));
    let mut temporary = fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&temporary_path)?;
    temporary.write_all(expected_bytes)?;
    temporary.sync_all()?;
    fs::rename(&temporary_path, path)?;
    Ok(())
}

fn load_existing_runs(
    workspace: &LocalRuntimeWorkspace,
) -> Result<BTreeMap<String, LocalRunRecord>, LocalRuntimeError> {
    let mut runs = BTreeMap::new();
    if !workspace.runs_root().exists() {
        return Ok(runs);
    }
    for entry in fs::read_dir(workspace.runs_root())? {
        let entry = entry?;
        if !entry.file_type()?.is_dir() {
            continue;
        }
        let run_id = entry.file_name().to_string_lossy().to_string();
        let metadata_path = workspace.metadata_path(&run_id);
        let store_root = workspace.store_root(&run_id);
        if !metadata_path.exists() || !store_root.exists() {
            continue;
        }
        let metadata: LocalRunMetadata = read_json(metadata_path)?;
        let store = DurableArtifactStore::bootstrap(store_root)?;
        let runtime_state = store.load_runtime_state()?;
        runs.insert(
            metadata.run_id.clone(),
            LocalRunRecord {
                metadata,
                runtime_state,
            },
        );
    }
    Ok(runs)
}

fn build_scenario_seed(scenario_id: &str, run_id: &str) -> Result<ScenarioSeed, LocalRuntimeError> {
    if scenario_definition(scenario_id).is_none() {
        return Err(LocalRuntimeError::UnknownScenario {
            scenario_id: scenario_id.to_string(),
        });
    }

    match scenario_id {
        "supervisor-approval-resume-worker-complete" => approval_resume_seed(run_id),
        "supervisor-background-quarantine-rollback-control-loop" => {
            background_quarantine_seed(run_id)
        }
        "supervisor-promote-activate-successor-campaign" => completed_program_seed(
            run_id,
            scenario_id,
            "Promoted successor campaign activated under governed review",
            "promotion-act",
            "successor campaign activated under bounded governance",
            vec!["successor-campaign-output".to_string()],
        ),
        "supervisor-second-cycle-v1-completion" => completed_program_seed(
            run_id,
            scenario_id,
            "Second cycle satisfied the bounded v1 completion gate",
            "v1-completion-gate",
            "bounded v1 completion evidence remained replayable",
            vec!["v1-completion-output".to_string()],
        ),
        "supervisor-durable-fixed-interface-self-hosting-loop" => completed_program_seed(
            run_id,
            scenario_id,
            "Durable fixed-interface self-hosting loop completed with replayable evidence",
            "self-hosting-loop",
            "durable self-hosting loop evidence remained reconstructable",
            vec!["self-hosting-loop-output".to_string()],
        ),
        "supervisor-durable-fixed-interface-continuous-self-hosting-program" => {
            paused_continuous_program_seed(run_id)
        }
        _ => Err(LocalRuntimeError::UnknownScenario {
            scenario_id: scenario_id.to_string(),
        }),
    }
}

fn build_run_seed_for_scenario(
    workspace: &LocalRuntimeWorkspace,
    scenario_id: &str,
    run_id: &str,
) -> Result<ScenarioSeed, LocalRuntimeError> {
    let mut seed = match scenario_id {
        LIVE_V4_SHELL_SCENARIO_ID => live_v4_shell_runner_seed(workspace, run_id),
        LIVE_NORTHSTAR_PROGRAM_SCENARIO_ID => live_northstar_program_seed(workspace, run_id),
        "supervisor-durable-fixed-interface-continuous-self-hosting-program" => {
            live_continuous_program_seed(workspace, run_id)
        }
        "supervisor-background-quarantine-rollback-control-loop" => {
            live_background_quarantine_seed(workspace, run_id)
        }
        LIVE_PHASE_B_FACTORY_SCENARIO_ID => live_phase_b_factory_seed(workspace, run_id),
        LIVE_PHASE_C_REPLICATION_SCENARIO_ID => live_phase_c_replication_seed(workspace, run_id),
        LIVE_PHASE_D_EXCHANGE_SCENARIO_ID => live_phase_d_exchange_seed(workspace, run_id),
        _ => build_scenario_seed(scenario_id, run_id),
    }?;
    annotate_launch_truth(&mut seed.record, &seed.bootstrap_states);
    Ok(seed)
}

fn annotate_launch_truth(record: &mut LocalRunRecord, bootstrap_states: &[ReplayableRuntimeState]) {
    let definition = scenario_definition(&record.metadata.scenario_id)
        .expect("scenario definition should exist");
    let support = scenario_support_classification(&definition);
    let assembly = build_launch_assembly_record(record, &support, bootstrap_states);
    let admission = build_campaign_admission_record(record, &support, assembly.as_ref());
    record.metadata.scenario_support = Some(support);
    record.metadata.launch_assembly = assembly;
    record.metadata.campaign_admission = admission;
}

fn scenario_support_classification(
    definition: &ScenarioDefinition,
) -> ScenarioSupportClassification {
    let support_class = match definition.runtime_class {
        ScenarioRuntimeClass::SupportedLive => ScenarioSupportClass::ShellBacked,
        ScenarioRuntimeClass::TransitionalLive => ScenarioSupportClass::MixedTransitional,
        ScenarioRuntimeClass::ReferenceDemo => ScenarioSupportClass::StagedDemoOnly,
    };

    let required_world_refs = match support_class {
        ScenarioSupportClass::ShellBacked => vec![
            "worker-world:v4-supervisory-shell".to_string(),
            "memory-protocol:skeptical-retrieval".to_string(),
            "capability-envelope:governed-shell".to_string(),
            "runner-law:universal-shell-launch".to_string(),
        ],
        ScenarioSupportClass::MixedTransitional => vec![
            "factory-runtime:bounded-artifact-family".to_string(),
            "runner-law:launch-truth".to_string(),
        ],
        ScenarioSupportClass::StagedDemoOnly => vec!["runner-fixture:seeded-scenario".to_string()],
    };
    let unsupported_refs = match support_class {
        ScenarioSupportClass::ShellBacked => Vec::new(),
        ScenarioSupportClass::MixedTransitional => vec![
            "missing:fully-live-shell-session-creation".to_string(),
            "missing:universal-shell-first-runner-path".to_string(),
        ],
        ScenarioSupportClass::StagedDemoOnly => vec![
            "missing:live-shell-launch".to_string(),
            "missing:kernel-owned-shell-admission".to_string(),
        ],
    };
    let claim_boundary = match definition.roadmap_class {
        RoadmapPathClass::Operational => {
            "This path may claim only the operational effect identified by its backing evidence; broader North Star closure remains independently gated.".to_string()
        }
        RoadmapPathClass::Transitional => {
            "This path performs a bounded local effect, but it is not yet restartable, recoverable, and verified enough to claim operational maturity.".to_string()
        }
        RoadmapPathClass::Rehearsal => {
            "This path constructs and transitions deterministic records or fixtures; it must not claim the advertised worker, service, factory, or ecosystem effect actually occurred.".to_string()
        }
        RoadmapPathClass::Unsupported => {
            "This advertised path is unsupported and must return an explicit refusal rather than synthetic success.".to_string()
        }
    };

    ScenarioSupportClassification {
        scenario_ref: definition.scenario_id.clone(),
        support_class,
        roadmap_class: definition.roadmap_class,
        maturity: definition.maturity,
        required_world_refs,
        unsupported_refs,
        backing_evidence_refs: definition.backing_evidence_refs.clone(),
        rollback_kind: definition.rollback_kind,
        claim_boundary,
    }
}

fn build_launch_assembly_record(
    record: &LocalRunRecord,
    support: &ScenarioSupportClassification,
    bootstrap_states: &[ReplayableRuntimeState],
) -> Option<ShellLaunchAssemblyRecord> {
    if matches!(support.support_class, ScenarioSupportClass::StagedDemoOnly) {
        return None;
    }
    Some(ShellLaunchAssemblyRecord {
        assembly_id: format!("launch-assembly:{}", record.metadata.run_id),
        scenario_ref: record.metadata.scenario_id.clone(),
        campaign_ref: record.runtime_state.session.header.campaign_id.clone(),
        task_graph_ref: record.runtime_state.task_graph.root_task_id.clone(),
        worker_component_ref: format!(
            "worker-component:{}:{}",
            sanitize_id(&record.metadata.scenario_id),
            sanitize_id(&record.metadata.run_id)
        ),
        capability_context_ref: record
            .runtime_state
            .session
            .header
            .capability_envelope_ref
            .clone(),
        bootstrap_refs: bootstrap_states
            .iter()
            .map(|state| format!("bootstrap-session:{}", state.session.header.session_id))
            .collect(),
        support_class_ref: format!(
            "scenario-support:{}",
            sanitize_id(&record.metadata.scenario_id)
        ),
    })
}

fn build_campaign_admission_record(
    record: &LocalRunRecord,
    support: &ScenarioSupportClassification,
    assembly: Option<&ShellLaunchAssemblyRecord>,
) -> Option<ShellCampaignAdmissionRecord> {
    let initial_state = match support.support_class {
        ScenarioSupportClass::ShellBacked => status_to_admission_state(&record.metadata.status),
        ScenarioSupportClass::MixedTransitional => ShellCampaignAdmissionState::MixedTransitional,
        ScenarioSupportClass::StagedDemoOnly => ShellCampaignAdmissionState::Unsupported,
    };
    Some(ShellCampaignAdmissionRecord {
        admission_id: format!("launch-admission:{}", record.metadata.run_id),
        assembly_ref: assembly
            .map(|item| item.assembly_id.clone())
            .unwrap_or_else(|| format!("launch-assembly:unsupported:{}", record.metadata.run_id)),
        session_refs: match support.support_class {
            ScenarioSupportClass::ShellBacked => {
                vec![record.runtime_state.session.header.session_id.clone()]
            }
            ScenarioSupportClass::MixedTransitional => {
                vec![record.runtime_state.session.header.session_id.clone()]
            }
            ScenarioSupportClass::StagedDemoOnly => Vec::new(),
        },
        agenda_refs: record
            .runtime_state
            .task_graph
            .agenda_items
            .iter()
            .map(|item| item.agenda_item_id.clone())
            .collect(),
        initial_state,
        summary: match support.support_class {
            ScenarioSupportClass::ShellBacked => format!(
                "Scenario `{}` entered the runner through an explicit shell-backed launch assembly and campaign admission record.",
                record.metadata.scenario_id
            ),
            ScenarioSupportClass::MixedTransitional => format!(
                "Scenario `{}` entered the runner through an explicit mixed-transitional launch record. Live artifact truth is present, but the shell path remains partial.",
                record.metadata.scenario_id
            ),
            ScenarioSupportClass::StagedDemoOnly => format!(
                "Scenario `{}` remains a staged demo path. The runner recorded this launch as unsupported for shell-backed admission rather than fabricating shell truth.",
                record.metadata.scenario_id
            ),
        },
    })
}

fn status_to_admission_state(status: &LocalRunStatus) -> ShellCampaignAdmissionState {
    match status {
        LocalRunStatus::AwaitingApproval => ShellCampaignAdmissionState::Paused,
        LocalRunStatus::AwaitingRollback => ShellCampaignAdmissionState::Denied,
        LocalRunStatus::Paused => ShellCampaignAdmissionState::Paused,
        LocalRunStatus::Completed => ShellCampaignAdmissionState::Completed,
        LocalRunStatus::Failed => ShellCampaignAdmissionState::Denied,
        LocalRunStatus::RolledBack => ShellCampaignAdmissionState::Denied,
    }
}

fn live_v4_shell_runner_seed(
    workspace: &LocalRuntimeWorkspace,
    run_id: &str,
) -> Result<ScenarioSeed, LocalRuntimeError> {
    let definition = scenario_definition(LIVE_V4_SHELL_SCENARIO_ID).expect("scenario should exist");
    let ids = ScenarioIds::new(run_id, &definition.scenario_id, "epoch-v4-live");
    let store = DurableArtifactStore::bootstrap(workspace.store_root(run_id))?;
    let shell = execute_live_shell_flow(
        &ids,
        "Execute one shell-first live runner path with approval, memory retrieval, and completion.",
    )?;
    persist_live_shell_flow(&store, &shell)?;
    let mut output_refs = Vec::new();
    append_shell_output_refs(&mut output_refs, &shell);
    output_refs.extend(persist_northstar_01_records(
        &store,
        &definition,
        &ids,
        &shell,
        false,
    )?);
    let mut runtime_state = shell.bundle.runtime_state.clone();
    runtime_state.root_task.output_refs.extend(output_refs);
    runtime_state.event_log.push(ExecutionEvent::new(
        format!("event-live-v4-shell-complete-{}", ids.slug),
        EventFamily::ShellSessionEvent,
        ids.campaign_id.clone(),
        ids.epoch_id.clone(),
        ids.session_id.clone(),
        shell.bundle.shell_session.latest_turn_ref.clone(),
        Some(ids.task_id.clone()),
        "live v4 shell-backed runner path completed with persisted shell evidence",
    ));

    Ok(ScenarioSeed {
        record: LocalRunRecord {
            metadata: LocalRunMetadata {
                run_id: run_id.to_string(),
                scenario_id: definition.scenario_id,
                status: LocalRunStatus::Completed,
                created_at: current_timestamp(),
                updated_at: current_timestamp(),
                studio_template_id: None,
                studio_pack_id: None,
                composition_id: None,
                run_set_id: None,
                hypothesis_id: None,
                review_packet_id: None,
                regression_pack_id: None,
                operator_goal: Some(
                    "Prove one live v4 shell-backed runner path without scenario-state fabrication."
                        .to_string(),
                ),
                rollback_handle: None,
                quarantines: Vec::new(),
                scenario_support: None,
                launch_assembly: None,
                campaign_admission: None,
            },
            runtime_state,
        },
        bootstrap_states: Vec::new(),
    })
}

fn live_v4_runtime_state(
    ids: &ScenarioIds,
    shell_session_id: &str,
    agenda_item_id: &str,
) -> ReplayableRuntimeState {
    let session = ExecutionSession::new(ExecutionSessionHeader {
        session_id: ids.session_id.clone(),
        actor_kind: ActorKind::Worker,
        actor_id: format!("worker-component-{}", ids.slug),
        campaign_id: ids.campaign_id.clone(),
        epoch_id: ids.epoch_id.clone(),
        capability_envelope_ref: format!("envelope-shell-{}", ids.slug),
        parent_session_id: None,
    });
    let task = TaskArtifact::new(
        ids.task_id.clone(),
        "Execute one shell-backed live runner path with approval, memory retrieval, and completion.",
    );
    let agenda_item = AgendaItem::new(
        agenda_item_id.to_string(),
        ids.task_id.clone(),
        "shell-task",
        Vec::new(),
        OwnershipBoundary {
            boundary_id: format!("boundary-{}", ids.slug),
            resource_scope: format!("scope:{}", ids.task_id),
            mode: OwnershipMode::ExclusiveMutable,
            owner_actor_ref: format!("worker-component-{}", ids.slug),
        },
    );
    let mut memory_store = MemoryStore::default();
    memory_store.insert_pointer_index(PointerIndex {
        index_id: ids.pointer_index_id.clone(),
        scope: MemoryScope::Session(shell_session_id.to_string()),
        entry_refs: vec![ids.topic_bundle_id.clone()],
        contested_refs: Vec::new(),
        critical_refs: Vec::new(),
        governance_constraints: vec![
            "skeptical-memory".to_string(),
            "live-shell-backed-runner".to_string(),
        ],
        open_task_refs: vec![ids.task_id.clone()],
        updated_at: "boot".to_string(),
    });
    memory_store.add_topic_bundle(TopicBundle {
        bundle_id: ids.topic_bundle_id.clone(),
        bundle_class: TopicBundleClass::WorkspaceMap,
        scope: MemoryScope::Session(shell_session_id.to_string()),
        summary: "bounded workspace map for the live shell-backed runner path".to_string(),
        evidence_refs: vec![format!("evidence:{}", ids.slug)],
        freshness_policy: "fresh".to_string(),
    });
    memory_store.add_transcript_slice(TranscriptSlice {
        slice_id: ids.transcript_slice_id.clone(),
        campaign_id: ids.campaign_id.clone(),
        epoch_id: ids.epoch_id.clone(),
        session_id: Some(ids.session_id.clone()),
        task_id: Some(ids.task_id.clone()),
        referenced_artifacts: vec![ids.topic_bundle_id.clone()],
        summary: "retrieve the bounded workspace map for the live shell-backed path".to_string(),
        excerpts: vec!["retrieve the bounded workspace map".to_string()],
    });
    ReplayableRuntimeState::new(
        session,
        task,
        TaskGraph::new(ids.task_id.clone(), vec![agenda_item]),
        memory_store,
        None,
        vec![ExecutionEvent::new(
            format!("event-live-v4-bootstrap-{}", ids.slug),
            EventFamily::ShellSessionEvent,
            ids.campaign_id.clone(),
            ids.epoch_id.clone(),
            ids.session_id.clone(),
            None,
            Some(ids.task_id.clone()),
            "live v4 shell-backed runner path bootstrapped",
        )],
    )
}

fn live_northstar_program_seed(
    workspace: &LocalRuntimeWorkspace,
    run_id: &str,
) -> Result<ScenarioSeed, LocalRuntimeError> {
    let definition =
        scenario_definition(LIVE_NORTHSTAR_PROGRAM_SCENARIO_ID).expect("scenario should exist");
    let ids = ScenarioIds::new(run_id, &definition.scenario_id, "epoch-northstar-program");
    let store = DurableArtifactStore::bootstrap(workspace.store_root(run_id))?;
    let mut shell = execute_live_shell_flow(
        &ids,
        "Execute one shell-first continuous program with persistent scheduler, approval, and continuity evidence.",
    )?;
    let secondary_bundle_id = format!("topic-bundle-secondary-{}", ids.slug);
    shell
        .bundle
        .runtime_state
        .memory_store
        .add_topic_bundle(TopicBundle {
            bundle_id: secondary_bundle_id.clone(),
            bundle_class: TopicBundleClass::CampaignOperatingNotes,
            scope: MemoryScope::Session(shell.shell_session_id.clone()),
            summary: "secondary continuity topic bundle for persistent shell consolidation"
                .to_string(),
            evidence_refs: vec![format!("evidence:continuity-secondary:{}", ids.slug)],
            freshness_policy: "fresh".to_string(),
        });
    let continuity_class = crate::execution::ContinuityJobClassification {
        job_class_id: format!("northstar-02-continuity-class-{}", ids.slug),
        job_class: "consolidation".to_string(),
        allowed_actions: vec![
            "pointer-compaction".to_string(),
            "verified-summary-write".to_string(),
        ],
        forbidden_actions: vec![
            "ambient-network".to_string(),
            "unverified-memory-rewrite".to_string(),
        ],
        claim_boundary: "Continuity jobs remain bounded maintenance only.".to_string(),
    };
    let lease = crate::execution::PersistentJobLease {
        lease_id: format!("northstar-02-lease-{}", ids.slug),
        job_class: continuity_class.job_class.clone(),
        owner_ref: format!("program:{}", definition.scenario_id),
        scope_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        authority_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .capability_envelope_ref
            .clone(),
        wake_policy_ref: format!("wake-policy:scheduler:{}", ids.slug),
        renewal_policy_ref: format!("renewal-policy:bounded:{}", ids.slug),
        interruption_policy_ref: format!("interruption-policy:bounded:{}", ids.slug),
        termination_policy_ref: format!("termination-policy:bounded:{}", ids.slug),
        lease_state: "active".to_string(),
    };
    let continuity_ref = shell
        .bundle
        .continuity_bundle
        .as_ref()
        .map(|bundle| bundle.continuity_id.clone())
        .ok_or_else(|| {
            LocalRuntimeError::Storage(
                "northstar persistent shell scenario expected a continuity bundle".to_string(),
            )
        })?;
    let tick = crate::execution::SchedulerTickRecord {
        tick_id: format!("northstar-02-tick-{}", ids.slug),
        tick_class: crate::execution::SchedulerTickClass::Time,
        target_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        lease_ref: lease.lease_id.clone(),
        result: crate::execution::SchedulerTickResult::Resumed,
        summary: "scheduler wake resumed one shell-owned continuous program step".to_string(),
    };
    let wake = crate::execution::ScheduledWakeRecord {
        wake_record_id: format!("northstar-02-wake-{}", ids.slug),
        continuity_ref: continuity_ref.clone(),
        lease_ref: lease.lease_id.clone(),
        tick_ref: tick.tick_id.clone(),
        scheduled_at: format!("scheduled-at:{}", ids.slug),
        executed_at: format!("executed-at:{}", ids.slug),
        result_ref: shell
            .bundle
            .shell_session
            .latest_turn_ref
            .clone()
            .unwrap_or_else(|| format!("shell-turn-missing-{}", ids.slug)),
    };
    let latest_approval = shell
        .bundle
        .approval_pause_records
        .last()
        .map(|record| record.approval_request_ref.clone())
        .unwrap_or_else(|| format!("approval-missing-{}", ids.slug));
    let inbox = crate::execution::ApprovalInboxRecord {
        approval_inbox_id: format!("northstar-02-inbox-{}", ids.slug),
        pause_ref: format!("shell-pause:{}", ids.slug),
        approval_refs: vec![latest_approval.clone()],
        decision_authority_refs: vec!["operator:local-supervisor".to_string()],
        deadline_policy_ref: format!("deadline-policy:{}", ids.slug),
        escalation_policy_ref: format!("escalation-policy:{}", ids.slug),
        response_ref: format!("approval-response:granted:{}", ids.slug),
        resume_ref: format!("resume-chain:{}", ids.slug),
        audit_summary_ref: format!("audit-summary:persistent-shell:{}", ids.slug),
        campaign_refs: vec![
            shell
                .bundle
                .runtime_state
                .session
                .header
                .campaign_id
                .clone(),
        ],
    };
    let decision_bundle = crate::execution::DeferredDecisionBundle {
        decision_bundle_id: format!("northstar-02-decision-bundle-{}", ids.slug),
        approval_ref: latest_approval,
        grant_resume_refs: vec![format!("resume-chain:{}", ids.slug)],
        deny_outcome_refs: vec![format!("deny-outcome:{}", ids.slug)],
        expired_outcome_refs: Vec::new(),
        escalation_outcome_refs: Vec::new(),
        risk_refs: vec![
            "risk:approval-timeout".to_string(),
            "risk:continuity-drift".to_string(),
        ],
        summary: "approval waiting remained explicit, resumable, and bounded.".to_string(),
    };
    let consolidation = shell
        .bundle
        .runtime_state
        .memory_store
        .run_consolidation_job(crate::execution::ConsolidationJob {
            job_id: format!("consolidation-job-{}", ids.slug),
            pointer_index_ref: ids.pointer_index_id.clone(),
            input_bundle_refs: vec![ids.topic_bundle_id.clone(), secondary_bundle_id.clone()],
            output_bundle_id: format!("consolidated-topic-bundle-{}", ids.slug),
            output_bundle_class: TopicBundleClass::WorkspaceMap,
            output_scope: MemoryScope::Session(shell.shell_session_id.clone()),
            output_summary: "bounded continuity consolidation preserved pointer lineage and contradiction visibility".to_string(),
            freshness_policy: "bounded-review-window".to_string(),
            status: crate::execution::ConsolidationJobStatus::Planned,
        })
        .map_err(|error| LocalRuntimeError::Storage(format!("{error:?}")))?;
    let checkpoint_id = shell
        .bundle
        .shell_checkpoints
        .last()
        .map(|checkpoint| checkpoint.shell_checkpoint_id.clone())
        .unwrap_or_else(|| format!("shell-checkpoint-{}", ids.slug));
    let consolidation_record = crate::execution::ConsolidationJobRecord {
        consolidation_id: format!("northstar-02-consolidation-{}", ids.slug),
        lease_ref: lease.lease_id.clone(),
        input_refs: vec![ids.topic_bundle_id.clone(), secondary_bundle_id],
        verification_policy_ref: format!("verification-policy:{}", ids.slug),
        output_refs: vec![consolidation.clone()],
        checkpoint_refs: vec![checkpoint_id],
    };
    let continuity_job = crate::execution::ContinuityJobRecord {
        job_record_id: format!("northstar-02-continuity-job-{}", ids.slug),
        job_kind: "repair".to_string(),
        continuity_ref: continuity_ref.clone(),
        lease_ref: lease.lease_id.clone(),
        budget_ref: format!("budget:repair:{}", ids.slug),
        result_ref: format!("result:repair-completed:{}", ids.slug),
        evidence_refs: vec![
            wake.wake_record_id.clone(),
            consolidation_record.consolidation_id.clone(),
            shell.packet.packet_id.clone(),
        ],
        checkpoint_refs: vec![consolidation_record.checkpoint_refs[0].clone()],
    };
    let audit_packet = crate::execution::PersistentShellAuditPacket {
        audit_packet_id: format!("northstar-02-audit-packet-{}", ids.slug),
        continuity_ref: continuity_ref.clone(),
        tick_refs: vec![tick.tick_id.clone()],
        wake_refs: vec![wake.wake_record_id.clone()],
        lease_refs: vec![lease.lease_id.clone()],
        approval_inbox_refs: vec![inbox.approval_inbox_id.clone()],
        decision_bundle_refs: vec![decision_bundle.decision_bundle_id.clone()],
        job_refs: vec![
            consolidation_record.consolidation_id.clone(),
            continuity_job.job_record_id.clone(),
        ],
        expiry_refs: Vec::new(),
        escalation_refs: Vec::new(),
        evidence_refs: vec![
            tick.tick_id.clone(),
            decision_bundle.decision_bundle_id.clone(),
            shell.packet.packet_id.clone(),
        ],
        operator_summary:
            "persistent shell audit packet links wake, approval, repair, and shell evidence into one bounded operational trail."
                .to_string(),
    };
    let operations_dossier = crate::execution::PersistentShellOperationsDossier {
        operations_dossier_id: format!("northstar-02-operations-dossier-{}", ids.slug),
        continuity_ref,
        tick_refs: vec![tick.tick_id.clone()],
        wake_refs: vec![wake.wake_record_id.clone()],
        lease_refs: vec![lease.lease_id.clone()],
        approval_inbox_refs: vec![inbox.approval_inbox_id.clone()],
        decision_bundle_refs: vec![decision_bundle.decision_bundle_id.clone()],
        continuity_job_refs: vec![
            continuity_class.job_class_id.clone(),
            consolidation_record.consolidation_id.clone(),
            continuity_job.job_record_id.clone(),
        ],
        expiry_refs: Vec::new(),
        escalation_refs: Vec::new(),
        quarantine_refs: Vec::new(),
        rollback_refs: Vec::new(),
        audit_refs: vec![
            tick.tick_id.clone(),
            decision_bundle.decision_bundle_id.clone(),
            audit_packet.audit_packet_id.clone(),
            shell.packet.packet_id.clone(),
        ],
        operator_summary_ref: format!("operator:northstar-02:persistent-shell:{}", ids.slug),
    };

    persist_live_shell_flow(&store, &shell)?;
    store.persist_scheduler_tick_record(&tick)?;
    store.persist_scheduled_wake_record(&wake)?;
    store.persist_persistent_job_lease(&lease)?;
    store.persist_approval_inbox_record(&inbox)?;
    store.persist_deferred_decision_bundle(&decision_bundle)?;
    store.persist_consolidation_job_record(&consolidation_record)?;
    store.persist_continuity_job_classification(&continuity_class)?;
    store.persist_continuity_job_record(&continuity_job)?;
    store.persist_persistent_shell_audit_packet(&audit_packet)?;
    store.persist_persistent_shell_operations_dossier(&operations_dossier)?;
    let northstar_03_refs = persist_northstar_03_service_records(
        &store,
        &ids,
        &format!("run:{run_id}"),
        &shell.bundle.runtime_state.session.header.actor_id,
        &[
            crate::execution::NativeWorkflowKind::Scheduling,
            crate::execution::NativeWorkflowKind::Continuity,
            crate::execution::NativeWorkflowKind::OperationalAttestation,
        ],
    )?;

    let mut output_refs = Vec::new();
    append_shell_output_refs(&mut output_refs, &shell);
    output_refs.extend(persist_northstar_01_records(
        &store,
        &definition,
        &ids,
        &shell,
        true,
    )?);
    output_refs.extend(northstar_03_refs);
    output_refs.extend([
        format!("{NS02_TICK_OUTPUT_PREFIX}{}", tick.tick_id),
        format!("{NS02_WAKE_OUTPUT_PREFIX}{}", wake.wake_record_id),
        format!("{NS02_LEASE_OUTPUT_PREFIX}{}", lease.lease_id),
        format!("{NS02_INBOX_OUTPUT_PREFIX}{}", inbox.approval_inbox_id),
        format!(
            "{NS02_DECISION_BUNDLE_OUTPUT_PREFIX}{}",
            decision_bundle.decision_bundle_id
        ),
        format!(
            "{NS02_CONSOLIDATION_OUTPUT_PREFIX}{}",
            consolidation_record.consolidation_id
        ),
        format!(
            "{NS02_CONTINUITY_CLASS_OUTPUT_PREFIX}{}",
            continuity_class.job_class_id
        ),
        format!(
            "{NS02_CONTINUITY_JOB_OUTPUT_PREFIX}{}",
            continuity_job.job_record_id
        ),
        format!(
            "{NS02_AUDIT_PACKET_OUTPUT_PREFIX}{}",
            audit_packet.audit_packet_id
        ),
        format!(
            "{NS02_OPERATIONS_DOSSIER_OUTPUT_PREFIX}{}",
            operations_dossier.operations_dossier_id
        ),
    ]);

    let mut runtime_state = shell.bundle.runtime_state.clone();
    runtime_state.root_task.summary =
        "Execute one persistent shell-first continuous program with bounded scheduler and continuity services.".to_string();
    runtime_state.root_task.output_refs.extend(output_refs);
    runtime_state.event_log.push(execution_event(
        &ids,
        "northstar-persistent-shell",
        EventFamily::GovernanceDecisionEvent,
        Some(&ids.task_id),
        "NorthStar persistent shell services completed with explicit tick, wake, lease, inbox, decision, consolidation, repair, audit, and operations-dossier evidence",
    ));

    Ok(ScenarioSeed {
        record: LocalRunRecord {
            metadata: LocalRunMetadata {
                run_id: run_id.to_string(),
                scenario_id: definition.scenario_id,
                status: LocalRunStatus::Completed,
                created_at: current_timestamp(),
                updated_at: current_timestamp(),
                studio_template_id: None,
                studio_pack_id: None,
                composition_id: None,
                run_set_id: None,
                hypothesis_id: None,
                review_packet_id: None,
                regression_pack_id: None,
                operator_goal: Some(
                    "Prove one shell-first continuous program with persistent scheduler and continuity evidence.".to_string(),
                ),
                rollback_handle: None,
                quarantines: Vec::new(),
                scenario_support: None,
                launch_assembly: None,
                campaign_admission: None,
            },
            runtime_state,
        },
        bootstrap_states: Vec::new(),
    })
}

fn live_continuous_program_seed(
    workspace: &LocalRuntimeWorkspace,
    run_id: &str,
) -> Result<ScenarioSeed, LocalRuntimeError> {
    let definition =
        scenario_definition("supervisor-durable-fixed-interface-continuous-self-hosting-program")
            .expect("scenario should exist");
    let ids = ScenarioIds::new(run_id, &definition.scenario_id, "epoch-2");
    let store = DurableArtifactStore::bootstrap(workspace.store_root(run_id))?;
    let shell = execute_live_shell_pause_flow(
        &ids,
        "Await governed approval before the continuous shell-owned factory program resumes.",
    )?;

    let continuity_ref = shell
        .bundle
        .shell_checkpoints
        .last()
        .map(|checkpoint| checkpoint.shell_checkpoint_id.clone())
        .unwrap_or_else(|| format!("shell-checkpoint-{}", ids.slug));
    let pause_ref = shell
        .bundle
        .approval_pause_records
        .last()
        .map(|record| record.pause_id.clone())
        .unwrap_or_else(|| format!("shell-pause-{}", ids.slug));
    let continuity_class = crate::execution::ContinuityJobClassification {
        job_class_id: format!("northstar-02-continuity-class-{}", ids.slug),
        job_class: "approval-wait".to_string(),
        allowed_actions: vec![
            "resume-after-governed-approval".to_string(),
            "checkpointed-expiry".to_string(),
        ],
        forbidden_actions: vec![
            "ambient-authority-escalation".to_string(),
            "hidden-background-resume".to_string(),
        ],
        claim_boundary:
            "Approval wait remains a bounded shell-owned continuity state rather than hidden daemon work."
                .to_string(),
    };
    let lease = crate::execution::PersistentJobLease {
        lease_id: format!("northstar-02-lease-{}", ids.slug),
        job_class: continuity_class.job_class.clone(),
        owner_ref: format!("program:{}", definition.scenario_id),
        scope_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        authority_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .capability_envelope_ref
            .clone(),
        wake_policy_ref: format!("wake-policy:approval:{}", ids.slug),
        renewal_policy_ref: format!("renewal-policy:approval-window:{}", ids.slug),
        interruption_policy_ref: format!("interruption-policy:approval-escalation:{}", ids.slug),
        termination_policy_ref: format!("termination-policy:approval-window:{}", ids.slug),
        lease_state: "active".to_string(),
    };
    let tick = crate::execution::SchedulerTickRecord {
        tick_id: format!("northstar-02-tick-{}", ids.slug),
        tick_class: crate::execution::SchedulerTickClass::Approval,
        target_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        lease_ref: lease.lease_id.clone(),
        result: crate::execution::SchedulerTickResult::Deferred,
        summary: "approval wait kept the shell-owned continuous program deferred under one lease."
            .to_string(),
    };
    let wake = crate::execution::ScheduledWakeRecord {
        wake_record_id: format!("northstar-02-wake-{}", ids.slug),
        continuity_ref: continuity_ref.clone(),
        lease_ref: lease.lease_id.clone(),
        tick_ref: tick.tick_id.clone(),
        scheduled_at: format!("scheduled-at:{}", ids.slug),
        executed_at: format!("executed-at:{}", ids.slug),
        result_ref: shell.approval_request.approval_request_id.clone(),
    };
    let inbox = crate::execution::ApprovalInboxRecord {
        approval_inbox_id: format!("northstar-02-inbox-{}", ids.slug),
        pause_ref,
        approval_refs: vec![shell.approval_request.approval_request_id.clone()],
        decision_authority_refs: vec!["operator:local-supervisor".to_string()],
        deadline_policy_ref: format!("deadline-policy:{}", ids.slug),
        escalation_policy_ref: format!("escalation-policy:{}", ids.slug),
        response_ref: format!("approval-response:pending:{}", ids.slug),
        resume_ref: format!("resume:pending:{}", ids.slug),
        audit_summary_ref: format!("audit-summary:approval-wait:{}", ids.slug),
        campaign_refs: vec![
            shell
                .bundle
                .runtime_state
                .session
                .header
                .campaign_id
                .clone(),
        ],
    };
    let decision_bundle = crate::execution::DeferredDecisionBundle {
        decision_bundle_id: format!("northstar-02-decision-bundle-{}", ids.slug),
        approval_ref: shell.approval_request.approval_request_id.clone(),
        grant_resume_refs: vec![format!("grant-resume:{}", ids.slug)],
        deny_outcome_refs: vec![format!("deny-outcome:{}", ids.slug)],
        expired_outcome_refs: vec![format!("expired-outcome:{}", ids.slug)],
        escalation_outcome_refs: vec![format!("escalation-outcome:{}", ids.slug)],
        risk_refs: vec![
            "risk:approval-timeout".to_string(),
            "risk:authority-expansion".to_string(),
        ],
        summary: "approval wait preserved explicit grant, deny, expire, and escalate outcomes."
            .to_string(),
    };
    let checkpoint_ref = shell
        .bundle
        .shell_checkpoints
        .last()
        .map(|checkpoint| checkpoint.shell_checkpoint_id.clone())
        .unwrap_or_else(|| format!("shell-checkpoint-{}", ids.slug));
    let continuity_job = crate::execution::ContinuityJobRecord {
        job_record_id: format!("northstar-02-continuity-job-{}", ids.slug),
        job_kind: "approval-wait".to_string(),
        continuity_ref: continuity_ref.clone(),
        lease_ref: lease.lease_id.clone(),
        budget_ref: format!("budget:approval-wait:{}", ids.slug),
        result_ref: format!("result:approval-pending:{}", ids.slug),
        evidence_refs: vec![
            tick.tick_id.clone(),
            wake.wake_record_id.clone(),
            decision_bundle.decision_bundle_id.clone(),
            shell.packet.packet_id.clone(),
        ],
        checkpoint_refs: vec![checkpoint_ref.clone()],
    };
    let audit_packet = crate::execution::PersistentShellAuditPacket {
        audit_packet_id: format!("northstar-02-audit-packet-{}", ids.slug),
        continuity_ref: continuity_ref.clone(),
        tick_refs: vec![tick.tick_id.clone()],
        wake_refs: vec![wake.wake_record_id.clone()],
        lease_refs: vec![lease.lease_id.clone()],
        approval_inbox_refs: vec![inbox.approval_inbox_id.clone()],
        decision_bundle_refs: vec![decision_bundle.decision_bundle_id.clone()],
        job_refs: vec![continuity_job.job_record_id.clone()],
        expiry_refs: Vec::new(),
        escalation_refs: Vec::new(),
        evidence_refs: vec![shell.packet.packet_id.clone(), checkpoint_ref.clone()],
        operator_summary:
            "pending approval remains a shell-owned persistent state with explicit wake, lease, inbox, and audit lineage."
                .to_string(),
    };
    let operations_dossier = crate::execution::PersistentShellOperationsDossier {
        operations_dossier_id: format!("northstar-02-operations-dossier-{}", ids.slug),
        continuity_ref,
        tick_refs: vec![tick.tick_id.clone()],
        wake_refs: vec![wake.wake_record_id.clone()],
        lease_refs: vec![lease.lease_id.clone()],
        approval_inbox_refs: vec![inbox.approval_inbox_id.clone()],
        decision_bundle_refs: vec![decision_bundle.decision_bundle_id.clone()],
        continuity_job_refs: vec![
            continuity_class.job_class_id.clone(),
            continuity_job.job_record_id.clone(),
        ],
        expiry_refs: Vec::new(),
        escalation_refs: Vec::new(),
        quarantine_refs: Vec::new(),
        rollback_refs: Vec::new(),
        audit_refs: vec![
            audit_packet.audit_packet_id.clone(),
            shell.packet.packet_id.clone(),
        ],
        operator_summary_ref: format!("operator:northstar-02:continuous-program:{}", ids.slug),
    };

    persist_pending_shell_flow(&store, &shell)?;
    store.persist_scheduler_tick_record(&tick)?;
    store.persist_scheduled_wake_record(&wake)?;
    store.persist_persistent_job_lease(&lease)?;
    store.persist_approval_inbox_record(&inbox)?;
    store.persist_deferred_decision_bundle(&decision_bundle)?;
    store.persist_continuity_job_classification(&continuity_class)?;
    store.persist_continuity_job_record(&continuity_job)?;
    store.persist_persistent_shell_audit_packet(&audit_packet)?;
    store.persist_persistent_shell_operations_dossier(&operations_dossier)?;
    let northstar_03_refs = persist_northstar_03_service_records(
        &store,
        &ids,
        &format!("run:{run_id}"),
        &shell.bundle.runtime_state.session.header.actor_id,
        &[crate::execution::NativeWorkflowKind::OperationalAttestation],
    )?;

    let mut output_refs = vec![
        format!("{V4_SHELL_SESSION_OUTPUT_PREFIX}{}", shell.shell_session_id),
        format!("{V4_SHELL_PACKET_OUTPUT_PREFIX}{}", shell.packet.packet_id),
    ];
    output_refs.extend(persist_northstar_01_pending_program_records(
        &store,
        &definition,
        &ids,
        &shell,
    )?);
    output_refs.extend(northstar_03_refs);
    output_refs.extend([
        format!("{NS02_TICK_OUTPUT_PREFIX}{}", tick.tick_id),
        format!("{NS02_WAKE_OUTPUT_PREFIX}{}", wake.wake_record_id),
        format!("{NS02_LEASE_OUTPUT_PREFIX}{}", lease.lease_id),
        format!("{NS02_INBOX_OUTPUT_PREFIX}{}", inbox.approval_inbox_id),
        format!(
            "{NS02_DECISION_BUNDLE_OUTPUT_PREFIX}{}",
            decision_bundle.decision_bundle_id
        ),
        format!(
            "{NS02_CONTINUITY_CLASS_OUTPUT_PREFIX}{}",
            continuity_class.job_class_id
        ),
        format!(
            "{NS02_CONTINUITY_JOB_OUTPUT_PREFIX}{}",
            continuity_job.job_record_id
        ),
        format!(
            "{NS02_AUDIT_PACKET_OUTPUT_PREFIX}{}",
            audit_packet.audit_packet_id
        ),
        format!(
            "{NS02_OPERATIONS_DOSSIER_OUTPUT_PREFIX}{}",
            operations_dossier.operations_dossier_id
        ),
    ]);

    let mut runtime_state = shell.bundle.runtime_state.clone();
    runtime_state.root_task.summary =
        "Await governed approval before resuming the continuous shell-owned factory program."
            .to_string();
    runtime_state.root_task.output_refs.extend(output_refs);
    runtime_state.event_log.push(execution_event(
        &ids,
        "continuous-program-awaiting-approval",
        EventFamily::ApprovalStateEvent,
        Some(&ids.task_id),
        "continuous self-hosting program entered shell-owned approval wait with explicit persistent-shell evidence",
    ));

    Ok(ScenarioSeed {
        record: LocalRunRecord {
            metadata: LocalRunMetadata {
                run_id: run_id.to_string(),
                scenario_id: definition.scenario_id,
                status: LocalRunStatus::AwaitingApproval,
                created_at: current_timestamp(),
                updated_at: current_timestamp(),
                studio_template_id: None,
                studio_pack_id: None,
                composition_id: None,
                run_set_id: None,
                hypothesis_id: None,
                review_packet_id: None,
                regression_pack_id: None,
                operator_goal: Some(
                    "Resolve the governed approval wait for the continuous shell-owned factory program."
                        .to_string(),
                ),
                rollback_handle: None,
                quarantines: Vec::new(),
                scenario_support: None,
                launch_assembly: None,
                campaign_admission: None,
            },
            runtime_state,
        },
        bootstrap_states: Vec::new(),
    })
}

fn live_background_quarantine_seed(
    workspace: &LocalRuntimeWorkspace,
    run_id: &str,
) -> Result<ScenarioSeed, LocalRuntimeError> {
    let definition = scenario_definition("supervisor-background-quarantine-rollback-control-loop")
        .expect("scenario should exist");
    let ids = ScenarioIds::new(run_id, &definition.scenario_id, "epoch-1");
    let safe_ids = ScenarioIds::new(run_id, "safe-rollback-state", "epoch-1");
    let store = DurableArtifactStore::bootstrap(workspace.store_root(run_id))?;
    let shell = execute_live_shell_flow(
        &ids,
        "Run the bounded background control loop and surface quarantine plus rollback under shell-owned law.",
    )?;

    let safe_state = completed_runtime_state(
        &safe_ids,
        "Safe pre-quarantine checkpoint persisted for rollback reconstruction",
        vec!["safe-background-output".to_string()],
        vec![(
            AuditRecordClass::GovernanceAuditRecord,
            "checkpoint-safe".to_string(),
            "safe background checkpoint remained available for rollback".to_string(),
        )],
    );

    let continuity_ref = shell
        .bundle
        .continuity_bundle
        .as_ref()
        .map(|bundle| bundle.continuity_id.clone())
        .unwrap_or_else(|| format!("continuity-{}", ids.slug));
    let continuity_class = crate::execution::ContinuityJobClassification {
        job_class_id: format!("northstar-02-continuity-class-{}", ids.slug),
        job_class: "rollback-recovery".to_string(),
        allowed_actions: vec![
            "bounded-repair".to_string(),
            "quarantine-and-rollback".to_string(),
        ],
        forbidden_actions: vec![
            "ambient-repair".to_string(),
            "unguarded-rollback".to_string(),
        ],
        claim_boundary:
            "Recovery jobs remain shell-owned and checkpointed even when quarantine and rollback are active."
                .to_string(),
    };
    let lease = crate::execution::PersistentJobLease {
        lease_id: format!("northstar-02-lease-{}", ids.slug),
        job_class: continuity_class.job_class.clone(),
        owner_ref: format!("program:{}", definition.scenario_id),
        scope_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        authority_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .capability_envelope_ref
            .clone(),
        wake_policy_ref: format!("wake-policy:recovery:{}", ids.slug),
        renewal_policy_ref: format!("renewal-policy:recovery:{}", ids.slug),
        interruption_policy_ref: format!("interruption-policy:quarantine:{}", ids.slug),
        termination_policy_ref: format!("termination-policy:rollback:{}", ids.slug),
        lease_state: "quarantined".to_string(),
    };
    let tick = crate::execution::SchedulerTickRecord {
        tick_id: format!("northstar-02-tick-{}", ids.slug),
        tick_class: crate::execution::SchedulerTickClass::Policy,
        target_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        lease_ref: lease.lease_id.clone(),
        result: crate::execution::SchedulerTickResult::Refused,
        summary: "policy tick refused background continuation because quarantine remained open."
            .to_string(),
    };
    let wake = crate::execution::ScheduledWakeRecord {
        wake_record_id: format!("northstar-02-wake-{}", ids.slug),
        continuity_ref: continuity_ref.clone(),
        lease_ref: lease.lease_id.clone(),
        tick_ref: tick.tick_id.clone(),
        scheduled_at: format!("scheduled-at:{}", ids.slug),
        executed_at: format!("executed-at:{}", ids.slug),
        result_ref: format!("quarantine-block:{}", ids.slug),
    };
    let rollback_handle = create_rollback_handle(
        format!("rollback-{}", ids.slug),
        ids.campaign_id.clone(),
        safe_ids.checkpoint_id.clone(),
        vec![format!("restore {}", safe_ids.checkpoint_id)],
        Vec::new(),
    );
    let quarantine = create_quarantine_record(
        format!("quarantine-{}", ids.slug),
        QuarantineReasonClass::PostApprovalAnomaly,
        vec![ids.task_id.clone()],
        Some(rollback_handle.rollback_handle_id.clone()),
    );
    let escalation = crate::execution::ShellEscalationRecord {
        escalation_id: format!("northstar-02-escalation-{}", ids.slug),
        source_ref: wake.wake_record_id.clone(),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        policy_ref: "policy:authority-escalation".to_string(),
        trigger_ref: quarantine.quarantine_id.clone(),
        outcome_ref: rollback_handle.rollback_handle_id.clone(),
        summary: "quarantine escalated the background path into explicit rollback control."
            .to_string(),
    };
    let checkpoint_ref = shell
        .bundle
        .shell_checkpoints
        .last()
        .map(|checkpoint| checkpoint.shell_checkpoint_id.clone())
        .unwrap_or_else(|| format!("shell-checkpoint-{}", ids.slug));
    let continuity_job = crate::execution::ContinuityJobRecord {
        job_record_id: format!("northstar-02-continuity-job-{}", ids.slug),
        job_kind: "rollback-recovery".to_string(),
        continuity_ref: continuity_ref.clone(),
        lease_ref: lease.lease_id.clone(),
        budget_ref: format!("budget:rollback-recovery:{}", ids.slug),
        result_ref: format!("result:rollback-required:{}", ids.slug),
        evidence_refs: vec![
            wake.wake_record_id.clone(),
            quarantine.quarantine_id.clone(),
            escalation.escalation_id.clone(),
            shell.packet.packet_id.clone(),
        ],
        checkpoint_refs: vec![checkpoint_ref.clone()],
    };
    let audit_packet = crate::execution::PersistentShellAuditPacket {
        audit_packet_id: format!("northstar-02-audit-packet-{}", ids.slug),
        continuity_ref: continuity_ref.clone(),
        tick_refs: vec![tick.tick_id.clone()],
        wake_refs: vec![wake.wake_record_id.clone()],
        lease_refs: vec![lease.lease_id.clone()],
        approval_inbox_refs: Vec::new(),
        decision_bundle_refs: Vec::new(),
        job_refs: vec![continuity_job.job_record_id.clone()],
        expiry_refs: Vec::new(),
        escalation_refs: vec![escalation.escalation_id.clone()],
        evidence_refs: vec![
            rollback_handle.rollback_handle_id.clone(),
            quarantine.quarantine_id.clone(),
            shell.packet.packet_id.clone(),
        ],
        operator_summary:
            "background recovery, quarantine, escalation, and rollback readiness remain explicit under shell-owned persistence."
                .to_string(),
    };
    let operations_dossier = crate::execution::PersistentShellOperationsDossier {
        operations_dossier_id: format!("northstar-02-operations-dossier-{}", ids.slug),
        continuity_ref,
        tick_refs: vec![tick.tick_id.clone()],
        wake_refs: vec![wake.wake_record_id.clone()],
        lease_refs: vec![lease.lease_id.clone()],
        approval_inbox_refs: Vec::new(),
        decision_bundle_refs: Vec::new(),
        continuity_job_refs: vec![
            continuity_class.job_class_id.clone(),
            continuity_job.job_record_id.clone(),
        ],
        expiry_refs: Vec::new(),
        escalation_refs: vec![escalation.escalation_id.clone()],
        quarantine_refs: vec![quarantine.quarantine_id.clone()],
        rollback_refs: vec![rollback_handle.rollback_handle_id.clone()],
        audit_refs: vec![
            audit_packet.audit_packet_id.clone(),
            shell.packet.packet_id.clone(),
        ],
        operator_summary_ref: format!("operator:northstar-02:background-rollback:{}", ids.slug),
    };

    persist_live_shell_flow(&store, &shell)?;
    store.persist_scheduler_tick_record(&tick)?;
    store.persist_scheduled_wake_record(&wake)?;
    store.persist_persistent_job_lease(&lease)?;
    store.persist_continuity_job_classification(&continuity_class)?;
    store.persist_continuity_job_record(&continuity_job)?;
    store.persist_shell_escalation_record(&escalation)?;
    store.persist_persistent_shell_audit_packet(&audit_packet)?;
    store.persist_persistent_shell_operations_dossier(&operations_dossier)?;
    let northstar_03_refs = persist_northstar_03_service_records(
        &store,
        &ids,
        &format!("run:{run_id}"),
        &shell.bundle.runtime_state.session.header.actor_id,
        &[
            crate::execution::NativeWorkflowKind::Continuity,
            crate::execution::NativeWorkflowKind::OperationalAttestation,
        ],
    )?;
    let northstar_04_refs = persist_northstar_04_ecology_records(
        &store,
        &ids,
        &shell.bundle.runtime_state.session.header.campaign_id,
        &ids.task_id,
        &[crate::execution::WorkerRoleKind::ContinuityWorker],
        vec![
            quarantine.quarantine_id.clone(),
            escalation.escalation_id.clone(),
        ],
        vec![rollback_handle.rollback_handle_id.clone()],
        "rollback-control",
    )?;

    let mut output_refs = Vec::new();
    append_shell_output_refs(&mut output_refs, &shell);
    output_refs.extend(persist_northstar_01_records(
        &store,
        &definition,
        &ids,
        &shell,
        false,
    )?);
    output_refs.extend(northstar_03_refs);
    output_refs.extend(northstar_04_refs);
    output_refs.extend([
        format!("{NS02_TICK_OUTPUT_PREFIX}{}", tick.tick_id),
        format!("{NS02_WAKE_OUTPUT_PREFIX}{}", wake.wake_record_id),
        format!("{NS02_LEASE_OUTPUT_PREFIX}{}", lease.lease_id),
        format!(
            "{NS02_CONTINUITY_CLASS_OUTPUT_PREFIX}{}",
            continuity_class.job_class_id
        ),
        format!(
            "{NS02_CONTINUITY_JOB_OUTPUT_PREFIX}{}",
            continuity_job.job_record_id
        ),
        format!(
            "{NS02_ESCALATION_OUTPUT_PREFIX}{}",
            escalation.escalation_id
        ),
        format!(
            "{NS02_AUDIT_PACKET_OUTPUT_PREFIX}{}",
            audit_packet.audit_packet_id
        ),
        format!(
            "{NS02_OPERATIONS_DOSSIER_OUTPUT_PREFIX}{}",
            operations_dossier.operations_dossier_id
        ),
    ]);

    let mut runtime_state = shell.bundle.runtime_state.clone();
    runtime_state.session.state = ExecutionSessionState::Blocked;
    runtime_state.session.blocked_reason = Some(BlockedReason::new(
        BlockedReasonKind::Governance,
        "quarantine blocks action until rollback is executed",
    ));
    runtime_state.root_task.state = TaskState::Paused;
    runtime_state.root_task.blocked_reason = runtime_state.session.blocked_reason.clone();
    runtime_state.root_task.summary =
        "Quarantine the background path and require explicit rollback under shell-owned runtime law."
            .to_string();
    runtime_state.root_task.output_refs.extend(output_refs);
    runtime_state.event_log.push(execution_event(
        &ids,
        "background-quarantine-live",
        EventFamily::GovernanceDecisionEvent,
        Some(&ids.task_id),
        "background path moved into quarantine and explicit rollback control with persistent shell evidence",
    ));

    Ok(ScenarioSeed {
        record: LocalRunRecord {
            metadata: LocalRunMetadata {
                run_id: run_id.to_string(),
                scenario_id: definition.scenario_id,
                status: LocalRunStatus::AwaitingRollback,
                created_at: current_timestamp(),
                updated_at: current_timestamp(),
                studio_template_id: None,
                studio_pack_id: None,
                composition_id: None,
                run_set_id: None,
                hypothesis_id: None,
                review_packet_id: None,
                regression_pack_id: None,
                operator_goal: Some(
                    "Review quarantine evidence and decide whether to execute governed rollback."
                        .to_string(),
                ),
                rollback_handle: Some(rollback_handle),
                quarantines: vec![quarantine],
                scenario_support: None,
                launch_assembly: None,
                campaign_admission: None,
            },
            runtime_state,
        },
        bootstrap_states: vec![safe_state],
    })
}

fn execute_live_shell_flow(
    ids: &ScenarioIds,
    task_summary: &str,
) -> Result<LiveShellFlowArtifacts, LocalRuntimeError> {
    let shell_session_id = format!("shell-session-{}", ids.slug);
    let agenda_item_id = format!("agenda-{}", ids.slug);
    let approval = live_v4_approval_component(ids, &shell_session_id)?;
    let memory = live_v4_memory_component(ids, &shell_session_id)?;
    let complete = live_v4_complete_component(ids, &shell_session_id)?;

    let mut failure_budget = FailureBudget::default();
    let mut bundle = open_shell_session_bundle(
        shell_session_id.clone(),
        format!("worker-component-{}", ids.slug),
        Some(agenda_item_id.clone()),
        live_v4_runtime_state(ids, &shell_session_id, &agenda_item_id),
        &failure_budget,
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    bundle.runtime_state.root_task.summary = task_summary.to_string();
    dispatch_shell_session(&mut bundle, &agenda_item_id)
        .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;

    start_shell_turn(
        &mut bundle,
        format!("shell-turn-approval-{}", ids.slug),
        "request-approval",
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    let approval_execution = execute_active_shell_turn(
        &mut bundle,
        &approval.build.component_bytes,
        &approval.context,
        &mut failure_budget,
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    let approval_request = approval_execution.approval_request.ok_or_else(|| {
        LocalRuntimeError::Storage("live shell flow expected an approval request".to_string())
    })?;
    resume_shell_session_from_approval(
        &mut bundle,
        &ApprovalDecision::granted(
            approval_request.approval_request_id.clone(),
            ids.campaign_id.clone(),
            ids.epoch_id.clone(),
            ids.session_id.clone(),
            ids.task_id.clone(),
            approval_request.action_ref.clone(),
            "local-runner-shell-flow".to_string(),
            approval_request.scope_ref.clone(),
            Some("resume shell-first flow".to_string()),
        ),
        "local-runner-shell-flow",
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;

    start_shell_turn(
        &mut bundle,
        format!("shell-turn-memory-{}", ids.slug),
        "retrieve-memory",
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    execute_active_shell_turn(
        &mut bundle,
        &memory.build.component_bytes,
        &memory.context,
        &mut failure_budget,
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    let memory_trace = bundle
        .memory_retrieval_traces
        .last()
        .map(|trace| trace.trace_id.clone())
        .ok_or_else(|| {
            LocalRuntimeError::Storage(
                "live shell flow expected a memory retrieval trace".to_string(),
            )
        })?;
    let contradiction = bundle.runtime_state.memory_store.register_contradiction(
        format!("contradiction-{}", ids.slug),
        vec![memory_trace.clone()],
        "shell-memory-verify",
        Some(ids.pointer_index_id.as_str()),
    );
    let _ = bundle.runtime_state.memory_store.resolve_contradiction(
        &contradiction.contradiction_id,
        Some(ids.pointer_index_id.as_str()),
    );
    record_shell_verified_memory_update(
        &mut bundle,
        format!("verified-memory-{}", ids.slug),
        &ids.pointer_index_id,
        TopicBundleClass::GovernanceNotes,
        format!("verified shell completion memory for {}", ids.slug),
        vec![memory_trace],
        vec![format!("verification:{}", ids.slug)],
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    finalize_shell_continuity_bundle(
        &mut bundle,
        format!("continuity-{}", ids.slug),
        &ids.pointer_index_id,
        vec![contradiction.contradiction_id.clone()],
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;

    start_shell_turn(
        &mut bundle,
        format!("shell-turn-complete-{}", ids.slug),
        "complete-task",
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    execute_active_shell_turn(
        &mut bundle,
        &complete.build.component_bytes,
        &complete.context,
        &mut failure_budget,
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    complete_shell_orchestration(&mut bundle, &agenda_item_id)
        .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;

    let packet = crate::execution::assemble_shell_evidence_packet(
        format!("packet-{}", ids.slug),
        shell_session_id.clone(),
        &bundle,
    );
    let gate = V4SupervisoryShellCompletionEvidence {
        shell_session_bundle_ref: shell_session_id.clone(),
        shell_evidence_packet_ref: packet.packet_id.clone(),
        shell_session_ref: shell_session_id.clone(),
        pause_resume_refs: packet.pause_resume_refs.clone(),
        membrane_trace_refs: packet.membrane_trace_refs.clone(),
        memory_trace_refs: packet.memory_trace_refs.clone(),
        verified_memory_refs: packet.verified_memory_refs.clone(),
        orchestration_trace_refs: packet.orchestration_trace_refs.clone(),
    };
    let completion_gate =
        evaluate_v4_supervisory_shell_completion_gate(format!("gate-{}", ids.slug), gate.clone());
    Ok(LiveShellFlowArtifacts {
        shell_session_id,
        bundle,
        packet,
        completion_gate,
    })
}

fn execute_live_shell_pause_flow(
    ids: &ScenarioIds,
    task_summary: &str,
) -> Result<PendingApprovalShellFlowArtifacts, LocalRuntimeError> {
    let shell_session_id = format!("shell-session-{}", ids.slug);
    let agenda_item_id = format!("agenda-{}", ids.slug);
    let memory = live_v4_memory_component(ids, &shell_session_id)?;
    let approval = live_v4_approval_component(ids, &shell_session_id)?;

    let mut failure_budget = FailureBudget::default();
    let mut bundle = open_shell_session_bundle(
        shell_session_id.clone(),
        format!("worker-component-{}", ids.slug),
        Some(agenda_item_id.clone()),
        live_v4_runtime_state(ids, &shell_session_id, &agenda_item_id),
        &failure_budget,
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    bundle.runtime_state.root_task.summary = task_summary.to_string();
    dispatch_shell_session(&mut bundle, &agenda_item_id)
        .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;

    start_shell_turn(
        &mut bundle,
        format!("shell-turn-memory-{}", ids.slug),
        "retrieve-memory",
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    execute_active_shell_turn(
        &mut bundle,
        &memory.build.component_bytes,
        &memory.context,
        &mut failure_budget,
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    let memory_trace = bundle
        .memory_retrieval_traces
        .last()
        .map(|trace| trace.trace_id.clone())
        .ok_or_else(|| {
            LocalRuntimeError::Storage(
                "live shell pause flow expected a memory retrieval trace".to_string(),
            )
        })?;
    let contradiction = bundle.runtime_state.memory_store.register_contradiction(
        format!("contradiction-{}", ids.slug),
        vec![memory_trace.clone()],
        "shell-memory-verify",
        Some(ids.pointer_index_id.as_str()),
    );
    let _ = bundle.runtime_state.memory_store.resolve_contradiction(
        &contradiction.contradiction_id,
        Some(ids.pointer_index_id.as_str()),
    );
    record_shell_verified_memory_update(
        &mut bundle,
        format!("verified-memory-{}", ids.slug),
        &ids.pointer_index_id,
        TopicBundleClass::GovernanceNotes,
        format!("verified shell approval-wait memory for {}", ids.slug),
        vec![memory_trace],
        vec![format!("verification:{}", ids.slug)],
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    finalize_shell_continuity_bundle(
        &mut bundle,
        format!("continuity-{}", ids.slug),
        &ids.pointer_index_id,
        vec![contradiction.contradiction_id.clone()],
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;

    start_shell_turn(
        &mut bundle,
        format!("shell-turn-approval-{}", ids.slug),
        "request-approval",
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    let approval_execution = execute_active_shell_turn(
        &mut bundle,
        &approval.build.component_bytes,
        &approval.context,
        &mut failure_budget,
    )
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    let approval_request = approval_execution.approval_request.ok_or_else(|| {
        LocalRuntimeError::Storage("live shell pause flow expected an approval request".to_string())
    })?;
    let packet = crate::execution::assemble_shell_evidence_packet(
        format!("packet-{}", ids.slug),
        shell_session_id.clone(),
        &bundle,
    );

    Ok(PendingApprovalShellFlowArtifacts {
        shell_session_id,
        bundle,
        packet,
        approval_request,
    })
}

fn persist_live_shell_flow(
    store: &DurableArtifactStore,
    shell: &LiveShellFlowArtifacts,
) -> Result<(), LocalRuntimeError> {
    store.persist_shell_session_bundle(&shell.bundle)?;
    store.persist_v4_shell_evidence_bundle(&crate::execution::V4ShellEvidenceBundle {
        shell_session_bundle: shell.bundle.clone(),
        shell_evidence_packet: shell.packet.clone(),
    })?;
    store.persist_v4_supervisory_shell_bundle(&crate::execution::V4SupervisoryShellBundle {
        shell_session_bundle: shell.bundle.clone(),
        shell_evidence_packet: shell.packet.clone(),
        completion_gate: shell.completion_gate.clone(),
    })?;
    Ok(())
}

fn persist_pending_shell_flow(
    store: &DurableArtifactStore,
    shell: &PendingApprovalShellFlowArtifacts,
) -> Result<(), LocalRuntimeError> {
    store.persist_shell_session_bundle(&shell.bundle)?;
    store.persist_v4_shell_evidence_bundle(&crate::execution::V4ShellEvidenceBundle {
        shell_session_bundle: shell.bundle.clone(),
        shell_evidence_packet: shell.packet.clone(),
    })?;
    Ok(())
}

fn append_shell_output_refs(output_refs: &mut Vec<String>, shell: &LiveShellFlowArtifacts) {
    output_refs.extend([
        format!("{V4_SHELL_SESSION_OUTPUT_PREFIX}{}", shell.shell_session_id),
        format!("{V4_SHELL_PACKET_OUTPUT_PREFIX}{}", shell.packet.packet_id),
        format!(
            "{V4_SHELL_GATE_OUTPUT_PREFIX}{}",
            shell.completion_gate.gate_id
        ),
    ]);
}

fn persist_northstar_01_records(
    store: &DurableArtifactStore,
    definition: &ScenarioDefinition,
    ids: &ScenarioIds,
    shell: &LiveShellFlowArtifacts,
    is_program: bool,
) -> Result<Vec<String>, LocalRuntimeError> {
    let support = northstar_path_support_classification(definition);
    let support_ref = support.path_ref.clone();
    store.persist_path_support_classification(&support)?;

    let launch = crate::execution::UniversalShellLaunchAssembly {
        launch_id: format!("northstar-01-launch-{}", ids.slug),
        path_ref: definition.scenario_id.clone(),
        support_class_ref: support_ref.clone(),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        agenda_ref: shell.bundle.runtime_state.task_graph.root_task_id.clone(),
        worker_binding_ref: format!("worker-binding:{}", ids.slug),
        capability_context_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .capability_envelope_ref
            .clone(),
        bootstrap_refs: vec![format!("shell-session:{}", shell.shell_session_id)],
    };
    store.persist_universal_shell_launch_assembly(&launch)?;

    let admission = crate::execution::CampaignAdmissionRecord {
        admission_id: format!("northstar-01-admission-{}", ids.slug),
        launch_ref: launch.launch_id.clone(),
        session_refs: vec![shell.bundle.runtime_state.session.header.session_id.clone()],
        task_refs: vec![shell.bundle.runtime_state.root_task.task_id.clone()],
        initial_state: crate::execution::LaunchAdmissionState::Completed,
        summary: format!(
            "{} entered through one shell-first launch and admission path.",
            definition.scenario_id
        ),
    };
    store.persist_campaign_admission_record(&admission)?;

    let lifecycle = crate::execution::UnifiedLifecycleTransitionRecord {
        transition_id: format!("northstar-01-lifecycle-{}", ids.slug),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        from_state: "created".to_string(),
        to_state: "completed".to_string(),
        turn_ref: shell
            .bundle
            .shell_session
            .latest_turn_ref
            .clone()
            .unwrap_or_else(|| format!("shell-turn-complete-{}", ids.slug)),
        decision_refs: unique_strings(
            shell
                .bundle
                .action_decisions
                .iter()
                .map(|decision| decision.decision_id.clone())
                .chain(
                    shell
                        .bundle
                        .approval_pause_records
                        .iter()
                        .map(|record| record.approval_request_ref.clone()),
                ),
        ),
    };
    store.persist_unified_lifecycle_transition_record(&lifecycle)?;

    let evidence_summary = crate::execution::ShellEvidenceSummary {
        summary_id: format!("northstar-01-evidence-summary-{}", ids.slug),
        launch_ref: launch.launch_id.clone(),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        continuity_ref: shell
            .bundle
            .continuity_bundle
            .as_ref()
            .map(|bundle| bundle.continuity_id.clone())
            .unwrap_or_else(|| format!("continuity-{}", ids.slug)),
        decision_refs: lifecycle.decision_refs.clone(),
        claim_boundary: support.claim_boundary.clone(),
    };
    store.persist_shell_evidence_summary(&evidence_summary)?;

    let export_bundle = crate::execution::ShellDerivedExportBundle {
        export_id: format!("northstar-01-export-{}", ids.slug),
        summary_ref: evidence_summary.summary_id.clone(),
        session_refs: vec![shell.shell_session_id.clone()],
        checkpoint_refs: unique_strings(
            shell
                .bundle
                .shell_checkpoints
                .iter()
                .map(|record| record.shell_checkpoint_id.clone()),
        ),
        memory_refs: unique_strings(
            shell
                .bundle
                .memory_retrieval_traces
                .iter()
                .map(|trace| trace.trace_id.clone())
                .chain(
                    shell
                        .bundle
                        .verified_memory_updates
                        .iter()
                        .map(|record| record.record_id.clone()),
                ),
        ),
        workspace_refs: vec![format!("shell-workspace:{}", ids.slug)],
    };
    store.persist_shell_derived_export_bundle(&export_bundle)?;

    let migration_gate = crate::execution::MigrationGateRecord {
        gate_id: format!("northstar-01-gate-{}", ids.slug),
        path_ref: definition.scenario_id.clone(),
        required_refs: vec![
            launch.launch_id.clone(),
            admission.admission_id.clone(),
            lifecycle.transition_id.clone(),
            export_bundle.export_id.clone(),
        ],
        result: crate::execution::MigrationGateResult::Passed,
        failure_refs: Vec::new(),
    };
    store.persist_migration_gate_record(&migration_gate)?;

    let mut output_refs = vec![
        format!(
            "{NS01_SUPPORT_OUTPUT_PREFIX}{}",
            northstar_safe_output_stem(&support.path_ref)
        ),
        format!("{NS01_LAUNCH_OUTPUT_PREFIX}{}", launch.launch_id),
        format!("{NS01_ADMISSION_OUTPUT_PREFIX}{}", admission.admission_id),
        format!("{NS01_LIFECYCLE_OUTPUT_PREFIX}{}", lifecycle.transition_id),
        format!(
            "{NS01_EVIDENCE_SUMMARY_OUTPUT_PREFIX}{}",
            evidence_summary.summary_id
        ),
        format!(
            "{NS01_EXPORT_BUNDLE_OUTPUT_PREFIX}{}",
            export_bundle.export_id
        ),
        format!("{NS01_GATE_OUTPUT_PREFIX}{}", migration_gate.gate_id),
    ];

    if is_program {
        let program_mapping = crate::execution::ProgramToShellMapping {
            mapping_id: format!("northstar-01-program-mapping-{}", ids.slug),
            program_ref: definition.scenario_id.clone(),
            campaign_refs: vec![shell.bundle.runtime_state.session.header.campaign_id.clone()],
            step_refs: shell
                .bundle
                .runtime_state
                .task_graph
                .agenda_items
                .iter()
                .map(|item| item.agenda_item_id.clone())
                .collect(),
            budget_ref: format!("budget:{}", ids.slug),
            summary: "Continuous program steps were expressed through one shell campaign and one shell lifecycle.".to_string(),
        };
        store.persist_program_to_shell_mapping(&program_mapping)?;
        let resume_chain = crate::execution::ResumeChainRecord {
            resume_chain_id: format!("northstar-01-resume-chain-{}", ids.slug),
            checkpoint_refs: export_bundle.checkpoint_refs.clone(),
            resume_trigger_ref: format!("scheduler:{}", ids.slug),
            campaign_ref: shell
                .bundle
                .runtime_state
                .session
                .header
                .campaign_id
                .clone(),
            outcome_ref: lifecycle.transition_id.clone(),
        };
        store.persist_resume_chain_record(&resume_chain)?;
        let acceptance_matrix = crate::execution::AcceptanceTruthMatrix {
            matrix_id: format!("northstar-01-matrix-{}", ids.slug),
            path_refs: curated_scenarios()
                .iter()
                .map(|scenario| scenario.scenario_id.clone())
                .collect(),
            support_expectations: curated_scenarios()
                .iter()
                .map(|scenario| {
                    let support = northstar_path_support_classification(scenario);
                    format!("{}={:?}", scenario.scenario_id, support.support_class)
                })
                .collect(),
            provenance_expectations: vec![
                "launch".to_string(),
                "admission".to_string(),
                "lifecycle".to_string(),
                "shell-export".to_string(),
            ],
            deprecation_expectations: curated_scenarios()
                .iter()
                .filter(|scenario| scenario.runtime_class == ScenarioRuntimeClass::ReferenceDemo)
                .map(|scenario| format!("{}=unsupported", scenario.scenario_id))
                .collect(),
        };
        store.persist_acceptance_truth_matrix(&acceptance_matrix)?;
        let retirement = crate::execution::PathRetirementRecord {
            retirement_id: format!("northstar-01-retirement-{}", ids.slug),
            path_ref: "supervisor-durable-fixed-interface-continuous-self-hosting-program"
                .to_string(),
            retired_refs: vec!["runner-fixture:seeded-pause-resume-demo".to_string()],
            replacement_refs: vec![definition.scenario_id.clone()],
            summary: "The staged continuous-program demo was retired from live-shell support in favor of a shell-first persistent program path.".to_string(),
        };
        store.persist_path_retirement_record(&retirement)?;
        output_refs.extend([
            format!(
                "{NS01_PROGRAM_MAPPING_OUTPUT_PREFIX}{}",
                program_mapping.mapping_id
            ),
            format!(
                "{NS01_RESUME_CHAIN_OUTPUT_PREFIX}{}",
                resume_chain.resume_chain_id
            ),
            format!("{NS01_MATRIX_OUTPUT_PREFIX}{}", acceptance_matrix.matrix_id),
            format!(
                "{NS01_RETIREMENT_OUTPUT_PREFIX}{}",
                retirement.retirement_id
            ),
        ]);
    }

    Ok(output_refs)
}

fn persist_northstar_01_pending_program_records(
    store: &DurableArtifactStore,
    definition: &ScenarioDefinition,
    ids: &ScenarioIds,
    shell: &PendingApprovalShellFlowArtifacts,
) -> Result<Vec<String>, LocalRuntimeError> {
    let support = northstar_path_support_classification(definition);
    let support_ref = support.path_ref.clone();
    store.persist_path_support_classification(&support)?;

    let launch = crate::execution::UniversalShellLaunchAssembly {
        launch_id: format!("northstar-01-launch-{}", ids.slug),
        path_ref: definition.scenario_id.clone(),
        support_class_ref: support_ref.clone(),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        agenda_ref: shell.bundle.runtime_state.task_graph.root_task_id.clone(),
        worker_binding_ref: format!("worker-binding:{}", ids.slug),
        capability_context_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .capability_envelope_ref
            .clone(),
        bootstrap_refs: vec![format!("shell-session:{}", shell.shell_session_id)],
    };
    store.persist_universal_shell_launch_assembly(&launch)?;

    let admission = crate::execution::CampaignAdmissionRecord {
        admission_id: format!("northstar-01-admission-{}", ids.slug),
        launch_ref: launch.launch_id.clone(),
        session_refs: vec![shell.bundle.runtime_state.session.header.session_id.clone()],
        task_refs: vec![shell.bundle.runtime_state.root_task.task_id.clone()],
        initial_state: crate::execution::LaunchAdmissionState::Paused,
        summary: format!(
            "{} entered through one shell-first launch path and remained in governed approval wait.",
            definition.scenario_id
        ),
    };
    store.persist_campaign_admission_record(&admission)?;

    let lifecycle = crate::execution::UnifiedLifecycleTransitionRecord {
        transition_id: format!("northstar-01-lifecycle-{}", ids.slug),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        from_state: "created".to_string(),
        to_state: "awaiting_approval".to_string(),
        turn_ref: shell
            .bundle
            .shell_session
            .latest_turn_ref
            .clone()
            .unwrap_or_else(|| format!("shell-turn-approval-{}", ids.slug)),
        decision_refs: unique_strings(
            shell
                .bundle
                .action_decisions
                .iter()
                .map(|decision| decision.decision_id.clone())
                .chain(
                    shell
                        .bundle
                        .approval_pause_records
                        .iter()
                        .map(|record| record.approval_request_ref.clone()),
                ),
        ),
    };
    store.persist_unified_lifecycle_transition_record(&lifecycle)?;

    let evidence_summary = crate::execution::ShellEvidenceSummary {
        summary_id: format!("northstar-01-evidence-summary-{}", ids.slug),
        launch_ref: launch.launch_id.clone(),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        continuity_ref: shell
            .bundle
            .shell_checkpoints
            .last()
            .map(|checkpoint| checkpoint.shell_checkpoint_id.clone())
            .unwrap_or_else(|| format!("shell-checkpoint-{}", ids.slug)),
        decision_refs: lifecycle.decision_refs.clone(),
        claim_boundary: support.claim_boundary.clone(),
    };
    store.persist_shell_evidence_summary(&evidence_summary)?;

    let export_bundle = crate::execution::ShellDerivedExportBundle {
        export_id: format!("northstar-01-export-{}", ids.slug),
        summary_ref: evidence_summary.summary_id.clone(),
        session_refs: vec![shell.shell_session_id.clone()],
        checkpoint_refs: unique_strings(
            shell
                .bundle
                .shell_checkpoints
                .iter()
                .map(|record| record.shell_checkpoint_id.clone()),
        ),
        memory_refs: unique_strings(
            shell
                .bundle
                .memory_retrieval_traces
                .iter()
                .map(|trace| trace.trace_id.clone())
                .chain(
                    shell
                        .bundle
                        .verified_memory_updates
                        .iter()
                        .map(|record| record.record_id.clone()),
                ),
        ),
        workspace_refs: vec![format!("shell-workspace:{}", ids.slug)],
    };
    store.persist_shell_derived_export_bundle(&export_bundle)?;

    let migration_gate = crate::execution::MigrationGateRecord {
        gate_id: format!("northstar-01-gate-{}", ids.slug),
        path_ref: definition.scenario_id.clone(),
        required_refs: vec![
            launch.launch_id.clone(),
            admission.admission_id.clone(),
            lifecycle.transition_id.clone(),
            export_bundle.export_id.clone(),
        ],
        result: crate::execution::MigrationGateResult::Passed,
        failure_refs: Vec::new(),
    };
    store.persist_migration_gate_record(&migration_gate)?;

    let program_mapping = crate::execution::ProgramToShellMapping {
        mapping_id: format!("northstar-01-program-mapping-{}", ids.slug),
        program_ref: definition.scenario_id.clone(),
        campaign_refs: vec![shell.bundle.runtime_state.session.header.campaign_id.clone()],
        step_refs: shell
            .bundle
            .runtime_state
            .task_graph
            .agenda_items
            .iter()
            .map(|item| item.agenda_item_id.clone())
            .collect(),
        budget_ref: format!("budget:{}", ids.slug),
        summary:
            "Continuous program steps were expressed through one shell campaign while approval wait remained explicit."
                .to_string(),
    };
    store.persist_program_to_shell_mapping(&program_mapping)?;

    let resume_chain = crate::execution::ResumeChainRecord {
        resume_chain_id: format!("northstar-01-resume-chain-{}", ids.slug),
        checkpoint_refs: export_bundle.checkpoint_refs.clone(),
        resume_trigger_ref: shell.approval_request.approval_request_id.clone(),
        campaign_ref: shell
            .bundle
            .runtime_state
            .session
            .header
            .campaign_id
            .clone(),
        outcome_ref: lifecycle.transition_id.clone(),
    };
    store.persist_resume_chain_record(&resume_chain)?;

    let acceptance_matrix = crate::execution::AcceptanceTruthMatrix {
        matrix_id: format!("northstar-01-matrix-{}", ids.slug),
        path_refs: curated_scenarios()
            .iter()
            .map(|scenario| scenario.scenario_id.clone())
            .collect(),
        support_expectations: curated_scenarios()
            .iter()
            .map(|scenario| {
                let support = northstar_path_support_classification(scenario);
                format!("{}={:?}", scenario.scenario_id, support.support_class)
            })
            .collect(),
        provenance_expectations: vec![
            "launch".to_string(),
            "admission".to_string(),
            "lifecycle".to_string(),
            "shell-export".to_string(),
        ],
        deprecation_expectations: curated_scenarios()
            .iter()
            .filter(|scenario| scenario.runtime_class == ScenarioRuntimeClass::ReferenceDemo)
            .map(|scenario| format!("{}=unsupported", scenario.scenario_id))
            .collect(),
    };
    store.persist_acceptance_truth_matrix(&acceptance_matrix)?;

    Ok(vec![
        format!(
            "{NS01_SUPPORT_OUTPUT_PREFIX}{}",
            northstar_safe_output_stem(&support.path_ref)
        ),
        format!("{NS01_LAUNCH_OUTPUT_PREFIX}{}", launch.launch_id),
        format!("{NS01_ADMISSION_OUTPUT_PREFIX}{}", admission.admission_id),
        format!("{NS01_LIFECYCLE_OUTPUT_PREFIX}{}", lifecycle.transition_id),
        format!(
            "{NS01_EVIDENCE_SUMMARY_OUTPUT_PREFIX}{}",
            evidence_summary.summary_id
        ),
        format!(
            "{NS01_EXPORT_BUNDLE_OUTPUT_PREFIX}{}",
            export_bundle.export_id
        ),
        format!(
            "{NS01_PROGRAM_MAPPING_OUTPUT_PREFIX}{}",
            program_mapping.mapping_id
        ),
        format!(
            "{NS01_RESUME_CHAIN_OUTPUT_PREFIX}{}",
            resume_chain.resume_chain_id
        ),
        format!("{NS01_GATE_OUTPUT_PREFIX}{}", migration_gate.gate_id),
        format!("{NS01_MATRIX_OUTPUT_PREFIX}{}", acceptance_matrix.matrix_id),
    ])
}

fn workflow_label(kind: crate::execution::NativeWorkflowKind) -> &'static str {
    match kind {
        crate::execution::NativeWorkflowKind::Build => "build",
        crate::execution::NativeWorkflowKind::Validation => "validation",
        crate::execution::NativeWorkflowKind::Packaging => "packaging",
        crate::execution::NativeWorkflowKind::Review => "review",
        crate::execution::NativeWorkflowKind::Scheduling => "scheduling",
        crate::execution::NativeWorkflowKind::Continuity => "continuity",
        crate::execution::NativeWorkflowKind::OperationalAttestation => "operational-attestation",
    }
}

fn workflow_service_family(
    kind: crate::execution::NativeWorkflowKind,
) -> crate::execution::NativeServiceFamily {
    match kind {
        crate::execution::NativeWorkflowKind::Build => crate::execution::NativeServiceFamily::Build,
        crate::execution::NativeWorkflowKind::Validation => {
            crate::execution::NativeServiceFamily::Validation
        }
        crate::execution::NativeWorkflowKind::Packaging => {
            crate::execution::NativeServiceFamily::Packaging
        }
        crate::execution::NativeWorkflowKind::Review => {
            crate::execution::NativeServiceFamily::Review
        }
        crate::execution::NativeWorkflowKind::Scheduling => {
            crate::execution::NativeServiceFamily::Scheduling
        }
        crate::execution::NativeWorkflowKind::Continuity => {
            crate::execution::NativeServiceFamily::Continuity
        }
        crate::execution::NativeWorkflowKind::OperationalAttestation => {
            crate::execution::NativeServiceFamily::Operations
        }
    }
}

fn workflow_world_ref(kind: crate::execution::NativeWorkflowKind) -> &'static str {
    match kind {
        crate::execution::NativeWorkflowKind::Build => "world:component-build",
        crate::execution::NativeWorkflowKind::Validation => "world:component-validation",
        crate::execution::NativeWorkflowKind::Packaging => "world:component-package",
        crate::execution::NativeWorkflowKind::Review => "world:operator-review",
        crate::execution::NativeWorkflowKind::Scheduling => "world:bounded-scheduler",
        crate::execution::NativeWorkflowKind::Continuity => "world:memory-continuity",
        crate::execution::NativeWorkflowKind::OperationalAttestation => "world:governed-operations",
    }
}

fn persist_northstar_03_service_records(
    store: &DurableArtifactStore,
    ids: &ScenarioIds,
    run_ref: &str,
    owner_ref: &str,
    workflows: &[crate::execution::NativeWorkflowKind],
) -> Result<Vec<String>, LocalRuntimeError> {
    let mut output_refs = Vec::new();
    for workflow_kind in workflows.iter().copied().collect::<BTreeSet<_>>() {
        let label = workflow_label(workflow_kind);
        let family = workflow_service_family(workflow_kind);
        let workflow_ref = format!("workflow:{label}");
        let effect_ref = format!("effect:{label}:{}", ids.slug);
        let manifest = crate::execution::ServiceFamilyManifest {
            service_manifest_id: format!("northstar-03-manifest-{label}-{}", ids.slug),
            service_family: family,
            classification: crate::execution::ServiceFamilyClassification::Mandatory,
            world_ref: workflow_world_ref(workflow_kind).to_string(),
            handle_schema_ref: format!("handle-schema:{label}:{}", ids.slug),
            authority_requirements: vec![
                "authority:bounded".to_string(),
                "approval:governed".to_string(),
            ],
            workflow_coverage_refs: vec![workflow_ref.clone()],
            closure_criteria_refs: vec![
                format!("criteria:{label}:required-services-present"),
                format!("criteria:{label}:attestation-complete"),
            ],
            attestation_policy_ref: format!("attestation-policy:{label}:{}", ids.slug),
            closure_policy_ref: format!("closure-policy:{label}:{}", ids.slug),
            closure_state: crate::execution::ServiceClosureState::Closed,
        };
        let handle = crate::execution::ServiceHandleLease {
            service_handle_id: format!("northstar-03-handle-{label}-{}", ids.slug),
            service_manifest_ref: manifest.service_manifest_id.clone(),
            owner_ref: owner_ref.to_string(),
            authority_ref: format!("authority-ref:{label}:{}", ids.slug),
            workflow_ref: workflow_ref.clone(),
            lease_policy_ref: format!("lease-policy:{label}:{}", ids.slug),
            effect_refs: vec![effect_ref.clone()],
            audit_refs: vec![format!("audit:{label}:{}", ids.slug)],
        };
        let attestation = crate::execution::ServiceAttestationBundle {
            attestation_id: format!("northstar-03-attestation-{label}-{}", ids.slug),
            service_manifest_ref: manifest.service_manifest_id.clone(),
            workflow_ref: workflow_ref.clone(),
            handle_ref: handle.service_handle_id.clone(),
            effect_ref: effect_ref.clone(),
            authority_ref: handle.authority_ref.clone(),
            compatibility_refs: vec![format!("compatibility:{label}:{}", ids.slug)],
            review_refs: vec![format!("review:{label}:{}", ids.slug)],
            rollback_refs: vec![format!("rollback:{label}:{}", ids.slug)],
            evidence_refs: vec![run_ref.to_string(), effect_ref.clone()],
            decision: crate::execution::ServiceAttestationDecision::Closed,
        };
        let family_dossier = crate::execution::ServiceClosureDossier {
            closure_dossier_id: format!("northstar-03-dossier-{label}-{}", ids.slug),
            service_family: family,
            required_refs: vec![
                manifest.service_manifest_id.clone(),
                handle.service_handle_id.clone(),
                attestation.attestation_id.clone(),
            ],
            gap_refs: Vec::new(),
            decision_ref: attestation.attestation_id.clone(),
            claim_boundary: format!(
                "{label} service family is closed for bounded local-first workflow execution only."
            ),
        };
        let sufficiency = crate::execution::WorkflowSufficiencyRecord {
            workflow_sufficiency_id: format!(
                "northstar-03-workflow-sufficiency-{label}-{}",
                ids.slug
            ),
            workflow_kind,
            required_service_refs: vec![manifest.service_manifest_id.clone()],
            present_service_refs: vec![manifest.service_manifest_id.clone()],
            transitional_gap_refs: Vec::new(),
            closure_status: crate::execution::WorkflowClosureStatus::ClosureGrade,
            supporting_run_refs: vec![run_ref.to_string()],
            summary: format!("{label} workflow satisfied all required native service families."),
        };
        let workflow_dossier = crate::execution::WorkflowServiceClosureDossier {
            workflow_dossier_id: format!("northstar-03-workflow-dossier-{label}-{}", ids.slug),
            workflow_kind,
            required_service_refs: vec![manifest.service_manifest_id.clone()],
            service_handle_refs: vec![handle.service_handle_id.clone()],
            attestation_refs: vec![attestation.attestation_id.clone()],
            transitional_gap_refs: Vec::new(),
            closure_status: crate::execution::WorkflowClosureStatus::ClosureGrade,
            claim_boundary: format!(
                "{label} workflow closure remains bounded, governed, and local-first."
            ),
            summary: format!(
                "{label} workflow closure is supported by manifest, handle, and attestation evidence."
            ),
        };
        store.persist_service_family_manifest(&manifest)?;
        store.persist_service_handle_lease(&handle)?;
        store.persist_service_attestation_bundle(&attestation)?;
        store.persist_service_closure_dossier(&family_dossier)?;
        store.persist_workflow_sufficiency_record(&sufficiency)?;
        store.persist_workflow_service_closure_dossier(&workflow_dossier)?;
        output_refs.extend([
            format!(
                "{NS03_SERVICE_MANIFEST_OUTPUT_PREFIX}{}",
                manifest.service_manifest_id
            ),
            format!(
                "{NS03_SERVICE_HANDLE_OUTPUT_PREFIX}{}",
                handle.service_handle_id
            ),
            format!(
                "{NS03_SERVICE_ATTESTATION_OUTPUT_PREFIX}{}",
                attestation.attestation_id
            ),
            format!(
                "{NS03_SERVICE_DOSSIER_OUTPUT_PREFIX}{}",
                family_dossier.closure_dossier_id
            ),
            format!(
                "{NS03_WORKFLOW_SUFFICIENCY_OUTPUT_PREFIX}{}",
                sufficiency.workflow_sufficiency_id
            ),
            format!(
                "{NS03_WORKFLOW_DOSSIER_OUTPUT_PREFIX}{}",
                workflow_dossier.workflow_dossier_id
            ),
        ]);
    }
    Ok(output_refs)
}

