fn persist_northstar_04_ecology_records(
    store: &DurableArtifactStore,
    ids: &ScenarioIds,
    campaign_ref: &str,
    task_ref: &str,
    role_kinds: &[crate::execution::WorkerRoleKind],
    recovery_trigger_refs: Vec<String>,
    rollback_refs: Vec<String>,
    summary_label: &str,
) -> Result<Vec<String>, LocalRuntimeError> {
    let role_kinds = role_kinds.iter().copied().collect::<BTreeSet<_>>();
    let mut worker_card_refs = Vec::new();
    let mut work_lease_refs = Vec::new();
    let mut output_refs = Vec::new();
    let planning_id = format!("northstar-04-planning-{}", ids.slug);
    let routing_packet_id = format!("northstar-04-routing-packet-{}", ids.slug);
    let synthesis_id = format!("northstar-04-synthesis-{}", ids.slug);

    for role_kind in role_kinds.iter().copied() {
        let label = worker_role_label(role_kind);
        let card = crate::execution::WorkerSpecializationCard {
            worker_card_id: format!("northstar-04-card-{label}-{}", ids.slug),
            role_kind,
            world_refs: vec![format!("world:{label}")],
            capability_ref: worker_role_capability(role_kind).to_string(),
            service_dependency_refs: worker_role_service_dependencies(role_kind),
            preferred_work_refs: worker_role_preferred_work(role_kind),
            ownership_scope: format!("scope:{label}:{}", ids.slug),
            responsibility_boundary: format!(
                "{label} stays within one bounded local-first responsibility boundary."
            ),
            routing_requirements: vec![format!("route:{label}:eligible")],
            failure_budget_ref: format!("failure-budget:{label}:{}", ids.slug),
            production_mode: None,
            production_program_instance_ref: None,
            production_turn_package_ref: None,
            production_parsed_turn_result_ref: None,
            production_cycle_ref: None,
            lineage_ref: None,
            production_summary: None,
        };
        let work_lease = crate::execution::WorkLease {
            work_lease_id: format!("northstar-04-work-lease-{label}-{}", ids.slug),
            campaign_ref: campaign_ref.to_string(),
            task_ref: task_ref.to_string(),
            worker_card_ref: card.worker_card_id.clone(),
            lease_budget_ref: format!("lease-budget:{label}:{}", ids.slug),
            output_requirements: vec![
                format!("deliverable:{label}:bounded-output"),
                format!("deliverable:{label}:handoff-ready"),
            ],
            handoff_refs: vec![routing_packet_id.clone(), synthesis_id.clone()],
        };
        store.persist_worker_specialization_card(&card)?;
        store.persist_work_lease(&work_lease)?;
        worker_card_refs.push(card.worker_card_id.clone());
        work_lease_refs.push(work_lease.work_lease_id.clone());
        output_refs.push(format!(
            "{NS04_WORKER_CARD_OUTPUT_PREFIX}{}",
            card.worker_card_id
        ));
        output_refs.push(format!(
            "{NS04_WORK_LEASE_OUTPUT_PREFIX}{}",
            work_lease.work_lease_id
        ));
    }

    let snapshot = crate::execution::EcologySnapshot {
        ecology_snapshot_id: format!("northstar-04-ecology-{}", ids.slug),
        worker_card_refs: worker_card_refs.clone(),
        capability_mix_refs: role_kinds
            .iter()
            .map(|kind| worker_role_capability(*kind).to_string())
            .collect(),
        lease_refs: work_lease_refs.clone(),
        performance_refs: vec![
            format!("performance:{summary_label}:balanced"),
            format!("performance:{summary_label}:traceable"),
        ],
        drift_refs: vec!["drift:none".to_string()],
        summary: format!(
            "{summary_label} ecology remained specialized, attributable, and governed."
        ),
    };
    let planning = crate::execution::CoordinatorPlanningRecord {
        planning_id: planning_id.clone(),
        campaign_ref: campaign_ref.to_string(),
        agenda_refs: vec![format!("agenda:{}", ids.slug)],
        routing_refs: vec![routing_packet_id.clone()],
        synthesis_target_ref: synthesis_id.clone(),
        summary: format!("{summary_label} coordinator planned one bounded worker ecology agenda."),
    };
    let synthesis = crate::execution::SynthesisDossier {
        synthesis_id: synthesis_id.clone(),
        input_refs: work_lease_refs.clone(),
        conflict_refs: vec!["conflict:none".to_string()],
        coordinator_ref: planning.planning_id.clone(),
        decision_ref: format!("synthesis-decision:{}", ids.slug),
        summary: format!("{summary_label} synthesis remained explicit and conflict-aware."),
    };
    let routing = crate::execution::RoutingPacketRecord {
        routing_packet_id: routing_packet_id.clone(),
        agenda_ref: planning.agenda_refs[0].clone(),
        worker_selection_refs: worker_card_refs.clone(),
        synthesis_ref: synthesis.synthesis_id.clone(),
        quality_ref: format!("quality:{summary_label}:accepted"),
        fallback_ref: format!(
            "fallback:{}",
            worker_card_refs
                .last()
                .cloned()
                .unwrap_or_else(|| format!("fallback:{}", ids.slug))
        ),
        summary: format!("{summary_label} routing stayed explicit, reviewable, and recoverable."),
    };
    let recovery = crate::execution::EcologyRecoveryRecord {
        recovery_id: format!("northstar-04-recovery-{}", ids.slug),
        ecology_snapshot_ref: snapshot.ecology_snapshot_id.clone(),
        trigger_refs: recovery_trigger_refs,
        reroute_refs: vec![
            routing.routing_packet_id.clone(),
            synthesis.synthesis_id.clone(),
        ],
        rollback_refs,
        outcome_ref: format!("outcome:{summary_label}:stable"),
        summary: format!("{summary_label} recovery law remained explicit and rollback-aware."),
    };
    let health = crate::execution::EcologyHealthRecord {
        health_record_id: format!("northstar-04-health-{}", ids.slug),
        ecology_snapshot_ref: snapshot.ecology_snapshot_id.clone(),
        lease_failure_refs: vec!["lease-failure:none".to_string()],
        bottleneck_refs: vec!["bottleneck:review-wait".to_string()],
        drift_refs: vec!["drift:none".to_string()],
        load_refs: vec![format!("load:{summary_label}:balanced")],
        fairness_refs: vec![format!("fairness:{summary_label}:bounded")],
        degradation_refs: vec![format!("degradation:{summary_label}:recoverable")],
        recovery_refs: vec![recovery.recovery_id.clone()],
        recommendation_ref: "continue".to_string(),
    };

    store.persist_ecology_snapshot(&snapshot)?;
    store.persist_coordinator_planning_record(&planning)?;
    store.persist_synthesis_dossier(&synthesis)?;
    store.persist_routing_packet_record(&routing)?;
    store.persist_ecology_recovery_record(&recovery)?;
    store.persist_ecology_health_record(&health)?;
    output_refs.extend([
        format!(
            "{NS04_ECOLOGY_SNAPSHOT_OUTPUT_PREFIX}{}",
            snapshot.ecology_snapshot_id
        ),
        format!("{NS04_PLANNING_OUTPUT_PREFIX}{}", planning.planning_id),
        format!("{NS04_SYNTHESIS_OUTPUT_PREFIX}{}", synthesis.synthesis_id),
        format!("{NS04_HEALTH_OUTPUT_PREFIX}{}", health.health_record_id),
        format!(
            "{NS04_ROUTING_PACKET_OUTPUT_PREFIX}{}",
            routing.routing_packet_id
        ),
        format!(
            "{NS04_RECOVERY_RECORD_OUTPUT_PREFIX}{}",
            recovery.recovery_id
        ),
    ]);
    Ok(output_refs)
}

fn persist_northstar_05_program_records(
    store: &DurableArtifactStore,
    ids: &ScenarioIds,
    root_factory_ref: &str,
    lineage_refs: Vec<String>,
    generation_agenda_refs: Vec<(String, String, Vec<String>, Vec<String>, Vec<String>)>,
) -> Result<Vec<String>, LocalRuntimeError> {
    let budget = crate::execution::RecursionBudgetRecord {
        recursion_budget_id: format!("northstar-05-budget-{}", ids.slug),
        max_depth: 3,
        max_campaigns: 2,
        risk_threshold_refs: vec![
            "risk:rollback-pressure".to_string(),
            "risk:lineage-drift".to_string(),
        ],
        exhaustion_policy: "pause_and_preserve_best_lineage".to_string(),
    };
    let program = crate::execution::FactoryImprovementProgram {
        improvement_program_id: format!("northstar-05-program-{}", ids.slug),
        root_factory_ref: root_factory_ref.to_string(),
        goal_refs: vec![
            "goal:improve-replayability".to_string(),
            "goal:improve-service-closure".to_string(),
        ],
        recursion_budget_ref: budget.recursion_budget_id.clone(),
        program_state: crate::execution::FactoryProgramState::Paused,
        lineage_refs: lineage_refs.clone(),
    };
    store.persist_recursion_budget_record(&budget)?;
    store.persist_factory_improvement_program(&program)?;

    let mut output_refs = vec![
        format!(
            "{NS05_PROGRAM_OUTPUT_PREFIX}{}",
            program.improvement_program_id
        ),
        format!(
            "{NS05_RECURSION_BUDGET_OUTPUT_PREFIX}{}",
            budget.recursion_budget_id
        ),
    ];
    let mut agenda_ids = Vec::new();
    for (agenda_id, candidate_factory_ref, proving_refs, observation_refs, decision_refs) in
        generation_agenda_refs
    {
        let agenda = crate::execution::LaterFactoryGenerationAgenda {
            generation_agenda_id: agenda_id.clone(),
            parent_factory_ref: root_factory_ref.to_string(),
            candidate_factory_ref: candidate_factory_ref.clone(),
            proving_refs,
            observation_refs: observation_refs.clone(),
            decision_refs: decision_refs.clone(),
        };
        let adoption_window = crate::execution::AdoptionWindowRecord {
            adoption_window_id: format!(
                "northstar-05-adoption-window-{}-{}",
                ids.slug,
                agenda_ids.len()
            ),
            candidate_factory_ref,
            observation_refs,
            rollback_refs: vec![format!("rollback:{}", ids.slug)],
            result: crate::execution::AdoptionWindowResult::Paused,
        };
        store.persist_later_factory_generation_agenda(&agenda)?;
        store.persist_adoption_window_record(&adoption_window)?;
        agenda_ids.push(agenda.generation_agenda_id.clone());
        output_refs.extend([
            format!(
                "{NS05_GENERATION_AGENDA_OUTPUT_PREFIX}{}",
                agenda.generation_agenda_id
            ),
            format!(
                "{NS05_ADOPTION_WINDOW_OUTPUT_PREFIX}{}",
                adoption_window.adoption_window_id
            ),
        ]);
    }
    let lineage_health = crate::execution::LineageHealthDossier {
        lineage_health_id: format!("northstar-05-lineage-health-{}", ids.slug),
        lineage_refs,
        comparison_refs: vec!["comparison:lineage-trend".to_string()],
        risk_refs: vec!["risk:governance-pressure".to_string()],
        trend_refs: vec!["trend:improving-service-closure".to_string()],
        recommendation_ref: "pause_for_operator_review".to_string(),
    };
    let stop_condition = crate::execution::StopConditionRecord {
        stop_condition_id: format!("northstar-05-stop-condition-{}", ids.slug),
        program_ref: program.improvement_program_id.clone(),
        trigger_refs: vec![
            budget.recursion_budget_id.clone(),
            lineage_health.lineage_health_id.clone(),
        ],
        decision: crate::execution::StopConditionDecision::Pause,
        operator_guidance:
            "Review the current lineage before admitting another later-factory cycle.".to_string(),
    };
    store.persist_lineage_health_dossier(&lineage_health)?;
    store.persist_stop_condition_record(&stop_condition)?;
    output_refs.extend([
        format!(
            "{NS05_LINEAGE_HEALTH_OUTPUT_PREFIX}{}",
            lineage_health.lineage_health_id
        ),
        format!(
            "{NS05_STOP_CONDITION_OUTPUT_PREFIX}{}",
            stop_condition.stop_condition_id
        ),
    ]);
    Ok(output_refs)
}

fn persist_northstar_06_ecosystem_records(
    store: &DurableArtifactStore,
    ids: &ScenarioIds,
    sender_identity_ref: &str,
    receiver_identity_ref: &str,
    packet_refs: Vec<String>,
    compatibility_refs: Vec<String>,
    import_refs: Vec<String>,
    review_refs: Vec<String>,
) -> Result<Vec<String>, LocalRuntimeError> {
    let sender_trust = crate::execution::TrustProfile {
        trust_profile_id: format!("northstar-06-trust-sender-{}", ids.slug),
        factory_identity_ref: sender_identity_ref.to_string(),
        allowed_exchange_classes: vec![
            crate::execution::FactoryExchangePacketClass::LineageImport,
            crate::execution::FactoryExchangePacketClass::MemoryExchange,
        ],
        adoption_scope: "local_first_only".to_string(),
        review_requirements: vec!["review:local-compatibility".to_string()],
        revocation_policy_ref: format!("revocation-policy:sender:{}", ids.slug),
    };
    let receiver_trust = crate::execution::TrustProfile {
        trust_profile_id: format!("northstar-06-trust-receiver-{}", ids.slug),
        factory_identity_ref: receiver_identity_ref.to_string(),
        allowed_exchange_classes: vec![
            crate::execution::FactoryExchangePacketClass::LineageImport,
            crate::execution::FactoryExchangePacketClass::MemoryExchange,
        ],
        adoption_scope: "bounded_review_only".to_string(),
        review_requirements: vec!["review:operator-approval".to_string()],
        revocation_policy_ref: format!("revocation-policy:receiver:{}", ids.slug),
    };
    let sender_admission = crate::execution::EcosystemAdmissionRecord {
        admission_id: format!("northstar-06-admission-sender-{}", ids.slug),
        factory_identity_ref: sender_identity_ref.to_string(),
        trust_profile_ref: sender_trust.trust_profile_id.clone(),
        compatibility_profile_ref: format!("compatibility-profile:sender:{}", ids.slug),
        decision: crate::execution::EcosystemAdmissionDecision::Admitted,
        summary: "sending factory admitted into the bounded local ecosystem".to_string(),
    };
    let receiver_admission = crate::execution::EcosystemAdmissionRecord {
        admission_id: format!("northstar-06-admission-receiver-{}", ids.slug),
        factory_identity_ref: receiver_identity_ref.to_string(),
        trust_profile_ref: receiver_trust.trust_profile_id.clone(),
        compatibility_profile_ref: format!("compatibility-profile:receiver:{}", ids.slug),
        decision: crate::execution::EcosystemAdmissionDecision::Admitted,
        summary: "receiving factory admitted into the bounded local ecosystem".to_string(),
    };
    let route = crate::execution::ExchangeRouteRecord {
        route_id: format!("northstar-06-route-{}", ids.slug),
        sender_factory_ref: sender_identity_ref.to_string(),
        receiver_factory_ref: receiver_identity_ref.to_string(),
        packet_refs,
        compatibility_refs: compatibility_refs.clone(),
        delivery_result_ref: "delivered".to_string(),
    };
    let route_cycle = crate::execution::RouteCompatibilityCycle {
        compatibility_cycle_id: format!("northstar-06-route-cycle-{}", ids.slug),
        route_ref: route.route_id.clone(),
        profile_refs: vec![
            sender_trust.trust_profile_id.clone(),
            receiver_trust.trust_profile_id.clone(),
        ],
        pressure_refs: vec!["pressure:bounded".to_string()],
        decision_ref: "continue".to_string(),
    };
    let adoption = crate::execution::CrossFactoryAdoptionDossier {
        adoption_dossier_id: format!("northstar-06-adoption-{}", ids.slug),
        receiver_factory_ref: receiver_identity_ref.to_string(),
        route_ref: route.route_id.clone(),
        import_refs,
        review_refs,
        result: crate::execution::CrossFactoryAdoptionResult::Adopted,
    };
    let rollback = crate::execution::EcosystemRollbackChoreographyRecord {
        rollback_choreography_id: format!("northstar-06-rollback-{}", ids.slug),
        affected_factory_refs: vec![
            sender_identity_ref.to_string(),
            receiver_identity_ref.to_string(),
        ],
        adoption_refs: vec![adoption.adoption_dossier_id.clone()],
        rollback_steps: vec![
            "quarantine imported lineage".to_string(),
            "revoke local adoption".to_string(),
        ],
        quarantine_refs: vec!["ecosystem-quarantine:none-active".to_string()],
        completion_ref: "rollback-ready".to_string(),
    };
    let workspace_snapshot = crate::execution::EcosystemWorkspaceSnapshot {
        workspace_id: format!("northstar-06-workspace-{}", ids.slug),
        factory_refs: vec![
            sender_identity_ref.to_string(),
            receiver_identity_ref.to_string(),
        ],
        trust_refs: vec![
            sender_trust.trust_profile_id.clone(),
            receiver_trust.trust_profile_id.clone(),
        ],
        route_refs: vec![route.route_id.clone()],
        adoption_refs: vec![adoption.adoption_dossier_id.clone()],
        health_refs: vec![format!("northstar-06-health-{}", ids.slug)],
    };
    let health_snapshot = crate::execution::EcosystemHealthSnapshot {
        ecosystem_snapshot_id: format!("northstar-06-health-{}", ids.slug),
        route_pressure_refs: vec!["pressure:stable".to_string()],
        adoption_stability_refs: vec!["stability:bounded-adoption".to_string()],
        quarantine_refs: vec!["quarantine:none-active".to_string()],
        rollback_refs: vec![rollback.rollback_choreography_id.clone()],
        claim_boundary: "Bounded local-first ecosystem only.".to_string(),
    };
    for record in [&sender_trust, &receiver_trust] {
        store.persist_trust_profile(record)?;
    }
    for record in [&sender_admission, &receiver_admission] {
        store.persist_ecosystem_admission_record(record)?;
    }
    store.persist_exchange_route_record(&route)?;
    store.persist_route_compatibility_cycle(&route_cycle)?;
    store.persist_cross_factory_adoption_dossier(&adoption)?;
    store.persist_ecosystem_rollback_choreography_record(&rollback)?;
    store.persist_ecosystem_workspace_snapshot(&workspace_snapshot)?;
    store.persist_ecosystem_health_snapshot(&health_snapshot)?;
    Ok(vec![
        format!(
            "{NS06_TRUST_PROFILE_OUTPUT_PREFIX}{}",
            sender_trust.trust_profile_id
        ),
        format!(
            "{NS06_TRUST_PROFILE_OUTPUT_PREFIX}{}",
            receiver_trust.trust_profile_id
        ),
        format!(
            "{NS06_ADMISSION_OUTPUT_PREFIX}{}",
            sender_admission.admission_id
        ),
        format!(
            "{NS06_ADMISSION_OUTPUT_PREFIX}{}",
            receiver_admission.admission_id
        ),
        format!("{NS06_ROUTE_OUTPUT_PREFIX}{}", route.route_id),
        format!(
            "{NS06_ROUTE_CYCLE_OUTPUT_PREFIX}{}",
            route_cycle.compatibility_cycle_id
        ),
        format!(
            "{NS06_ADOPTION_DOSSIER_OUTPUT_PREFIX}{}",
            adoption.adoption_dossier_id
        ),
        format!(
            "{NS06_ROLLBACK_CHOREOGRAPHY_OUTPUT_PREFIX}{}",
            rollback.rollback_choreography_id
        ),
        format!(
            "{NS06_WORKSPACE_OUTPUT_PREFIX}{}",
            workspace_snapshot.workspace_id
        ),
        format!(
            "{NS06_HEALTH_OUTPUT_PREFIX}{}",
            health_snapshot.ecosystem_snapshot_id
        ),
    ])
}

fn live_v4_manifest(build_id: impl Into<String>, ids: &ScenarioIds) -> GenerationManifest {
    let build_id = build_id.into();
    GenerationManifest::new(
        format!("generation-{}-{build_id}", ids.slug),
        None,
        "package:aiaf/supervisor@v4",
        "aiaf-supervisor-v4",
        vec![format!("src:{}", ids.slug)],
        vec!["policy:bounded-single-factory".to_string()],
        vec![format!("input:{}", ids.slug)],
        format!("live v4 shell-backed manifest for {}", ids.slug),
    )
    .expect("live v4 manifest should remain valid")
}

fn live_v4_approval_component(
    ids: &ScenarioIds,
    shell_session_id: &str,
) -> Result<BuiltWorkerComponent, LocalRuntimeError> {
    let build = build_component_package(ComponentBuildRequest {
        build_id: format!("build-approval-{}", ids.slug),
        manifest: live_v4_manifest("approval", ids),
        wit_source:
            "world aiaf-supervisor-v4 { import approval-request: func(); export request-approval: func(); }"
                .to_string(),
        component_source: r#"
            (component
                (import "approval-request" (func $approval))
                (core func $approval-core (canon lower (func $approval)))
                (core module $m
                    (import "" "approval-request" (func $approval))
                    (func (export "request-approval")
                        call $approval))
                (core instance $i (instantiate $m
                    (with "" (instance
                        (export "approval-request" (func $approval-core))))))
                (func $request-approval (canon lift (core func $i "request-approval")))
                (export "request-approval" (func $request-approval)))
        "#.to_string(),
        required_capability_world_refs: vec!["world:approval".to_string()],
    })
    .map_err(|error| LocalRuntimeError::Storage(error.to_string()))?;
    let context = ComponentExecutionContext {
        capability_envelope: CapabilityEnvelope {
            envelope_id: format!("envelope-approval-{}", ids.slug),
            actor_scope: format!("worker-component-{}", ids.slug),
            world_grants: vec![CapabilityWorldGrant {
                world: CapabilityWorld::ApprovalGateway,
                allowed_operations: vec!["request-approval".to_string()],
                default_authority_class: AuthorityClass::CampaignControl,
                default_approval_class: ApprovalClass::AutoAllowed,
                operation_approval_overrides: Vec::new(),
            }],
            authority_ceiling: AuthorityClass::CampaignControl,
            isolation_profile: IsolationProfile::ArtifactSandbox,
            allowed_resource_scopes: vec![format!("scope:{shell_session_id}")],
            approval_overrides: Vec::new(),
            quota_policy: None,
            campaign_scope: None,
            epoch_scope: None,
        },
        import_bindings: vec![ComponentImportBinding {
            import_name: "approval-request".to_string(),
            world: CapabilityWorld::ApprovalGateway,
            operation: "request-approval".to_string(),
            resource_scope: format!("scope:{shell_session_id}"),
            required_authority_class: AuthorityClass::CampaignControl,
        }],
    };
    Ok(BuiltWorkerComponent { build, context })
}

