fn scenario_definition(scenario_id: &str) -> Option<ScenarioDefinition> {
    curated_scenarios()
        .into_iter()
        .find(|definition| definition.scenario_id == scenario_id)
}

fn approval_request_for(
    memory_store: &MemoryStore,
    approval_request_id: &str,
) -> Option<ApprovalRequest> {
    memory_store
        .approval_lineage(approval_request_id)
        .into_iter()
        .find_map(|artifact| match &artifact.payload {
            MemoryArtifactPayload::ApprovalRequest(request) => Some(request.clone()),
            _ => None,
        })
}

fn seeded_memory_store(
    ids: &ScenarioIds,
    topic_summary: &str,
    governance_constraints: &[String],
) -> MemoryStore {
    let mut memory_store = MemoryStore::default();
    memory_store.insert_pointer_index(PointerIndex {
        index_id: ids.pointer_index_id.clone(),
        scope: MemoryScope::Campaign(ids.campaign_id.clone()),
        entry_refs: vec![ids.task_id.clone(), ids.topic_bundle_id.clone()],
        contested_refs: Vec::new(),
        critical_refs: vec![ids.task_id.clone(), ids.topic_bundle_id.clone()],
        governance_constraints: governance_constraints.to_vec(),
        open_task_refs: vec![ids.task_id.clone()],
        updated_at: "seeded".to_string(),
    });
    memory_store.add_topic_bundle(TopicBundle {
        bundle_id: ids.topic_bundle_id.clone(),
        bundle_class: TopicBundleClass::CampaignOperatingNotes,
        scope: MemoryScope::Campaign(ids.campaign_id.clone()),
        summary: topic_summary.to_string(),
        evidence_refs: vec![ids.task_id.clone()],
        freshness_policy: "local-run-bundle".to_string(),
    });
    memory_store.add_transcript_slice(TranscriptSlice {
        slice_id: ids.transcript_slice_id.clone(),
        campaign_id: ids.campaign_id.clone(),
        epoch_id: ids.epoch_id.clone(),
        session_id: Some(ids.session_id.clone()),
        task_id: Some(ids.task_id.clone()),
        referenced_artifacts: vec![ids.task_id.clone(), ids.topic_bundle_id.clone()],
        summary: topic_summary.to_string(),
        excerpts: vec!["local observer bundle".to_string()],
    });
    memory_store
}

fn ownership_boundary_for(
    ids: &ScenarioIds,
    scope_suffix: &str,
    mode: OwnershipMode,
) -> OwnershipBoundary {
    OwnershipBoundary {
        boundary_id: format!("boundary-{}-{scope_suffix}", ids.slug),
        resource_scope: format!("{}:{scope_suffix}", ids.campaign_id),
        mode,
        owner_actor_ref: ids.session_id.clone(),
    }
}

fn agenda_item_with_status(
    ids: &ScenarioIds,
    item_suffix: &str,
    task_kind: &str,
    status: AgendaStatus,
    assigned_worker_id: Option<String>,
    output_refs: Vec<String>,
    ownership_mode: OwnershipMode,
) -> AgendaItem {
    let mut agenda_item = AgendaItem::new(
        format!("agenda-{}-{item_suffix}", ids.slug),
        format!("worker-task-{}-{item_suffix}", ids.slug),
        task_kind.to_string(),
        Vec::new(),
        ownership_boundary_for(ids, item_suffix, ownership_mode),
    );
    agenda_item.status = status;
    agenda_item.assigned_worker_id = assigned_worker_id;
    agenda_item.output_refs = output_refs;
    agenda_item
}

fn completed_runtime_state(
    ids: &ScenarioIds,
    summary: &str,
    output_refs: Vec<String>,
    audits: Vec<(AuditRecordClass, String, String)>,
) -> ReplayableRuntimeState {
    let mut session = ExecutionSession::new(ExecutionSessionHeader {
        session_id: ids.session_id.clone(),
        actor_kind: ActorKind::Supervisor,
        actor_id: "supervisor-local-runner".to_string(),
        campaign_id: ids.campaign_id.clone(),
        epoch_id: ids.epoch_id.clone(),
        capability_envelope_ref: format!("envelope-{}", ids.slug),
        parent_session_id: None,
    });
    session.state = ExecutionSessionState::Completed;
    session.active_task_id = Some(ids.task_id.clone());

    let mut task = TaskArtifact::new(ids.task_id.clone(), summary);
    task.state = TaskState::Completed;
    task.owner_session_id = Some(ids.session_id.clone());
    task.output_refs = output_refs;

    let mut memory_store = seeded_memory_store(
        ids,
        summary,
        &[
            "local observer bundle is report-first".to_string(),
            "stable execution contract remains unchanged".to_string(),
        ],
    );
    for (class, related_ref, summary) in audits {
        append_audit_artifact(
            &mut memory_store,
            &session,
            Some(&task.task_id),
            class,
            related_ref,
            summary,
        );
    }
    let checkpoint = capture_checkpoint(
        &mut memory_store,
        &session,
        &task,
        &ids.checkpoint_id,
        "completed checkpoint persisted for local export",
    );
    session.latest_checkpoint_ref = Some(checkpoint.checkpoint_id.clone());

    ReplayableRuntimeState::new(
        session.clone(),
        task.clone(),
        TaskGraph::new(
            task.task_id.clone(),
            vec![agenda_item_with_status(
                ids,
                "factory-step",
                "factory-step",
                AgendaStatus::Completed,
                Some(format!("worker-{}", ids.slug)),
                task.output_refs.clone(),
                OwnershipMode::MergeRequired,
            )],
        ),
        memory_store,
        Some(checkpoint),
        vec![
            execution_event(
                ids,
                "session-start",
                EventFamily::SessionLifecycleEvent,
                Some(&task.task_id),
                "local run started",
            ),
            execution_event(
                ids,
                "task-complete",
                EventFamily::TaskLifecycleEvent,
                Some(&task.task_id),
                "task completed and remained exportable",
            ),
            execution_event(
                ids,
                "checkpointed",
                EventFamily::CheckpointEvent,
                Some(&task.task_id),
                "completed checkpoint captured",
            ),
        ],
    )
}

fn capture_checkpoint(
    memory_store: &mut MemoryStore,
    session: &ExecutionSession,
    task: &TaskArtifact,
    checkpoint_id: &str,
    audit_summary: &str,
) -> RunCheckpoint {
    let checkpoint = RunCheckpoint::capture(
        checkpoint_id,
        session,
        Some(task),
        Vec::new(),
        vec![format!(
            "memory-pointer-index-{}",
            sanitize_id(checkpoint_id)
        )],
        FailureBudget::default().snapshot(),
        vec![format!("idempotency:{checkpoint_id}")],
    );
    memory_store.persist_checkpoint_artifact(
        format!("memory-checkpoint-{checkpoint_id}"),
        checkpoint.clone(),
        format!("checkpoint {checkpoint_id} persisted"),
    );
    memory_store.append(MemoryArtifact::audit_record(
        format!("memory-audit-checkpoint-{checkpoint_id}"),
        AuditRecord::new(
            format!("audit-checkpoint-{checkpoint_id}"),
            AuditRecordClass::GovernanceAuditRecord,
            session.header.campaign_id.clone(),
            session.header.epoch_id.clone(),
            session.header.session_id.clone(),
            Some(task.task_id.clone()),
            checkpoint.checkpoint_id.clone(),
            audit_summary.to_string(),
        ),
    ));
    checkpoint
}

fn append_audit_artifact(
    memory_store: &mut MemoryStore,
    session: &ExecutionSession,
    task_id: Option<&str>,
    class: AuditRecordClass,
    related_ref: impl Into<String>,
    summary: impl Into<String>,
) {
    let related_ref = related_ref.into();
    let artifact_id = format!(
        "memory-audit-{}-{}",
        sanitize_id(&session.header.session_id),
        sanitize_id(&related_ref)
    );
    memory_store.append(MemoryArtifact::audit_record(
        artifact_id,
        AuditRecord::new(
            format!(
                "audit-{}-{}",
                sanitize_id(&session.header.session_id),
                sanitize_id(&related_ref)
            ),
            class,
            session.header.campaign_id.clone(),
            session.header.epoch_id.clone(),
            session.header.session_id.clone(),
            task_id.map(str::to_string),
            related_ref,
            summary,
        ),
    ));
}

fn execution_event(
    ids: &ScenarioIds,
    suffix: &str,
    family: EventFamily,
    task_id: Option<&str>,
    detail: &str,
) -> ExecutionEvent {
    ExecutionEvent::new(
        format!("event-{}-{suffix}", ids.slug),
        family,
        ids.campaign_id.clone(),
        ids.epoch_id.clone(),
        ids.session_id.clone(),
        None,
        task_id.map(str::to_string),
        detail.to_string(),
    )
}

fn execution_event_from_state(
    state: &ReplayableRuntimeState,
    suffix: &str,
    family: EventFamily,
    detail: &str,
) -> ExecutionEvent {
    ExecutionEvent::new(
        format!(
            "event-{}-{suffix}",
            sanitize_id(&state.session.header.session_id)
        ),
        family,
        state.session.header.campaign_id.clone(),
        state.session.header.epoch_id.clone(),
        state.session.header.session_id.clone(),
        state
            .session
            .current_turn
            .as_ref()
            .map(|turn| turn.turn_id.clone()),
        Some(state.root_task.task_id.clone()),
        detail.to_string(),
    )
}

impl LocalRunRecord {
    fn view_model(
        &self,
        workspace: &LocalRuntimeWorkspace,
    ) -> Result<RunViewModel, LocalRuntimeError> {
        let definition = scenario_definition(&self.metadata.scenario_id).ok_or_else(|| {
            LocalRuntimeError::UnknownScenario {
                scenario_id: self.metadata.scenario_id.clone(),
            }
        })?;
        let approvals = collect_approvals(&self.runtime_state.memory_store);
        let checkpoints = collect_checkpoints(&self.runtime_state.memory_store);
        let memory = collect_memory_summary(&self.runtime_state.memory_store);
        let promotion = collect_promotion_summary(
            &self.runtime_state.memory_store,
            &self.metadata.quarantines,
            self.metadata.rollback_handle.as_ref(),
        );
        let summary = RunSummary {
            run_id: self.metadata.run_id.clone(),
            scenario_id: definition.scenario_id.clone(),
            title: definition.title.clone(),
            description: definition.description.clone(),
            status: self.metadata.status.clone(),
            created_at: self.metadata.created_at.clone(),
            updated_at: self.metadata.updated_at.clone(),
            session_id: self.runtime_state.session.header.session_id.clone(),
            campaign_id: self.runtime_state.session.header.campaign_id.clone(),
            epoch_id: self.runtime_state.session.header.epoch_id.clone(),
            root_task_id: self.runtime_state.root_task.task_id.clone(),
            root_task_state: self.runtime_state.root_task.state.clone(),
            latest_checkpoint_id: self
                .runtime_state
                .latest_checkpoint
                .as_ref()
                .map(|checkpoint| checkpoint.checkpoint_id.clone()),
            event_count: self.runtime_state.event_log.len(),
            approval_request_count: approvals.len(),
            pending_approval_count: self.runtime_state.session.pending_approval_refs.len(),
            quarantine_count: self.metadata.quarantines.len(),
            rollback_available: self.metadata.rollback_handle.is_some(),
            template_id: self.metadata.studio_template_id.clone(),
            pack_id: self.metadata.studio_pack_id.clone(),
            composition_id: self.metadata.composition_id.clone(),
            run_set_id: self.metadata.run_set_id.clone(),
            hypothesis_id: self.metadata.hypothesis_id.clone(),
            review_packet_id: self.metadata.review_packet_id.clone(),
            regression_pack_id: self.metadata.regression_pack_id.clone(),
            operator_goal: self.metadata.operator_goal.clone(),
            output_refs: self.runtime_state.root_task.output_refs.clone(),
            bundle_path: workspace
                .bundle_root(&self.metadata.run_id)
                .display()
                .to_string(),
        };
        Ok(RunViewModel {
            definition,
            summary,
            approvals,
            checkpoints,
            quarantines: self.metadata.quarantines.clone(),
            rollback_handle: self.metadata.rollback_handle.clone(),
            promotion,
            memory,
            events: self.runtime_state.event_log.clone(),
        })
    }
}

fn run_timestamp(value: &str) -> u128 {
    value.parse::<u128>().unwrap_or_default()
}

fn is_active_status(status: &LocalRunStatus) -> bool {
    matches!(
        status,
        LocalRunStatus::AwaitingApproval
            | LocalRunStatus::AwaitingRollback
            | LocalRunStatus::Paused
    )
}

