fn build_system_overview(run_views: &[RunViewModel]) -> SystemOverviewView {
    let mut sorted = run_views.to_vec();
    sorted.sort_by(|left, right| {
        run_timestamp(&right.summary.updated_at)
            .cmp(&run_timestamp(&left.summary.updated_at))
            .then_with(|| left.summary.run_id.cmp(&right.summary.run_id))
    });

    let latest_run = sorted.first().map(|view| view.summary.clone());
    let active_run_count = sorted
        .iter()
        .filter(|view| is_active_status(&view.summary.status))
        .count();
    let pending_approval_count = sorted
        .iter()
        .map(|view| view.summary.pending_approval_count)
        .sum();
    let quarantine_count = sorted
        .iter()
        .map(|view| view.summary.quarantine_count)
        .sum();
    let rollback_ready_count = sorted
        .iter()
        .filter(|view| view.summary.rollback_available)
        .count();

    let local_runner_state = match (sorted.len(), active_run_count) {
        (0, _) => "No local runs have been started yet.".to_string(),
        (stored, 0) => {
            format!("Runner is idle with {stored} stored run bundle(s) available for review.")
        }
        (stored, active) => format!(
            "Runner is tracking {active} active run(s) across {stored} stored local run(s)."
        ),
    };
    let factory_program_state = latest_run
        .as_ref()
        .map(describe_factory_program_state)
        .unwrap_or_else(|| "No local factory program has been launched yet.".to_string());

    SystemOverviewView {
        operational_north_star_decision:
            crate::execution::NorthStarClosureDecision::NotYet,
        status_authority_ref: "notes/ROADMAP.md".to_string(),
        status_basis: "Capability maturity is derived from real effects and evidence. Historical record-completeness closure decisions remain lineage and do not determine current operational status.".to_string(),
        operator_truth_surfaces: operator_truth_surface_authority(),
        north_star_nodes: north_star_nodes(),
        current_status: CurrentSystemStatusView {
            local_runner_state,
            factory_program_state,
            stored_run_count: sorted.len(),
            active_run_count,
            pending_approval_count,
            quarantine_count,
            rollback_ready_count,
            latest_run_id: latest_run.as_ref().map(|summary| summary.run_id.clone()),
            latest_run_title: latest_run.as_ref().map(|summary| summary.title.clone()),
            latest_run_status: latest_run.as_ref().map(|summary| summary.status.clone()),
            latest_campaign_id: latest_run
                .as_ref()
                .map(|summary| summary.campaign_id.clone()),
            latest_epoch_id: latest_run.as_ref().map(|summary| summary.epoch_id.clone()),
        },
        progress_tracker: progress_tracker_items(),
        attention_queue: build_attention_queue_from_views(&sorted),
        latest_run,
    }
}

fn split_markdown_paragraph_blocks(markdown: &str) -> Vec<String> {
    let mut paragraphs = Vec::new();
    let mut current = Vec::new();
    for line in markdown.lines() {
        if line.trim().is_empty() {
            if !current.is_empty() {
                paragraphs.push(current.join(" ").trim().to_string());
                current.clear();
            }
            continue;
        }
        current.push(line.trim_end().to_string());
    }
    if !current.is_empty() {
        paragraphs.push(current.join(" ").trim().to_string());
    }
    paragraphs
        .into_iter()
        .filter(|paragraph| !paragraph.is_empty())
        .collect()
}

fn general_audience_intro_paragraphs() -> Vec<String> {
    let introduction = GENERAL_AUDIENCE_INTRODUCTION_MARKDOWN
        .split_once("\nCore AIAF reference anchors:\n")
        .map_or(GENERAL_AUDIENCE_INTRODUCTION_MARKDOWN, |(prose, _)| prose);
    split_markdown_paragraph_blocks(introduction)
}

fn local_run_status_label(status: &LocalRunStatus) -> &'static str {
    match status {
        LocalRunStatus::AwaitingApproval => "awaiting_approval",
        LocalRunStatus::AwaitingRollback => "awaiting_rollback",
        LocalRunStatus::Paused => "paused",
        LocalRunStatus::Completed => "completed",
        LocalRunStatus::Failed => "failed",
        LocalRunStatus::RolledBack => "rolled_back",
    }
}

fn combine_console_progress_statuses<I>(statuses: I) -> ConsoleProgressStatus
where
    I: IntoIterator<Item = ConsoleProgressStatus>,
{
    let mut combined = ConsoleProgressStatus::NativeNow;
    for status in statuses {
        match status {
            ConsoleProgressStatus::NotYet => return ConsoleProgressStatus::NotYet,
            ConsoleProgressStatus::LiveButBounded => {
                combined = ConsoleProgressStatus::LiveButBounded;
            }
            ConsoleProgressStatus::NativeNow => {}
        }
    }
    combined
}

fn progress_status_index(items: &[ProgressTrackerItem]) -> BTreeMap<String, ConsoleProgressStatus> {
    items
        .iter()
        .map(|item| (item.area.clone(), item.status.clone()))
        .collect()
}

fn combined_progress_status(
    progress_index: &BTreeMap<String, ConsoleProgressStatus>,
    areas: &[&str],
) -> ConsoleProgressStatus {
    combine_console_progress_statuses(
        areas
            .iter()
            .filter_map(|area| progress_index.get(*area).cloned())
            .collect::<Vec<_>>(),
    )
}

fn build_general_audience_current_snapshot(
    sorted_runs: &[RunViewModel],
    overview: &SystemOverviewView,
) -> GeneralAudienceCurrentSnapshotView {
    let latest_active_run = sorted_runs
        .iter()
        .find(|view| is_active_status(&view.summary.status))
        .map(|view| GeneralAudienceRunLinkView {
            run_id: view.summary.run_id.clone(),
            title: view.summary.title.clone(),
            scenario_id: view.summary.scenario_id.clone(),
            status: view.summary.status.clone(),
        });
    let latest_reference = latest_active_run
        .as_ref()
        .and_then(|active| {
            sorted_runs
                .iter()
                .find(|view| view.summary.run_id == active.run_id)
        })
        .or_else(|| sorted_runs.first());
    GeneralAudienceCurrentSnapshotView {
        local_runner_state: overview.current_status.local_runner_state.clone(),
        factory_program_state: overview.current_status.factory_program_state.clone(),
        stored_run_count: overview.current_status.stored_run_count,
        active_run_count: overview.current_status.active_run_count,
        pending_approval_count: overview.current_status.pending_approval_count,
        rollback_ready_count: overview.current_status.rollback_ready_count,
        latest_active_run,
        latest_campaign_id: latest_reference.map(|view| view.summary.campaign_id.clone()),
        latest_epoch_id: latest_reference.map(|view| view.summary.epoch_id.clone()),
        expert_console_path: "/console".to_string(),
    }
}

