#[allow(clippy::too_many_arguments)]
fn build_general_audience_capability_groups(
    progress_tracker: &[ProgressTrackerItem],
    transition: &V2TransitionWorkspaceView,
    convergence_transition: &V2ConvergenceTransitionWorkspaceView,
    world_taxonomy: &V2CapabilityWorldTaxonomyView,
    service_handles: &V2ServiceContractHandleView,
    service_attestation: &V2ServiceAttestationLedgerView,
    memory_closure: &V2MemoryReviewLineageClosureView,
    topology: &V2CoordinationTopologyMapView,
    scheduler: &V2SchedulerQueueContractView,
    governance: &V2GovernanceReleaseClosureView,
    reviewable_generation: &V2OperatorReviewableNativeServiceGenerationView,
    challenger_comparison: &V2ChallengerIncumbentGenerationComparisonView,
    pressure: &V2CapabilityPressureApprovalLoadView,
    recovery: &V2RecoveryInterventionSharedResourcesView,
    phase01: &RemediationPhase01LifecycleClosureView,
    phase02: &RemediationPhase02ServiceEcologyClosureView,
    phase03: &RemediationPhase03ReproductionEcosystemClosureView,
) -> Vec<GeneralAudienceCapabilityGroupView> {
    let progress_index = progress_status_index(progress_tracker);
    general_audience_capability_group_specs()
        .into_iter()
        .map(|spec| {
            let status = combined_progress_status(&progress_index, spec.areas);
            let (summary, highlights, source_refs) = match spec.group_id {
                "workspace" => (
                    transition.summary.clone(),
                    vec![
                        transition.final_v1_readiness.clone(),
                        transition.boundary_summary.clone(),
                        format!(
                            "{} workspace check(s) are recorded for the current handoff.",
                            convergence_transition.workspace_checks.len()
                        ),
                    ],
                    vec![
                        "transition.v2".to_string(),
                        "transition.v2.convergence".to_string(),
                    ],
                ),
                "execution" => (
                    phase01.northstar02.summary.clone(),
                    vec![
                        phase01.summary.clone(),
                        format!(
                            "{} shell tick(s) and {} approval inbox record(s) are carried in the current execution line.",
                            phase01.northstar02.ticks.len(),
                            phase01.northstar02.approval_inboxes.len()
                        ),
                        phase01.boundary_statement.clone(),
                    ],
                    vec![
                        "northstar.02.persistent-shell".to_string(),
                        "remediation.phase-01".to_string(),
                    ],
                ),
                "memory" => (
                    memory_closure.summary.clone(),
                    vec![
                        memory_closure.retrieval_summary.clone(),
                        memory_closure.evidence_summary.clone(),
                        memory_closure.context_summary.clone(),
                    ],
                    vec![
                        "v2.continuity.closure".to_string(),
                        "progress.skeptical-memory".to_string(),
                    ],
                ),
                "worker-coordination" => (
                    phase02.northstar04.summary.clone(),
                    vec![
                        topology.summary.clone(),
                        format!(
                            "{} worker card(s), {} routing packet(s), and {} recovery record(s) are tracked in the current ecology.",
                            phase02.northstar04.worker_cards.len(),
                            phase02.northstar04.routing_packets.len(),
                            phase02.northstar04.recovery_records.len()
                        ),
                        phase02.summary.clone(),
                    ],
                    vec![
                        "northstar.04.worker-ecology".to_string(),
                        "v2.topology.domains".to_string(),
                    ],
                ),
                "approval-governance" => (
                    governance.summary.clone(),
                    vec![
                        governance.release_summary.clone(),
                        format!(
                            "{} approval pressure signal(s) and {} recovery intervention(s) are currently recorded.",
                            pressure.entries.len(),
                            recovery.entries.len()
                        ),
                        governance.next_line.clone(),
                    ],
                    vec![
                        "v2.governance.closure".to_string(),
                        "v2.operations.pressure".to_string(),
                    ],
                ),
                "review-promotion" => (
                    reviewable_generation.summary.clone(),
                    vec![
                        reviewable_generation.maturity_signal.clone(),
                        challenger_comparison.decision_posture.clone(),
                        phase03.summary.clone(),
                    ],
                    vec![
                        "v2.service-generation.review".to_string(),
                        "v2.self-hosting.comparison".to_string(),
                    ],
                ),
                "scheduling" => (
                    scheduler.summary.clone(),
                    vec![
                        phase01.northstar02.summary.clone(),
                        format!(
                            "{} scheduler rule(s), {} queue rule(s), and {} recurring program(s) are carried.",
                            scheduler.scheduler_rules.len(),
                            scheduler.queue_rules.len(),
                            phase03.northstar05.recurring_factory_programs.len()
                        ),
                        phase03.northstar05.summary.clone(),
                    ],
                    vec![
                        "v2.topology.scheduler-queue".to_string(),
                        "northstar.05.factory-programs".to_string(),
                    ],
                ),
                "infrastructure" => (
                    world_taxonomy.summary.clone(),
                    vec![
                        format!(
                            "{} world family(ies), {} service handle(s), and {} service attestation(s) are currently carried.",
                            world_taxonomy.world_families.len(),
                            service_handles.services.len(),
                            service_attestation.attestations.len()
                        ),
                        service_handles.summary.clone(),
                        phase02.northstar03.summary.clone(),
                    ],
                    vec![
                        "v2.services.worlds".to_string(),
                        "v2.services.contracts".to_string(),
                    ],
                ),
                _ => (
                    "No current capability summary is available.".to_string(),
                    Vec::new(),
                    Vec::new(),
                ),
            };
            GeneralAudienceCapabilityGroupView {
                group_id: spec.group_id.to_string(),
                title: spec.title.to_string(),
                status,
                summary,
                highlights,
                source_refs,
            }
        })
        .collect()
}

fn build_general_audience_in_flight_capabilities(
    sorted_runs: &[RunViewModel],
    planning: &PlanningGuidanceView,
    programs: &FactoryProgramLedgerView,
    factory_views: &BTreeMap<String, FactoryView>,
    agent_views: &BTreeMap<String, AgentView>,
) -> Vec<GeneralAudienceInFlightCapabilityItem> {
    let mut items = Vec::new();
    for view in sorted_runs
        .iter()
        .filter(|view| is_active_status(&view.summary.status))
        .take(8)
    {
        let factory_state = factory_views
            .get(&view.summary.run_id)
            .map(|factory| {
                format!(
                    "{} {} {}",
                    factory.comparison_state, factory.promotion_state, factory.rollback_state
                )
            })
            .unwrap_or_else(|| comparison_highlight_for_view(view));
        let agent_state = agent_views
            .get(&view.summary.run_id)
            .map(|agent| {
                format!(
                    "{} worker(s), {} blocked, {} failed.",
                    agent.workers.len(),
                    agent.blocked_agent_count,
                    agent.failed_agent_count
                )
            })
            .unwrap_or_else(|| "Worker state is not expanded for this run.".to_string());
        let governance_state = if view.summary.pending_approval_count > 0 {
            format!(
                "Awaiting {} governed approval decision(s).",
                view.summary.pending_approval_count
            )
        } else if view.summary.rollback_available {
            "Rollback can be exercised against this run.".to_string()
        } else if view.summary.quarantine_count > 0 {
            format!(
                "{} quarantine containment record(s) are still active.",
                view.summary.quarantine_count
            )
        } else {
            format!(
                "Run is currently `{}`.",
                local_run_status_label(&view.summary.status)
            )
        };
        items.push(GeneralAudienceInFlightCapabilityItem {
            item_id: format!("run:{}", view.summary.run_id),
            title: view.summary.title.clone(),
            summary: format!("{} {}", factory_state, agent_state),
            state_label: "run".to_string(),
            governance_state,
            run_id: Some(view.summary.run_id.clone()),
            program_instance_id: None,
            related_refs: view_evidence_refs(view),
        });
    }

    for program in programs
        .programs
        .iter()
        .filter(|program| {
            !matches!(
                program.instance.program_state,
                crate::execution::FactoryProgramState::Completed
                    | crate::execution::FactoryProgramState::Stopped
            )
        })
        .take(6)
    {
        let governance_state = program
            .receipts
            .last()
            .map(|receipt| receipt.stop_condition.operator_guidance.clone())
            .unwrap_or_else(|| {
                format!(
                    "Program is currently `{}` and has not emitted a governed tick receipt yet.",
                    factory_program_state_label(program.instance.program_state)
                )
            });
        items.push(GeneralAudienceInFlightCapabilityItem {
            item_id: format!("program:{}", program.instance.instance_id),
            title: program.spec.title.clone(),
            summary: program.summary.clone(),
            state_label: "program".to_string(),
            governance_state,
            run_id: None,
            program_instance_id: Some(program.instance.instance_id.clone()),
            related_refs: unique_strings(
                program
                    .instance
                    .latest_tick_id
                    .clone()
                    .into_iter()
                    .chain(std::iter::once(program.spec.spec_id.clone())),
            ),
        });
    }

    for recommendation in planning.recommendations.iter().take(6) {
        items.push(GeneralAudienceInFlightCapabilityItem {
            item_id: recommendation.recommendation_id.clone(),
            title: recommendation.title.clone(),
            summary: recommendation.detail.clone(),
            state_label: "planning".to_string(),
            governance_state: recommendation
                .suggested_scenario_id
                .as_ref()
                .map(|scenario_id| format!("Suggested next scenario: `{scenario_id}`."))
                .unwrap_or_else(|| "Queued for operator review.".to_string()),
            run_id: recommendation.run_id.clone(),
            program_instance_id: None,
            related_refs: recommendation.supporting_refs.clone(),
        });
    }
    items
}

fn build_general_audience_historical_timeline(
    history: &RunHistoryView,
    portfolio: &FactoryPortfolioView,
    progress_tracker: &[ProgressTrackerItem],
    phase01: &RemediationPhase01LifecycleClosureView,
    phase02: &RemediationPhase02ServiceEcologyClosureView,
    phase03: &RemediationPhase03ReproductionEcosystemClosureView,
    phase04: Option<&RemediationPhase04FinalClosureRereviewView>,
) -> Vec<GeneralAudienceHistoricalMilestoneItem> {
    let mut items = Vec::new();
    let mut seen = BTreeSet::new();
    let mut push_item = |item: GeneralAudienceHistoricalMilestoneItem| {
        if seen.insert(item.milestone_id.clone()) {
            items.push(item);
        }
    };

    for (phase_id, title, status_label, summary, evidence_refs) in [
        (
            "phase-01",
            "Remediation Phase 01 Lifecycle Closure".to_string(),
            phase01.phase_status.clone(),
            phase01.summary.clone(),
            phase01
                .workstreams
                .iter()
                .flat_map(|workstream| workstream.evidence_refs.clone())
                .collect::<Vec<_>>(),
        ),
        (
            "phase-02",
            "Remediation Phase 02 Service And Ecology Closure".to_string(),
            phase02.phase_status.clone(),
            phase02.summary.clone(),
            phase02.acceptance_packet_refs.clone(),
        ),
        (
            "phase-03",
            "Remediation Phase 03 Reproduction And Ecosystem Closure".to_string(),
            phase03.phase_status.clone(),
            phase03.summary.clone(),
            phase03.closure_review_packet_refs.clone(),
        ),
    ] {
        push_item(GeneralAudienceHistoricalMilestoneItem {
            milestone_id: phase_id.to_string(),
            title,
            source_kind: "remediation".to_string(),
            status_label,
            summary,
            evidence_refs,
        });
    }
    if let Some(phase04) = phase04 {
        push_item(GeneralAudienceHistoricalMilestoneItem {
            milestone_id: "phase-04".to_string(),
            title: "Historical Remediation Phase 04 Record-Completeness Review".to_string(),
            source_kind: "remediation".to_string(),
            status_label: format!("{}:{}", phase04.review_scope, phase04.phase_status),
            summary: phase04.summary.clone(),
            evidence_refs: phase04.final_decision_refs.clone(),
        });
    } else {
        push_item(GeneralAudienceHistoricalMilestoneItem {
            milestone_id: "phase-04".to_string(),
            title: "Historical Remediation Phase 04 Review Unavailable".to_string(),
            source_kind: "historical_review_unavailable".to_string(),
            status_label: "historical_review_unavailable:not_yet".to_string(),
            summary: "The exact archived Phase 04 Closed corpus is unavailable in this local workspace. No historical success projection is emitted; the operational North Star decision remains NotYet."
                .to_string(),
            evidence_refs: Vec::new(),
        });
    }

    for item in progress_tracker.iter().filter(|item| {
        matches!(
            item.maturity,
            CapabilityMaturity::Effectful
                | CapabilityMaturity::Operational
                | CapabilityMaturity::Verified
        )
    }) {
        push_item(GeneralAudienceHistoricalMilestoneItem {
            milestone_id: format!("progress:{}", sanitize_id(&item.area)),
            title: item.area.clone(),
            source_kind: "progress_tracker".to_string(),
            status_label: format!("{:?}", item.maturity).to_ascii_lowercase(),
            summary: item.detail.clone(),
            evidence_refs: item.backing_evidence_refs.clone(),
        });
    }

    for entry in portfolio.timeline.iter().take(6) {
        push_item(GeneralAudienceHistoricalMilestoneItem {
            milestone_id: format!("portfolio:{}", entry.run_id),
            title: entry.title.clone(),
            source_kind: "portfolio".to_string(),
            status_label: format!("{:?}", entry.status),
            summary: format!("{} {}", entry.adoption_state, entry.risk_state),
            evidence_refs: entry.evidence_refs.clone(),
        });
    }

    for entry in history
        .recent_runs
        .iter()
        .filter(|entry| !is_active_status(&entry.status))
        .take(6)
    {
        push_item(GeneralAudienceHistoricalMilestoneItem {
            milestone_id: format!("history:{}", entry.run_id),
            title: entry.title.clone(),
            source_kind: "run_history".to_string(),
            status_label: local_run_status_label(&entry.status).to_string(),
            summary: format!("{} {}", entry.comparison_highlight, entry.adoption_signal),
            evidence_refs: entry.evidence_refs.clone(),
        });
    }

    items
}

fn build_general_audience_future_roadmap(
    progress_tracker: &[ProgressTrackerItem],
    planning: &PlanningGuidanceView,
    transition: &V2TransitionWorkspaceView,
    convergence_transition: &V2ConvergenceTransitionWorkspaceView,
    phase01: &RemediationPhase01LifecycleClosureView,
    phase02: &RemediationPhase02ServiceEcologyClosureView,
    phase03: &RemediationPhase03ReproductionEcosystemClosureView,
    phase04: Option<&RemediationPhase04FinalClosureRereviewView>,
) -> Vec<GeneralAudienceFutureRoadmapItem> {
    let mut items = Vec::new();
    let mut seen = BTreeSet::new();
    let mut push_item = |item: GeneralAudienceFutureRoadmapItem| {
        if seen.insert(item.roadmap_id.clone()) {
            items.push(item);
        }
    };

    for item in progress_tracker.iter().filter(|item| {
        matches!(
            item.status,
            ConsoleProgressStatus::LiveButBounded | ConsoleProgressStatus::NotYet
        )
    }) {
        push_item(GeneralAudienceFutureRoadmapItem {
            roadmap_id: format!("progress:{}", sanitize_id(&item.area)),
            title: item.area.clone(),
            source_kind: "progress_tracker".to_string(),
            status: item.status.clone(),
            horizon: if matches!(item.status, ConsoleProgressStatus::LiveButBounded) {
                "active_bounded_work".to_string()
            } else {
                "not_yet_closed".to_string()
            },
            summary: item.detail.clone(),
            blockers: Vec::new(),
            source_refs: vec![item.north_star_meaning.clone()],
        });
    }

    for recommendation in &planning.recommendations {
        push_item(GeneralAudienceFutureRoadmapItem {
            roadmap_id: recommendation.recommendation_id.clone(),
            title: recommendation.title.clone(),
            source_kind: "planning".to_string(),
            status: ConsoleProgressStatus::LiveButBounded,
            horizon: "operator_planning".to_string(),
            summary: recommendation.detail.clone(),
            blockers: Vec::new(),
            source_refs: recommendation.supporting_refs.clone(),
        });
    }

    push_item(GeneralAudienceFutureRoadmapItem {
        roadmap_id: "transition:v2".to_string(),
        title: "v2 transition workspace".to_string(),
        source_kind: "transition".to_string(),
        status: ConsoleProgressStatus::LiveButBounded,
        horizon: "near_term_transition".to_string(),
        summary: format!("{} {}", transition.summary, transition.final_v1_readiness),
        blockers: transition.pending_questions.clone(),
        source_refs: unique_strings(
            transition.release_board_refs.iter().cloned().chain(
                transition
                    .latest_packet
                    .as_ref()
                    .map(|packet| packet.packet_id.clone())
                    .into_iter(),
            ),
        ),
    });
    push_item(GeneralAudienceFutureRoadmapItem {
        roadmap_id: "transition:convergence".to_string(),
        title: "Next-line convergence handoff".to_string(),
        source_kind: "transition".to_string(),
        status: ConsoleProgressStatus::LiveButBounded,
        horizon: "next_line_handoff".to_string(),
        summary: format!(
            "{} {} {}",
            convergence_transition.summary,
            convergence_transition.phase_summary,
            convergence_transition.pressure_summary
        ),
        blockers: convergence_transition.workspace_checks.clone(),
        source_refs: convergence_transition
            .latest_handoff_packet
            .as_ref()
            .map(|packet| {
                unique_strings(
                    std::iter::once(packet.packet_id.clone()).chain(packet.evidence_refs.clone()),
                )
            })
            .unwrap_or_default(),
    });

    for (phase_id, title, summary, next_phase, blockers) in [
        (
            "phase-01",
            "Remediation Phase 01 remaining blockers".to_string(),
            phase01.summary.clone(),
            phase01.next_phase.clone(),
            phase01.remaining_blockers.clone(),
        ),
        (
            "phase-02",
            "Remediation Phase 02 remaining blockers".to_string(),
            phase02.summary.clone(),
            phase02.next_phase.clone(),
            phase02.remaining_blockers.clone(),
        ),
        (
            "phase-03",
            "Remediation Phase 03 remaining blockers".to_string(),
            phase03.summary.clone(),
            phase03.next_phase.clone(),
            phase03.remaining_blockers.clone(),
        ),
    ] {
        if blockers.is_empty() {
            continue;
        }
        push_item(GeneralAudienceFutureRoadmapItem {
            roadmap_id: format!("blockers:{phase_id}"),
            title,
            source_kind: "blocker".to_string(),
            status: ConsoleProgressStatus::NotYet,
            horizon: next_phase,
            summary,
            blockers,
            source_refs: vec![phase_id.to_string()],
        });
    }
    if let Some(phase04) = phase04 {
        if !phase04.remaining_blockers.is_empty() {
            push_item(GeneralAudienceFutureRoadmapItem {
                roadmap_id: "blockers:phase-04".to_string(),
                title: "Historical Remediation Phase 04 remaining blockers".to_string(),
                source_kind: "blocker".to_string(),
                status: ConsoleProgressStatus::NotYet,
                horizon: phase04.next_phase.clone(),
                summary: phase04.summary.clone(),
                blockers: phase04.remaining_blockers.clone(),
                source_refs: vec!["phase-04".to_string()],
            });
        }
    } else {
        push_item(GeneralAudienceFutureRoadmapItem {
            roadmap_id: "blockers:phase-04-unavailable".to_string(),
            title: "Historical Phase 04 review unavailable".to_string(),
            source_kind: "blocker".to_string(),
            status: ConsoleProgressStatus::NotYet,
            horizon: "materialize_exact_archived_closed_corpus".to_string(),
            summary: "The home view cannot resolve the exact archived Phase 04 Closed corpus and therefore emits no historical success projection."
                .to_string(),
            blockers: vec![
                "Materialize and validate the exact archived Closed record-completeness corpus before serving the historical Phase 04 projection."
                    .to_string(),
            ],
            source_refs: Vec::new(),
        });
    }

    items
}

fn action_payload_template(value: serde_json::Value) -> Option<String> {
    serde_json::to_string_pretty(&value).ok()
}

fn default_program_tick_request(
    program: &FactoryProgramView,
) -> crate::execution::FactoryProgramTickRequest {
    let campaign_count = program.instance.campaign_count + 1;
    let instance_slug = sanitize_id(&program.instance.instance_id);
    let candidate_factory_ref = format!("factory:{instance_slug}:candidate:{campaign_count}");
    crate::execution::FactoryProgramTickRequest {
        candidate_factory_ref: candidate_factory_ref.clone(),
        proving_refs: vec![format!("proof:{instance_slug}:{campaign_count}:validation")],
        observation_refs: vec![format!(
            "observation:{instance_slug}:{campaign_count}:stability"
        )],
        comparison_refs: vec![format!(
            "comparison:{instance_slug}:{campaign_count}:vs:{}",
            sanitize_id(&program.instance.current_factory_ref)
        )],
        risk_refs: vec![format!("risk:{instance_slug}:{campaign_count}:bounded")],
        trend_refs: vec![format!("trend:{instance_slug}:{campaign_count}:upward")],
        rollback_refs: vec![format!("rollback:{instance_slug}:{campaign_count}:ready")],
        adoption_result: crate::execution::AdoptionWindowResult::Adopted,
        operator_note: Some(format!(
            "review candidate `{candidate_factory_ref}` against incumbent `{}`",
            program.instance.current_factory_ref
        )),
    }
}

fn default_llm_drive_request(program: &FactoryProgramView) -> DriveLlmFactoryProgramRequest {
    DriveLlmFactoryProgramRequest {
        provider_ref: "provider:configure-me".to_string(),
        model_ref: "gpt-5.4-mini".to_string(),
        generation_policy: InferenceGenerationPolicy {
            generation_policy_id: format!(
                "policy:{}:bounded-llm-drive",
                sanitize_id(&program.instance.instance_id)
            ),
            max_output_tokens: 512,
            max_retries: 1,
            summary: format!("bounded LLM drive for {}", program.instance.instance_id),
        },
        max_cycles: Some(1),
    }
}

fn build_general_audience_recommended_actions() -> Vec<GeneralAudienceActionItem> {
    let recommendations = [
        (
            "supervisor-approval-resume-worker-complete",
            "See an approval-gated run become a concrete governed decision.",
            "Good first run if you want to inspect approval, evidence, and completion together.",
        ),
        (
            "supervisor-background-quarantine-rollback-control-loop",
            "See how AIAF records containment signals and prepares rollback.",
            "Useful when you want a concrete rollback-ready artifact bundle to inspect.",
        ),
        (
            "supervisor-durable-fixed-interface-continuous-self-hosting-program",
            "See a paused continuous improvement path that can be resumed under explicit control.",
            "Shows the continuous-program pattern without jumping straight into deeper expert surfaces.",
        ),
    ];

    recommendations
        .into_iter()
        .filter_map(|(scenario_id, description, guardrail)| {
            let definition = scenario_definition(scenario_id)?;
            Some(GeneralAudienceActionItem {
                action_id: format!("recommended:{}", definition.scenario_id),
                title: definition.title,
                description: description.to_string(),
                kind: "recommended_run".to_string(),
                button_label: "Start run".to_string(),
                endpoint: "/api/runs".to_string(),
                method: "POST".to_string(),
                scenario_id: Some(definition.scenario_id.clone()),
                run_id: None,
                program_instance_id: None,
                payload_template: action_payload_template(serde_json::json!({
                    "scenario_id": definition.scenario_id
                })),
                guardrail: Some(guardrail.to_string()),
            })
        })
        .collect()
}

fn build_general_audience_advanced_actions(
    sorted_runs: &[RunViewModel],
    programs: &FactoryProgramLedgerView,
) -> GeneralAudienceAdvancedActionsView {
    let scenario_actions = curated_scenarios()
        .into_iter()
        .map(|definition| GeneralAudienceActionItem {
            action_id: format!("scenario:{}", definition.scenario_id),
            title: definition.title.clone(),
            description: definition.description.clone(),
            kind: "scenario".to_string(),
            button_label: "Start scenario".to_string(),
            endpoint: "/api/runs".to_string(),
            method: "POST".to_string(),
            scenario_id: Some(definition.scenario_id.clone()),
            run_id: None,
            program_instance_id: None,
            payload_template: action_payload_template(serde_json::json!({
                "scenario_id": definition.scenario_id
            })),
            guardrail: Some(if definition.requires_approval {
                "This scenario will surface an explicit approval gate.".to_string()
            } else if definition.supports_rollback {
                "This scenario can expose rollback-ready evidence.".to_string()
            } else {
                "This scenario stays within the current bounded catalog.".to_string()
            }),
        })
        .collect::<Vec<_>>();

    let mut run_controls = Vec::new();
    for view in sorted_runs
        .iter()
        .filter(|view| is_active_status(&view.summary.status))
    {
        match view.summary.status {
            LocalRunStatus::AwaitingApproval => {
                for (suffix, title, description, guardrail) in [
                    (
                        "grant",
                        "Grant approval",
                        "Advance the run through its current approval gate.",
                        "Only grant after reviewing the run evidence and requested authority.",
                    ),
                    (
                        "deny",
                        "Deny approval",
                        "Stop the current gated step and record a denied decision.",
                        "Use denial when the candidate should not advance under current evidence.",
                    ),
                    (
                        "expire",
                        "Expire approval",
                        "Record timeout on the current approval window.",
                        "Use expiry when the request should lapse without being granted.",
                    ),
                    (
                        "escalate",
                        "Escalate approval",
                        "Pause the run under escalation policy for further review.",
                        "Escalation is appropriate when more review is needed before continuing.",
                    ),
                ] {
                    run_controls.push(GeneralAudienceActionItem {
                        action_id: format!("run:{}:{suffix}", view.summary.run_id),
                        title: format!("{title} for {}", view.summary.title),
                        description: description.to_string(),
                        kind: "run_control".to_string(),
                        button_label: title.to_string(),
                        endpoint: format!("/api/runs/{}/approval/{suffix}", view.summary.run_id),
                        method: "POST".to_string(),
                        scenario_id: Some(view.summary.scenario_id.clone()),
                        run_id: Some(view.summary.run_id.clone()),
                        program_instance_id: None,
                        payload_template: None,
                        guardrail: Some(guardrail.to_string()),
                    });
                }
            }
            LocalRunStatus::Paused => {
                run_controls.push(GeneralAudienceActionItem {
                    action_id: format!("run:{}:resume", view.summary.run_id),
                    title: format!("Resume {}", view.summary.title),
                    description: "Complete the currently paused governed run.".to_string(),
                    kind: "run_control".to_string(),
                    button_label: "Resume".to_string(),
                    endpoint: format!("/api/runs/{}/resume", view.summary.run_id),
                    method: "POST".to_string(),
                    scenario_id: Some(view.summary.scenario_id.clone()),
                    run_id: Some(view.summary.run_id.clone()),
                    program_instance_id: None,
                    payload_template: None,
                    guardrail: Some(
                        "Resume only after the paused evidence and current state have been reviewed."
                            .to_string(),
                    ),
                });
            }
            LocalRunStatus::AwaitingRollback => {
                run_controls.push(GeneralAudienceActionItem {
                    action_id: format!("run:{}:rollback", view.summary.run_id),
                    title: format!("Rollback {}", view.summary.title),
                    description: "Execute rollback on the currently rollback-ready run.".to_string(),
                    kind: "run_control".to_string(),
                    button_label: "Rollback".to_string(),
                    endpoint: format!("/api/runs/{}/rollback", view.summary.run_id),
                    method: "POST".to_string(),
                    scenario_id: Some(view.summary.scenario_id.clone()),
                    run_id: Some(view.summary.run_id.clone()),
                    program_instance_id: None,
                    payload_template: None,
                    guardrail: Some(
                        "Rollback will preserve the governed evidence trail while restoring the incumbent."
                            .to_string(),
                    ),
                });
            }
            LocalRunStatus::Completed | LocalRunStatus::Failed | LocalRunStatus::RolledBack => {}
        }
    }

    let mut program_actions = vec![GeneralAudienceActionItem {
        action_id: "program:drive-controlled-evolution".to_string(),
        title: "Drive controlled evolution".to_string(),
        description:
            "Create and execute the carried controlled-evolution demo through the existing program driver endpoint."
                .to_string(),
        kind: "program_control".to_string(),
        button_label: "Drive program".to_string(),
        endpoint: "/api/programs/controlled-evolution/drive".to_string(),
        method: "POST".to_string(),
        scenario_id: None,
        run_id: None,
        program_instance_id: None,
        payload_template: None,
        guardrail: Some(
            "This runs the bounded built-in controlled-evolution demonstration.".to_string(),
        ),
    }];

    for program in programs.programs.iter().filter(|program| {
        !matches!(
            program.instance.program_state,
            crate::execution::FactoryProgramState::Completed
                | crate::execution::FactoryProgramState::Stopped
        )
    }) {
        let tick_request = default_program_tick_request(program);
        program_actions.push(GeneralAudienceActionItem {
            action_id: format!("program:{}:tick", program.instance.instance_id),
            title: format!("Tick {}", program.spec.title),
            description: "Submit one bounded program tick against the selected program instance."
                .to_string(),
            kind: "program_control".to_string(),
            button_label: "Submit tick".to_string(),
            endpoint: format!("/api/programs/{}/tick", program.instance.instance_id),
            method: "POST".to_string(),
            scenario_id: None,
            run_id: None,
            program_instance_id: Some(program.instance.instance_id.clone()),
            payload_template: serde_json::to_string_pretty(&tick_request).ok(),
            guardrail: Some(
                "Edit the JSON if you need different proving, observation, or rollback references."
                    .to_string(),
            ),
        });

        let llm_request = default_llm_drive_request(program);
        program_actions.push(GeneralAudienceActionItem {
            action_id: format!("program:{}:llm-drive", program.instance.instance_id),
            title: format!("LLM-drive {}", program.spec.title),
            description:
                "Drive the selected program instance through the existing LLM-backed endpoint."
                    .to_string(),
            kind: "program_control".to_string(),
            button_label: "Run LLM drive".to_string(),
            endpoint: format!("/api/programs/{}/llm-drive", program.instance.instance_id),
            method: "POST".to_string(),
            scenario_id: None,
            run_id: None,
            program_instance_id: Some(program.instance.instance_id.clone()),
            payload_template: serde_json::to_string_pretty(&llm_request).ok(),
            guardrail: Some(
                "This requires a configured inference provider and model reference.".to_string(),
            ),
        });
    }

    GeneralAudienceAdvancedActionsView {
        scenario_actions,
        run_controls,
        program_actions,
        guardrails: vec![
            "Advanced controls call the existing run and program endpoints directly; they do not add any new execution path.".to_string(),
            "Pause is only relevant when a supported live shell run is actually active in the current runtime state.".to_string(),
            "LLM-drive requests require a configured provider, model, and bounded generation policy.".to_string(),
        ],
    }
}

