fn seed_factory_01_assets(
    workspace: &LocalRuntimeWorkspace,
    factory_program_specs: &mut Vec<crate::execution::FactoryProgramSpec>,
    inference_store: &DurableArtifactStore,
) -> Result<(), LocalRuntimeError> {
    let mut specs_changed = false;
    if !factory_program_specs
        .iter()
        .any(|spec| spec.spec_id == FACTORY_01_SPEC_ID)
    {
        factory_program_specs.push(build_factory_01_program_spec());
        specs_changed = true;
    }
    if !factory_program_specs
        .iter()
        .any(|spec| spec.spec_id == FACTORY_01_M1_SPEC_ID)
    {
        factory_program_specs.push(build_factory_01_m1_program_spec());
        specs_changed = true;
    }
    if specs_changed {
        factory_program_specs.sort_by(|left, right| {
            left.title
                .cmp(&right.title)
                .then_with(|| left.spec_id.cmp(&right.spec_id))
        });
        write_json(
            workspace.factory_program_specs_path(),
            factory_program_specs,
        )?;
    }

    let profiles = inference_store.list_llm_factory_program_profiles()?;
    if !profiles
        .iter()
        .any(|profile| profile.llm_factory_program_profile_id == FACTORY_01_PROFILE_ID)
    {
        inference_store
            .persist_llm_factory_program_profile(&build_factory_01_llm_driver_profile())?;
    }
    if !profiles
        .iter()
        .any(|profile| profile.llm_factory_program_profile_id == FACTORY_01_M1_PROFILE_ID)
    {
        inference_store
            .persist_llm_factory_program_profile(&build_factory_01_m1_llm_driver_profile())?;
    }

    Ok(())
}

