fn build_experiment_program_view(
    run_views: &[RunViewModel],
    review_packets: &[OperatorReviewPacket],
) -> ExperimentProgramView {
    let compositions = scenario_compositions();
    let run_sets = run_set_registry();
    let rehearsal_programs = rehearsal_programs();
    let regression_packs = regression_packs();
    let summary = if run_views.is_empty() {
        format!(
            "The experiment workspace exposes {} composition(s), {} run-set(s), {} rehearsal program(s), and {} regression pack(s) before local history exists.",
            compositions.len(),
            run_sets.len(),
            rehearsal_programs.len(),
            regression_packs.len()
        )
    } else {
        format!(
            "The experiment workspace exposes {} composition(s), {} run-set(s), {} rehearsal program(s), {} regression pack(s), and {} stored review packet(s) across {} local run(s).",
            compositions.len(),
            run_sets.len(),
            rehearsal_programs.len(),
            regression_packs.len(),
            review_packets.len(),
            run_views.len()
        )
    };

    ExperimentProgramView {
        summary,
        compositions,
        run_sets,
        rehearsal_programs,
        regression_packs,
        governance_rules: vec![
            "Composition resolves back into the existing fixed-interface runtime contract."
                .to_string(),
            "Run-sets and regression packs remain bounded, local, and evidence-linked.".to_string(),
            "Experiment-program metadata cannot override approval, rollback, or replay truth."
                .to_string(),
        ],
    }
}

