fn persist_tool_catalog_bundle(
    store: &DurableArtifactStore,
    bundle: &CanonicalToolCatalogBundle,
) -> Result<(), LocalRuntimeError> {
    bundle.validate().map_err(map_tool_membrane_runtime_error)?;
    store.persist_tool_catalog_record(&bundle.catalog)?;
    for record in &bundle.definitions {
        store.persist_model_tool_definition(record)?;
    }
    for record in &bundle.argument_schemas {
        store.persist_tool_argument_schema_record(record)?;
    }
    for record in &bundle.result_schemas {
        store.persist_tool_result_schema_record(record)?;
    }
    for record in &bundle.exposure_decisions {
        store.persist_tool_exposure_decision_record(record)?;
    }
    for record in &bundle.operator_only_surfaces {
        store.persist_operator_only_surface_record(record)?;
    }
    Ok(())
}

fn load_tool_execution_view(
    store: &DurableArtifactStore,
    tool_execution_id: &str,
) -> Result<ToolExecutionView, LocalRuntimeError> {
    let execution = store.load_tool_execution_record(tool_execution_id)?;
    let legality = store.load_tool_call_legality_record(&execution.legality_ref)?;
    let tool_definition = store.load_model_tool_definition(&execution.tool_id)?;
    let argument_schema =
        store.load_tool_argument_schema_record(&tool_definition.argument_schema_ref)?;
    let result_schema = store.load_tool_result_schema_record(&tool_definition.result_schema_ref)?;
    let exposure_decision = store.load_tool_exposure_decision_record(&format!(
        "tool-exposure:{}",
        tool_definition.tool_id
    ))?;
    let summary = format!(
        "Tool execution `{}` resolved as `{:?}` for tool `{}`.",
        execution.tool_execution_id, execution.decision, execution.tool_id
    );
    Ok(ToolExecutionView {
        summary,
        execution,
        legality,
        tool_definition,
        argument_schema,
        result_schema,
        exposure_decision,
    })
}

fn load_parsed_turn_tool_execution_view(
    store: &DurableArtifactStore,
    parsed_turn_tool_execution_receipt_id: &str,
) -> Result<ParsedTurnToolExecutionView, LocalRuntimeError> {
    let receipt =
        store.load_parsed_turn_tool_execution_receipt(parsed_turn_tool_execution_receipt_id)?;
    let executions = receipt
        .tool_execution_refs
        .iter()
        .map(|record_ref| load_tool_execution_view(store, record_ref))
        .collect::<Result<Vec<_>, _>>()?;
    let summary = format!(
        "Parsed turn tool execution receipt `{}` stopped as `{:?}`.",
        receipt.parsed_turn_tool_execution_receipt_id, receipt.terminal_decision
    );
    Ok(ParsedTurnToolExecutionView {
        summary,
        receipt,
        executions,
    })
}

fn build_tool_catalog_view(bundle: &CanonicalToolCatalogBundle) -> ToolCatalogView {
    ToolCatalogView {
        summary: format!(
            "Canonical tool catalog `{}` exposes {} model-facing tool(s).",
            bundle.catalog.tool_catalog_id,
            bundle.definitions.len()
        ),
        catalog: bundle.catalog.clone(),
        definitions: bundle.definitions.clone(),
        argument_schemas: bundle.argument_schemas.clone(),
        result_schemas: bundle.result_schemas.clone(),
        exposure_decisions: bundle.exposure_decisions.clone(),
    }
}

fn build_tool_definition_view(
    bundle: &CanonicalToolCatalogBundle,
    tool_id: &str,
) -> Result<ToolDefinitionView, LocalRuntimeError> {
    let tool_definition = bundle.definition(tool_id).cloned().ok_or_else(|| {
        LocalRuntimeError::InvalidTurnPackageOperation {
            identifier: tool_id.to_string(),
            reason: format!("tool '{tool_id}' is not defined"),
        }
    })?;
    let argument_schema = bundle
        .argument_schema_for(tool_id)
        .cloned()
        .ok_or_else(|| LocalRuntimeError::InvalidTurnPackageOperation {
            identifier: tool_id.to_string(),
            reason: format!("tool '{tool_id}' is missing an argument schema"),
        })?;
    let result_schema = bundle.result_schema_for(tool_id).cloned().ok_or_else(|| {
        LocalRuntimeError::InvalidTurnPackageOperation {
            identifier: tool_id.to_string(),
            reason: format!("tool '{tool_id}' is missing a result schema"),
        }
    })?;
    let exposure_decision = bundle.exposure_for(tool_id).cloned().ok_or_else(|| {
        LocalRuntimeError::InvalidTurnPackageOperation {
            identifier: tool_id.to_string(),
            reason: format!("tool '{tool_id}' is missing an exposure decision"),
        }
    })?;
    Ok(ToolDefinitionView {
        summary: format!(
            "Tool `{}` is exposed as a {:?} membrane tool.",
            tool_id, tool_definition.family
        ),
        tool_definition,
        argument_schema,
        result_schema,
        exposure_decision,
    })
}

fn map_tool_membrane_runtime_error(error: ToolMembraneError) -> LocalRuntimeError {
    match error {
        ToolMembraneError::ServiceFailure { tool_id, reason } => {
            LocalRuntimeError::InferenceExecutionFailed {
                identifier: tool_id,
                reason,
            }
        }
        other => LocalRuntimeError::InvalidTurnPackageOperation {
            identifier: "tool-membrane".to_string(),
            reason: other.to_string(),
        },
    }
}

fn persist_turn_render_bundle(
    store: &DurableArtifactStore,
    bundle: &crate::execution::TurnRenderBundle,
) -> Result<(), LocalRuntimeError> {
    bundle.validate().map_err(|error| {
        invalid_turn_package_operation(&bundle.turn_package.turn_package_id, error)
    })?;
    store.persist_context_budget_record(&bundle.context_budget)?;
    store.persist_context_truncation_record(&bundle.truncation)?;
    for layer in &bundle.prompt_layers {
        store.persist_prompt_layer_record(layer)?;
    }
    store.persist_turn_response_schema_record(&bundle.response_schema)?;
    store.persist_prompt_rendering_record(&bundle.rendering)?;
    Ok(())
}

fn persist_parsed_turn_bundle(
    store: &DurableArtifactStore,
    bundle: &crate::execution::ParsedTurnBundle,
) -> Result<(), LocalRuntimeError> {
    bundle.validate().map_err(|error| {
        invalid_turn_package_operation(&bundle.parsed_result.parsed_turn_result_id, error)
    })?;
    for record in &bundle.repair_records {
        store.persist_parse_repair_record(record)?;
    }
    for record in &bundle.parsed_tool_call_intents {
        store.persist_parsed_tool_call_intent_record(record)?;
    }
    for record in &bundle.parsed_proposals {
        store.persist_parsed_proposal_record(record)?;
    }
    if let Some(record) = &bundle.parsed_approval_request {
        store.persist_parsed_approval_request_record(record)?;
    }
    store.persist_parsed_turn_result(&bundle.parsed_result)?;
    Ok(())
}

fn upsert_turn_package(turn_packages: &mut Vec<TurnPackage>, turn_package: TurnPackage) {
    if let Some(entry) = turn_packages
        .iter_mut()
        .find(|entry| entry.turn_package_id == turn_package.turn_package_id)
    {
        *entry = turn_package;
    } else {
        turn_packages.push(turn_package);
    }
    turn_packages.sort_by(|left, right| {
        run_timestamp(&right.created_at)
            .cmp(&run_timestamp(&left.created_at))
            .then_with(|| left.turn_package_id.cmp(&right.turn_package_id))
    });
}

