fn required_m1_argument_digest(
    definition: &ModelToolDefinition,
    arguments: &serde_json::Value,
    field: &str,
) -> Result<ContentDigest, ToolMembraneError> {
    let value = required_argument_string(arguments, field)?;
    ContentDigest::new(value).map_err(|error| m1_tool_service_failure(definition, error))
}

fn m1_tool_service_failure(
    definition: &ModelToolDefinition,
    reason: impl Display,
) -> ToolMembraneError {
    ToolMembraneError::ServiceFailure {
        tool_id: definition.tool_id.clone(),
        reason: reason.to_string(),
    }
}

fn execute_continuity_retrieve_tool(
    definition: &ModelToolDefinition,
    arguments: &serde_json::Value,
    turn_package: &TurnPackage,
    context: &ToolExecutionContextRecord,
) -> Result<crate::execution::ToolServiceExecutionOutcome, ToolMembraneError> {
    let bundle_class = topic_bundle_class_from_args(arguments);
    let search_term = arguments
        .get("search_term")
        .and_then(serde_json::Value::as_str)
        .map(str::to_string);
    let max_bundle_refs = arguments
        .get("max_bundle_refs")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(2) as usize;
    let pointer_index_ref = context.pointer_index_ref.clone().ok_or(
        ToolMembraneError::MissingExecutionContextField {
            field: crate::execution::ToolContextField::PointerIndexRef,
        },
    )?;
    let mut memory_store = MemoryStore::default();
    let topic_bundle_id = format!(
        "topic-bundle:{}:{}",
        sanitize_id(&pointer_index_ref),
        sanitize_id(&definition.tool_id)
    );
    let transcript_slice_id = format!(
        "transcript-slice:{}:{}",
        sanitize_id(&turn_package.turn_ref),
        sanitize_id(&definition.tool_id)
    );
    memory_store.add_topic_bundle(TopicBundle {
        bundle_id: topic_bundle_id.clone(),
        bundle_class,
        scope: MemoryScope::Session(turn_package.session_ref.clone()),
        summary: "bounded continuity bundle".to_string(),
        evidence_refs: vec![turn_package.turn_ref.clone()],
        freshness_policy: "bounded".to_string(),
    });
    memory_store.add_transcript_slice(TranscriptSlice {
        slice_id: transcript_slice_id,
        campaign_id: context
            .campaign_ref
            .clone()
            .unwrap_or_else(|| "campaign:continuity".to_string()),
        epoch_id: context
            .epoch_ref
            .clone()
            .unwrap_or_else(|| "epoch:continuity".to_string()),
        session_id: Some(turn_package.session_ref.clone()),
        task_id: context.task_ref.clone(),
        referenced_artifacts: vec![turn_package.turn_ref.clone()],
        summary: "bounded transcript slice".to_string(),
        excerpts: vec!["bounded continuity excerpt".to_string()],
    });
    memory_store.insert_pointer_index(PointerIndex {
        index_id: pointer_index_ref.clone(),
        scope: MemoryScope::Session(turn_package.session_ref.clone()),
        entry_refs: vec![topic_bundle_id],
        contested_refs: Vec::new(),
        critical_refs: vec![turn_package.turn_ref.clone()],
        governance_constraints: vec!["bounded".to_string()],
        open_task_refs: context.task_ref.clone().into_iter().collect(),
        updated_at: current_timestamp(),
    });
    let trace = crate::execution::execute_memory_retrieval_protocol(
        &memory_store,
        &crate::execution::MemoryRetrievalRequest {
            retrieval_request_id: format!(
                "retrieval:{}",
                sanitize_id(&turn_package.turn_package_id)
            ),
            shell_session_id: turn_package.session_ref.clone(),
            shell_turn_id: turn_package.turn_ref.clone(),
            pointer_index_ref,
            bundle_class,
            transcript_query: crate::execution::TranscriptSliceQuery {
                campaign_id: context.campaign_ref.clone(),
                epoch_id: context.epoch_ref.clone(),
                session_id: Some(turn_package.session_ref.clone()),
                task_id: context.task_ref.clone(),
                artifact_ref: None,
                search_term,
            },
            max_bundle_refs,
        },
    )
    .map_err(|error| ToolMembraneError::ServiceFailure {
        tool_id: definition.tool_id.clone(),
        reason: error.to_string(),
    })?;
    let payload = serde_json::json!({
        "trace_id": trace.trace_id,
        "bundle_refs": trace.bundle_refs,
        "transcript_slice_refs": trace.transcript_slice_refs,
        "evidence_refs": trace.evidence_refs,
    });
    Ok(successful_tool_outcome(
        payload
            .get("trace_id")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("retrieval-trace:unknown"),
        payload.to_string(),
        Vec::new(),
    ))
}

