fn execute_ecology_dispatch_worker_tool(
    definition: &ModelToolDefinition,
    arguments: &serde_json::Value,
    turn_package: &TurnPackage,
    context: &ToolExecutionContextRecord,
) -> Result<crate::execution::ToolServiceExecutionOutcome, ToolMembraneError> {
    let requested_capabilities = arguments
        .get("requested_capabilities")
        .and_then(serde_json::Value::as_array)
        .ok_or_else(|| ToolMembraneError::ServiceFailure {
            tool_id: definition.tool_id.clone(),
            reason: "requested_capabilities must be an array".to_string(),
        })?
        .iter()
        .map(|item| {
            Ok(crate::execution::CapabilityOperationRequest {
                world: capability_world_from_wire(required_json_string(item, "world")?)?,
                operation: required_json_string(item, "operation")?,
                resource_scope: required_json_string(item, "resource_scope")?,
            })
        })
        .collect::<Result<Vec<_>, ToolMembraneError>>()?;
    let dispatch = crate::execution::WorkerDispatch {
        dispatch_id: format!(
            "worker-dispatch:{}:{}",
            sanitize_id(&turn_package.turn_package_id),
            sanitize_id(&required_argument_string(arguments, "worker_id")?)
        ),
        task_id: context
            .task_ref
            .clone()
            .unwrap_or_else(|| turn_package.turn_ref.clone()),
        parent_session_id: turn_package.session_ref.clone(),
        worker_id: required_argument_string(arguments, "worker_id")?,
        worker_task_ref: required_argument_string(arguments, "worker_task_ref")?,
        capability_envelope_ref: context.capability_envelope.envelope_id.clone(),
        requested_capabilities,
        dispatch_message: crate::execution::MessageArtifact {
            message_id: format!("message:{}", sanitize_id(&turn_package.turn_ref)),
            campaign_id: context
                .campaign_ref
                .clone()
                .unwrap_or_else(|| "campaign:worker".to_string()),
            epoch_id: context
                .epoch_ref
                .clone()
                .unwrap_or_else(|| "epoch:worker".to_string()),
            task_id: context
                .task_ref
                .clone()
                .unwrap_or_else(|| turn_package.turn_ref.clone()),
            sender_actor_ref: turn_package.turn_ref.clone(),
            receiver_actor_ref: required_argument_string(arguments, "worker_id")?,
            message_class: crate::execution::MessageArtifactClass::DispatchMessage,
            payload_summary: arguments
                .get("task_kind")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("bounded-task")
                .to_string(),
            referenced_artifacts: vec![turn_package.turn_package_id.clone()],
            status: crate::execution::MessageArtifactStatus::Prepared,
        },
    };
    let payload = serde_json::json!({
        "dispatch_id": dispatch.dispatch_id,
        "worker_id": dispatch.worker_id,
        "worker_task_ref": dispatch.worker_task_ref,
    });
    Ok(successful_tool_outcome(
        payload
            .get("dispatch_id")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("worker-dispatch:unknown"),
        payload.to_string(),
        Vec::new(),
    ))
}

