fn required_argument_string(
    arguments: &serde_json::Value,
    field: &str,
) -> Result<String, ToolMembraneError> {
    arguments
        .get(field)
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| ToolMembraneError::ServiceFailure {
            tool_id: field.to_string(),
            reason: format!("missing required argument '{field}'"),
        })
}

fn required_argument_string_array(
    arguments: &serde_json::Value,
    field: &str,
) -> Result<Vec<String>, ToolMembraneError> {
    let array = arguments
        .get(field)
        .and_then(serde_json::Value::as_array)
        .ok_or_else(|| ToolMembraneError::ServiceFailure {
            tool_id: field.to_string(),
            reason: format!("missing required argument array '{field}'"),
        })?;
    array
        .iter()
        .map(|item| {
            item.as_str()
                .map(str::to_string)
                .filter(|value| !value.trim().is_empty())
                .ok_or_else(|| ToolMembraneError::ServiceFailure {
                    tool_id: field.to_string(),
                    reason: format!("argument array '{field}' contains an invalid value"),
                })
        })
        .collect()
}

fn required_json_string(
    value: &serde_json::Value,
    field: &str,
) -> Result<String, ToolMembraneError> {
    value
        .get(field)
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| ToolMembraneError::ServiceFailure {
            tool_id: field.to_string(),
            reason: format!("missing required field '{field}'"),
        })
}

fn parse_json_object(raw: &str) -> Result<serde_json::Value, LocalRuntimeError> {
    let value: serde_json::Value = serde_json::from_str(raw)?;
    if !value.is_object() {
        return Err(LocalRuntimeError::InvalidTurnPackageOperation {
            identifier: "json-object".to_string(),
            reason: "expected JSON object payload".to_string(),
        });
    }
    Ok(value)
}

fn parse_optional_json_object(
    raw: Option<&str>,
) -> Result<Option<serde_json::Value>, LocalRuntimeError> {
    raw.map(parse_json_object).transpose()
}

fn json_string_field(value: Option<&serde_json::Value>, field: &str) -> Option<String> {
    value
        .and_then(|value| value.get(field))
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .filter(|value| !value.trim().is_empty())
}

fn json_string_array_field(value: Option<&serde_json::Value>, field: &str) -> Vec<String> {
    value
        .and_then(|value| value.get(field))
        .and_then(serde_json::Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| {
                    item.as_str()
                        .map(str::to_string)
                        .filter(|value| !value.trim().is_empty())
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn capability_requests_from_json(
    value: &serde_json::Value,
    field: &str,
) -> Result<Vec<crate::execution::CapabilityOperationRequest>, LocalRuntimeError> {
    let Some(items) = value.get(field).and_then(serde_json::Value::as_array) else {
        return Ok(Vec::new());
    };
    let mut requests = Vec::with_capacity(items.len());
    for item in items {
        let world = item
            .get("world")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
            .ok_or_else(|| LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: field.to_string(),
                reason: "requested capability is missing `world`".to_string(),
            })?;
        let operation = item
            .get("operation")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
            .ok_or_else(|| LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: field.to_string(),
                reason: "requested capability is missing `operation`".to_string(),
            })?;
        let resource_scope = item
            .get("resource_scope")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
            .ok_or_else(|| LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: field.to_string(),
                reason: "requested capability is missing `resource_scope`".to_string(),
            })?;
        requests.push(crate::execution::CapabilityOperationRequest {
            world: capability_world_from_wire(world).map_err(map_tool_membrane_runtime_error)?,
            operation,
            resource_scope,
        });
    }
    Ok(requests)
}

fn capability_world_wire_value(world: &CapabilityWorld) -> String {
    match world {
        CapabilityWorld::WorkspaceObserve => "workspace_observe",
        CapabilityWorld::WorkspaceMutate => "workspace_mutate",
        CapabilityWorld::MemoryAccess => "memory_access",
        CapabilityWorld::WorkerMessaging => "worker_messaging",
        CapabilityWorld::CampaignControl => "campaign_control",
        CapabilityWorld::ApprovalGateway => "approval_gateway",
        CapabilityWorld::ScheduleTick => "schedule_tick",
        CapabilityWorld::ServiceOrganelle => "service_organelle",
        CapabilityWorld::ReviewPromotion => "review_promotion",
    }
    .to_string()
}

fn determine_recursive_cycle_outcome(
    authority_decision: ModelAuthorityDecisionKind,
    pending_actions: &[PendingGovernedTurnActionRecord],
    has_tool_execution: bool,
    has_worker_activity: bool,
    tick_receipt: Option<&crate::execution::FactoryProgramTickReceipt>,
) -> crate::execution::RecursiveCycleOutcome {
    let granted_execution = pending_actions
        .iter()
        .any(|action| action.resolution_status == PendingGovernedTurnActionStatus::GrantedExecuted);
    let resolved_without_execution = pending_actions.iter().any(|action| {
        matches!(
            action.resolution_status,
            PendingGovernedTurnActionStatus::Denied
                | PendingGovernedTurnActionStatus::Expired
                | PendingGovernedTurnActionStatus::Escalated
        )
    });
    if let Some(receipt) = tick_receipt {
        return crate::execution::recursive_cycle_outcome_from_adoption_result(
            receipt.adoption_window.result,
        );
    }
    if authority_decision == ModelAuthorityDecisionKind::ApprovalBlock
        && !granted_execution
        && !resolved_without_execution
    {
        return crate::execution::RecursiveCycleOutcome::ApprovalBlocked;
    }
    if authority_decision == ModelAuthorityDecisionKind::ApprovalBlock && resolved_without_execution
    {
        return crate::execution::RecursiveCycleOutcome::Denied;
    }
    match authority_decision {
        ModelAuthorityDecisionKind::Deny => crate::execution::RecursiveCycleOutcome::Denied,
        ModelAuthorityDecisionKind::Quarantine => {
            crate::execution::RecursiveCycleOutcome::Quarantined
        }
        ModelAuthorityDecisionKind::Fail => crate::execution::RecursiveCycleOutcome::Failed,
        ModelAuthorityDecisionKind::Allow | ModelAuthorityDecisionKind::ApprovalBlock => {
            if has_worker_activity || has_tool_execution || granted_execution {
                crate::execution::RecursiveCycleOutcome::WorkerDispatched
            } else {
                crate::execution::RecursiveCycleOutcome::WorkerDispatched
            }
        }
    }
}

