fn build_factory_program_view(
    spec: &crate::execution::FactoryProgramSpec,
    instance: &crate::execution::FactoryProgramInstance,
    receipts: &[crate::execution::FactoryProgramTickReceipt],
) -> Result<FactoryProgramView, LocalRuntimeError> {
    spec.validate()
        .map_err(|error| invalid_factory_program_operation(&spec.spec_id, error))?;
    instance
        .validate()
        .map_err(|error| invalid_factory_program_operation(&instance.instance_id, error))?;

    let mut receipts = receipts.to_vec();
    receipts.sort_by(|left, right| {
        left.campaign_count
            .cmp(&right.campaign_count)
            .then_with(|| run_timestamp(&left.created_at).cmp(&run_timestamp(&right.created_at)))
            .then_with(|| left.tick_id.cmp(&right.tick_id))
    });
    for receipt in &receipts {
        receipt
            .validate()
            .map_err(|error| invalid_factory_program_operation(&instance.instance_id, error))?;
    }

    let recurring_program = receipts
        .last()
        .map(|receipt| receipt.recurring_program.clone());
    let lineage_ledger = if receipts.is_empty() {
        None
    } else {
        Some(build_factory_program_lineage_ledger(instance, &receipts)?)
    };
    let regression_packet = match (&lineage_ledger, receipts.is_empty()) {
        (Some(ledger), false) => Some(build_factory_program_regression_packet(
            spec, instance, ledger, &receipts,
        )?),
        _ => None,
    };
    let longitudinal_lineage_dossier = match (&lineage_ledger, &regression_packet) {
        (Some(ledger), Some(packet)) => Some(build_factory_program_longitudinal_dossier(
            instance, ledger, packet, &receipts,
        )?),
        _ => None,
    };
    let summary = if receipts.is_empty() {
        format!(
            "Program `{}` is `{}` at the root factory with no governed evolution tick recorded yet.",
            spec.title,
            factory_program_state_label(instance.program_state)
        )
    } else {
        format!(
            "Program `{}` is `{}` after {} governed campaign(s), with generation depth {} of {} and current factory `{}`.",
            spec.title,
            factory_program_state_label(instance.program_state),
            instance.campaign_count,
            instance.generation_depth,
            spec.recursion_budget.max_depth,
            instance.current_factory_ref
        )
    };

    Ok(FactoryProgramView {
        summary,
        spec: spec.clone(),
        instance: instance.clone(),
        recurring_program,
        receipts,
        lineage_ledger,
        regression_packet,
        longitudinal_lineage_dossier,
        llm_driver_profile: None,
        model_factory_cycles: Vec::new(),
        produced_worker_agents: Vec::new(),
        recursive_lineage_execution: None,
        architectural_dependency_statement: None,
        recursion_closure_dossier: None,
    })
}

