fn factory_template_replacements(
    spec: &crate::execution::FactoryProgramSpec,
    instance: &crate::execution::FactoryProgramInstance,
    program_key: &str,
    campaign_number: usize,
    campaign_ref: &str,
    epoch_ref: &str,
    task_ref: &str,
) -> Vec<(String, String)> {
    vec![
        (
            "program_instance_ref".to_string(),
            instance.instance_id.clone(),
        ),
        ("program_spec_id".to_string(), spec.spec_id.clone()),
        ("program_title".to_string(), spec.title.clone()),
        (
            "program_instance_short_token".to_string(),
            program_key.to_string(),
        ),
        (
            "root_factory_ref".to_string(),
            spec.root_factory_ref.clone(),
        ),
        (
            "current_factory_ref".to_string(),
            instance.current_factory_ref.clone(),
        ),
        (
            "program_state".to_string(),
            factory_program_state_label(instance.program_state).to_string(),
        ),
        (
            "generation_depth".to_string(),
            instance.generation_depth.to_string(),
        ),
        (
            "campaign_count".to_string(),
            instance.campaign_count.to_string(),
        ),
        (
            "next_campaign_number".to_string(),
            campaign_number.to_string(),
        ),
        (
            "max_generation_depth".to_string(),
            spec.recursion_budget.max_depth.to_string(),
        ),
        (
            "max_campaigns".to_string(),
            spec.recursion_budget.max_campaigns.to_string(),
        ),
        ("campaign_ref".to_string(), campaign_ref.to_string()),
        ("epoch_ref".to_string(), epoch_ref.to_string()),
        ("task_ref".to_string(), task_ref.to_string()),
    ]
}

fn render_factory_profile_template(template: &str, replacements: &[(String, String)]) -> String {
    let mut rendered = template.to_string();
    for (key, value) in replacements {
        rendered = rendered.replace(&format!("{{{{{key}}}}}"), value);
    }
    rendered
}

fn render_factory_profile_capability_envelope(
    envelope: &crate::execution::CapabilityEnvelope,
    replacements: &[(String, String)],
) -> crate::execution::CapabilityEnvelope {
    crate::execution::CapabilityEnvelope {
        envelope_id: render_factory_profile_template(&envelope.envelope_id, replacements),
        actor_scope: render_factory_profile_template(&envelope.actor_scope, replacements),
        world_grants: envelope.world_grants.clone(),
        authority_ceiling: envelope.authority_ceiling.clone(),
        isolation_profile: envelope.isolation_profile.clone(),
        allowed_resource_scopes: envelope
            .allowed_resource_scopes
            .iter()
            .map(|scope| render_factory_profile_template(scope, replacements))
            .collect(),
        approval_overrides: envelope
            .approval_overrides
            .iter()
            .map(|scope| render_factory_profile_template(scope, replacements))
            .collect(),
        quota_policy: envelope
            .quota_policy
            .as_deref()
            .map(|value| render_factory_profile_template(value, replacements)),
        campaign_scope: envelope
            .campaign_scope
            .as_deref()
            .map(|value| render_factory_profile_template(value, replacements)),
        epoch_scope: envelope
            .epoch_scope
            .as_deref()
            .map(|value| render_factory_profile_template(value, replacements)),
    }
}

fn build_architectural_dependency_statement(
    store: &DurableArtifactStore,
    lineage: &crate::execution::RecursiveLineageExecutionRecord,
    cycles: &[crate::execution::ModelDrivenFactoryCycleRecord],
) -> Result<crate::execution::ArchitecturalDependencyStatement, LocalRuntimeError> {
    let mut inference_provider_refs = Vec::new();
    for cycle in cycles {
        let inference_turn = store.load_inference_turn_result(&cycle.inference_turn_result_ref)?;
        let turn_request = store.load_inference_turn_request(&inference_turn.turn_request_ref)?;
        inference_provider_refs.push(turn_request.provider_ref);
    }
    Ok(crate::execution::ArchitecturalDependencyStatement {
        architectural_dependency_statement_id: architectural_dependency_statement_id(
            &lineage.program_instance_ref,
        ),
        lineage_ref: lineage.recursive_lineage_execution_id.clone(),
        inference_provider_refs: unique_strings(inference_provider_refs),
        turn_refs: lineage.model_turn_refs.clone(),
        tool_membrane_refs: unique_strings(cycles.iter().flat_map(|cycle| {
            std::iter::once(cycle.parsed_turn_result_ref.clone())
                .chain(cycle.tool_execution_receipt_refs.clone())
                .chain(cycle.tool_execution_refs.clone())
        })),
        continuity_refs: lineage.continuity_refs.clone(),
        governance_refs: lineage.governance_refs.clone(),
        operator_boundary_refs: unique_strings(cycles.iter().flat_map(|cycle| {
            std::iter::once(cycle.authority_decision_ref.clone())
                .chain(cycle.quarantine_refs.clone())
                .chain(cycle.approval_request_refs.clone())
                .chain(cycle.checkpoint_refs.clone())
                .chain(cycle.pending_action_refs.clone())
        })),
        claim_posture: lineage.claim_posture,
        claim_boundary_statement: crate::execution::claim_boundary_statement(lineage.claim_posture)
            .to_string(),
        created_at: current_timestamp(),
    })
}

fn build_interface_native_recursion_closure_dossier(
    lineage: &crate::execution::RecursiveLineageExecutionRecord,
    cycles: &[crate::execution::ModelDrivenFactoryCycleRecord],
    dependency_statement: &crate::execution::ArchitecturalDependencyStatement,
) -> Result<crate::execution::InterfaceNativeRecursionClosureDossier, LocalRuntimeError> {
    Ok(crate::execution::InterfaceNativeRecursionClosureDossier {
        recursion_closure_dossier_id: recursion_closure_dossier_id(&lineage.program_instance_ref),
        lineage_ref: lineage.recursive_lineage_execution_id.clone(),
        cycle_refs: lineage.cycle_refs.clone(),
        produced_worker_refs: lineage.produced_worker_refs.clone(),
        proving_refs: unique_strings(cycles.iter().flat_map(|cycle| cycle.proving_refs.clone())),
        observation_refs: unique_strings(
            cycles
                .iter()
                .flat_map(|cycle| cycle.observation_refs.clone()),
        ),
        comparison_refs: unique_strings(
            cycles
                .iter()
                .flat_map(|cycle| cycle.comparison_refs.clone()),
        ),
        continuity_refs: lineage.continuity_refs.clone(),
        governance_refs: lineage.governance_refs.clone(),
        dependency_statement_ref: dependency_statement
            .architectural_dependency_statement_id
            .clone(),
        claim_posture: lineage.claim_posture,
        claim_boundary_statement: dependency_statement.claim_boundary_statement.clone(),
        created_at: current_timestamp(),
    })
}

fn build_factory_program_lineage_ledger(
    instance: &crate::execution::FactoryProgramInstance,
    receipts: &[crate::execution::FactoryProgramTickReceipt],
) -> Result<crate::execution::LineageHealthLedger, LocalRuntimeError> {
    let ledger = crate::execution::LineageHealthLedger {
        lineage_ledger_id: format!(
            "factory-program-lineage-ledger:{}",
            sanitize_id(&instance.instance_id)
        ),
        program_ref: instance.recurring_program_ref.clone(),
        generation_refs: instance.adopted_factory_refs.clone(),
        cycle_result_refs: instance.cycle_refs.clone(),
        continuity_refs: instance.continuity_window_refs.clone(),
        regression_refs: vec![format!(
            "factory-program-regression-packet:{}",
            sanitize_id(&instance.instance_id)
        )],
        rollback_refs: unique_strings(
            receipts
                .iter()
                .flat_map(|receipt| receipt.adoption_window.rollback_refs.iter().cloned()),
        ),
    };
    ledger
        .validate()
        .map_err(|error| invalid_factory_program_operation(&instance.instance_id, error))?;
    Ok(ledger)
}

fn build_factory_program_regression_packet(
    spec: &crate::execution::FactoryProgramSpec,
    instance: &crate::execution::FactoryProgramInstance,
    ledger: &crate::execution::LineageHealthLedger,
    receipts: &[crate::execution::FactoryProgramTickReceipt],
) -> Result<crate::execution::RegressionReviewPacket, LocalRuntimeError> {
    let packet = crate::execution::RegressionReviewPacket {
        regression_packet_id: format!(
            "factory-program-regression-packet:{}",
            sanitize_id(&instance.instance_id)
        ),
        lineage_ledger_ref: ledger.lineage_ledger_id.clone(),
        threshold_refs: unique_strings(
            spec.utility_metric_refs
                .iter()
                .cloned()
                .chain(spec.rollback_gate_refs.iter().cloned()),
        ),
        trigger_refs: unique_strings(
            receipts
                .iter()
                .flat_map(|receipt| receipt.stop_condition.trigger_refs.iter().cloned()),
        ),
        mitigation_refs: unique_strings(
            receipts
                .iter()
                .flat_map(|receipt| receipt.adoption_window.rollback_refs.iter().cloned())
                .chain(spec.rollback_gate_refs.iter().cloned()),
        ),
        summary: format!(
            "Regression review preserves bounded rollout gates across {} campaign(s).",
            receipts.len()
        ),
    };
    packet
        .validate()
        .map_err(|error| invalid_factory_program_operation(&instance.instance_id, error))?;
    Ok(packet)
}

fn build_factory_program_longitudinal_dossier(
    instance: &crate::execution::FactoryProgramInstance,
    ledger: &crate::execution::LineageHealthLedger,
    packet: &crate::execution::RegressionReviewPacket,
    receipts: &[crate::execution::FactoryProgramTickReceipt],
) -> Result<crate::execution::LongitudinalLineageDossier, LocalRuntimeError> {
    let dossier = crate::execution::LongitudinalLineageDossier {
        lineage_dossier_id: format!(
            "factory-program-longitudinal-lineage:{}",
            sanitize_id(&instance.instance_id)
        ),
        program_ref: instance.recurring_program_ref.clone(),
        health_ref: ledger.lineage_ledger_id.clone(),
        cycle_refs: instance.cycle_refs.clone(),
        continuity_window_refs: instance.continuity_window_refs.clone(),
        regression_packet_refs: vec![packet.regression_packet_id.clone()],
        stability_refs: unique_strings(
            receipts
                .iter()
                .flat_map(|receipt| receipt.lineage_health.trend_refs.iter().cloned())
                .chain(
                    receipts
                        .iter()
                        .map(|receipt| receipt.budget_history.exhaustion_posture_ref.clone()),
                ),
        ),
        closure_posture: factory_program_state_label(instance.program_state).to_string(),
    };
    dossier
        .validate()
        .map_err(|error| invalid_factory_program_operation(&instance.instance_id, error))?;
    Ok(dossier)
}

