fn runbook_action_class(kind: &RunbookEntryKind) -> &'static str {
    match kind {
        RunbookEntryKind::ScenarioLaunched => "start-run",
        RunbookEntryKind::HeadlessRunCompleted => "headless-complete",
        RunbookEntryKind::RunPaused => "pause",
        RunbookEntryKind::RunResumed => "resume",
        RunbookEntryKind::ApprovalGranted => "approval-grant",
        RunbookEntryKind::ApprovalDenied => "approval-deny",
        RunbookEntryKind::ApprovalExpired => "approval-expire",
        RunbookEntryKind::ApprovalEscalated => "approval-escalate",
        RunbookEntryKind::RollbackExecuted => "rollback",
        RunbookEntryKind::BundleExported => "bundle-export",
    }
}

fn build_v2_governance_protocol_record_view(
    run_views: &[RunViewModel],
    runbook: &[OperatorRunbookEntry],
) -> V2GovernanceProtocolRecordView {
    let sorted_runs = sorted_run_views(run_views);
    let fallback_refs = sorted_runs
        .first()
        .map(view_evidence_refs)
        .unwrap_or_default();
    let records = if runbook.is_empty() {
        vec![V2GovernanceProtocolRecordEntry {
            record_id: "governance-record:fallback".to_string(),
            title: "Governance baseline remains bounded".to_string(),
            action_class: "baseline".to_string(),
            generation_scope: "v2 governance baseline".to_string(),
            protocol_meaning: "The runtime already preserves approval, rollback, and intervention as governed actions; v2.4 maps those into explicit protocol records.".to_string(),
            evidence_refs: fallback_refs,
        }]
    } else {
        runbook
            .iter()
            .take(8)
            .map(|entry| V2GovernanceProtocolRecordEntry {
                record_id: format!("governance-record:{}", entry.entry_id),
                title: entry.title.clone(),
                action_class: runbook_action_class(&entry.kind).to_string(),
                generation_scope: entry
                    .run_id
                    .as_ref()
                    .map(|run_id| format!("run `{run_id}`"))
                    .unwrap_or_else(|| "operator surface".to_string()),
                protocol_meaning: format!(
                    "This record preserves `{}` as an explicit governance-bearing action instead of ambient console behavior.",
                    entry.title
                ),
                evidence_refs: unique_strings(
                    entry.related_refs
                        .iter()
                        .cloned()
                        .chain(entry.run_id.iter().cloned()),
                ),
            })
            .collect()
    };

    V2GovernanceProtocolRecordView {
        summary: format!(
            "The v2.4 governance protocol currently exposes {} protocol-bearing action record(s).",
            records.len()
        ),
        records,
        guardrails: vec![
            "Governance actions remain records before they become claims.".to_string(),
            "Protocol meaning stays bounded to approval, release, rollback, and intervention law."
                .to_string(),
        ],
    }
}

fn build_v2_approval_intervention_semantic_view(
    run_views: &[RunViewModel],
    runbook: &[OperatorRunbookEntry],
) -> V2ApprovalInterventionSemanticView {
    let sorted = sorted_run_views(run_views);
    let awaiting_approval = sorted
        .iter()
        .filter(|view| matches!(view.summary.status, LocalRunStatus::AwaitingApproval))
        .count();
    let paused = sorted
        .iter()
        .filter(|view| matches!(view.summary.status, LocalRunStatus::Paused))
        .count();
    let awaiting_rollback = sorted
        .iter()
        .filter(|view| matches!(view.summary.status, LocalRunStatus::AwaitingRollback))
        .count();
    let granted = runbook
        .iter()
        .filter(|entry| matches!(entry.kind, RunbookEntryKind::ApprovalGranted))
        .count();
    let denied = runbook
        .iter()
        .filter(|entry| matches!(entry.kind, RunbookEntryKind::ApprovalDenied))
        .count();
    let semantics = vec![
        V2ApprovalInterventionSemanticEntry {
            semantic_id: "semantic:grant".to_string(),
            action: "grant".to_string(),
            continuity_rule: "Grant continues a blocked generation only when the approval boundary is explicit and durable.".to_string(),
            current_signal: format!("{granted} grant decision(s) are recorded while {awaiting_approval} run(s) remain approval-bound."),
            evidence_refs: unique_strings(
                sorted
                    .iter()
                    .filter(|view| matches!(view.summary.status, LocalRunStatus::AwaitingApproval))
                    .flat_map(|view| view_evidence_refs(view).into_iter()),
            ),
        },
        V2ApprovalInterventionSemanticEntry {
            semantic_id: "semantic:deny".to_string(),
            action: "deny".to_string(),
            continuity_rule: "Deny keeps containment explicit and must remain distinguishable from rollback or quarantine.".to_string(),
            current_signal: format!("{denied} deny decision(s) are currently retained in the operator trace."),
            evidence_refs: unique_strings(
                runbook
                    .iter()
                    .filter(|entry| matches!(entry.kind, RunbookEntryKind::ApprovalDenied))
                    .flat_map(|entry| entry.related_refs.clone()),
            ),
        },
        V2ApprovalInterventionSemanticEntry {
            semantic_id: "semantic:hold".to_string(),
            action: "hold".to_string(),
            continuity_rule: "Hold means the generation remains governed but not advanced; it does not count as success or failure.".to_string(),
            current_signal: format!("{paused} paused run(s) currently prove hold semantics remain explicit."),
            evidence_refs: unique_strings(
                sorted
                    .iter()
                    .filter(|view| matches!(view.summary.status, LocalRunStatus::Paused))
                    .flat_map(|view| view_evidence_refs(view).into_iter()),
            ),
        },
        V2ApprovalInterventionSemanticEntry {
            semantic_id: "semantic:resume".to_string(),
            action: "resume".to_string(),
            continuity_rule: "Resume is a governed continuation of a held run, not a hidden scheduler restart.".to_string(),
            current_signal: format!(
                "{} resume action(s) are stored in the operator history.",
                runbook
                    .iter()
                    .filter(|entry| matches!(entry.kind, RunbookEntryKind::RunResumed))
                    .count()
            ),
            evidence_refs: unique_strings(
                runbook
                    .iter()
                    .filter(|entry| matches!(entry.kind, RunbookEntryKind::RunResumed))
                    .flat_map(|entry| entry.related_refs.clone()),
            ),
        },
        V2ApprovalInterventionSemanticEntry {
            semantic_id: "semantic:intervene".to_string(),
            action: "intervene".to_string(),
            continuity_rule: "Intervention stays bounded to pause, approval, rollback, and containment surfaces across generations.".to_string(),
            current_signal: format!("{awaiting_rollback} rollback-bound run(s) currently keep intervention semantics explicit."),
            evidence_refs: unique_strings(
                sorted
                    .iter()
                    .filter(|view| matches!(view.summary.status, LocalRunStatus::AwaitingRollback))
                    .flat_map(|view| view_evidence_refs(view).into_iter()),
            ),
        },
    ];

    V2ApprovalInterventionSemanticView {
        summary: "The v2.4 semantics layer preserves grant, deny, hold, resume, and intervene as explicit governed moves across contract generations.".to_string(),
        semantics,
        guardrails: vec![
            "Approval meaning stays stricter than interface evolution.".to_string(),
            "Intervention remains visible rather than ambient runtime power.".to_string(),
        ],
    }
}

