fn build_v2_rollback_safety_envelope_view(
    run_views: &[RunViewModel],
) -> V2RollbackSafetyEnvelopeView {
    let sorted = sorted_run_views(run_views);
    let mut envelopes = sorted
        .iter()
        .filter(|view| view.summary.rollback_available || view.summary.quarantine_count > 0)
        .map(|view| V2RollbackSafetyEnvelopeEntry {
            envelope_id: format!("rollback-envelope:{}", view.summary.run_id),
            title: format!("Rollback safety for {}", view.summary.title),
            rollback_anchor: view
                .promotion
                .rollback_handle_id
                .clone()
                .unwrap_or_else(|| "bounded rollback evidence".to_string()),
            safety_requirements: vec![
                "Rollback must remain executable from durable evidence.".to_string(),
                "Quarantine and release state must remain attributable after rollback.".to_string(),
                "Rejected generations must preserve operator-readable traces.".to_string(),
            ],
            evidence_refs: view_evidence_refs(view),
        })
        .collect::<Vec<_>>();
    if envelopes.is_empty() {
        if let Some(view) = sorted.first() {
            envelopes.push(V2RollbackSafetyEnvelopeEntry {
                envelope_id: format!("rollback-envelope:{}", view.summary.run_id),
                title: format!("Rollback safety baseline for {}", view.summary.title),
                rollback_anchor: "no active rollback pressure".to_string(),
                safety_requirements: vec![
                    "Every accepted generation still declares a rollback posture.".to_string(),
                    "Safety law remains explicit before adoption claims continue.".to_string(),
                ],
                evidence_refs: view_evidence_refs(view),
            });
        }
    }

    V2RollbackSafetyEnvelopeView {
        summary: format!(
            "The v2.4 rollback/safety layer currently exposes {} rollback safety envelope(s).",
            envelopes.len()
        ),
        envelopes,
        rejection_paths: vec![
            "Reject by quarantine when governance confidence falls below the release threshold."
                .to_string(),
            "Reject by rollback when the incumbent safety anchor must be restored.".to_string(),
        ],
        guardrails: vec![
            "Rollback law must stay stricter than release enthusiasm.".to_string(),
            "Safety envelopes remain generation-wide rather than subsystem-local.".to_string(),
        ],
    }
}

fn build_v2_operator_protocol_audit_view(
    run_views: &[RunViewModel],
    runbook: &[OperatorRunbookEntry],
    packets: &[OperatorReviewPacket],
) -> V2OperatorProtocolAuditView {
    let sorted = sorted_run_views(run_views);
    let mut actions = runbook
        .iter()
        .take(8)
        .map(|entry| V2OperatorProtocolAuditEntry {
            action_id: format!("operator-audit:{}", entry.entry_id),
            title: entry.title.clone(),
            action_kind: runbook_action_class(&entry.kind).to_string(),
            summary: format!(
                "{} Next checks: {}",
                entry.detail,
                if entry.next_checks.is_empty() {
                    "none".to_string()
                } else {
                    entry.next_checks.join(" | ")
                }
            ),
            audit_refs: unique_strings(
                entry
                    .related_refs
                    .iter()
                    .cloned()
                    .chain(entry.run_id.iter().cloned()),
            ),
        })
        .collect::<Vec<_>>();
    if actions.is_empty() {
        actions.push(V2OperatorProtocolAuditEntry {
            action_id: "operator-audit:fallback".to_string(),
            title: "No explicit operator action recorded yet".to_string(),
            action_kind: "baseline".to_string(),
            summary: "The operator surface remains bounded, but explicit runbook evidence has not been emitted yet.".to_string(),
            audit_refs: sorted.first().map(view_evidence_refs).unwrap_or_default(),
        });
    }

    if let Some(packet) = packets.first() {
        actions.push(V2OperatorProtocolAuditEntry {
            action_id: format!("operator-audit:review-packet:{}", packet.packet_id),
            title: packet.title.clone(),
            action_kind: "review-packet".to_string(),
            summary: format!(
                "Review verdict `{}` remains part of the explicit operator protocol trace.",
                packet.verdict
            ),
            audit_refs: unique_strings(
                std::iter::once(packet.packet_id.clone()).chain(packet.evidence_refs.clone()),
            ),
        });
    }

    V2OperatorProtocolAuditView {
        summary: format!(
            "The v2.4 operator-protocol audit view currently tracks {} explicit operator record(s).",
            actions.len()
        ),
        actions,
        guardrails: vec![
            "Operator actions remain governed records, not out-of-band console power.".to_string(),
            "Audit closure must stay reconstructable from runbook and review evidence.".to_string(),
        ],
    }
}

