fn build_v2_multicampaign_portfolio_topology_view(
    run_views: &[RunViewModel],
) -> V2MultiCampaignPortfolioTopologyView {
    let mut grouped = BTreeMap::<String, Vec<RunViewModel>>::new();
    for view in sorted_run_views(run_views) {
        grouped
            .entry(view.summary.campaign_id.clone())
            .or_default()
            .push(view);
    }

    let campaigns = grouped
        .into_iter()
        .map(|(campaign_id, views)| {
            let leading = views.first().expect("campaign group is never empty");
            let pending_approval_count = views
                .iter()
                .map(|view| view.summary.pending_approval_count)
                .sum();
            let quarantine_count = views.iter().map(|view| view.summary.quarantine_count).sum();
            let rollback_ready_count = views
                .iter()
                .filter(|view| view.summary.rollback_available)
                .count();
            let evidence_refs = unique_strings(
                views
                    .iter()
                    .flat_map(|view| view_evidence_refs(view).into_iter())
                    .chain([campaign_id.clone()]),
            );
            V2OperationalCampaignEntryView {
                title: format!("Campaign {}", campaign_id),
                campaign_id,
                run_count: views.len(),
                leading_status: format!("{:?}", leading.summary.status),
                pending_approval_count,
                quarantine_count,
                rollback_ready_count,
                evidence_refs,
            }
        })
        .collect::<Vec<_>>();

    V2MultiCampaignPortfolioTopologyView {
        summary: format!(
            "The v2.7 portfolio topology currently exposes {} bounded campaign lane(s) across the live v2 generation.",
            campaigns.len()
        ),
        campaigns,
        concurrency_rule:
            "All campaign concurrency remains bounded inside one factory and stays visible through explicit campaign and run records."
                .to_string(),
        guardrails: vec![
            "Multi-campaign does not imply multi-factory.".to_string(),
            "Every concurrent campaign must remain attributable to explicit run and campaign identifiers.".to_string(),
        ],
    }
}

fn build_v2_queue_fairness_scheduler_contention_view(
    run_views: &[RunViewModel],
) -> V2QueueFairnessSchedulerContentionView {
    let statuses = [
        (
            "approval",
            "Awaiting approval",
            LocalRunStatus::AwaitingApproval,
        ),
        (
            "rollback",
            "Awaiting rollback",
            LocalRunStatus::AwaitingRollback,
        ),
        ("paused", "Paused lanes", LocalRunStatus::Paused),
        ("completed", "Completed lanes", LocalRunStatus::Completed),
        ("failed", "Failed lanes", LocalRunStatus::Failed),
        (
            "rolled-back",
            "Rolled-back lanes",
            LocalRunStatus::RolledBack,
        ),
    ];

    let lanes = statuses
        .into_iter()
        .filter_map(|(lane_id, title, status)| {
            let matching = sorted_run_views(run_views)
                .into_iter()
                .filter(|view| view.summary.status == status)
                .collect::<Vec<_>>();
            (!matching.is_empty()).then(|| V2QueueFairnessLaneView {
                lane_id: lane_id.to_string(),
                title: title.to_string(),
                run_count: matching.len(),
                contention_signal: format!(
                    "{} run(s) currently occupy the `{}` scheduler lane.",
                    matching.len(),
                    title
                ),
                fairness_rule:
                    "No lane may hide pressure: queue occupancy and waiting states remain explicit."
                        .to_string(),
                run_refs: matching
                    .iter()
                    .map(|view| view.summary.run_id.clone())
                    .collect(),
            })
        })
        .collect::<Vec<_>>();

    V2QueueFairnessSchedulerContentionView {
        summary: format!(
            "The v2.7 fairness view currently reports {} explicit scheduler lane(s) for bounded operational pressure.",
            lanes.len()
        ),
        scheduler_posture:
            "Scheduler pressure stays visible as lane occupancy rather than implicit backlog."
                .to_string(),
        lanes,
        guardrails: vec![
            "Fairness claims require visible queue occupancy.".to_string(),
            "Operational pressure remains bounded to one factory scheduler story.".to_string(),
        ],
    }
}

fn build_v2_capability_pressure_approval_load_view(
    run_views: &[RunViewModel],
) -> V2CapabilityPressureApprovalLoadView {
    let entries = sorted_run_views(run_views)
        .into_iter()
        .map(|view| V2CapabilityPressureEntryView {
            pressure_id: format!("capability-pressure:{}", view.summary.run_id),
            title: view.summary.title.clone(),
            capability_signal: format!(
                "{} event(s) and {} output ref(s) are flowing through this bounded capability surface.",
                view.summary.event_count,
                view.summary.output_refs.len()
            ),
            approval_load: format!(
                "{} approval request(s), {} still pending.",
                view.summary.approval_request_count, view.summary.pending_approval_count
            ),
            containment_note: if view.summary.quarantine_count > 0 || view.summary.rollback_available {
                "Containment or rollback remains available if pressure becomes unsafe.".to_string()
            } else {
                "No active containment is currently required for this run.".to_string()
            },
            evidence_refs: unique_strings(
                view_evidence_refs(&view)
                    .into_iter()
                    .chain([view.summary.run_id.clone(), view.summary.campaign_id.clone()]),
            ),
        })
        .collect::<Vec<_>>();

    V2CapabilityPressureApprovalLoadView {
        summary: format!(
            "The v2.7 pressure view currently tracks {} run-scoped capability and approval signal(s).",
            entries.len()
        ),
        total_pending_approvals: run_views
            .iter()
            .map(|view| view.summary.pending_approval_count)
            .sum(),
        entries,
        guardrails: vec![
            "Capability strain is never interpreted without approval-load visibility.".to_string(),
            "Containment and rollback signals remain attached to the same run-scoped evidence."
                .to_string(),
        ],
    }
}

