fn build_v2_next_line_handoff_packet(
    run_views: &[RunViewModel],
    records: &[LocalRunRecord],
    runbook: &[OperatorRunbookEntry],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    request: &V2NextLineHandoffPacketExportRequest,
    exported: bool,
) -> V2NextLineHandoffPacket {
    let sorted = sorted_run_views(run_views);
    let selected_runs = if request.run_ids.is_empty() {
        sorted
            .iter()
            .filter(|view| {
                matches!(
                    view.summary.scenario_id.as_str(),
                    "supervisor-promote-activate-successor-campaign"
                        | "supervisor-second-cycle-v1-completion"
                        | "supervisor-durable-fixed-interface-continuous-self-hosting-program"
                )
            })
            .cloned()
            .collect::<Vec<_>>()
    } else {
        sorted
            .iter()
            .filter(|view| request.run_ids.contains(&view.summary.run_id))
            .cloned()
            .collect::<Vec<_>>()
    };
    let scorecards =
        build_v2_final_generation_scorecards_view(run_views, records, runbook, review_packets);
    let unresolved = build_v2_unresolved_pressure_summary_view(
        run_views,
        records,
        runbook,
        review_packets,
        transition_packets,
    );
    let phase =
        build_v2_self_hosting_phase_declaration_view(run_views, records, runbook, review_packets);
    let title = request
        .title
        .clone()
        .unwrap_or_else(|| "v2 next-line handoff packet".to_string());
    let timestamp = current_timestamp();
    let summary = request.summary.clone().unwrap_or_else(|| {
        format!(
            "v2 next-line handoff packet exported from {} selected run(s), {} final scorecard(s), and {} unresolved pressure family(ies).",
            selected_runs.len(),
            scorecards.scorecards.len(),
            unresolved.pressures.len()
        )
    });
    let next_line_focus = if request.next_line_focus.is_empty() {
        default_v2_next_line_focus()
    } else {
        request.next_line_focus.clone()
    };
    V2NextLineHandoffPacket {
        packet_id: format!("v2-next-line-handoff:{}:{}", sanitize_id(&title), timestamp),
        title,
        summary,
        created_at: timestamp,
        source_transition_packet_id: transition_packets
            .first()
            .map(|packet| packet.packet_id.clone()),
        strongest_run_ids: selected_runs
            .iter()
            .map(|view| view.summary.run_id.clone())
            .collect(),
        unresolved_pressure_ids: unresolved
            .pressures
            .iter()
            .map(|pressure| pressure.pressure_id.clone())
            .collect(),
        scorecard_ids: scorecards
            .scorecards
            .iter()
            .map(|scorecard| scorecard.scorecard_id.clone())
            .collect(),
        achieved_structure: unique_strings(
            scorecards
                .scorecards
                .iter()
                .flat_map(|scorecard| scorecard.achieved_structure.clone())
                .chain(phase.achieved_capabilities.clone()),
        ),
        next_line_focus,
        evidence_refs: unique_strings(
            selected_runs
                .iter()
                .flat_map(|view| view_evidence_refs(view).into_iter())
                .chain(scorecards.release_evidence.clone())
                .chain(scorecards.adoption_evidence.clone())
                .chain(phase.evidence_refs.clone())
                .chain(
                    unresolved
                        .pressures
                        .iter()
                        .flat_map(|pressure| pressure.evidence_refs.clone()),
                )
                .chain(
                    transition_packets
                        .first()
                        .into_iter()
                        .map(|packet| packet.packet_id.clone()),
                ),
        ),
        exported,
    }
}

fn build_v2_convergence_transition_workspace_view(
    run_views: &[RunViewModel],
    records: &[LocalRunRecord],
    runbook: &[OperatorRunbookEntry],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    handoff_packets: &[V2NextLineHandoffPacket],
) -> V2ConvergenceTransitionWorkspaceView {
    let scorecards =
        build_v2_final_generation_scorecards_view(run_views, records, runbook, review_packets);
    let unresolved = build_v2_unresolved_pressure_summary_view(
        run_views,
        records,
        runbook,
        review_packets,
        transition_packets,
    );
    let phase =
        build_v2_self_hosting_phase_declaration_view(run_views, records, runbook, review_packets);
    let latest_handoff_packet = handoff_packets.first().cloned();
    let transition_anchor = latest_handoff_packet
        .as_ref()
        .and_then(|packet| packet.source_transition_packet_id.clone())
        .or_else(|| {
            transition_packets
                .first()
                .map(|packet| packet.packet_id.clone())
        });

    let workspace_checks = vec![
        format!(
            "{} final generation scorecard(s) remain visible in the closing workspace.",
            scorecards.scorecards.len()
        ),
        format!(
            "{} unresolved pressure family(ies) remain explicit for the next line.",
            unresolved.pressures.len()
        ),
        if latest_handoff_packet.is_some() {
            "A next-line handoff packet has been exported from the current workspace.".to_string()
        } else {
            "No next-line handoff packet has been exported yet.".to_string()
        },
        if transition_anchor.is_some() {
            "The v1.9 to v2 transition anchor remains attached to the convergence workspace."
                .to_string()
        } else {
            "The convergence workspace currently lacks an explicit transition anchor packet."
                .to_string()
        },
    ];

    V2ConvergenceTransitionWorkspaceView {
        summary: "The v2.9 convergence workspace keeps achieved structure, unresolved pressure, self-hosting phase language, and next-line handoff material in one operator-readable surface.".to_string(),
        scorecard_summary: scorecards.summary,
        pressure_summary: unresolved.summary,
        phase_summary: phase.summary,
        latest_handoff_packet,
        transition_anchor,
        workspace_checks,
        guardrails: vec![
            "The workspace must distinguish completed first-phase structure from deferred next-line pressure.".to_string(),
            "Exportable handoff packets remain compact operational packets rather than a second truth model.".to_string(),
            "The convergence workspace closes the first v2 phase; it does not silently open the next one.".to_string(),
        ],
    }
}

fn build_v2_final_convergence_next_line_readiness_view(
    run_views: &[RunViewModel],
    records: &[LocalRunRecord],
    runbook: &[OperatorRunbookEntry],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    handoff_packets: &[V2NextLineHandoffPacket],
) -> V2FinalConvergenceNextLineReadinessView {
    let workspace = build_v2_convergence_transition_workspace_view(
        run_views,
        records,
        runbook,
        review_packets,
        transition_packets,
        handoff_packets,
    );
    let scorecards =
        build_v2_final_generation_scorecards_view(run_views, records, runbook, review_packets);
    let unresolved = build_v2_unresolved_pressure_summary_view(
        run_views,
        records,
        runbook,
        review_packets,
        transition_packets,
    );
    let phase =
        build_v2_self_hosting_phase_declaration_view(run_views, records, runbook, review_packets);
    let handoff_summary = workspace
        .latest_handoff_packet
        .as_ref()
        .map(|packet| {
            format!(
                "Latest handoff packet `{}` keeps {} next-line focus item(s) explicit.",
                packet.packet_id,
                packet.next_line_focus.len()
            )
        })
        .unwrap_or_else(|| {
            "No next-line handoff packet has been exported yet; convergence remains inspectable but not fully packaged.".to_string()
        });

    V2FinalConvergenceNextLineReadinessView {
        summary: "The v2.9 closure gate says the first v2 phase is complete when final scorecards, unresolved pressure, bounded self-hosting phase language, and one exportable next-line handoff packet all agree.".to_string(),
        scorecard_summary: scorecards.summary,
        pressure_summary: unresolved.summary,
        phase_summary: phase.summary,
        handoff_summary,
        next_line: if workspace.latest_handoff_packet.is_some() {
            "v3 architecture foundation and next-generation boundary design".to_string()
        } else {
            "Export the next-line handoff packet before opening v3 architecture work".to_string()
        },
        guardrails: vec![
            "Do not reopen diffuse v2.x scope once the first v2 phase is closed.".to_string(),
            "Treat the exported handoff packet as the input dossier for the next design line.".to_string(),
            "Keep unresolved ecosystem, hosting, and broader topology pressure visible instead of flattening it into scorecard optimism.".to_string(),
        ],
    }
}

fn build_operator_runbook_view(
    run_views: &[RunViewModel],
    runbook: &[OperatorRunbookEntry],
) -> OperatorRunbookView {
    let sorted = sorted_run_views(run_views);
    let unresolved_attention = build_attention_queue_from_views(&sorted);
    let last_action = runbook.first().map(|entry| entry.title.clone());
    let steering_context = match (runbook.first(), sorted.first()) {
        (Some(entry), Some(run)) => format!(
            "Latest operator action was `{}` for `{}`. Current leading run is `{}` with status `{:?}`.",
            entry.title,
            entry.run_id.clone().unwrap_or_default(),
            run.summary.title,
            run.summary.status
        ),
        (Some(entry), None) => format!(
            "Latest operator action was `{}` with no active local run selected.",
            entry.title
        ),
        (None, Some(run)) => format!(
            "No operator runbook entries are stored yet. Current leading run is `{}`.",
            run.summary.title
        ),
        (None, None) => "No local operator history is stored yet.".to_string(),
    };

    OperatorRunbookView {
        entries: runbook.to_vec(),
        unresolved_attention,
        steering_context,
        last_action,
    }
}

fn build_planning_guidance_view(
    run_views: &[RunViewModel],
    runbook: &[OperatorRunbookEntry],
) -> PlanningGuidanceView {
    let sorted = sorted_run_views(run_views);
    let mut recommendations = Vec::new();

    if let Some(run) = sorted
        .iter()
        .find(|view| matches!(view.summary.status, LocalRunStatus::AwaitingApproval))
    {
        recommendations.push(PlanningRecommendation {
            recommendation_id: format!("planning:approval:{}", run.summary.run_id),
            title: "Resolve pending approval".to_string(),
            detail: format!(
                "The next bounded action should be to review and resolve the pending approval for `{}`.",
                run.summary.title
            ),
            run_id: Some(run.summary.run_id.clone()),
            suggested_scenario_id: None,
            supporting_refs: view_evidence_refs(run),
        });
    }

    if let Some(run) = sorted
        .iter()
        .find(|view| matches!(view.summary.status, LocalRunStatus::AwaitingRollback))
    {
        recommendations.push(PlanningRecommendation {
            recommendation_id: format!("planning:rollback:{}", run.summary.run_id),
            title: "Review rollback path".to_string(),
            detail: format!(
                "Rollback pressure is currently open for `{}` and should be reviewed before new campaigns are launched.",
                run.summary.title
            ),
            run_id: Some(run.summary.run_id.clone()),
            suggested_scenario_id: None,
            supporting_refs: view_evidence_refs(run),
        });
    }

    if let Some(run) = sorted.iter().find(|view| {
        matches!(view.summary.status, LocalRunStatus::Completed)
            && !view.promotion.self_hosting_refs.is_empty()
    }) {
        recommendations.push(PlanningRecommendation {
            recommendation_id: format!("planning:review-self-hosting:{}", run.summary.run_id),
            title: "Review durable self-hosting evidence".to_string(),
            detail: format!(
                "A completed self-hosting path exists for `{}` and should be reviewed in the comparison and evidence workspaces.",
                run.summary.title
            ),
            run_id: Some(run.summary.run_id.clone()),
            suggested_scenario_id: Some(
                "supervisor-durable-fixed-interface-continuous-self-hosting-program".to_string(),
            ),
            supporting_refs: view_evidence_refs(run),
        });
    }

    if sorted.is_empty() {
        recommendations.push(PlanningRecommendation {
            recommendation_id: "planning:start-first-run".to_string(),
            title: "Launch a curated scenario".to_string(),
            detail:
                "The cockpit has no local history yet. Start a curated scenario to seed run history, evidence, and portfolio context."
                    .to_string(),
            run_id: None,
            suggested_scenario_id: Some("supervisor-approval-resume-worker-complete".to_string()),
            supporting_refs: Vec::new(),
        });
    } else if recommendations.is_empty() {
        recommendations.push(PlanningRecommendation {
            recommendation_id: "planning:review-history".to_string(),
            title: "Review history before launching the next campaign".to_string(),
            detail:
                "No urgent approval or rollback pressure is open. Compare recent runs, inspect evidence, and then choose the next bounded campaign."
                    .to_string(),
            run_id: sorted.first().map(|view| view.summary.run_id.clone()),
            suggested_scenario_id: Some("supervisor-promote-activate-successor-campaign".to_string()),
            supporting_refs: sorted
                .first()
                .map(view_evidence_refs)
                .unwrap_or_default(),
        });
    }

    let planning_summary = if let Some(entry) = runbook.first() {
        format!(
            "Planning guidance is anchored to the latest operator context: `{}`.",
            entry.title
        )
    } else {
        "Planning guidance is anchored to the current local run history and unresolved attention."
            .to_string()
    };

    PlanningGuidanceView {
        planning_summary,
        recommendations,
        guardrails: vec![
            "Planning guidance remains bounded and explainable from local evidence.".to_string(),
            "The operator remains the decision authority for launches, approvals, and rollback."
                .to_string(),
            "No guidance item mutates execution state on its own.".to_string(),
        ],
    }
}

fn annotate_operator_runbook_with_factory_01(
    view: &mut OperatorRunbookView,
    factory_01_programs: &[FactoryProgramView],
) {
    let detail = if let Some(program) = factory_01_programs.first() {
        format!(
            " Factory_01 is active through `{}` with state `{}`, generation depth {}, and {} recorded campaign(s).",
            program.instance.instance_id,
            factory_program_state_label(program.instance.program_state),
            program.instance.generation_depth,
            program.instance.campaign_count
        )
    } else {
        format!(
            " Factory_01 is preseeded locally as spec `{}` with driver profile `{}` and can be instantiated through `/api/programs`.",
            FACTORY_01_SPEC_ID, FACTORY_01_PROFILE_ID
        )
    };
    view.steering_context.push_str(&detail);
}

fn annotate_planning_guidance_with_factory_01(
    view: &mut PlanningGuidanceView,
    factory_01_programs: &[FactoryProgramView],
) {
    if !view.planning_summary.is_empty() {
        view.planning_summary.push(' ');
    }
    if let Some(program) = factory_01_programs.first() {
        view.planning_summary.push_str(&format!(
            "Factory_01 currently tracks `{}` at depth {} after {} campaign(s).",
            program.instance.instance_id,
            program.instance.generation_depth,
            program.instance.campaign_count
        ));
    } else {
        view.planning_summary.push_str(&format!(
            "Factory_01 is available through seeded spec `{}` and seeded profile `{}`.",
            FACTORY_01_SPEC_ID, FACTORY_01_PROFILE_ID
        ));
    }

    view.recommendations
        .retain(|item| !item.recommendation_id.starts_with("planning:factory-01"));

    let replace_empty_cockpit_prompt = view
        .recommendations
        .iter()
        .position(|item| item.recommendation_id == "planning:start-first-run");

    let recommendation = if let Some(program) = factory_01_programs.first() {
        let latest_outcome = program
            .model_factory_cycles
            .last()
            .map(|cycle| cycle.cycle.outcome);
        let (title, detail) = match latest_outcome {
            Some(crate::execution::RecursiveCycleOutcome::ApprovalBlocked) => (
                "Resolve Factory_01 approval boundary",
                "Factory_01 has a promotion decision waiting for explicit operator grant or deny before the bounded cycle may continue.",
            ),
            Some(crate::execution::RecursiveCycleOutcome::Quarantined) => (
                "Review Factory_01 quarantine evidence",
                "Factory_01 is on hold behind a quarantine recommendation and should be reviewed through the Review, Evidence, and recursive health surfaces before resuming.",
            ),
            Some(crate::execution::RecursiveCycleOutcome::Denied)
            | Some(crate::execution::RecursiveCycleOutcome::Failed) => (
                "Inspect Factory_01 incident evidence",
                "Factory_01 recorded a denied or failed model-driven cycle; inspect the parsed turn, tool execution, lineage, and health ledgers before launching another cycle.",
            ),
            Some(_) => (
                "Review Factory_01 cycle evidence",
                "Factory_01 has governed cycle evidence ready for inspection in the Factory, Review, History, and recursive lineage surfaces.",
            ),
            None => (
                "Drive Factory_01 through the seeded profile",
                "Factory_01 is instantiated but has no recorded model-driven cycle yet. Register a provider, drive the first bounded cycle, and watch the recursive ledgers populate.",
            ),
        };
        PlanningRecommendation {
            recommendation_id: format!(
                "planning:factory-01:{}",
                sanitize_id(&program.instance.instance_id)
            ),
            title: title.to_string(),
            detail: detail.to_string(),
            run_id: None,
            suggested_scenario_id: None,
            supporting_refs: factory_01_supporting_refs(Some(program)),
        }
    } else {
        if replace_empty_cockpit_prompt.is_none() {
            return;
        }
        PlanningRecommendation {
            recommendation_id: "planning:factory-01:create".to_string(),
            title: "Instantiate Factory_01".to_string(),
            detail: format!(
                "No Factory_01 instance exists yet. Create one from seeded spec `{}` and seeded profile `{}`, then register an OpenAI provider and drive the first governed cycle.",
                FACTORY_01_SPEC_ID, FACTORY_01_PROFILE_ID
            ),
            run_id: None,
            suggested_scenario_id: None,
            supporting_refs: factory_01_supporting_refs(None),
        }
    };

    if let Some(index) = replace_empty_cockpit_prompt {
        view.recommendations.remove(index);
    }
    view.recommendations.insert(0, recommendation);
}

fn factory_01_supporting_refs(program: Option<&FactoryProgramView>) -> Vec<String> {
    let mut refs = vec![
        FACTORY_01_SPEC_ID.to_string(),
        FACTORY_01_PROFILE_ID.to_string(),
        FACTORY_01_PROVIDER_EXAMPLE_ID.to_string(),
        FACTORY_01_GENERATION_POLICY_ID.to_string(),
    ];
    if let Some(program) = program {
        refs.push(program.instance.instance_id.clone());
        if let Some(latest_tick_id) = &program.instance.latest_tick_id {
            refs.push(latest_tick_id.clone());
        }
        if let Some(lineage) = &program.recursive_lineage_execution {
            refs.push(lineage.lineage.recursive_lineage_execution_id.clone());
        }
        if let Some(statement) = &program.architectural_dependency_statement {
            refs.push(
                statement
                    .statement
                    .architectural_dependency_statement_id
                    .clone(),
            );
        }
        if let Some(dossier) = &program.recursion_closure_dossier {
            refs.push(dossier.dossier.recursion_closure_dossier_id.clone());
        }
        for cycle in &program.model_factory_cycles {
            refs.push(cycle.cycle.model_factory_cycle_id.clone());
        }
    }
    unique_strings(refs)
}

fn build_attention_queue_from_views(run_views: &[RunViewModel]) -> Vec<AttentionItem> {
    let mut items = Vec::new();
    for view in run_views {
        items.extend(build_attention_queue_for_view(view));
    }
    sort_attention_items(&mut items);
    if items.is_empty() {
        items.push(AttentionItem {
            attention_id: "attention:none".to_string(),
            severity: AttentionSeverity::Info,
            title: "No immediate operator attention required".to_string(),
            detail: "The local system has no pending approvals, open quarantines, or blocked runs right now.".to_string(),
            run_id: None,
            related_refs: Vec::new(),
            recommended_action: "Review recent runs or start a new scenario when ready.".to_string(),
        });
    }
    items
}

fn build_factory_view(
    record: &LocalRunRecord,
    view: &RunViewModel,
    active_campaign_count: usize,
) -> FactoryView {
    let has_challenger = !view.promotion.promotion_refs.is_empty()
        || !view.promotion.self_hosting_refs.is_empty()
        || !view.promotion.completion_refs.is_empty();
    let challenger_ref = has_challenger.then(|| format!("challenger:{}", view.summary.run_id));
    let comparison_state = if has_challenger {
        "Bounded challenger, successor, or promotion evidence is present in the current run."
            .to_string()
    } else {
        "This run is operating the incumbent path without challenger comparison evidence."
            .to_string()
    };
    let promotion_state = if !view.promotion.promotion_refs.is_empty() {
        format!(
            "Promotion or adoption evidence is present across {} related reference(s).",
            view.promotion.promotion_refs.len()
        )
    } else if !view.promotion.completion_refs.is_empty() {
        "Completion evidence is present, but explicit promotion references are not surfaced in this run.".to_string()
    } else {
        "No promotion or adoption evidence is surfaced in this run.".to_string()
    };
    let canary_release_state =
        if view.summary.quarantine_count > 0 || view.summary.rollback_available {
            "Release remains bounded by quarantine or rollback readiness in the current run."
                .to_string()
        } else if !view.promotion.promotion_refs.is_empty() {
            "Bounded release-path evidence is present in the current artifact set.".to_string()
        } else {
            "No explicit canary or release evidence is surfaced in this run.".to_string()
        };
    let quarantine_state = if view.summary.quarantine_count > 0 {
        format!(
            "{} quarantine record(s) currently constrain this factory path.",
            view.summary.quarantine_count
        )
    } else {
        "No open quarantine records are attached to this factory path.".to_string()
    };
    let rollback_state = if matches!(view.summary.status, LocalRunStatus::RolledBack) {
        "Rollback has already been executed and the run now reflects the restored state."
            .to_string()
    } else if view.summary.rollback_available {
        "A governed rollback handle is attached to this run and remains operator-visible."
            .to_string()
    } else {
        "No rollback handle is currently attached to this run.".to_string()
    };
    let campaign_budget_state = if active_campaign_count > 1 {
        format!(
            "{active_campaign_count} active local campaign(s) currently share the bounded operator surface."
        )
    } else if is_active_status(&view.summary.status) {
        "A single bounded local campaign currently occupies the operator surface.".to_string()
    } else {
        "This run is no longer exerting active campaign pressure on the local operator surface."
            .to_string()
    };

    FactoryView {
        run_id: view.summary.run_id.clone(),
        title: view.definition.title.clone(),
        incumbent_ref: format!(
            "incumbent:{}:{}",
            view.summary.campaign_id, view.summary.epoch_id
        ),
        challenger_ref,
        comparison_state,
        campaign_id: view.summary.campaign_id.clone(),
        epoch_id: view.summary.epoch_id.clone(),
        campaign_state: describe_factory_program_state(&view.summary),
        campaign_budget_state,
        pending_approval_count: view.summary.pending_approval_count,
        quarantine_count: view.summary.quarantine_count,
        rollback_available: view.summary.rollback_available,
        promotion_state,
        canary_release_state,
        quarantine_state,
        rollback_state,
        evidence: view.promotion.clone(),
        attention_queue: build_attention_queue_for_run(record, view),
    }
}

fn build_agent_view(record: &LocalRunRecord, view: &RunViewModel) -> AgentView {
    let supervisor = AgentCardView {
        agent_id: record.runtime_state.session.header.actor_id.clone(),
        role_kind: "Supervisor".to_string(),
        display_name: "Local Supervisor".to_string(),
        current_state: format!("{:?}", record.runtime_state.session.state),
        session_id: Some(record.runtime_state.session.header.session_id.clone()),
        task_ref: Some(record.runtime_state.root_task.task_id.clone()),
        capability_envelope_ref: Some(
            record
                .runtime_state
                .session
                .header
                .capability_envelope_ref
                .clone(),
        ),
        capability_summary: supervisor_capabilities(view),
        approval_state: if view.summary.pending_approval_count > 0 {
            format!(
                "Awaiting {} approval decision(s) before the supervised path can progress.",
                view.summary.pending_approval_count
            )
        } else {
            "No pending approval currently blocks the supervisor.".to_string()
        },
        blocked_reason: record
            .runtime_state
            .session
            .blocked_reason
            .as_ref()
            .map(|reason| reason.detail.clone()),
        ownership_scope: Some(record.runtime_state.session.header.campaign_id.clone()),
        evidence_refs: supervisor_evidence_refs(record),
    };

    let workers = build_worker_cards(record, view);
    let blocked_agent_count = usize::from(supervisor.blocked_reason.is_some())
        + workers
            .iter()
            .filter(|card| {
                card.current_state.contains("Pending")
                    || card.current_state.contains("Ready")
                    || card.current_state.contains("Awaiting")
            })
            .count();
    let failed_agent_count = usize::from(matches!(
        view.summary.status,
        LocalRunStatus::Failed | LocalRunStatus::RolledBack
    )) + workers
        .iter()
        .filter(|card| card.current_state.contains("Failed"))
        .count();

    AgentView {
        run_id: view.summary.run_id.clone(),
        title: view.definition.title.clone(),
        supervisor,
        workers,
        pending_approval_count: view.summary.pending_approval_count,
        blocked_agent_count,
        failed_agent_count,
        attention_queue: build_attention_queue_for_run(record, view),
    }
}

fn build_worker_cards(record: &LocalRunRecord, view: &RunViewModel) -> Vec<AgentCardView> {
    let agenda_items = &record.runtime_state.task_graph.agenda_items;
    if agenda_items.is_empty() {
        return vec![AgentCardView {
            agent_id: format!("worker-slot:{}", view.summary.run_id),
            role_kind: "Worker".to_string(),
            display_name: "Worker role not yet persisted for this run".to_string(),
            current_state: "NoWorkerStatePersisted".to_string(),
            session_id: Some(record.runtime_state.session.header.session_id.clone()),
            task_ref: Some(record.runtime_state.root_task.task_id.clone()),
            capability_envelope_ref: Some(
                record
                    .runtime_state
                    .session
                    .header
                    .capability_envelope_ref
                    .clone(),
            ),
            capability_summary: vec![
                "No explicit worker agenda item is persisted for this run.".to_string(),
                "This placeholder keeps the Agent view honest instead of inventing hidden worker state.".to_string(),
            ],
            approval_state: "No worker-specific approval state is persisted.".to_string(),
            blocked_reason: None,
            ownership_scope: Some(record.runtime_state.session.header.campaign_id.clone()),
            evidence_refs: supervisor_evidence_refs(record),
        }];
    }

    agenda_items
        .iter()
        .map(|agenda_item| {
            let worker_id = agenda_item
                .assigned_worker_id
                .clone()
                .unwrap_or_else(|| format!("worker-slot:{}", agenda_item.agenda_item_id));
            let approval_state = if view.summary.pending_approval_count > 0 {
                format!(
                    "Dispatch remains gated by {} pending approval decision(s).",
                    view.summary.pending_approval_count
                )
            } else {
                "No pending approval currently blocks this worker path.".to_string()
            };
            let mut evidence_refs = vec![
                agenda_item.agenda_item_id.clone(),
                agenda_item.task_id.clone(),
            ];
            evidence_refs.extend(agenda_item.output_refs.clone());

            AgentCardView {
                agent_id: worker_id.clone(),
                role_kind: "Worker".to_string(),
                display_name: format!("Worker path: {}", agenda_item.task_kind),
                current_state: format!("{:?}", agenda_item.status),
                session_id: Some(record.runtime_state.session.header.session_id.clone()),
                task_ref: Some(agenda_item.task_id.clone()),
                capability_envelope_ref: Some(
                    record
                        .runtime_state
                        .session
                        .header
                        .capability_envelope_ref
                        .clone(),
                ),
                capability_summary: vec![
                    format!("task kind: {}", agenda_item.task_kind),
                    format!(
                        "ownership: {:?} over {}",
                        agenda_item.ownership_boundary.mode,
                        agenda_item.ownership_boundary.resource_scope
                    ),
                    if agenda_item.assigned_worker_id.is_some() {
                        format!("live worker assignment: {worker_id}")
                    } else {
                        "no persisted live worker assignment".to_string()
                    },
                ],
                approval_state,
                blocked_reason: worker_blocked_reason(agenda_item),
                ownership_scope: Some(agenda_item.ownership_boundary.resource_scope.clone()),
                evidence_refs,
            }
        })
        .collect()
}

fn supervisor_capabilities(view: &RunViewModel) -> Vec<String> {
    let mut summary = vec![
        "governed session control".to_string(),
        "checkpoint and replay visibility".to_string(),
        "promotion, quarantine, and rollback awareness".to_string(),
    ];
    if let Some(approval) = view
        .approvals
        .iter()
        .find(|approval| approval.decision.is_none())
    {
        summary.push(format!(
            "approval-bound authority: {:?}",
            approval.requested_authority_class
        ));
    }
    if !view.promotion.self_hosting_refs.is_empty() {
        summary.push("bounded self-hosting evidence is attached to this run".to_string());
    }
    summary
}

fn supervisor_evidence_refs(record: &LocalRunRecord) -> Vec<String> {
    let mut refs = vec![record.runtime_state.root_task.task_id.clone()];
    if let Some(checkpoint) = &record.runtime_state.latest_checkpoint {
        refs.push(checkpoint.checkpoint_id.clone());
    }
    refs.extend(record.runtime_state.session.pending_approval_refs.clone());
    refs.extend(
        record
            .metadata
            .quarantines
            .iter()
            .map(|quarantine| quarantine.quarantine_id.clone()),
    );
    if let Some(handle) = &record.metadata.rollback_handle {
        refs.push(handle.rollback_handle_id.clone());
    }
    refs
}

fn worker_blocked_reason(agenda_item: &AgendaItem) -> Option<String> {
    match agenda_item.status {
        AgendaStatus::PendingDependencies => {
            Some("waiting for dependency completion before the worker path can start".to_string())
        }
        AgendaStatus::Ready => Some("ready for governed dispatch".to_string()),
        AgendaStatus::AwaitingSynthesis => {
            Some("awaiting supervisor synthesis before the worker path can continue".to_string())
        }
        AgendaStatus::Failed => {
            Some("worker path failed and requires containment or review".to_string())
        }
        _ => None,
    }
}

fn build_attention_queue_for_run(
    record: &LocalRunRecord,
    view: &RunViewModel,
) -> Vec<AttentionItem> {
    let mut items = build_attention_queue_for_view(view);

    for agenda_item in &record.runtime_state.task_graph.agenda_items {
        if agenda_item.status == AgendaStatus::Failed {
            items.push(AttentionItem {
                attention_id: format!("worker-failure:{}:{}", view.summary.run_id, agenda_item.agenda_item_id),
                severity: AttentionSeverity::Warning,
                title: "Worker path failed".to_string(),
                detail: format!(
                    "Worker path `{}` failed inside the bounded orchestration graph.",
                    agenda_item.task_kind
                ),
                run_id: Some(view.summary.run_id.clone()),
                related_refs: vec![
                    agenda_item.agenda_item_id.clone(),
                    agenda_item.task_id.clone(),
                ],
                recommended_action: "Review the worker path, inspect evidence, and decide whether to retry, contain, or roll back.".to_string(),
            });
        }
    }

    sort_attention_items(&mut items);
    if items.is_empty() {
        items.push(AttentionItem {
            attention_id: format!("attention-clear:{}", view.summary.run_id),
            severity: AttentionSeverity::Info,
            title: "No immediate run-specific operator action required".to_string(),
            detail: "This run does not currently expose pending approvals, rollback pressure, or failed worker paths.".to_string(),
            run_id: Some(view.summary.run_id.clone()),
            related_refs: Vec::new(),
            recommended_action: "Review the factory and agent state or export the run bundle.".to_string(),
        });
    }
    items
}

fn build_attention_queue_for_view(view: &RunViewModel) -> Vec<AttentionItem> {
    let mut items = Vec::new();
    let pending_approval_refs = view
        .approvals
        .iter()
        .filter(|approval| approval.decision.is_none())
        .map(|approval| approval.approval_request_id.clone())
        .collect::<Vec<_>>();
    if !pending_approval_refs.is_empty() {
        items.push(AttentionItem {
            attention_id: format!("approval-required:{}", view.summary.run_id),
            severity: AttentionSeverity::Critical,
            title: "Approval required".to_string(),
            detail: format!(
                "Run `{}` is awaiting {} approval decision(s) before it can proceed.",
                view.summary.title,
                pending_approval_refs.len()
            ),
            run_id: Some(view.summary.run_id.clone()),
            related_refs: pending_approval_refs,
            recommended_action: "Review the approval request and grant or deny it through the governed operator surface.".to_string(),
        });
    }

    if !view.quarantines.is_empty() {
        let mut related_refs = view
            .quarantines
            .iter()
            .map(|quarantine| quarantine.quarantine_id.clone())
            .collect::<Vec<_>>();
        if let Some(handle) = &view.rollback_handle {
            related_refs.push(handle.rollback_handle_id.clone());
        }
        items.push(AttentionItem {
            attention_id: format!("quarantine-open:{}", view.summary.run_id),
            severity: AttentionSeverity::Critical,
            title: "Quarantine constrains this run".to_string(),
            detail: format!(
                "{} quarantine record(s) are attached to the current factory path.",
                view.quarantines.len()
            ),
            run_id: Some(view.summary.run_id.clone()),
            related_refs,
            recommended_action: if view.summary.rollback_available {
                "Review the quarantine and execute rollback if the bounded path must be restored."
                    .to_string()
            } else {
                "Review and resolve the quarantine before treating this path as healthy."
                    .to_string()
            },
        });
    }

    if view.summary.rollback_available
        && matches!(view.summary.status, LocalRunStatus::AwaitingRollback)
    {
        items.push(AttentionItem {
            attention_id: format!("rollback-ready:{}", view.summary.run_id),
            severity: AttentionSeverity::Critical,
            title: "Rollback available".to_string(),
            detail: "A governed rollback handle is available and the run is waiting for operator action.".to_string(),
            run_id: Some(view.summary.run_id.clone()),
            related_refs: view
                .rollback_handle
                .as_ref()
                .map(|handle| vec![handle.rollback_handle_id.clone()])
                .unwrap_or_default(),
            recommended_action: "Inspect the factory state and execute rollback if restoration is required.".to_string(),
        });
    }

    if matches!(view.summary.status, LocalRunStatus::Paused) {
        items.push(AttentionItem {
            attention_id: format!("paused-run:{}", view.summary.run_id),
            severity: AttentionSeverity::Warning,
            title: "Run paused under operator control".to_string(),
            detail: "The run is paused and requires an explicit operator resume decision."
                .to_string(),
            run_id: Some(view.summary.run_id.clone()),
            related_refs: view
                .summary
                .latest_checkpoint_id
                .clone()
                .into_iter()
                .collect(),
            recommended_action:
                "Resume the run when the operator is satisfied with the current state.".to_string(),
        });
    }

    if matches!(view.summary.status, LocalRunStatus::Failed) {
        items.push(AttentionItem {
            attention_id: format!("failed-run:{}", view.summary.run_id),
            severity: AttentionSeverity::Warning,
            title: "Run failed closed".to_string(),
            detail: "The run has failed closed and should be reviewed before being treated as complete.".to_string(),
            run_id: Some(view.summary.run_id.clone()),
            related_refs: view.summary.latest_checkpoint_id.clone().into_iter().collect(),
            recommended_action: "Inspect the failure evidence and determine whether a retry, review, or rollback path is needed.".to_string(),
        });
    }

    items
}

fn sort_attention_items(items: &mut [AttentionItem]) {
    items.sort_by(|left, right| {
        attention_rank(&left.severity)
            .cmp(&attention_rank(&right.severity))
            .then_with(|| left.attention_id.cmp(&right.attention_id))
    });
}

fn attention_rank(severity: &AttentionSeverity) -> usize {
    match severity {
        AttentionSeverity::Critical => 0,
        AttentionSeverity::Warning => 1,
        AttentionSeverity::Info => 2,
    }
}

fn describe_factory_program_state(summary: &RunSummary) -> String {
    match summary.status {
        LocalRunStatus::AwaitingApproval => {
            "Factory program is blocked on governed approval.".to_string()
        }
        LocalRunStatus::AwaitingRollback => {
            "Factory program is constrained by quarantine and waiting on rollback review."
                .to_string()
        }
        LocalRunStatus::Paused => "Factory program is paused under operator control.".to_string(),
        LocalRunStatus::Completed => {
            "Factory program has completed its current bounded run.".to_string()
        }
        LocalRunStatus::Failed => "Factory program failed closed and needs review.".to_string(),
        LocalRunStatus::RolledBack => {
            "Factory program has been rolled back to a previously safe checkpoint.".to_string()
        }
    }
}

fn collect_approvals(memory_store: &MemoryStore) -> Vec<ApprovalView> {
    let mut requests = BTreeMap::<String, ApprovalRequest>::new();
    let mut decisions = BTreeMap::<String, ApprovalDecision>::new();
    for artifact in &memory_store.artifacts {
        match &artifact.payload {
            MemoryArtifactPayload::ApprovalRequest(request) => {
                requests.insert(request.approval_request_id.clone(), request.clone());
            }
            MemoryArtifactPayload::ApprovalDecision(decision) => {
                decisions.insert(decision.approval_request_id.clone(), decision.clone());
            }
            _ => {}
        }
    }

    let mut views = Vec::with_capacity(requests.len());
    for request in requests.into_values() {
        let decision = decisions.get(&request.approval_request_id);
        views.push(ApprovalView {
            approval_request_id: request.approval_request_id.clone(),
            action_ref: request.action_ref.clone(),
            scope_ref: request.scope_ref.clone(),
            requested_authority_class: request.requested_authority_class.clone(),
            decision: decision.map(|decision| decision.decision.clone()),
            decided_by: decision.map(|decision| decision.decided_by.clone()),
            notes: decision.and_then(|decision| decision.notes.clone()),
        });
    }
    views
}

fn collect_checkpoints(memory_store: &MemoryStore) -> Vec<CheckpointView> {
    let mut checkpoints = Vec::new();
    for artifact in &memory_store.artifacts {
        if let MemoryArtifactPayload::Checkpoint(checkpoint) = &artifact.payload {
            checkpoints.push(CheckpointView {
                checkpoint_id: checkpoint.checkpoint_id.clone(),
                session_state: checkpoint.session_state.clone(),
                active_task_refs: checkpoint.active_task_refs.clone(),
                blocked_reason: checkpoint
                    .blocked_reason
                    .as_ref()
                    .map(|reason| reason.detail.clone()),
                pending_approval_count: checkpoint.pending_approval_refs.len(),
                outstanding_worker_count: checkpoint.outstanding_worker_refs.len(),
            });
        }
    }
    checkpoints.sort_by(|left, right| left.checkpoint_id.cmp(&right.checkpoint_id));
    checkpoints
}

fn collect_memory_summary(memory_store: &MemoryStore) -> MemorySummary {
    let mut approval_artifact_count = 0;
    let mut checkpoint_artifact_count = 0;
    let mut audit_artifact_count = 0;
    for artifact in &memory_store.artifacts {
        match artifact.class {
            MemoryArtifactClass::ApprovalRequestArtifact
            | MemoryArtifactClass::ApprovalDecisionArtifact => approval_artifact_count += 1,
            MemoryArtifactClass::CheckpointArtifact => checkpoint_artifact_count += 1,
            MemoryArtifactClass::AuditRecordArtifact => audit_artifact_count += 1,
            _ => {}
        }
    }
    MemorySummary {
        artifact_count: memory_store.artifacts.len(),
        pointer_index_count: memory_store.pointer_indexes.len(),
        topic_bundle_count: memory_store.topic_bundles.len(),
        transcript_slice_count: memory_store.transcript_slices.len(),
        contradiction_count: memory_store.contradiction_records.len(),
        approval_artifact_count,
        checkpoint_artifact_count,
        audit_artifact_count,
    }
}

fn collect_promotion_summary(
    memory_store: &MemoryStore,
    quarantines: &[QuarantineRecord],
    rollback_handle: Option<&RollbackHandle>,
) -> PromotionSummary {
    let mut promotion_refs = BTreeSet::new();
    let mut completion_refs = BTreeSet::new();
    let mut self_hosting_refs = BTreeSet::new();
    for artifact in &memory_store.artifacts {
        if let MemoryArtifactPayload::AuditRecord(audit) = &artifact.payload {
            let related_ref = audit.related_ref.clone();
            if related_ref.contains("promotion")
                || related_ref.contains("adoption")
                || related_ref.contains("reversal")
            {
                promotion_refs.insert(related_ref.clone());
            }
            if related_ref.contains("completion") || related_ref.contains("cycle") {
                completion_refs.insert(related_ref.clone());
            }
            if related_ref.contains("self-hosting")
                || related_ref.contains("successor")
                || related_ref.contains("continuous-program")
            {
                self_hosting_refs.insert(related_ref);
            }
        }
    }
    PromotionSummary {
        promotion_refs: promotion_refs.into_iter().collect(),
        completion_refs: completion_refs.into_iter().collect(),
        self_hosting_refs: self_hosting_refs.into_iter().collect(),
        quarantine_refs: quarantines
            .iter()
            .map(|quarantine| quarantine.quarantine_id.clone())
            .collect(),
        rollback_handle_id: rollback_handle.map(|handle| handle.rollback_handle_id.clone()),
    }
}

#[derive(Clone, Debug)]
struct V3GenerationSelection {
    selected_runs: Vec<RunViewModel>,
    incumbent: RunViewModel,
    challenger: RunViewModel,
    successor: Option<RunViewModel>,
}

fn build_v3_generation_artifact_packaging_view(
    run_views: &[RunViewModel],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    handoff_packets: &[V2NextLineHandoffPacket],
    artifacts: &[V3GenerationArtifact],
) -> V3GenerationArtifactPackagingView {
    let artifact = artifacts.first().cloned().unwrap_or_else(|| {
        build_v3_generation_artifact(
            run_views,
            review_packets,
            transition_packets,
            handoff_packets,
            &default_v3_generation_artifact_export_request(),
            false,
        )
    });
    V3GenerationArtifactPackagingView {
        summary: if artifact.exported {
            "The v3 generation artifact view keeps one explicit governed generation artifact, build closure, package bundle manifest, and activation envelope live in the runtime.".to_string()
        } else {
            "The v3 generation artifact view can derive the next governed generation candidate, but no first-class exported generation artifact has been persisted yet.".to_string()
        },
        build_closure_summary: artifact.build_closure.summary.clone(),
        package_summary: artifact.package_bundle.summary.clone(),
        activation_summary: format!(
            "{} activation keeps coexistence mode `{}` and {} rollback ref(s) explicit.",
            artifact.title,
            artifact.activation_envelope.coexistence_mode,
            artifact.activation_envelope.rollback_refs.len()
        ),
        artifact,
        guardrails: vec![
            "No generation claim is valid without explicit build, validation, and lineage refs.".to_string(),
            "Packaging remains a governed artifact move rather than uncontrolled source-tree mutation.".to_string(),
            "Activation stays bounded by coexistence mode, rollback refs, and operator constraints.".to_string(),
        ],
    }
}

fn build_v3_native_service_validation_closure_view(
    run_views: &[RunViewModel],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    handoff_packets: &[V2NextLineHandoffPacket],
    artifacts: &[V3GenerationArtifact],
) -> V3NativeServiceValidationClosureView {
    let packaging = build_v3_generation_artifact_packaging_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let artifact = &packaging.artifact;
    let service_maturity = vec![
        build_v3_service_maturity_record(
            "service:generation-build",
            "build",
            "hybrid",
            artifact,
            &["bounded build service", "explicit carried inputs"],
        ),
        build_v3_service_maturity_record(
            "service:semantic-validation",
            "validation",
            "hybrid",
            artifact,
            &["semantic checks", "behavior checks"],
        ),
        build_v3_service_maturity_record(
            "service:review-evidence",
            "review",
            "native-enough",
            artifact,
            &["review packet", "decision support"],
        ),
        build_v3_service_maturity_record(
            "service:artifact-storage",
            "storage",
            "native-enough",
            artifact,
            &["durable storage", "lineage continuity"],
        ),
        build_v3_service_maturity_record(
            "service:approval-release",
            "approval",
            "native-enough",
            artifact,
            &["approval linkage", "rollback symmetry"],
        ),
        build_v3_service_maturity_record(
            "service:package-bundle",
            "packaging",
            "hybrid",
            artifact,
            &["bundle manifest", "activation envelope"],
        ),
    ];
    let service_handles = service_maturity
        .iter()
        .map(|record| V3SelfProductionServiceHandle {
            handle_id: format!("service-handle:{}", sanitize_id(&record.service_ref)),
            service_ref: record.service_ref.clone(),
            family: record.family.clone(),
            bound_scope: format!("generation:{}", artifact.generation_id),
            maturity_class: record.maturity_class.clone(),
        })
        .collect::<Vec<_>>();
    let effect_attestations = service_handles
        .iter()
        .map(|handle| V3BuildEffectAttestation {
            attestation_id: format!(
                "attestation:{}:{}",
                sanitize_id(&handle.service_ref),
                sanitize_id(&artifact.generation_id)
            ),
            service_handle_ref: handle.handle_id.clone(),
            generation_ref: artifact.generation_id.clone(),
            effect_scope: match handle.family.as_str() {
                "build" => "build".to_string(),
                "packaging" => "package".to_string(),
                "storage" => "store".to_string(),
                _ => "validation-prep".to_string(),
            },
            evidence_refs: unique_strings(
                artifact
                    .build_closure
                    .validation_refs
                    .iter()
                    .cloned()
                    .chain(artifact.validation_refs.iter().cloned())
                    .chain([handle.handle_id.clone()]),
            ),
        })
        .collect::<Vec<_>>();
    let validation_bundle = V3GenerationValidationBundle {
        validation_bundle_id: format!("validation-bundle:{}", artifact.generation_id),
        generation_ref: artifact.generation_id.clone(),
        semantic_checks: vec![
            "Genome, phenotype, package bundle, and lineage refs are all explicit.".to_string(),
            "The candidate remains comparable to the incumbent through an explicit compatibility surface.".to_string(),
        ],
        service_checks: vec![
            "Build, validation, review, storage, approval, and packaging services stay explicit.".to_string(),
            "Each service family is bound through a named handle with effect attestation.".to_string(),
        ],
        governance_checks: vec![
            "Activation envelope retains coexistence mode and rollback refs.".to_string(),
            "Operator constraints remain attached to the candidate generation move.".to_string(),
        ],
        decision_summary: "The candidate generation is admissible for bounded adopt, reject, or defer review because build closure, service closure, validation, and governance linkage are all explicit.".to_string(),
    };
    let review_packet = V3GenerationReviewPacket {
        packet_id: format!("generation-review:{}", artifact.generation_id),
        generation_ref: artifact.generation_id.clone(),
        decision_classes: vec![
            "retain incumbent".to_string(),
            "adopt challenger".to_string(),
            "reject challenger".to_string(),
            "defer decision".to_string(),
            "roll back adopted challenger".to_string(),
        ],
        operator_summary: "The review packet keeps the generation decision vocabulary compact enough to support real adopt, reject, defer, and rollback moves.".to_string(),
        evidence_refs: unique_strings(
            artifact
                .validation_refs
                .iter()
                .cloned()
                .chain(
                    review_packets
                        .iter()
                        .take(3)
                        .map(|packet| packet.packet_id.clone()),
                )
                .chain([artifact.generation_id.clone()]),
        ),
    };
    let lineage_record = build_v3_lineage_continuity_record(run_views, artifact);

    V3NativeServiceValidationClosureView {
        summary: "The v3 service-closure view makes the minimal self-production loop explicit through active build, validation, review, storage, approval, and packaging surfaces.".to_string(),
        closure_state: "The self-production service subset is explicit, attributable, and bounded enough to support one governed v3 loop without claiming a final substrate.".to_string(),
        service_maturity,
        service_handles,
        effect_attestations,
        validation_bundle,
        review_packet,
        lineage_record,
        guardrails: vec![
            "No active self-production effect may rely on hidden ambient capability.".to_string(),
            "Build and packaging effects must remain attributable through service handles and attestations.".to_string(),
            "This closure is loop-specific; it does not claim every imaginable service surface is native.".to_string(),
        ],
    }
}

fn build_v3_generation_comparison_adoption_rollback_view(
    run_views: &[RunViewModel],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    handoff_packets: &[V2NextLineHandoffPacket],
    artifacts: &[V3GenerationArtifact],
) -> V3GenerationComparisonAdoptionRollbackView {
    let packaging = build_v3_generation_artifact_packaging_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let services = build_v3_native_service_validation_closure_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let artifact = &packaging.artifact;
    let decision = V3GenerationAdoptionDecision {
        decision_id: format!("generation-decision:{}", artifact.generation_id),
        incumbent_ref: artifact.compatibility_surface.incumbent_ref.clone(),
        challenger_ref: artifact.generation_id.clone(),
        decision: "adopt challenger under bounded observation".to_string(),
        operator_burden_assessment:
            "Operator burden is preserved inside one bounded observation window with rollback still live."
                .to_string(),
        rollback_refs: artifact.activation_envelope.rollback_refs.clone(),
    };
    let observation_window = V3ObservationWindowReport {
        report_id: format!("observation-window:{}", artifact.generation_id),
        generation_ref: artifact.generation_id.clone(),
        window_bounds: vec![
            "one bounded observation window".to_string(),
            "incumbent retained until observation completes".to_string(),
            "one successor-production attempt maximum".to_string(),
        ],
        findings: vec![
            "The adopted generation stays replayable and lineage-preserving during observation."
                .to_string(),
            "Rollback remains a symmetric and explicit outcome of the same decision surface."
                .to_string(),
        ],
        decision_ref: format!("decision-followup:{}", artifact.generation_id),
    };
    let rollback_envelope = V3RollbackEnvelope {
        envelope_id: format!("rollback-envelope:{}", artifact.generation_id),
        generation_ref: artifact.generation_id.clone(),
        rollback_refs: artifact.activation_envelope.rollback_refs.clone(),
        coexistence_guarantees: vec![
            "Incumbent retention remains mandatory until observation law closes.".to_string(),
            "Rollback preserves lineage continuity and decision evidence.".to_string(),
        ],
    };
    let release_evidence = V3ReleaseEvidencePack {
        pack_id: format!("release-evidence:{}", artifact.generation_id),
        generation_ref: artifact.generation_id.clone(),
        release_posture: "bounded adopt with explicit observation and rollback symmetry"
            .to_string(),
        operator_burden_summary: decision.operator_burden_assessment.clone(),
        evidence_refs: unique_strings(
            services
                .review_packet
                .evidence_refs
                .iter()
                .cloned()
                .chain(artifact.activation_envelope.rollback_refs.iter().cloned())
                .chain([
                    decision.decision_id.clone(),
                    observation_window.report_id.clone(),
                ]),
        ),
    };

    V3GenerationComparisonAdoptionRollbackView {
        summary: "The v3 adoption view keeps retain, adopt, reject, defer, and rollback law explicit for one governed generation move.".to_string(),
        comparison_summary: artifact.compatibility_surface.summary.clone(),
        decision,
        observation_window,
        rollback_envelope,
        release_evidence,
        lineage_record: services.lineage_record,
        guardrails: vec![
            "No generation activation is valid without rollback guarantees.".to_string(),
            "Activation and long-term acceptance remain distinct because observation is first-class.".to_string(),
            "Operator burden is part of release truth rather than an afterthought.".to_string(),
        ],
    }
}

fn build_v3_adopted_generation_successor_production_view(
    run_views: &[RunViewModel],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    handoff_packets: &[V2NextLineHandoffPacket],
    artifacts: &[V3GenerationArtifact],
) -> V3AdoptedGenerationSuccessorProductionView {
    let packaging = build_v3_generation_artifact_packaging_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let adoption = build_v3_generation_comparison_adoption_rollback_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let selection = select_v3_generation_runs(run_views, &[]);
    let artifact = &packaging.artifact;
    let successor_run = selection
        .successor
        .as_ref()
        .map(|view| V3SuccessorProductionRunRecord {
            run_id: format!("successor-run:{}", view.summary.run_id),
            adopted_generation_ref: artifact.generation_id.clone(),
            produced_generation_ref: format!(
                "generation:successor:{}",
                sanitize_id(&view.summary.run_id)
            ),
            runtime_bounds: vec![
                "single-factory scope".to_string(),
                "one bounded successor-production run".to_string(),
                "explicit stop conditions preserved".to_string(),
            ],
            evidence_refs: unique_strings(view_evidence_refs(view).into_iter().chain([
                view.summary.run_id.clone(),
                view.summary.bundle_path.clone(),
            ])),
        });
    let campaign = V3SelfProductionCampaign {
        campaign_id: format!("self-production-campaign:{}", artifact.generation_id),
        incumbent_generation_ref: artifact.compatibility_surface.incumbent_ref.clone(),
        challenger_generation_ref: artifact.generation_id.clone(),
        runtime_stage: if successor_run.is_some() {
            "successor-production-complete".to_string()
        } else {
            "bounded-observation-complete".to_string()
        },
        governance_refs: unique_strings(
            artifact
                .activation_envelope
                .rollback_refs
                .iter()
                .cloned()
                .chain([
                    adoption.decision.decision_id.clone(),
                    adoption.observation_window.report_id.clone(),
                ]),
        ),
        replay_refs: unique_strings(selection.selected_runs.iter().flat_map(|view| {
            view.summary
                .latest_checkpoint_id
                .clone()
                .into_iter()
                .chain([view.summary.run_id.clone()])
        })),
    };

    V3AdoptedGenerationSuccessorProductionView {
        summary: "The v3 successor-production view proves that an adopted generation gets one bounded chance to produce a later candidate inside the same governed pipeline.".to_string(),
        adopted_generation_ref: artifact.generation_id.clone(),
        observation_summary: adoption.release_evidence.release_posture,
        campaign,
        successor_run,
        runtime_stage_story: vec![
            "candidate definition".to_string(),
            "build closure".to_string(),
            "validation and review".to_string(),
            "bounded adopt and observation".to_string(),
            "single successor-production run".to_string(),
        ],
        guardrails: vec![
            "Activation and successor production remain separately reconstructable.".to_string(),
            "No successor-production run is valid before observation-window completion.".to_string(),
            "The self-production campaign remains single-factory and bounded.".to_string(),
        ],
    }
}

fn build_v3_self_production_workspace_view(
    run_views: &[RunViewModel],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    handoff_packets: &[V2NextLineHandoffPacket],
    artifacts: &[V3GenerationArtifact],
    packets: &[V3SelfProductionEvidencePacket],
) -> V3SelfProductionWorkspaceView {
    let packaging = build_v3_generation_artifact_packaging_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let services = build_v3_native_service_validation_closure_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let adoption = build_v3_generation_comparison_adoption_rollback_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let successor = build_v3_adopted_generation_successor_production_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );

    V3SelfProductionWorkspaceView {
        summary: "The v3 self-production workspace keeps generation production, service closure, adoption law, successor-production evidence, and one exportable packet in a single compact operator surface.".to_string(),
        artifact_ref: packaging.artifact.generation_id.clone(),
        service_summary: services.summary,
        adoption_summary: adoption.summary,
        successor_summary: successor.summary,
        latest_evidence_packet: packets.first().cloned(),
        milestone_checks: vec![
            if packaging.artifact.exported {
                "A first-class exported generation artifact is present.".to_string()
            } else {
                "The runtime can derive a v3 generation artifact, but it has not been exported yet.".to_string()
            },
            services.closure_state,
            format!("Decision posture: {}", adoption.decision.decision),
            if successor.successor_run.is_some() {
                "An adopted-generation successor-production run is explicit.".to_string()
            } else {
                "No explicit successor-production run is attached yet.".to_string()
            },
            if packets.first().is_some() {
                "A self-production evidence packet has been exported.".to_string()
            } else {
                "No self-production evidence packet has been exported yet.".to_string()
            },
        ],
        guardrails: vec![
            "The workspace supports inspection; it does not replace the underlying evidence closure.".to_string(),
            "Self-production scope remains explicitly single-factory and bounded.".to_string(),
            "Later-factory creation and federation remain outside this workspace claim.".to_string(),
        ],
    }
}

fn build_v3_bounded_single_factory_self_production_gate_view(
    run_views: &[RunViewModel],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    handoff_packets: &[V2NextLineHandoffPacket],
    artifacts: &[V3GenerationArtifact],
    packets: &[V3SelfProductionEvidencePacket],
) -> V3BoundedSingleFactorySelfProductionGateView {
    let packaging = build_v3_generation_artifact_packaging_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let services = build_v3_native_service_validation_closure_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let adoption = build_v3_generation_comparison_adoption_rollback_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let successor = build_v3_adopted_generation_successor_production_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        artifacts,
    );
    let latest_packet = packets.first().cloned();
    let claim = if packaging.artifact.exported
        && successor.successor_run.is_some()
        && latest_packet.is_some()
    {
        let successor_run = successor.successor_run.as_ref().unwrap();
        Some(V3SingleFactorySelfProductionClaim {
            claim_id: format!("v3-claim:{}", packaging.artifact.generation_id),
            incumbent_ref: packaging
                .artifact
                .compatibility_surface
                .incumbent_ref
                .clone(),
            adopted_generation_ref: packaging.artifact.generation_id.clone(),
            successor_candidate_ref: successor_run.produced_generation_ref.clone(),
            evidence_refs: unique_strings(
                latest_packet
                    .iter()
                    .flat_map(|packet| {
                        packet
                            .generation_refs
                            .iter()
                            .cloned()
                            .chain(packet.comparison_refs.iter().cloned())
                            .chain(packet.runtime_refs.iter().cloned())
                            .chain(packet.governance_refs.iter().cloned())
                    })
                    .chain([packaging.artifact.generation_id.clone()]),
            ),
            claimed_scope: "single-factory self-production only".to_string(),
        })
    } else {
        None
    };

    V3BoundedSingleFactorySelfProductionGateView {
        summary: if claim.is_some() {
            "The v3 gate can now state one bounded native single-factory self-production milestone without claiming later-factory creation or federation.".to_string()
        } else {
            "The v3 gate remains incomplete until the runtime holds an explicit exported generation artifact, one bounded successor-production record, and one evidence packet supporting the claim boundary.".to_string()
        },
        milestone_ladder: vec![
            V3MilestoneStepView {
                milestone_id: "M1".to_string(),
                title: "Generation artifact and packaging closure".to_string(),
                status: if packaging.artifact.exported {
                    "complete".to_string()
                } else {
                    "incomplete".to_string()
                },
                detail: packaging.summary.clone(),
            },
            V3MilestoneStepView {
                milestone_id: "M2".to_string(),
                title: "Native service and validation closure".to_string(),
                status: "complete".to_string(),
                detail: services.closure_state.clone(),
            },
            V3MilestoneStepView {
                milestone_id: "M3".to_string(),
                title: "Adoption and rollback-safe generation replacement".to_string(),
                status: "complete".to_string(),
                detail: adoption.decision.decision.clone(),
            },
            V3MilestoneStepView {
                milestone_id: "M4".to_string(),
                title: "Adopted-generation successor-production proof".to_string(),
                status: if successor.successor_run.is_some() {
                    "complete".to_string()
                } else {
                    "incomplete".to_string()
                },
                detail: successor.summary.clone(),
            },
            V3MilestoneStepView {
                milestone_id: "M5".to_string(),
                title: "Bounded single-factory self-production gate".to_string(),
                status: if claim.is_some() {
                    "complete".to_string()
                } else {
                    "incomplete".to_string()
                },
                detail: "The final v3 claim requires an explicit exported generation artifact, one adopted-generation successor candidate, and one compact evidence packet.".to_string(),
            },
        ],
        claim,
        boundary_statement: default_v3_claim_boundary(),
        next_line: if latest_packet.is_some() {
            "Keep the packaging and service substrate explicit, deepen the active loop, and preserve the boundary between single-factory self-production and later-factory creation.".to_string()
        } else {
            "Export the self-production evidence packet before issuing the first bounded v3 milestone claim.".to_string()
        },
        guardrails: vec![
            "No self-production claim without adopted-generation successor production.".to_string(),
            "No scope statement may imply later-factory creation, federation, or hosted ecosystem readiness.".to_string(),
            "The v3 milestone is stronger than v2 transition-readiness, but it remains bounded and single-factory.".to_string(),
        ],
    }
}

fn build_phase_b_factory_dossier_view(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
) -> Result<PhaseBFactoryDossierView, LocalRuntimeError> {
    let relevant_records = records
        .iter()
        .filter(|record| {
            record
                .runtime_state
                .root_task
                .output_refs
                .iter()
                .any(|reference| {
                    reference.starts_with(FACTORY_PACKET_OUTPUT_PREFIX)
                        || reference.starts_with(FACTORY_COMPARISON_OUTPUT_PREFIX)
                        || reference.starts_with(FACTORY_ACTIVATION_OUTPUT_PREFIX)
                })
        })
        .collect::<Vec<_>>();
    if relevant_records.is_empty() {
        return Ok(PhaseBFactoryDossierView {
            summary: "No live Phase B factory dossier is available yet.".to_string(),
            run_refs: Vec::new(),
            incumbent_factory_refs: Vec::new(),
            challenger_factory_refs: Vec::new(),
            genomes: Vec::new(),
            phenotypes: Vec::new(),
            lineage_records: Vec::new(),
            validation_profiles: Vec::new(),
            validation_evidence: Vec::new(),
            validation_records: Vec::new(),
            comparisons: Vec::new(),
            activations: Vec::new(),
            active_states: Vec::new(),
            governance_transitions: Vec::new(),
            rollback_envelopes: Vec::new(),
            quarantine_records: Vec::new(),
            evidence_packets: Vec::new(),
            boundary_statement:
                "Phase B proves explicit single-factory artifact identity, comparison, adoption, and rollback only."
                    .to_string(),
            guardrails: vec![
                "No Phase B claim without stored comparison and activation refs.".to_string(),
                "No adoption summary without retained-incumbent and rollback visibility."
                    .to_string(),
                "Phase B does not imply later-factory creation or federation.".to_string(),
            ],
        });
    }

    let mut run_refs = Vec::new();
    let mut genomes = BTreeMap::new();
    let mut phenotypes = BTreeMap::new();
    let mut lineage_records = BTreeMap::new();
    let mut validation_profiles = BTreeMap::new();
    let mut validation_evidence = BTreeMap::new();
    let mut validation_records = BTreeMap::new();
    let mut comparisons = BTreeMap::new();
    let mut activations = BTreeMap::new();
    let mut active_states = BTreeMap::new();
    let mut governance_transitions = BTreeMap::new();
    let mut rollback_envelopes = BTreeMap::new();
    let mut quarantine_records = BTreeMap::new();
    let mut evidence_packets = BTreeMap::new();

    for record in relevant_records {
        run_refs.push(record.metadata.run_id.clone());
        let store = DurableArtifactStore::bootstrap(workspace.store_root(&record.metadata.run_id))?;

        for genome_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_GENOME_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_genome_artifact(&genome_id)?;
            genomes.insert(item.factory_genome_id.clone(), item);
        }
        for phenotype_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_PHENOTYPE_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_phenotype_artifact(&phenotype_id)?;
            phenotypes.insert(item.factory_phenotype_id.clone(), item);
        }
        for lineage_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_LINEAGE_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_lineage_record(&lineage_id)?;
            lineage_records.insert(item.lineage_id.clone(), item);
        }
        for profile_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_VALIDATION_PROFILE_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_validation_profile(&profile_id)?;
            validation_profiles.insert(item.validation_profile_id.clone(), item);
        }
        for evidence_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_VALIDATION_EVIDENCE_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_validation_evidence(&evidence_id)?;
            validation_evidence.insert(item.evidence_id.clone(), item);
        }
        for record_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_VALIDATION_RECORD_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_validation_record(&record_id)?;
            validation_records.insert(item.validation_id.clone(), item);
        }
        for comparison_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_COMPARISON_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_comparison_record(&comparison_id)?;
            comparisons.insert(item.comparison_id.clone(), item);
        }
        for activation_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_ACTIVATION_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_activation_bundle(&activation_id)?;
            activations.insert(item.activation_id.clone(), item);
        }
        for state_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_STATE_OUTPUT_PREFIX,
        ) {
            let item = store.load_active_factory_state(&state_id)?;
            active_states.insert(item.state_id.clone(), item);
        }
        for transition_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_GOVERNANCE_TRANSITION_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_governance_transition(&transition_id)?;
            governance_transitions.insert(item.transition_id.clone(), item);
        }
        for rollback_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_ROLLBACK_ENVELOPE_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_rollback_envelope(&rollback_id)?;
            rollback_envelopes.insert(item.rollback_id.clone(), item);
        }
        for quarantine_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_QUARANTINE_RECORD_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_quarantine_record(&quarantine_id)?;
            quarantine_records.insert(item.quarantine_id.clone(), item);
        }
        for packet_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_PACKET_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_evidence_packet(&packet_id)?;
            evidence_packets.insert(item.packet_id.clone(), item);
        }
    }

    let genomes = genomes.into_values().collect::<Vec<_>>();
    let phenotypes = phenotypes.into_values().collect::<Vec<_>>();
    let lineage_records = lineage_records.into_values().collect::<Vec<_>>();
    let validation_profiles = validation_profiles.into_values().collect::<Vec<_>>();
    let validation_evidence = validation_evidence.into_values().collect::<Vec<_>>();
    let validation_records = validation_records.into_values().collect::<Vec<_>>();
    let comparisons = comparisons.into_values().collect::<Vec<_>>();
    let activations = activations.into_values().collect::<Vec<_>>();
    let active_states = active_states.into_values().collect::<Vec<_>>();
    let governance_transitions = governance_transitions.into_values().collect::<Vec<_>>();
    let rollback_envelopes = rollback_envelopes.into_values().collect::<Vec<_>>();
    let quarantine_records = quarantine_records.into_values().collect::<Vec<_>>();
    let evidence_packets = evidence_packets.into_values().collect::<Vec<_>>();
    let incumbent_factory_refs = unique_strings(
        comparisons
            .iter()
            .map(|comparison| comparison.incumbent_factory_ref.clone())
            .chain(
                activations
                    .iter()
                    .map(|activation| activation.retained_incumbent_ref.clone()),
            ),
    );
    let challenger_factory_refs = unique_strings(
        comparisons
            .iter()
            .map(|comparison| comparison.challenger_factory_ref.clone())
            .chain(
                activations
                    .iter()
                    .map(|activation| activation.adopted_factory_ref.clone()),
            ),
    );
    let boundary_statement = unique_strings(
        lineage_records
            .iter()
            .map(|record| record.claim_boundary.clone())
            .chain(
                evidence_packets
                    .iter()
                    .map(|packet| packet.claim_boundary.clone()),
            ),
    )
    .join(" ");

    Ok(PhaseBFactoryDossierView {
        summary: format!(
            "The Phase B factory dossier reconstructs {} genome(s), {} phenotype(s), {} comparison record(s), {} activation bundle(s), and {} evidence packet(s) from live local runs.",
            genomes.len(),
            phenotypes.len(),
            comparisons.len(),
            activations.len(),
            evidence_packets.len()
        ),
        run_refs: unique_strings(run_refs),
        incumbent_factory_refs,
        challenger_factory_refs,
        genomes,
        phenotypes,
        lineage_records,
        validation_profiles,
        validation_evidence,
        validation_records,
        comparisons,
        activations,
        active_states,
        governance_transitions,
        rollback_envelopes,
        quarantine_records,
        evidence_packets,
        boundary_statement: if boundary_statement.is_empty() {
            "Phase B proves explicit single-factory artifact identity, adoption, and rollback only."
                .to_string()
        } else {
            boundary_statement
        },
        guardrails: vec![
            "No factory review without stored lineage, validation, comparison, and activation refs."
                .to_string(),
            "No adoption summary without retained-incumbent and rollback visibility."
                .to_string(),
            "No Phase B summary may imply later-factory creation or federation.".to_string(),
        ],
    })
}

fn build_phase_b_factory_adoption_workspace_view(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
    packets: &[PhaseBFactoryReviewPacket],
) -> Result<PhaseBFactoryAdoptionWorkspaceView, LocalRuntimeError> {
    let dossier = build_phase_b_factory_dossier_view(workspace, records)?;
    Ok(PhaseBFactoryAdoptionWorkspaceView {
        summary: format!(
            "The Phase B adoption workspace binds {} comparison record(s), {} activation path(s), and {} retained-incumbent view(s) into one operator-grade adoption surface.",
            dossier.comparisons.len(),
            dossier.activations.len(),
            dossier.active_states.len()
        ),
        run_refs: dossier.run_refs.clone(),
        comparison_refs: unique_strings(
            dossier
                .comparisons
                .iter()
                .map(|comparison| comparison.comparison_id.clone()),
        ),
        activation_refs: unique_strings(
            dossier
                .activations
                .iter()
                .map(|activation| activation.activation_id.clone())
                .chain(
                    dossier
                    .active_states
                    .iter()
                    .map(|state| state.state_id.clone()),
                ),
        ),
        governance_transition_refs: unique_strings(
            dossier
                .governance_transitions
                .iter()
                .map(|record| record.transition_id.clone()),
        ),
        retained_incumbent_refs: unique_strings(
            dossier
                .activations
                .iter()
                .map(|activation| activation.retained_incumbent_ref.clone())
                .chain(
                    dossier
                        .active_states
                        .iter()
                        .filter_map(|state| state.retained_incumbent_ref.clone()),
                ),
        ),
        observation_window_refs: unique_strings(
            dossier
                .activations
                .iter()
                .map(|activation| activation.observation_window_ref.clone()),
        ),
        rollback_handle_refs: unique_strings(
            dossier
                .activations
                .iter()
                .map(|activation| activation.rollback_handle_ref.clone())
                .chain(
                    dossier
                        .rollback_envelopes
                        .iter()
                        .map(|record| record.rollback_id.clone()),
                )
                .chain(dossier.active_states.iter().flat_map(|state| {
                    state
                        .rollback_history
                        .iter()
                        .map(|record| record.rollback_handle_ref.clone())
                })),
        ),
        quarantine_refs: unique_strings(
            dossier
                .quarantine_records
                .iter()
                .map(|record| record.quarantine_id.clone()),
        ),
        latest_review_packet_id: packets.first().map(|packet| packet.packet_id.clone()),
        boundary_statement: dossier.boundary_statement,
        guardrails: vec![
            "No Phase B adoption workspace without retained incumbent, observation, and rollback visibility.".to_string(),
            "Phase B remains factory adoption and reversal only; it does not imply later-factory creation.".to_string(),
        ],
    })
}

fn build_phase_c_replication_dossier_view(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
) -> Result<PhaseCReplicationDossierView, LocalRuntimeError> {
    let relevant_records = records
        .iter()
        .filter(|record| {
            !collect_factory_replication_output_refs(&record.runtime_state.root_task.output_refs)
                .is_empty()
        })
        .collect::<Vec<_>>();
    if relevant_records.is_empty() {
        return Ok(PhaseCReplicationDossierView {
            summary: "No live Phase C replication dossier is available yet.".to_string(),
            run_refs: Vec::new(),
            parent_factory_refs: Vec::new(),
            child_factory_refs: Vec::new(),
            campaigns: Vec::new(),
            candidates: Vec::new(),
            proving_runs: Vec::new(),
            observation_windows: Vec::new(),
            quarantine_protocols: Vec::new(),
            dispositions: Vec::new(),
            decisions: Vec::new(),
            evidence_packets: Vec::new(),
            boundary_statement:
                "Phase C proves bounded later-factory creation only when a produced child remains attributable, proven, reviewable, and bounded.".to_string(),
            guardrails: vec![
                "No later-factory claim without an explicit replication campaign.".to_string(),
                "No child adoption claim without a passing proving run.".to_string(),
                "Phase C remains single-factory and bounded.".to_string(),
            ],
        });
    }

    let mut run_refs = Vec::new();
    let mut campaigns = BTreeMap::new();
    let mut candidates = BTreeMap::new();
    let mut proving_runs = BTreeMap::new();
    let mut observation_windows = BTreeMap::new();
    let mut quarantine_protocols = BTreeMap::new();
    let mut dispositions = BTreeMap::new();
    let mut decisions = BTreeMap::new();
    let mut packets = BTreeMap::new();

    for record in relevant_records {
        run_refs.push(record.metadata.run_id.clone());
        let store = DurableArtifactStore::bootstrap(workspace.store_root(&record.metadata.run_id))?;

        for campaign_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_REPLICATION_CAMPAIGN_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_replication_campaign(&campaign_id)?;
            campaigns.insert(item.replication_campaign_id.clone(), item);
        }
        for candidate_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            LATER_FACTORY_CANDIDATE_OUTPUT_PREFIX,
        ) {
            let item = store.load_later_factory_candidate(&candidate_id)?;
            candidates.insert(item.later_factory_candidate_id.clone(), item);
        }
        for proving_run_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_PROVING_RUN_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_proving_run_record(&proving_run_id)?;
            proving_runs.insert(item.proving_run_id.clone(), item);
        }
        for observation_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            CHILD_FACTORY_OBSERVATION_OUTPUT_PREFIX,
        ) {
            let item = store.load_child_factory_observation_window(&observation_id)?;
            observation_windows.insert(item.observation_window_id.clone(), item);
        }
        for protocol_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            CHILD_FACTORY_QUARANTINE_PROTOCOL_OUTPUT_PREFIX,
        ) {
            let item = store.load_child_factory_quarantine_protocol(&protocol_id)?;
            quarantine_protocols.insert(item.protocol_id.clone(), item);
        }
        for disposition_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            CHILD_FACTORY_DISPOSITION_OUTPUT_PREFIX,
        ) {
            let item = store.load_child_factory_disposition(&disposition_id)?;
            dispositions.insert(item.disposition_id.clone(), item);
        }
        for decision_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_REPLICATION_DECISION_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_replication_decision(&decision_id)?;
            decisions.insert(item.decision_id.clone(), item);
        }
        for packet_id in output_ref_suffixes(
            &record.runtime_state.root_task.output_refs,
            FACTORY_REPLICATION_PACKET_OUTPUT_PREFIX,
        ) {
            let item = store.load_factory_replication_evidence_packet(&packet_id)?;
            packets.insert(item.packet_id.clone(), item);
        }
    }

    let campaigns = campaigns.into_values().collect::<Vec<_>>();
    let candidates = candidates.into_values().collect::<Vec<_>>();
    let proving_runs = proving_runs.into_values().collect::<Vec<_>>();
    let observation_windows = observation_windows.into_values().collect::<Vec<_>>();
    let quarantine_protocols = quarantine_protocols.into_values().collect::<Vec<_>>();
    let dispositions = dispositions.into_values().collect::<Vec<_>>();
    let decisions = decisions.into_values().collect::<Vec<_>>();
    let evidence_packets = packets.into_values().collect::<Vec<_>>();
    let parent_factory_refs = unique_strings(
        campaigns
            .iter()
            .map(|campaign| campaign.adopted_factory_ref.clone()),
    );
    let child_factory_refs = unique_strings(
        candidates
            .iter()
            .map(|candidate| candidate.factory_phenotype_ref.clone()),
    );
    let boundary_statement = unique_strings(
        evidence_packets
            .iter()
            .map(|packet| packet.claim_boundary.clone()),
    )
    .join(" ");

    Ok(PhaseCReplicationDossierView {
        summary: format!(
            "The Phase C replication dossier reconstructs {} bounded replication campaign(s), {} child candidate(s), {} proving run(s), {} observation window(s), and {} decision record(s) from live local runs.",
            campaigns.len(),
            candidates.len(),
            proving_runs.len(),
            observation_windows.len(),
            decisions.len()
        ),
        run_refs: unique_strings(run_refs),
        parent_factory_refs,
        child_factory_refs,
        campaigns,
        candidates,
        proving_runs,
        observation_windows,
        quarantine_protocols,
        dispositions,
        decisions,
        evidence_packets,
        boundary_statement: if boundary_statement.is_empty() {
            "Phase C proves bounded later-factory creation only.".to_string()
        } else {
            boundary_statement
        },
        guardrails: vec![
            "No later-factory claim without an explicit replication campaign.".to_string(),
            "No produced-child claim without proving evidence.".to_string(),
            "No bounded observation story without explicit observation and quarantine-ready refs."
                .to_string(),
            "No Phase C summary may imply ecosystem federation or unbounded recursion.".to_string(),
        ],
    })
}

fn build_phase_c_observation_workspace_view(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
    packets: &[PhaseCReplicationReviewPacket],
) -> Result<PhaseCObservationWorkspaceView, LocalRuntimeError> {
    let dossier = build_phase_c_replication_dossier_view(workspace, records)?;
    Ok(PhaseCObservationWorkspaceView {
        summary: format!(
            "The Phase C observation workspace binds {} observation window(s), {} quarantine protocol(s), and {} decision record(s) into one child-factory review surface.",
            dossier.observation_windows.len(),
            dossier.quarantine_protocols.len(),
            dossier.decisions.len()
        ),
        run_refs: dossier.run_refs.clone(),
        campaign_refs: unique_strings(
            dossier
                .campaigns
                .iter()
                .map(|campaign| campaign.replication_campaign_id.clone()),
        ),
        child_factory_refs: dossier.child_factory_refs.clone(),
        observation_window_refs: unique_strings(
            dossier
                .observation_windows
                .iter()
                .map(|record| record.observation_window_id.clone()),
        ),
        quarantine_protocol_refs: unique_strings(
            dossier
                .quarantine_protocols
                .iter()
                .map(|record| record.protocol_id.clone()),
        ),
        decision_refs: unique_strings(
            dossier
                .decisions
                .iter()
                .map(|record| record.decision_id.clone()),
        ),
        disposition_refs: unique_strings(
            dossier
                .dispositions
                .iter()
                .map(|record| record.disposition_id.clone()),
        ),
        rollback_refs: unique_strings(
            dossier
                .observation_windows
                .iter()
                .flat_map(|record| record.rollback_refs.iter().cloned())
                .chain(
                    dossier
                        .quarantine_protocols
                        .iter()
                        .flat_map(|record| record.rollback_refs.iter().cloned()),
                )
                .chain(
                    dossier
                        .decisions
                        .iter()
                        .flat_map(|record| record.rollback_refs.iter().cloned()),
                )
                .chain(
                    dossier
                        .dispositions
                        .iter()
                        .flat_map(|record| record.rollback_refs.iter().cloned()),
                ),
        ),
        latest_review_packet_id: packets.first().map(|packet| packet.packet_id.clone()),
        boundary_statement: dossier.boundary_statement,
        guardrails: vec![
            "No child-factory observation story without explicit observation, decision, and quarantine-ready refs.".to_string(),
            "Phase C remains one bounded later-factory proof, not open-ended recursion.".to_string(),
        ],
    })
}

