fn aggregate_closure_criterion_status(
    criteria: &[crate::execution::ClosureCriterionRecord],
) -> crate::execution::ClosureCriterionStatus {
    if criteria
        .iter()
        .any(|criterion| criterion.status == crate::execution::ClosureCriterionStatus::Failed)
    {
        crate::execution::ClosureCriterionStatus::Failed
    } else if criteria
        .iter()
        .any(|criterion| criterion.status == crate::execution::ClosureCriterionStatus::Caveated)
    {
        crate::execution::ClosureCriterionStatus::Caveated
    } else {
        crate::execution::ClosureCriterionStatus::Passed
    }
}

fn closure_decision_from_review(
    criteria: &[crate::execution::ClosureCriterionRecord],
    residual_risks: &[crate::execution::ResidualRiskRecord],
) -> crate::execution::NorthStarClosureDecision {
    if criteria
        .iter()
        .any(|criterion| criterion.status == crate::execution::ClosureCriterionStatus::Failed)
        || residual_risks
            .iter()
            .any(|risk| risk.closure_effect == crate::execution::ClosureEffect::BlocksClosure)
    {
        crate::execution::NorthStarClosureDecision::NotYet
    } else if criteria
        .iter()
        .any(|criterion| criterion.status == crate::execution::ClosureCriterionStatus::Caveated)
        || residual_risks
            .iter()
            .any(|risk| risk.closure_effect == crate::execution::ClosureEffect::Caveated)
    {
        crate::execution::NorthStarClosureDecision::ClosedWithCaveats
    } else {
        crate::execution::NorthStarClosureDecision::Closed
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Phase03ClaimAssessment {
    Blocked,
    PositiveWithCaveats,
}

fn assess_phase03_claim_posture(
    phase01_status: &str,
    phase02_status: &str,
    phase03_status: &str,
    phase03_packet: Option<&crate::execution::Phase03ClosureReviewPacket>,
) -> (Phase03ClaimAssessment, Vec<String>) {
    let mut gap_refs = Vec::new();

    if phase01_status != "closure_grade" {
        gap_refs.push("gap:phase01-lifecycle-closure-not-closure-grade".to_string());
    }
    if phase02_status != "closure_grade" {
        gap_refs.push("gap:phase02-service-ecology-closure-not-closure-grade".to_string());
    }
    if phase03_status != "closure_grade" {
        gap_refs.push("gap:phase03-reproduction-ecosystem-closure-not-closure-grade".to_string());
    }
    match phase03_packet {
        Some(packet) => gap_refs.extend(packet.blocking_risk_refs.iter().cloned()),
        None => gap_refs.push("gap:phase03-closure-review-packet-missing".to_string()),
    }

    let gap_refs = unique_strings(gap_refs);
    let assessment = if gap_refs.is_empty() {
        Phase03ClaimAssessment::PositiveWithCaveats
    } else {
        Phase03ClaimAssessment::Blocked
    };
    (assessment, gap_refs)
}

fn remediation_workstream(
    workstream_id: &str,
    title: &str,
    status: &str,
    summary: impl Into<String>,
    evidence_refs: Vec<String>,
    blocker_refs: Vec<String>,
) -> RemediationWorkstreamView {
    RemediationWorkstreamView {
        workstream_id: workstream_id.to_string(),
        title: title.to_string(),
        status: status.to_string(),
        summary: summary.into(),
        evidence_refs,
        blocker_refs,
    }
}

fn remediation_phase_status(workstreams: &[RemediationWorkstreamView]) -> String {
    if workstreams.iter().any(|item| item.status == "not_yet") {
        "not_yet".to_string()
    } else if workstreams
        .iter()
        .any(|item| item.status == "live_but_bounded")
    {
        "live_but_bounded".to_string()
    } else {
        "closure_grade".to_string()
    }
}

fn build_remediation_phase_01_lifecycle_closure_view(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
) -> Result<RemediationPhase01LifecycleClosureView, LocalRuntimeError> {
    let northstar01 = build_northstar_01_universal_shell_view(workspace, records)?;
    let northstar02 = build_northstar_02_persistent_shell_view(workspace, records)?;
    let persistent_shell_scenarios_present = [
        LIVE_NORTHSTAR_PROGRAM_SCENARIO_ID,
        "supervisor-durable-fixed-interface-continuous-self-hosting-program",
        "supervisor-background-quarantine-rollback-control-loop",
    ]
    .iter()
    .all(|scenario_id| {
        records.iter().any(|record| {
            record.metadata.scenario_id == *scenario_id
                && collect_output_refs_with_prefixes(
                    &record.runtime_state.root_task.output_refs,
                    &[
                        NS02_TICK_OUTPUT_PREFIX,
                        NS02_WAKE_OUTPUT_PREFIX,
                        NS02_LEASE_OUTPUT_PREFIX,
                        NS02_INBOX_OUTPUT_PREFIX,
                        NS02_DECISION_BUNDLE_OUTPUT_PREFIX,
                        NS02_EXPIRY_OUTPUT_PREFIX,
                        NS02_ESCALATION_OUTPUT_PREFIX,
                        NS02_CONTINUITY_JOB_OUTPUT_PREFIX,
                        NS02_AUDIT_PACKET_OUTPUT_PREFIX,
                        NS02_OPERATIONS_DOSSIER_OUTPUT_PREFIX,
                    ],
                )
                .len()
                    > 0
        })
    });

    let shell_first_paths = unique_strings(
        northstar01
            .support
            .iter()
            .filter(|item| item.support_class == crate::execution::PathSupportClass::ShellFirst)
            .map(|item| item.path_ref.clone()),
    );
    let transitional_paths = unique_strings(
        northstar01
            .support
            .iter()
            .filter(|item| {
                item.support_class == crate::execution::PathSupportClass::Transitional
                    && !matches!(
                        scenario_definition(&item.path_ref)
                            .map(|definition| definition.runtime_class),
                        Some(ScenarioRuntimeClass::ReferenceDemo)
                    )
            })
            .map(|item| item.path_ref.clone()),
    );
    let unsupported_paths = unique_strings(
        northstar01
            .support
            .iter()
            .filter(|item| {
                item.support_class == crate::execution::PathSupportClass::Unsupported
                    && !matches!(
                        scenario_definition(&item.path_ref)
                            .map(|definition| definition.runtime_class),
                        Some(ScenarioRuntimeClass::ReferenceDemo)
                    )
            })
            .map(|item| item.path_ref.clone()),
    );
    let reference_demo_paths = unique_strings(
        northstar01
            .support
            .iter()
            .filter(|item| {
                matches!(
                    scenario_definition(&item.path_ref).map(|definition| definition.runtime_class),
                    Some(ScenarioRuntimeClass::ReferenceDemo)
                )
            })
            .map(|item| item.path_ref.clone()),
    );
    let launch_evidence = unique_strings(
        northstar01
            .launches
            .iter()
            .map(|item| item.launch_id.clone())
            .chain(
                northstar01
                    .admissions
                    .iter()
                    .map(|item| item.admission_id.clone()),
            ),
    );
    let lifecycle_evidence = unique_strings(
        northstar01
            .lifecycle_transitions
            .iter()
            .map(|item| item.transition_id.clone())
            .chain(
                northstar01
                    .program_mappings
                    .iter()
                    .map(|item| item.mapping_id.clone()),
            )
            .chain(
                northstar01
                    .resume_chains
                    .iter()
                    .map(|item| item.resume_chain_id.clone()),
            ),
    );
    let persistent_evidence = unique_strings(
        northstar02
            .ticks
            .iter()
            .map(|item| item.tick_id.clone())
            .chain(
                northstar02
                    .wakes
                    .iter()
                    .map(|item| item.wake_record_id.clone()),
            )
            .chain(northstar02.leases.iter().map(|item| item.lease_id.clone()))
            .chain(
                northstar02
                    .approval_inboxes
                    .iter()
                    .map(|item| item.approval_inbox_id.clone()),
            )
            .chain(
                northstar02
                    .deferred_decision_bundles
                    .iter()
                    .map(|item| item.decision_bundle_id.clone()),
            )
            .chain(
                northstar02
                    .lease_expiries
                    .iter()
                    .map(|item| item.expiry_id.clone()),
            )
            .chain(
                northstar02
                    .escalations
                    .iter()
                    .map(|item| item.escalation_id.clone()),
            )
            .chain(
                northstar02
                    .consolidation_jobs
                    .iter()
                    .map(|item| item.consolidation_id.clone()),
            )
            .chain(
                northstar02
                    .continuity_jobs
                    .iter()
                    .map(|item| item.job_record_id.clone()),
            )
            .chain(
                northstar02
                    .audit_packets
                    .iter()
                    .map(|item| item.audit_packet_id.clone()),
            )
            .chain(
                northstar02
                    .operations_dossiers
                    .iter()
                    .map(|item| item.operations_dossier_id.clone()),
            ),
    );
    let operator_evidence = unique_strings(
        northstar01
            .migration_gates
            .iter()
            .map(|item| item.gate_id.clone())
            .chain(
                northstar01
                    .acceptance_matrices
                    .iter()
                    .map(|item| item.matrix_id.clone()),
            )
            .chain(
                northstar01
                    .export_bundles
                    .iter()
                    .map(|item| item.export_id.clone()),
            ),
    );

    let workstreams = vec![
        remediation_workstream(
            "phase-01-workstream-a",
            "Universal Launch Assembly and Support Classification",
            if transitional_paths.is_empty() && unsupported_paths.is_empty() {
                "closure_grade"
            } else {
                "live_but_bounded"
            },
            format!(
                "{} shell-first supported path(s), {} transitional supported path(s), {} unsupported supported path(s), and {} explicit reference/demo path(s) are currently classified under one launch law.",
                shell_first_paths.len(),
                transitional_paths.len(),
                unsupported_paths.len(),
                reference_demo_paths.len()
            ),
            unique_strings(
                shell_first_paths
                    .iter()
                    .cloned()
                    .chain(launch_evidence.iter().cloned()),
            ),
            unique_strings(
                transitional_paths
                    .iter()
                    .cloned()
                    .chain(unsupported_paths.iter().cloned()),
            ),
        ),
        remediation_workstream(
            "phase-01-workstream-b",
            "Unified Shell Lifecycle Across Scenarios, Programs, and Reruns",
            if transitional_paths.is_empty()
                && unsupported_paths.is_empty()
                && !northstar01.lifecycle_transitions.is_empty()
                && !northstar01.program_mappings.is_empty()
            {
                "closure_grade"
            } else {
                "live_but_bounded"
            },
            format!(
                "{} lifecycle transition(s), {} program mapping(s), and {} resume chain(s) prove shared shell continuity across supported live paths; {} reference/demo path(s) remain explicit outside closure scope.",
                northstar01.lifecycle_transitions.len(),
                northstar01.program_mappings.len(),
                northstar01.resume_chains.len(),
                reference_demo_paths.len()
            ),
            lifecycle_evidence,
            unique_strings(
                transitional_paths
                    .iter()
                    .cloned()
                    .chain(unsupported_paths.iter().cloned()),
            ),
        ),
        remediation_workstream(
            "phase-01-workstream-c",
            "Persistent Operational Shell Services",
            if persistent_shell_scenarios_present
                && !northstar02.ticks.is_empty()
                && !northstar02.wakes.is_empty()
                && !northstar02.leases.is_empty()
                && !northstar02.approval_inboxes.is_empty()
                && !northstar02.deferred_decision_bundles.is_empty()
                && !northstar02.lease_expiries.is_empty()
                && !northstar02.escalations.is_empty()
                && !northstar02.consolidation_jobs.is_empty()
                && !northstar02.continuity_jobs.is_empty()
                && !northstar02.audit_packets.is_empty()
                && !northstar02.operations_dossiers.is_empty()
            {
                "closure_grade"
            } else {
                "not_yet"
            },
            format!(
                "{} tick(s), {} wake record(s), {} lease(s), {} approval inbox(es), {} decision bundle(s), {} expiry record(s), {} escalation record(s), {} consolidation job(s), {} continuity repair job(s), and {} operations dossier(s) now close shell-owned persistent operations across the supported live continuous-program, rollback-control, and NorthStar program paths.",
                northstar02.ticks.len(),
                northstar02.wakes.len(),
                northstar02.leases.len(),
                northstar02.approval_inboxes.len(),
                northstar02.deferred_decision_bundles.len(),
                northstar02.lease_expiries.len(),
                northstar02.escalations.len(),
                northstar02.consolidation_jobs.len(),
                northstar02.continuity_jobs.len(),
                northstar02.operations_dossiers.len()
            ),
            persistent_evidence,
            Vec::new(),
        ),
        remediation_workstream(
            "phase-01-workstream-d",
            "Operator Truth, Migration Gates, and Acceptance Discipline",
            if !northstar01.migration_gates.is_empty()
                && !northstar01.acceptance_matrices.is_empty()
                && !northstar01.export_bundles.is_empty()
            {
                "closure_grade"
            } else {
                "not_yet"
            },
            format!(
                "{} migration gate(s), {} acceptance truth matrix/matrices, and {} shell-derived export bundle(s) keep the cockpit aligned with runtime truth.",
                northstar01.migration_gates.len(),
                northstar01.acceptance_matrices.len(),
                northstar01.export_bundles.len()
            ),
            operator_evidence,
            unique_strings(
                northstar01
                    .migration_gates
                    .iter()
                    .flat_map(|item| item.failure_refs.iter().cloned()),
            ),
        ),
    ];

    let phase_status = remediation_phase_status(&workstreams);
    let mut remaining_blockers = Vec::new();
    if !transitional_paths.is_empty() || !unsupported_paths.is_empty() {
        remaining_blockers.push(
            "Universal shell-first execution is not yet true for every supported live path."
                .to_string(),
        );
    }

    Ok(RemediationPhase01LifecycleClosureView {
        summary: format!(
            "Remediation Phase 01 groups NorthStar 01 and NorthStar 02 into one runtime-closure line. Current posture: {}.",
            phase_status
        ),
        phase_status,
        shell_first_paths,
        transitional_paths,
        unsupported_paths,
        reference_demo_paths,
        northstar01,
        northstar02,
        workstreams,
        remaining_blockers,
        boundary_statement: "Phase 01 can claim unified shell-owned runtime law only when every supported live path is shell-first and persistent shell life is no longer bounded.".to_string(),
        next_phase: "Remediation Phase 02: Service And Ecology Closure".to_string(),
        guardrails: vec![
            "No supported live path may bypass shell-owned lifecycle truth.".to_string(),
            "Persistent shell life must remain auditable and bounded even as it broadens."
                .to_string(),
            "Phase 01 does not yet justify broader service or ecology closure claims."
                .to_string(),
        ],
    })
}

fn required_phase_02_workflows() -> Vec<crate::execution::NativeWorkflowKind> {
    vec![
        crate::execution::NativeWorkflowKind::Build,
        crate::execution::NativeWorkflowKind::Validation,
        crate::execution::NativeWorkflowKind::Packaging,
        crate::execution::NativeWorkflowKind::Review,
        crate::execution::NativeWorkflowKind::Scheduling,
        crate::execution::NativeWorkflowKind::Continuity,
        crate::execution::NativeWorkflowKind::OperationalAttestation,
    ]
}

fn required_phase_02_worker_roles() -> BTreeSet<crate::execution::WorkerRoleKind> {
    [
        crate::execution::WorkerRoleKind::Planner,
        crate::execution::WorkerRoleKind::Builder,
        crate::execution::WorkerRoleKind::Validator,
        crate::execution::WorkerRoleKind::Reviewer,
        crate::execution::WorkerRoleKind::Packager,
        crate::execution::WorkerRoleKind::ContinuityWorker,
    ]
    .into_iter()
    .collect()
}

fn build_remediation_phase_02_service_ecology_closure_view(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
) -> Result<RemediationPhase02ServiceEcologyClosureView, LocalRuntimeError> {
    let northstar03 = build_northstar_03_native_services_view(workspace, records)?;
    let northstar04 = build_northstar_04_worker_ecology_view(workspace, records)?;

    let run_refs = unique_strings(
        northstar03
            .run_refs
            .iter()
            .cloned()
            .chain(northstar04.run_refs.iter().cloned()),
    );
    let service_manifest_refs = unique_strings(
        northstar03
            .manifests
            .iter()
            .map(|item| item.service_manifest_id.clone()),
    );
    let service_closure_refs = unique_strings(
        northstar03
            .closure_dossiers
            .iter()
            .map(|item| item.closure_dossier_id.clone())
            .chain(
                northstar03
                    .workflow_closure_dossiers
                    .iter()
                    .map(|item| item.workflow_dossier_id.clone()),
            ),
    );
    let worker_card_refs = unique_strings(
        northstar04
            .worker_cards
            .iter()
            .map(|item| item.worker_card_id.clone()),
    );
    let ecology_health_refs = unique_strings(
        northstar04
            .health_records
            .iter()
            .map(|item| item.health_record_id.clone()),
    );

    let required_workflows = required_phase_02_workflows();
    let sufficiency_by_kind = northstar03
        .workflow_sufficiency_records
        .iter()
        .filter(|item| {
            item.closure_status == crate::execution::WorkflowClosureStatus::ClosureGrade
                && item.transitional_gap_refs.is_empty()
        })
        .map(|item| (item.workflow_kind, item.workflow_sufficiency_id.clone()))
        .collect::<BTreeMap<_, _>>();
    let dossiers_by_kind = northstar03
        .workflow_closure_dossiers
        .iter()
        .filter(|item| {
            item.closure_status == crate::execution::WorkflowClosureStatus::ClosureGrade
                && item.transitional_gap_refs.is_empty()
        })
        .map(|item| (item.workflow_kind, item.workflow_dossier_id.clone()))
        .collect::<BTreeMap<_, _>>();
    let closure_grade_workflow_refs = required_workflows
        .iter()
        .filter_map(|kind| sufficiency_by_kind.get(kind).cloned())
        .collect::<Vec<_>>();
    let sufficiency_closed = required_workflows
        .iter()
        .all(|kind| sufficiency_by_kind.contains_key(kind));
    let workflow_dossiers_closed = required_workflows
        .iter()
        .all(|kind| dossiers_by_kind.contains_key(kind));
    let service_gaps = unique_strings(
        northstar03
            .workflow_sufficiency_records
            .iter()
            .flat_map(|item| item.transitional_gap_refs.iter().cloned())
            .chain(
                northstar03
                    .workflow_closure_dossiers
                    .iter()
                    .flat_map(|item| item.transitional_gap_refs.iter().cloned()),
            ),
    );

    let required_roles = required_phase_02_worker_roles();
    let observed_roles = northstar04
        .worker_cards
        .iter()
        .map(|item| item.role_kind)
        .collect::<BTreeSet<_>>();
    let health_records_closed = !northstar04.health_records.is_empty()
        && northstar04.health_records.iter().all(|item| {
            !item.load_refs.is_empty()
                && !item.fairness_refs.is_empty()
                && !item.degradation_refs.is_empty()
                && !item.recovery_refs.is_empty()
        });
    let rollback_recovery_present = records.iter().any(|record| {
        record.metadata.scenario_id == "supervisor-background-quarantine-rollback-control-loop"
            && record
                .runtime_state
                .root_task
                .output_refs
                .iter()
                .any(|reference| reference.starts_with(NS04_RECOVERY_RECORD_OUTPUT_PREFIX))
    });
    let ecology_roles_closed = observed_roles == required_roles;

    let workstream_a_closed = sufficiency_closed
        && service_gaps.is_empty()
        && required_workflows.len() == closure_grade_workflow_refs.len();
    let workstream_b_closed = workflow_dossiers_closed
        && service_gaps.is_empty()
        && !northstar03.handles.is_empty()
        && !northstar03.attestations.is_empty();
    let workstream_c_closed = ecology_roles_closed
        && !northstar04.routing_packets.is_empty()
        && !northstar04.work_leases.is_empty()
        && !northstar04.synthesis_dossiers.is_empty()
        && !northstar04.health_records.is_empty()
        && !northstar04.recovery_records.is_empty()
        && health_records_closed
        && rollback_recovery_present;

    let service_workspace =
        if !closure_grade_workflow_refs.is_empty() && !northstar03.attestations.is_empty() {
            Some(crate::execution::ServiceClosureWorkspacePacket {
                service_workspace_id: "remediation-phase-02-service-workspace".to_string(),
                workflow_sufficiency_refs: closure_grade_workflow_refs.clone(),
                workflow_dossier_refs: required_workflows
                    .iter()
                    .filter_map(|kind| dossiers_by_kind.get(kind).cloned())
                    .collect(),
                attestation_refs: northstar03
                    .attestations
                    .iter()
                    .map(|item| item.attestation_id.clone())
                    .collect(),
                transitional_gap_refs: service_gaps.clone(),
                operator_summary_ref: "operator:remediation-phase-02:service-workspace".to_string(),
            })
        } else {
            None
        };
    let ecology_workspace = if !worker_card_refs.is_empty()
        && !northstar04.routing_packets.is_empty()
        && !northstar04.health_records.is_empty()
    {
        Some(crate::execution::EcologyClosureWorkspacePacket {
            ecology_workspace_id: "remediation-phase-02-ecology-workspace".to_string(),
            worker_card_refs: worker_card_refs.clone(),
            ecology_ledger_refs: unique_strings(
                northstar04
                    .ecology_snapshots
                    .iter()
                    .map(|item| item.ecology_snapshot_id.clone())
                    .chain(
                        northstar04
                            .planning_records
                            .iter()
                            .map(|item| item.planning_id.clone()),
                    )
                    .chain(
                        northstar04
                            .work_leases
                            .iter()
                            .map(|item| item.work_lease_id.clone()),
                    )
                    .chain(
                        northstar04
                            .synthesis_dossiers
                            .iter()
                            .map(|item| item.synthesis_id.clone()),
                    )
                    .chain(ecology_health_refs.iter().cloned())
                    .chain(
                        northstar04
                            .recovery_records
                            .iter()
                            .map(|item| item.recovery_id.clone()),
                    ),
            ),
            routing_packet_refs: northstar04
                .routing_packets
                .iter()
                .map(|item| item.routing_packet_id.clone())
                .collect(),
            degradation_refs: unique_strings(
                northstar04
                    .health_records
                    .iter()
                    .flat_map(|item| item.degradation_refs.iter().cloned()),
            ),
            operator_summary_ref: "operator:remediation-phase-02:ecology-workspace".to_string(),
        })
    } else {
        None
    };
    let acceptance_packet = match (&service_workspace, &ecology_workspace) {
        (Some(service_workspace), Some(ecology_workspace))
            if !closure_grade_workflow_refs.is_empty() && !northstar03.attestations.is_empty() =>
        {
            Some(crate::execution::Phase02AcceptancePacket {
                acceptance_packet_id: "remediation-phase-02-acceptance-packet".to_string(),
                workflow_refs: closure_grade_workflow_refs.clone(),
                closure_refs: unique_strings(
                    service_closure_refs
                        .iter()
                        .cloned()
                        .chain([service_workspace.service_workspace_id.clone()]),
                ),
                ecology_refs: unique_strings(
                    northstar04
                        .routing_packets
                        .iter()
                        .map(|item| item.routing_packet_id.clone())
                        .chain(
                            northstar04
                                .recovery_records
                                .iter()
                                .map(|item| item.recovery_id.clone()),
                        )
                        .chain([ecology_workspace.ecology_workspace_id.clone()]),
                ),
                attestation_refs: northstar03
                    .attestations
                    .iter()
                    .map(|item| item.attestation_id.clone())
                    .collect(),
                summary: "Phase 02 acceptance packet binds workflow closure, ecology recovery, and operator workspace truth into one closure-grade review surface."
                    .to_string(),
            })
        }
        _ => None,
    };

    let phase02_store =
        DurableArtifactStore::bootstrap(workspace.remediation_phase_02_store_root())?;
    if let Some(service_workspace) = &service_workspace {
        phase02_store.persist_service_closure_workspace_packet(service_workspace)?;
    }
    if let Some(ecology_workspace) = &ecology_workspace {
        phase02_store.persist_ecology_closure_workspace_packet(ecology_workspace)?;
    }
    if let Some(acceptance_packet) = &acceptance_packet {
        phase02_store.persist_phase02_acceptance_packet(acceptance_packet)?;
    }

    let workstream_d_closed = workstream_a_closed
        && workstream_b_closed
        && workstream_c_closed
        && service_workspace.is_some()
        && ecology_workspace.is_some()
        && acceptance_packet.is_some()
        && acceptance_packet
            .as_ref()
            .zip(service_workspace.as_ref())
            .map(|(acceptance_packet, service_workspace)| {
                acceptance_packet.workflow_refs.iter().all(|reference| {
                    service_workspace
                        .workflow_sufficiency_refs
                        .contains(reference)
                })
            })
            .unwrap_or(false);

    let service_workspace_refs = service_workspace
        .as_ref()
        .map(|packet| vec![packet.service_workspace_id.clone()])
        .unwrap_or_default();
    let ecology_workspace_refs = ecology_workspace
        .as_ref()
        .map(|packet| vec![packet.ecology_workspace_id.clone()])
        .unwrap_or_default();
    let acceptance_packet_refs = acceptance_packet
        .as_ref()
        .map(|packet| vec![packet.acceptance_packet_id.clone()])
        .unwrap_or_default();

    let workstreams = vec![
        remediation_workstream(
            "phase-02-workstream-a",
            "Service Taxonomy and Sufficiency Law",
            if workstream_a_closed {
                "closure_grade"
            } else if !northstar03.workflow_sufficiency_records.is_empty() {
                "live_but_bounded"
            } else {
                "not_yet"
            },
            format!(
                "{} workflow sufficiency record(s) now cover the seven required service workflows.",
                northstar03.workflow_sufficiency_records.len()
            ),
            northstar03
                .workflow_sufficiency_records
                .iter()
                .map(|item| item.workflow_sufficiency_id.clone())
                .collect(),
            if workstream_a_closed {
                Vec::new()
            } else {
                vec!["gap:workflow-sufficiency-not-yet-closure-grade".to_string()]
            },
        ),
        remediation_workstream(
            "phase-02-workstream-b",
            "Workflow Service Closure and Attestation",
            if workstream_b_closed {
                "closure_grade"
            } else if !northstar03.workflow_closure_dossiers.is_empty() {
                "live_but_bounded"
            } else {
                "not_yet"
            },
            format!(
                "{} workflow closure dossier(s) and {} attestation bundle(s) now bind service use to explicit workflow closure law.",
                northstar03.workflow_closure_dossiers.len(),
                northstar03.attestations.len()
            ),
            unique_strings(
                northstar03
                    .attestations
                    .iter()
                    .map(|item| item.attestation_id.clone())
                    .chain(
                        northstar03
                            .workflow_closure_dossiers
                            .iter()
                            .map(|item| item.workflow_dossier_id.clone()),
                    ),
            ),
            if workstream_b_closed {
                Vec::new()
            } else {
                vec!["gap:workflow-closure-dossiers-not-yet-closure-grade".to_string()]
            },
        ),
        remediation_workstream(
            "phase-02-workstream-c",
            "Worker Ecology State, Routing, and Recovery",
            if workstream_c_closed {
                "closure_grade"
            } else if !northstar04.worker_cards.is_empty() {
                "live_but_bounded"
            } else {
                "not_yet"
            },
            format!(
                "{} worker card(s), {} routing packet(s), {} recovery record(s), and {} ecology health record(s) now define the generalized bounded worker ecology.",
                northstar04.worker_cards.len(),
                northstar04.routing_packets.len(),
                northstar04.recovery_records.len(),
                northstar04.health_records.len()
            ),
            unique_strings(
                worker_card_refs
                    .iter()
                    .cloned()
                    .chain(
                        northstar04
                            .routing_packets
                            .iter()
                            .map(|item| item.routing_packet_id.clone()),
                    )
                    .chain(
                        northstar04
                            .recovery_records
                            .iter()
                            .map(|item| item.recovery_id.clone()),
                    )
                    .chain(ecology_health_refs.iter().cloned()),
            ),
            if workstream_c_closed {
                Vec::new()
            } else {
                vec![
                    "gap:ecology-closure-grade-role-coverage-not-yet-proven".to_string(),
                    "gap:rollback-recovery-path-still-insufficient".to_string(),
                ]
            },
        ),
        remediation_workstream(
            "phase-02-workstream-d",
            "Operator Closure Surfaces and Acceptance Discipline",
            if workstream_d_closed {
                "closure_grade"
            } else if !run_refs.is_empty() {
                "live_but_bounded"
            } else {
                "not_yet"
            },
            format!(
                "{} run ref(s), one service workspace packet, one ecology workspace packet, and one Phase 02 acceptance packet now surface the closure evidence to operators.",
                run_refs.len()
            ),
            unique_strings(
                run_refs
                    .iter()
                    .cloned()
                    .chain(service_workspace_refs.iter().cloned())
                    .chain(ecology_workspace_refs.iter().cloned())
                    .chain(acceptance_packet_refs.iter().cloned()),
            ),
            if workstream_d_closed {
                Vec::new()
            } else {
                vec!["gap:closure-grade-phase02-acceptance-packet-not-yet-proven".to_string()]
            },
        ),
    ];

    let phase_status = remediation_phase_status(&workstreams);
    let remaining_blockers = if phase_status == "closure_grade" {
        Vec::new()
    } else {
        let mut blockers = Vec::new();
        if !workstream_a_closed || !workstream_b_closed {
            blockers.push(
                "Native service closure is still missing at least one closure-grade workflow or workflow dossier."
                    .to_string(),
            );
        }
        if !workstream_c_closed {
            blockers.push(
                "Worker ecology is still missing closure-grade role coverage, routing, recovery, or rollback-path evidence."
                    .to_string(),
            );
        }
        if !workstream_d_closed {
            blockers.push(
                "Phase 02 operator closure packets are not yet fully aligned with the closure-grade workflow and ecology evidence."
                    .to_string(),
            );
        }
        blockers
    };

    Ok(RemediationPhase02ServiceEcologyClosureView {
        summary: format!(
            "Remediation Phase 02 groups NorthStar 03 and NorthStar 04 into one service-and-ecology closure line. Current posture: {}.",
            phase_status
        ),
        phase_status,
        run_refs,
        service_manifest_refs,
        service_closure_refs,
        worker_card_refs,
        ecology_health_refs,
        closure_grade_workflow_refs,
        service_workspace_refs,
        ecology_workspace_refs,
        acceptance_packet_refs,
        northstar03,
        northstar04,
        workstreams,
        remaining_blockers,
        boundary_statement: "Phase 02 can claim closure-grade substrate and ecology only when all seven workflows are service-closed and the six-role worker ecology remains healthy, routed, and recoverable under live supported paths.".to_string(),
        next_phase: "Remediation Phase 03: Reproduction And Ecosystem Closure".to_string(),
        guardrails: vec![
            "Service power must remain capability-bounded, workflow-scoped, and attested."
                .to_string(),
            "Ecology breadth must improve traceability rather than hide degradation or recovery."
                .to_string(),
            "Phase 02 closure does not yet justify recurring factory or broader ecosystem closure claims."
                .to_string(),
        ],
    })
}

fn build_remediation_phase_03_reproduction_ecosystem_closure_view(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
) -> Result<RemediationPhase03ReproductionEcosystemClosureView, LocalRuntimeError> {
    let northstar05 = build_northstar_05_factory_programs_view(workspace, records)?;
    let northstar06 = build_northstar_06_ecosystem_view(workspace, records)?;

    let run_refs = unique_strings(
        northstar05
            .run_refs
            .iter()
            .cloned()
            .chain(northstar06.run_refs.iter().cloned()),
    );
    let factory_program_refs = unique_strings(
        northstar05
            .improvement_programs
            .iter()
            .map(|item| item.improvement_program_id.clone()),
    );
    let lineage_health_refs = unique_strings(
        northstar05
            .lineage_health_dossiers
            .iter()
            .map(|item| item.lineage_health_id.clone()),
    );
    let ecosystem_route_refs =
        unique_strings(northstar06.routes.iter().map(|item| item.route_id.clone()));
    let ecosystem_health_refs = unique_strings(
        northstar06
            .health_snapshots
            .iter()
            .map(|item| item.ecosystem_snapshot_id.clone()),
    );
    let rollback_control_run_refs = records
        .iter()
        .filter(|record| {
            record.metadata.scenario_id == "supervisor-background-quarantine-rollback-control-loop"
        })
        .map(|record| format!("run:{}", record.metadata.run_id))
        .collect::<Vec<_>>();
    let recurring_program = northstar05.recurring_factory_programs.iter().find(|item| {
        northstar05
            .closure_grade_program_refs
            .contains(&item.factory_program_id)
    });
    let recurring_budget = recurring_program.and_then(|program| {
        northstar05
            .recursion_budgets
            .iter()
            .find(|item| item.recursion_budget_id == program.budget_ref)
    });
    let recurring_stop_condition = recurring_program.and_then(|program| {
        northstar05
            .stop_conditions
            .iter()
            .find(|item| item.stop_condition_id == program.policy_ref)
            .or_else(|| {
                program.bounded_program_refs.first().and_then(|reference| {
                    northstar05
                        .stop_conditions
                        .iter()
                        .find(|item| item.program_ref == *reference)
                })
            })
    });
    let recurring_budget_history = recurring_program.and_then(|program| {
        northstar05
            .budget_histories
            .iter()
            .find(|item| item.budget_history_id == program.budget_history_ref)
    });
    let recurring_policy_compliance = recurring_program.and_then(|program| {
        northstar05
            .policy_compliance_records
            .iter()
            .find(|item| item.policy_compliance_id == program.policy_compliance_ref)
    });
    let workstream_a_closed = recurring_program
        .zip(recurring_budget)
        .zip(recurring_stop_condition)
        .zip(recurring_budget_history)
        .zip(recurring_policy_compliance)
        .map(
            |((((program, budget), _stop_condition), budget_history), policy_compliance)| {
                program.cycle_refs.len() >= 2
                    && program.cycle_refs.len() <= budget.max_campaigns
                    && program.continuity_window_refs.len() == program.cycle_refs.len()
                    && !program.restart_resume_refs.is_empty()
                    && budget_history
                        .cycle_refs
                        .iter()
                        .all(|reference| program.cycle_refs.contains(reference))
                    && !budget_history.consumption_refs.is_empty()
                    && !budget_history.exhaustion_posture_ref.trim().is_empty()
                    && policy_compliance
                        .cycle_refs
                        .iter()
                        .all(|reference| program.cycle_refs.contains(reference))
                    && !policy_compliance.compliance_refs.is_empty()
                    && !policy_compliance.variance_refs.is_empty()
                    && program.cycle_refs.iter().all(|reference| {
                        northstar05
                            .cycle_dossiers
                            .iter()
                            .find(|item| item.cycle_dossier_id == *reference)
                            .map(|item| {
                                !item.proving_refs.is_empty()
                                    && !item.observation_refs.is_empty()
                                    && !item.rollback_posture_refs.is_empty()
                                    && !item.continuity_ref.trim().is_empty()
                                    && program
                                        .continuity_window_refs
                                        .contains(&item.continuity_ref)
                                    && !item.disposition_ref.trim().is_empty()
                                    && northstar05
                                        .adoption_windows
                                        .iter()
                                        .find(|window| {
                                            window.adoption_window_id == item.adoption_window_ref
                                        })
                                        .map(|window| !window.rollback_refs.is_empty())
                                        .unwrap_or(false)
                            })
                            .unwrap_or(false)
                    })
            },
        )
        .unwrap_or(false);
    let workstream_b_closed = recurring_program
        .map(|program| {
            let ledger = northstar05
                .lineage_ledgers
                .iter()
                .find(|item| item.program_ref == program.factory_program_id);
            let regression = ledger.and_then(|entry| {
                northstar05
                    .regression_packets
                    .iter()
                    .find(|item| item.lineage_ledger_ref == entry.lineage_ledger_id)
            });
            let dossier = northstar05
                .longitudinal_lineage_dossiers
                .iter()
                .find(|item| {
                    item.program_ref == program.factory_program_id
                        && ledger
                            .map(|entry| item.health_ref == entry.lineage_ledger_id)
                            .unwrap_or(false)
                });
            let budget_history = northstar05
                .budget_histories
                .iter()
                .find(|item| item.budget_history_id == program.budget_history_ref);
            let policy_compliance = northstar05
                .policy_compliance_records
                .iter()
                .find(|item| item.policy_compliance_id == program.policy_compliance_ref);
            ledger
                .zip(regression)
                .zip(dossier)
                .zip(budget_history)
                .zip(policy_compliance)
                .map(
                    |((((ledger, regression), dossier), budget_history), policy_compliance)| {
                        program
                            .cycle_refs
                            .iter()
                            .all(|reference| dossier.cycle_refs.contains(reference))
                            && program
                                .continuity_window_refs
                                .iter()
                                .all(|reference| ledger.continuity_refs.contains(reference))
                            && program
                                .continuity_window_refs
                                .iter()
                                .all(|reference| dossier.continuity_window_refs.contains(reference))
                            && !ledger.generation_refs.is_empty()
                            && !ledger.cycle_result_refs.is_empty()
                            && !ledger.continuity_refs.is_empty()
                            && !ledger.regression_refs.is_empty()
                            && !ledger.rollback_refs.is_empty()
                            && !regression.threshold_refs.is_empty()
                            && !regression.trigger_refs.is_empty()
                            && !regression.mitigation_refs.is_empty()
                            && dossier
                                .regression_packet_refs
                                .contains(&regression.regression_packet_id)
                            && dossier
                                .stability_refs
                                .contains(&budget_history.budget_history_id)
                            && dossier
                                .stability_refs
                                .contains(&policy_compliance.policy_compliance_id)
                    },
                )
                .unwrap_or(false)
        })
        .unwrap_or(false);

    let closure_grade_ecosystem_ref = northstar06.closure_grade_ecosystem_refs.first().cloned();
    let selected_health_ledger = closure_grade_ecosystem_ref.as_ref().and_then(|reference| {
        northstar06
            .health_ledgers
            .iter()
            .find(|item| item.ecosystem_health_id == *reference)
    });
    let selected_route_ledgers = selected_health_ledger
        .map(|ledger| {
            northstar06
                .route_ledgers
                .iter()
                .filter(|item| ledger.route_refs.contains(&item.exchange_route_ledger_id))
                .cloned()
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let selected_route_history_records = selected_route_ledgers
        .iter()
        .flat_map(|ledger| ledger.route_history_refs.iter())
        .filter_map(|reference| {
            northstar06
                .route_history_records
                .iter()
                .find(|item| item.route_history_id == *reference)
                .cloned()
        })
        .collect::<Vec<_>>();
    let selected_continuity_windows = selected_route_ledgers
        .iter()
        .flat_map(|ledger| ledger.continuity_window_refs.iter())
        .filter_map(|reference| {
            northstar06
                .continuity_windows
                .iter()
                .find(|item| item.continuity_window_id == *reference)
                .cloned()
        })
        .collect::<Vec<_>>();
    let selected_rollback_symmetry_records = selected_health_ledger
        .map(|ledger| {
            northstar06
                .rollback_symmetry_records
                .iter()
                .filter(|item| {
                    ledger
                        .rollback_symmetry_refs
                        .contains(&item.rollback_symmetry_id)
                })
                .cloned()
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let selected_compatibility_persistence_records = selected_health_ledger
        .map(|ledger| {
            northstar06
                .compatibility_persistence_records
                .iter()
                .filter(|item| {
                    ledger
                        .compatibility_persistence_refs
                        .contains(&item.compatibility_persistence_id)
                })
                .cloned()
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let workstream_c_closed = selected_health_ledger
        .map(|health_ledger| {
            northstar06.admission_profiles.len() >= 2
                && selected_route_ledgers
                    .iter()
                    .any(|ledger| ledger.route_history_refs.len() >= 2)
                && !selected_continuity_windows.is_empty()
                && !selected_rollback_symmetry_records.is_empty()
                && !selected_compatibility_persistence_records.is_empty()
                && selected_route_ledgers.iter().all(|ledger| {
                    !ledger.adoption_refs.is_empty()
                        && !ledger.quarantine_refs.is_empty()
                        && !ledger.rollback_refs.is_empty()
                        && !ledger.route_history_refs.is_empty()
                        && !ledger.continuity_window_refs.is_empty()
                })
                && selected_route_history_records.iter().all(|record| {
                    !record.adoption_ref.trim().is_empty()
                        && !record.quarantine_ref.trim().is_empty()
                        && !record.rollback_ref.trim().is_empty()
                })
                && !health_ledger.continuity_refs.is_empty()
                && !health_ledger.failure_refs.is_empty()
                && !health_ledger.recovery_refs.is_empty()
                && !health_ledger.rollback_symmetry_refs.is_empty()
                && !health_ledger.compatibility_persistence_refs.is_empty()
                && health_ledger
                    .rollback_symmetry_refs
                    .iter()
                    .all(|reference| {
                        selected_rollback_symmetry_records
                            .iter()
                            .any(|item| item.rollback_symmetry_id == *reference)
                    })
                && health_ledger
                    .compatibility_persistence_refs
                    .iter()
                    .all(|reference| {
                        selected_compatibility_persistence_records
                            .iter()
                            .any(|item| item.compatibility_persistence_id == *reference)
                    })
                && rollback_control_run_refs
                    .iter()
                    .any(|reference| health_ledger.recovery_refs.contains(reference))
        })
        .unwrap_or(false);

    let factory_workspace = if workstream_a_closed && workstream_b_closed {
        recurring_program.map(
            |program| crate::execution::RecurringFactoryWorkspacePacket {
                factory_workspace_id: "remediation-phase-03-factory-workspace".to_string(),
                program_ref: program.factory_program_id.clone(),
                cycle_refs: program.cycle_refs.clone(),
                lineage_refs: unique_strings(
                    northstar05
                        .lineage_ledgers
                        .iter()
                        .filter(|item| item.program_ref == program.factory_program_id)
                        .map(|item| item.lineage_ledger_id.clone())
                        .chain(
                            northstar05
                                .regression_packets
                                .iter()
                                .map(|item| item.regression_packet_id.clone()),
                        )
                        .chain(
                            northstar05
                                .longitudinal_lineage_dossiers
                                .iter()
                                .filter(|item| item.program_ref == program.factory_program_id)
                                .map(|item| item.lineage_dossier_id.clone()),
                        ),
                ),
                budget_ref: program.budget_ref.clone(),
                continuity_refs: unique_strings(
                    program
                        .continuity_window_refs
                        .iter()
                        .cloned()
                        .chain(std::iter::once(program.budget_history_ref.clone()))
                        .chain(std::iter::once(program.policy_compliance_ref.clone())),
                ),
                stability_refs: vec![
                    program.budget_history_ref.clone(),
                    program.policy_compliance_ref.clone(),
                ],
                claim_boundary_ref: "claim:phase03:bounded-recurring-factory-program".to_string(),
            },
        )
    } else {
        None
    };
    let ecosystem_workspace = if workstream_c_closed {
        selected_health_ledger.map(|health_ledger| {
            crate::execution::EcosystemClosureWorkspacePacket {
                ecosystem_workspace_id: "remediation-phase-03-ecosystem-workspace".to_string(),
                admission_refs: northstar06
                    .admission_profiles
                    .iter()
                    .map(|item| item.admission_profile_id.clone())
                    .collect(),
                route_refs: selected_route_ledgers
                    .iter()
                    .map(|item| item.exchange_route_ledger_id.clone())
                    .collect(),
                health_refs: vec![health_ledger.ecosystem_health_id.clone()],
                rollback_refs: unique_strings(
                    selected_route_ledgers
                        .iter()
                        .flat_map(|route| route.rollback_refs.iter().cloned()),
                ),
                continuity_refs: selected_continuity_windows
                    .iter()
                    .map(|item| item.continuity_window_id.clone())
                    .collect(),
                stability_refs: unique_strings(
                    selected_rollback_symmetry_records
                        .iter()
                        .map(|item| item.rollback_symmetry_id.clone())
                        .chain(
                            selected_compatibility_persistence_records
                                .iter()
                                .map(|item| item.compatibility_persistence_id.clone()),
                        ),
                ),
                claim_boundary_ref: "claim:phase03:bounded-ecosystem".to_string(),
            }
        })
    } else {
        None
    };
    let closure_review_packet = match (&factory_workspace, &ecosystem_workspace) {
        (Some(factory_workspace), Some(ecosystem_workspace))
            if workstream_a_closed && workstream_b_closed && workstream_c_closed =>
        {
            let acceptable_caveat_refs = vec![
                "risk:phase03:recurring-program-publication-caveat".to_string(),
                "risk:phase03:bounded-ecosystem-publication-caveat".to_string(),
            ];
            let blocking_risk_refs = Vec::new();
            Some(crate::execution::Phase03ClosureReviewPacket {
                closure_review_packet_id: "remediation-phase-03-closure-review-packet".to_string(),
                factory_program_refs: vec![factory_workspace.program_ref.clone()],
                lineage_refs: factory_workspace.lineage_refs.clone(),
                continuity_refs: factory_workspace.continuity_refs.clone(),
                ecosystem_refs: unique_strings(
                    ecosystem_workspace
                        .route_refs
                        .iter()
                        .cloned()
                        .chain(ecosystem_workspace.health_refs.iter().cloned()),
                )
                .into_iter()
                .chain(ecosystem_workspace.continuity_refs.iter().cloned())
                .chain(ecosystem_workspace.stability_refs.iter().cloned())
                .collect(),
                acceptable_caveat_refs: acceptable_caveat_refs.clone(),
                blocking_risk_refs: blocking_risk_refs.clone(),
                risk_refs: unique_strings(
                    acceptable_caveat_refs
                        .into_iter()
                        .chain(blocking_risk_refs.into_iter()),
                ),
                summary: "Phase 03 closure review binds closure-grade recurring-factory and bounded-ecosystem evidence into one packet with explicit publication caveats, while final-claim adjudication remains deferred to Phase 04."
                    .to_string(),
            })
        }
        _ => None,
    };
    let phase03_store =
        DurableArtifactStore::bootstrap(workspace.remediation_phase_03_store_root())?;
    if let Some(packet) = &factory_workspace {
        phase03_store.persist_recurring_factory_workspace_packet(packet)?;
    }
    if let Some(packet) = &ecosystem_workspace {
        phase03_store.persist_ecosystem_closure_workspace_packet(packet)?;
    }
    if let Some(packet) = &closure_review_packet {
        phase03_store.persist_phase03_closure_review_packet(packet)?;
    }

    let factory_workspace_refs = factory_workspace
        .as_ref()
        .map(|packet| vec![packet.factory_workspace_id.clone()])
        .unwrap_or_default();
    let ecosystem_workspace_refs = ecosystem_workspace
        .as_ref()
        .map(|packet| vec![packet.ecosystem_workspace_id.clone()])
        .unwrap_or_default();
    let closure_review_packet_refs = closure_review_packet
        .as_ref()
        .map(|packet| vec![packet.closure_review_packet_id.clone()])
        .unwrap_or_default();
    let acceptable_caveat_refs = closure_review_packet
        .as_ref()
        .map(|packet| packet.acceptable_caveat_refs.clone())
        .unwrap_or_default();
    let blocking_claim_risk_refs = closure_review_packet
        .as_ref()
        .map(|packet| packet.blocking_risk_refs.clone())
        .unwrap_or_default();
    let workstream_d_closed = workstream_a_closed
        && workstream_b_closed
        && workstream_c_closed
        && factory_workspace
            .as_ref()
            .zip(ecosystem_workspace.as_ref())
            .zip(closure_review_packet.as_ref())
            .map(
                |((factory_workspace, ecosystem_workspace), review_packet)| {
                    review_packet
                        .factory_program_refs
                        .contains(&factory_workspace.program_ref)
                        && review_packet
                            .continuity_refs
                            .iter()
                            .all(|reference| factory_workspace.continuity_refs.contains(reference))
                        && ecosystem_workspace
                            .route_refs
                            .iter()
                            .all(|reference| review_packet.ecosystem_refs.contains(reference))
                        && ecosystem_workspace
                            .health_refs
                            .iter()
                            .all(|reference| review_packet.ecosystem_refs.contains(reference))
                        && ecosystem_workspace
                            .continuity_refs
                            .iter()
                            .all(|reference| review_packet.ecosystem_refs.contains(reference))
                        && ecosystem_workspace
                            .stability_refs
                            .iter()
                            .all(|reference| review_packet.ecosystem_refs.contains(reference))
                        && !ecosystem_workspace.rollback_refs.is_empty()
                        && !ecosystem_workspace.continuity_refs.is_empty()
                        && !ecosystem_workspace.stability_refs.is_empty()
                        && !review_packet.acceptable_caveat_refs.is_empty()
                        && review_packet.blocking_risk_refs.is_empty()
                        && review_packet.risk_refs
                            == unique_strings(
                                review_packet
                                    .acceptable_caveat_refs
                                    .iter()
                                    .cloned()
                                    .chain(review_packet.blocking_risk_refs.iter().cloned()),
                            )
                },
            )
            .unwrap_or(false);

    let workstreams = vec![
        remediation_workstream(
            "phase-03-workstream-a",
            "Recurring Factory Programs and Recursion Budgets",
            if workstream_a_closed {
                "closure_grade"
            } else if !northstar05.recurring_factory_programs.is_empty() {
                "live_but_bounded"
            } else {
                "not_yet"
            },
            format!(
                "{} recurring program(s), {} cycle dossier(s), and {} recursion budget(s) now define bounded recurring factory work.",
                northstar05.recurring_factory_programs.len(),
                northstar05.cycle_dossiers.len(),
                northstar05.recursion_budgets.len()
            ),
            unique_strings(
                northstar05
                    .closure_grade_program_refs
                    .iter()
                    .cloned()
                    .chain(
                        northstar05
                            .cycle_dossiers
                            .iter()
                            .map(|item| item.cycle_dossier_id.clone()),
                    )
                    .chain(
                        northstar05
                            .recursion_budgets
                            .iter()
                            .map(|item| item.recursion_budget_id.clone()),
                    ),
            ),
            if workstream_a_closed {
                Vec::new()
            } else {
                vec![
                    "gap:recurring-factory-program-not-yet-closure-grade".to_string(),
                    "gap:recursion-budget-or-stop-condition-linkage-missing".to_string(),
                ]
            },
        ),
        remediation_workstream(
            "phase-03-workstream-b",
            "Longitudinal Lineage Health and Regression Review",
            if workstream_b_closed {
                "closure_grade"
            } else if !northstar05.lineage_ledgers.is_empty() {
                "live_but_bounded"
            } else {
                "not_yet"
            },
            format!(
                "{} lineage ledger(s), {} regression packet(s), and {} longitudinal dossier(s) now keep recurring factory health reviewable.",
                northstar05.lineage_ledgers.len(),
                northstar05.regression_packets.len(),
                northstar05.longitudinal_lineage_dossiers.len()
            ),
            unique_strings(
                northstar05
                    .lineage_ledgers
                    .iter()
                    .map(|item| item.lineage_ledger_id.clone())
                    .chain(
                        northstar05
                            .regression_packets
                            .iter()
                            .map(|item| item.regression_packet_id.clone()),
                    )
                    .chain(
                        northstar05
                            .longitudinal_lineage_dossiers
                            .iter()
                            .map(|item| item.lineage_dossier_id.clone()),
                    ),
            ),
            if workstream_b_closed {
                Vec::new()
            } else {
                vec!["gap:longitudinal-lineage-review-not-yet-closure-grade".to_string()]
            },
        ),
        remediation_workstream(
            "phase-03-workstream-c",
            "Bounded Ecosystem Admissions, Exchange, and Rollback",
            if workstream_c_closed {
                "closure_grade"
            } else if !northstar06.health_ledgers.is_empty() {
                "live_but_bounded"
            } else {
                "not_yet"
            },
            format!(
                "{} admission profile(s), {} route ledger(s), and {} ecosystem health ledger(s) now define bounded ecosystem law.",
                northstar06.admission_profiles.len(),
                northstar06.route_ledgers.len(),
                northstar06.health_ledgers.len()
            ),
            unique_strings(
                northstar06
                    .admission_profiles
                    .iter()
                    .map(|item| item.admission_profile_id.clone())
                    .chain(
                        northstar06
                            .route_ledgers
                            .iter()
                            .map(|item| item.exchange_route_ledger_id.clone()),
                    )
                    .chain(
                        northstar06
                            .health_ledgers
                            .iter()
                            .map(|item| item.ecosystem_health_id.clone()),
                    ),
            ),
            if workstream_c_closed {
                Vec::new()
            } else {
                vec![
                    "gap:bounded-ecosystem-ledger-not-yet-closure-grade".to_string(),
                    "gap:rollback-symmetry-still-insufficient".to_string(),
                ]
            },
        ),
        remediation_workstream(
            "phase-03-workstream-d",
            "Ecosystem Operator Closure and Claim Discipline",
            if workstream_d_closed {
                "closure_grade"
            } else if !run_refs.is_empty() {
                "live_but_bounded"
            } else {
                "not_yet"
            },
            format!(
                "{} run ref(s), {} workspace packet(s), and {} closure review packet(s) now surface recurring factory and ecosystem closure to operators.",
                run_refs.len(),
                factory_workspace_refs.len() + ecosystem_workspace_refs.len(),
                closure_review_packet_refs.len()
            ),
            unique_strings(
                run_refs
                    .iter()
                    .cloned()
                    .chain(factory_workspace_refs.iter().cloned())
                    .chain(ecosystem_workspace_refs.iter().cloned())
                    .chain(closure_review_packet_refs.iter().cloned()),
            ),
            if workstream_d_closed {
                Vec::new()
            } else {
                vec!["gap:phase03-closure-review-packet-not-yet-aligned".to_string()]
            },
        ),
    ];

    let phase_status = remediation_phase_status(&workstreams);
    let remaining_blockers = if phase_status == "closure_grade" {
        Vec::new()
    } else {
        let mut blockers = Vec::new();
        if !workstream_a_closed || !workstream_b_closed {
            blockers.push(
                "Recurring factory programs are still missing closure-grade cycle, budget, or lineage-review linkage."
                    .to_string(),
            );
        }
        if !workstream_c_closed {
            blockers.push(
                "The bounded ecosystem is still missing closure-grade admission, route, rollback, or health-ledger coverage."
                    .to_string(),
            );
        }
        if !workstream_d_closed {
            blockers.push(
                "Phase 03 workspace and closure-review packets are not yet fully aligned with the closure-grade recurring factory and ecosystem evidence."
                    .to_string(),
            );
        }
        blockers
    };

    Ok(RemediationPhase03ReproductionEcosystemClosureView {
        summary: format!(
            "Remediation Phase 03 groups NorthStar 05 and NorthStar 06 into one recurring-factory and bounded-ecosystem closure line. Current posture: {}.",
            phase_status
        ),
        phase_status,
        run_refs,
        factory_program_refs,
        lineage_health_refs,
        ecosystem_route_refs,
        ecosystem_health_refs,
        closure_grade_program_refs: northstar05.closure_grade_program_refs.clone(),
        closure_grade_ecosystem_refs: northstar06.closure_grade_ecosystem_refs.clone(),
        acceptable_caveat_refs,
        blocking_claim_risk_refs,
        factory_workspace_refs,
        ecosystem_workspace_refs,
        closure_review_packet_refs,
        northstar05,
        northstar06,
        workstreams,
        remaining_blockers,
        boundary_statement: "Phase 03 can claim recursive-factory and bounded-ecosystem closure only when repeated factory improvement and repeated bounded ecosystem operation are normal governed practice under durable lineage, rollback, and operator review law.".to_string(),
        next_phase: "Remediation Phase 04: Final Closure Re-Review".to_string(),
        guardrails: vec![
            "Recursive improvement must remain budgeted, reviewable, and reversible."
                .to_string(),
            "Bounded ecosystem exchange must remain packet-first, quarantine-capable, and rollback-safe.".to_string(),
            "Phase 03 still stops short of a positive NorthStar claim until Phase 04 refreshes the closure review."
                .to_string(),
        ],
    })
}

#[derive(Clone, Debug)]
struct Phase04RereviewBundle {
    criteria: Vec<crate::execution::ClosureCriterionRecord>,
    criteria_matrix: crate::execution::ClosureCriteriaMatrix,
    evidence_inventory: crate::execution::EvidenceInventoryPacket,
    adversarial_review: crate::execution::AdversarialReviewRecord,
    residual_risks: Vec<crate::execution::ResidualRiskRecord>,
    closure_dossier: crate::execution::ClosureDossier,
    claim_boundary: crate::execution::ClaimBoundaryReviewPacket,
    publication_policy: crate::execution::PublicationPolicyRecord,
    decision: crate::execution::ClosureDecisionRecord,
}

fn build_phase04_rereview_bundle(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
) -> Result<Phase04RereviewBundle, LocalRuntimeError> {
    let precursor = build_precursor_northstar_07_closure_review_view(workspace, records)?;
    let phase01 = build_remediation_phase_01_lifecycle_closure_view(workspace, records)?;
    let phase02 = build_remediation_phase_02_service_ecology_closure_view(workspace, records)?;
    let phase03 =
        build_remediation_phase_03_reproduction_ecosystem_closure_view(workspace, records)?;
    let phase03_store =
        DurableArtifactStore::bootstrap(workspace.remediation_phase_03_store_root())?;
    let phase03_closure_packet = phase03_store
        .load_phase03_closure_review_packet("remediation-phase-03-closure-review-packet")
        .ok();

    let precursor_criterion = |criterion_id: &str| -> Result<
        crate::execution::ClosureCriterionRecord,
        LocalRuntimeError,
    > {
        precursor
            .criteria
            .iter()
            .find(|item| item.criterion_id == criterion_id)
            .cloned()
            .ok_or_else(|| {
                LocalRuntimeError::Storage(format!(
                    "missing precursor northstar 07 criterion: {criterion_id}"
                ))
            })
    };

    let universal_shell = precursor_criterion("northstar-07-criterion-universal-shell")?;
    let persistent_shell = precursor_criterion("northstar-07-criterion-persistent-shell")?;
    let native_services = precursor_criterion("northstar-07-criterion-native-services")?;
    let worker_ecology = precursor_criterion("northstar-07-criterion-worker-ecology")?;
    let factory_programs = precursor_criterion("northstar-07-criterion-factory-programs")?;
    let ecosystem = precursor_criterion("northstar-07-criterion-ecosystem")?;
    let precursor_final_claim = precursor_criterion("northstar-07-criterion-final-claim")?;

    let phase01_refs = unique_strings(
        std::iter::once("api:/api/remediation/phase-01/lifecycle-closure".to_string())
            .chain(
                phase01
                    .workstreams
                    .iter()
                    .map(|item| item.workstream_id.clone()),
            )
            .chain(phase01.shell_first_paths.iter().cloned()),
    );
    let phase02_refs = unique_strings(
        std::iter::once("api:/api/remediation/phase-02/service-ecology-closure".to_string())
            .chain(
                phase02
                    .workstreams
                    .iter()
                    .map(|item| item.workstream_id.clone()),
            )
            .chain(phase02.closure_grade_workflow_refs.iter().cloned())
            .chain(phase02.service_workspace_refs.iter().cloned())
            .chain(phase02.ecology_workspace_refs.iter().cloned())
            .chain(phase02.acceptance_packet_refs.iter().cloned()),
    );
    let phase03_refs = unique_strings(
        std::iter::once("api:/api/remediation/phase-03/reproduction-ecosystem-closure".to_string())
            .chain(
                phase03
                    .workstreams
                    .iter()
                    .map(|item| item.workstream_id.clone()),
            )
            .chain(phase03.closure_grade_program_refs.iter().cloned())
            .chain(phase03.closure_grade_ecosystem_refs.iter().cloned())
            .chain(phase03.factory_workspace_refs.iter().cloned())
            .chain(phase03.ecosystem_workspace_refs.iter().cloned())
            .chain(phase03.closure_review_packet_refs.iter().cloned()),
    );

    let phase03_packet_risks = phase03_closure_packet
        .as_ref()
        .map(|packet| packet.risk_refs.clone())
        .unwrap_or_default();
    let phase03_acceptable_caveat_refs = phase03_closure_packet
        .as_ref()
        .map(|packet| packet.acceptable_caveat_refs.clone())
        .unwrap_or_default();
    let phase03_blocking_risk_refs = phase03_closure_packet
        .as_ref()
        .map(|packet| packet.blocking_risk_refs.clone())
        .unwrap_or_default();
    let (phase03_claim_assessment, final_claim_gap_refs) = assess_phase03_claim_posture(
        &phase01.phase_status,
        &phase02.phase_status,
        &phase03.phase_status,
        phase03_closure_packet.as_ref(),
    );

    let criteria = vec![
        crate::execution::ClosureCriterionRecord {
            criterion_id: universal_shell.criterion_id.clone(),
            title: universal_shell.title.clone(),
            status: universal_shell.status,
            evidence_refs: universal_shell.evidence_refs.clone(),
            phase_evidence_refs: phase01_refs.clone(),
            delta_crosswalk_refs: vec!["delta:universal-shell-first-execution".to_string()],
            gap_refs: universal_shell.gap_refs.clone(),
            summary: format!(
                "Phase 04 rereview reconfirmed precursor shell-universality status: {}",
                universal_shell.summary
            ),
        },
        crate::execution::ClosureCriterionRecord {
            criterion_id: persistent_shell.criterion_id.clone(),
            title: persistent_shell.title.clone(),
            status: persistent_shell.status,
            evidence_refs: persistent_shell.evidence_refs.clone(),
            phase_evidence_refs: phase01_refs.clone(),
            delta_crosswalk_refs: vec!["delta:persistent-operational-shell-services".to_string()],
            gap_refs: persistent_shell.gap_refs.clone(),
            summary: format!(
                "Phase 04 rereview reconfirmed precursor persistent-shell status: {}",
                persistent_shell.summary
            ),
        },
        crate::execution::ClosureCriterionRecord {
            criterion_id: native_services.criterion_id.clone(),
            title: native_services.title.clone(),
            status: native_services.status,
            evidence_refs: unique_strings(
                native_services
                    .evidence_refs
                    .iter()
                    .cloned()
                    .chain(phase02.closure_grade_workflow_refs.iter().cloned()),
            ),
            phase_evidence_refs: phase02_refs.clone(),
            delta_crosswalk_refs: vec!["delta:broader-native-services".to_string()],
            gap_refs: native_services.gap_refs.clone(),
            summary: "Phase 04 rereview refreshed broader native services against closure-grade Phase 02 workflow and workspace evidence."
                .to_string(),
        },
        crate::execution::ClosureCriterionRecord {
            criterion_id: worker_ecology.criterion_id.clone(),
            title: worker_ecology.title.clone(),
            status: worker_ecology.status,
            evidence_refs: unique_strings(
                worker_ecology
                    .evidence_refs
                    .iter()
                    .cloned()
                    .chain(phase02.worker_card_refs.iter().cloned()),
            ),
            phase_evidence_refs: phase02_refs.clone(),
            delta_crosswalk_refs: vec![
                "delta:generalized-orchestration-and-worker-ecology".to_string()
            ],
            gap_refs: worker_ecology.gap_refs.clone(),
            summary: "Phase 04 rereview refreshed worker ecology against closure-grade Phase 02 routing, recovery, and workspace evidence."
                .to_string(),
        },
        crate::execution::ClosureCriterionRecord {
            criterion_id: factory_programs.criterion_id.clone(),
            title: factory_programs.title.clone(),
            status: factory_programs.status,
            evidence_refs: unique_strings(
                factory_programs
                    .evidence_refs
                    .iter()
                    .cloned()
                    .chain(phase03.closure_grade_program_refs.iter().cloned()),
            ),
            phase_evidence_refs: phase03_refs.clone(),
            delta_crosswalk_refs: vec!["delta:generalized-later-factory-creation".to_string()],
            gap_refs: factory_programs.gap_refs.clone(),
            summary: "Phase 04 rereview refreshed recurring factory programs against closure-grade Phase 03 recurring-program, lineage, and workspace evidence."
                .to_string(),
        },
        crate::execution::ClosureCriterionRecord {
            criterion_id: ecosystem.criterion_id.clone(),
            title: ecosystem.title.clone(),
            status: ecosystem.status,
            evidence_refs: unique_strings(
                ecosystem
                    .evidence_refs
                    .iter()
                    .cloned()
                    .chain(phase03.closure_grade_ecosystem_refs.iter().cloned()),
            ),
            phase_evidence_refs: phase03_refs.clone(),
            delta_crosswalk_refs: vec!["delta:bounded-multi-factory-ecosystem".to_string()],
            gap_refs: ecosystem.gap_refs.clone(),
            summary: "Phase 04 rereview refreshed bounded ecosystem closure against repeated admission, route-ledger, recovery, and workspace evidence."
                .to_string(),
        },
        crate::execution::ClosureCriterionRecord {
            criterion_id: precursor_final_claim.criterion_id.clone(),
            title: "Historical Phase 04 record-completeness boundary".to_string(),
            status: match phase03_claim_assessment {
                Phase03ClaimAssessment::Blocked => {
                    crate::execution::ClosureCriterionStatus::Failed
                }
                Phase03ClaimAssessment::PositiveWithCaveats => {
                    crate::execution::ClosureCriterionStatus::Passed
                }
            },
            evidence_refs: unique_strings(
                precursor_final_claim
                    .evidence_refs
                    .iter()
                    .cloned()
                    .chain(phase01_refs.iter().cloned())
                    .chain(phase02_refs.iter().cloned())
                    .chain(phase03_refs.iter().cloned()),
            ),
            phase_evidence_refs: unique_strings(
                phase01_refs
                    .iter()
                    .cloned()
                    .chain(phase02_refs.iter().cloned())
                    .chain(phase03_refs.iter().cloned()),
            ),
            delta_crosswalk_refs: vec![
                "delta:historical-phase04-record-completeness-only".to_string(),
                "delta:self-sustaining-wasm-biotic-world-remains-unauthorized".to_string(),
            ],
            gap_refs: match phase03_claim_assessment {
                Phase03ClaimAssessment::Blocked => final_claim_gap_refs.clone(),
                Phase03ClaimAssessment::PositiveWithCaveats => Vec::new(),
            },
            summary: match phase03_claim_assessment {
                Phase03ClaimAssessment::Blocked => {
                    "Phase 04 rereview is implemented, but the refreshed evidence still lacks the closure-grade phase posture or packet discipline required for a positive bounded/local-first NorthStar closure."
                        .to_string()
                }
                Phase03ClaimAssessment::PositiveWithCaveats => {
                    "Phase 04 rereview found its historical record-completeness criteria satisfied. That result is lineage only and does not decide the current operational North Star."
                        .to_string()
                }
            },
        },
    ];

    let criteria_matrix = crate::execution::ClosureCriteriaMatrix {
        criteria_matrix_id: "remediation-phase-04-criteria-matrix".to_string(),
        criterion_refs: criteria
            .iter()
            .map(|criterion| criterion.criterion_id.clone())
            .collect(),
        status: aggregate_closure_criterion_status(&criteria),
        evidence_refs: unique_strings(
            criteria
                .iter()
                .flat_map(|criterion| criterion.evidence_refs.iter().cloned()),
        ),
        phase_evidence_refs: unique_strings(
            criteria
                .iter()
                .flat_map(|criterion| criterion.phase_evidence_refs.iter().cloned()),
        ),
        delta_crosswalk_refs: unique_strings(
            criteria
                .iter()
                .flat_map(|criterion| criterion.delta_crosswalk_refs.iter().cloned()),
        ),
        gap_refs: unique_strings(
            criteria
                .iter()
                .flat_map(|criterion| criterion.gap_refs.iter().cloned()),
        ),
        review_status: "historical_record_completeness".to_string(),
    };

    let residual_risks = vec![
        crate::execution::ResidualRiskRecord {
            risk_record_id: "remediation-phase-04-risk-shell-universality".to_string(),
            risk_class: crate::execution::ResidualRiskClass::ShellUniversality,
            supporting_refs: criteria[0].evidence_refs.clone(),
            severity: if criteria[0].status == crate::execution::ClosureCriterionStatus::Passed {
                crate::execution::RiskSeverity::Low
            } else {
                crate::execution::RiskSeverity::Blocking
            },
            closure_effect: if criteria[0].status == crate::execution::ClosureCriterionStatus::Passed {
                crate::execution::ClosureEffect::Acceptable
            } else {
                crate::execution::ClosureEffect::BlocksClosure
            },
            summary: "Phase 04 rereview keeps shell universality evidence explicit and decision-bearing."
                .to_string(),
        },
        crate::execution::ResidualRiskRecord {
            risk_record_id: "remediation-phase-04-risk-persistent-shell".to_string(),
            risk_class: crate::execution::ResidualRiskClass::Autonomy,
            supporting_refs: criteria[1].evidence_refs.clone(),
            severity: if criteria[1].status == crate::execution::ClosureCriterionStatus::Passed {
                crate::execution::RiskSeverity::Low
            } else {
                crate::execution::RiskSeverity::Blocking
            },
            closure_effect: if criteria[1].status == crate::execution::ClosureCriterionStatus::Passed {
                crate::execution::ClosureEffect::Acceptable
            } else {
                crate::execution::ClosureEffect::BlocksClosure
            },
            summary: "Persistent shell lifecycle, expiry, escalation, recovery, and rollback remain explicit in the refreshed review."
                .to_string(),
        },
        crate::execution::ResidualRiskRecord {
            risk_record_id: "remediation-phase-04-risk-native-services".to_string(),
            risk_class: crate::execution::ResidualRiskClass::ServiceClosure,
            supporting_refs: criteria[2].evidence_refs.clone(),
            severity: if phase02.phase_status == "closure_grade" {
                crate::execution::RiskSeverity::Low
            } else {
                crate::execution::RiskSeverity::Blocking
            },
            closure_effect: if phase02.phase_status == "closure_grade" {
                crate::execution::ClosureEffect::Acceptable
            } else {
                crate::execution::ClosureEffect::BlocksClosure
            },
            summary: "The rereview treats native services as passed only because closure-grade workflow and acceptance packets exist."
                .to_string(),
        },
        crate::execution::ResidualRiskRecord {
            risk_record_id: "remediation-phase-04-risk-worker-ecology".to_string(),
            risk_class: crate::execution::ResidualRiskClass::Autonomy,
            supporting_refs: criteria[3].evidence_refs.clone(),
            severity: if phase02.phase_status == "closure_grade" {
                crate::execution::RiskSeverity::Low
            } else {
                crate::execution::RiskSeverity::Blocking
            },
            closure_effect: if phase02.phase_status == "closure_grade" {
                crate::execution::ClosureEffect::Acceptable
            } else {
                crate::execution::ClosureEffect::BlocksClosure
            },
            summary: "The rereview keeps worker ecology grounded in routing, recovery, and workspace evidence rather than in blanket helper output."
                .to_string(),
        },
        crate::execution::ResidualRiskRecord {
            risk_record_id: "remediation-phase-04-risk-factory-programs".to_string(),
            risk_class: crate::execution::ResidualRiskClass::Autonomy,
            supporting_refs: criteria[4].evidence_refs.clone(),
            severity: if phase03.phase_status == "closure_grade" {
                crate::execution::RiskSeverity::Low
            } else {
                crate::execution::RiskSeverity::Blocking
            },
            closure_effect: if phase03.phase_status == "closure_grade" {
                crate::execution::ClosureEffect::Acceptable
            } else {
                crate::execution::ClosureEffect::BlocksClosure
            },
            summary: "Recurring factory programs remain bounded but now carry closure-grade cycle, lineage, and review evidence."
                .to_string(),
        },
        crate::execution::ResidualRiskRecord {
            risk_record_id: "remediation-phase-04-risk-ecosystem".to_string(),
            risk_class: crate::execution::ResidualRiskClass::EcosystemTrust,
            supporting_refs: criteria[5].evidence_refs.clone(),
            severity: if phase03.phase_status == "closure_grade" {
                crate::execution::RiskSeverity::Low
            } else {
                crate::execution::RiskSeverity::Blocking
            },
            closure_effect: if phase03.phase_status == "closure_grade" {
                crate::execution::ClosureEffect::Acceptable
            } else {
                crate::execution::ClosureEffect::BlocksClosure
            },
            summary: "Bounded ecosystem law is closure-grade, but it remains packet-first, local-first, and intentionally bounded."
                .to_string(),
        },
        crate::execution::ResidualRiskRecord {
            risk_record_id: "remediation-phase-04-risk-publication-overclaim".to_string(),
            risk_class: crate::execution::ResidualRiskClass::Legibility,
            supporting_refs: unique_strings(
                phase01_refs
                    .iter()
                    .cloned()
                    .chain(phase02_refs.iter().cloned())
                    .chain(phase03_refs.iter().cloned()),
            ),
            severity: crate::execution::RiskSeverity::Low,
            closure_effect: crate::execution::ClosureEffect::Acceptable,
            summary: "Publication overclaim remains a material risk. It is acceptable only for this historical record-completeness disposition because every publication must retain the historical-scope caveats and the separate operational NotYet decision."
                .to_string(),
        },
        crate::execution::ResidualRiskRecord {
            risk_record_id: "remediation-phase-04-risk-final-claim-boundedness".to_string(),
            risk_class: crate::execution::ResidualRiskClass::Stability,
            supporting_refs: match phase03_claim_assessment {
                Phase03ClaimAssessment::Blocked => unique_strings(
                    final_claim_gap_refs
                        .iter()
                        .cloned()
                        .chain(phase03_blocking_risk_refs.iter().cloned()),
                ),
                Phase03ClaimAssessment::PositiveWithCaveats => unique_strings(
                    criteria[6]
                        .evidence_refs
                        .iter()
                        .cloned()
                        .chain(phase03_acceptable_caveat_refs.iter().cloned()),
                ),
            },
            severity: match phase03_claim_assessment {
                Phase03ClaimAssessment::Blocked => crate::execution::RiskSeverity::Blocking,
                Phase03ClaimAssessment::PositiveWithCaveats => {
                    crate::execution::RiskSeverity::Low
                }
            },
            closure_effect: match phase03_claim_assessment {
                Phase03ClaimAssessment::Blocked => crate::execution::ClosureEffect::BlocksClosure,
                Phase03ClaimAssessment::PositiveWithCaveats => {
                    crate::execution::ClosureEffect::Acceptable
                }
            },
            summary: match phase03_claim_assessment {
                Phase03ClaimAssessment::Blocked => {
                    "The refreshed evidence still lacks the closure-grade phase posture or blocking-risk clearance required for a positive bounded/local-first NorthStar closure."
                        .to_string()
                }
                Phase03ClaimAssessment::PositiveWithCaveats => {
                    "The historical Phase 04 evidence satisfies its record-completeness criteria. It is not an operational M7 proof run and cannot change the current NotYet decision."
                        .to_string()
                }
            },
        },
    ];

    let decision_posture = closure_decision_from_review(&criteria, &residual_risks);
    let decision = crate::execution::ClosureDecisionRecord {
        closure_decision_id: "remediation-phase-04-final-decision".to_string(),
        decision: decision_posture,
        rationale: match decision_posture {
            crate::execution::NorthStarClosureDecision::Closed => {
                "[HISTORICAL RECORD-COMPLETENESS LINEAGE; NOT OPERATIONAL] The Phase 04 rereview closed under its archived criteria. This lineage record is not a current operational North Star decision; operational status remains NotYet until an evidence-derived M7 dossier passes."
                    .to_string()
            }
            crate::execution::NorthStarClosureDecision::ClosedWithCaveats => {
                "[HISTORICAL RECORD-COMPLETENESS LINEAGE; NOT OPERATIONAL] The Phase 04 rereview closed with caveats under its archived criteria. This lineage record is not a current operational North Star decision; operational status remains NotYet until an evidence-derived M7 dossier passes."
                    .to_string()
            }
            crate::execution::NorthStarClosureDecision::NotYet => {
                "[HISTORICAL RECORD-COMPLETENESS LINEAGE; NOT OPERATIONAL] The Phase 04 rereview remained NotYet under its archived criteria. Current operational status is also NotYet and can change only through an evidence-derived M7 dossier."
                    .to_string()
            }
        },
        required_followups: vec![
            "followup:closed-means-historical-record-only-never-operational".to_string(),
            "followup:produce-one-same-run-m0-through-m6-evidence-chain".to_string(),
            "followup:qualify-any-provider-in-the-frozen-m7-scope".to_string(),
            "followup:obtain-external-exact-source-inventory-attestation".to_string(),
            "followup:obtain-independent-m7-review-and-recommendation".to_string(),
            "followup:keep-phase04-decision-labelled-historical-lineage".to_string(),
            "followup:retain-bounded-publication-caveats-until-m7-evidence-changes"
                .to_string(),
        ],
        publication_policy_ref: "remediation-phase-04-publication-policy".to_string(),
        supersedes_ref: precursor.decision.closure_decision_id.clone(),
    };
    require_closed_historical_phase04_decision(decision.decision)?;

    let active_truth_claim_catalog =
        crate::execution::ActiveTruthClaimCatalogV1::bounded_local_first()
            .expect("the active-truth claim catalog must remain valid");
    let claim_boundary = crate::execution::ClaimBoundaryReviewPacket {
        claim_review_id: "remediation-phase-04-claim-boundary".to_string(),
        claim_catalog: active_truth_claim_catalog.clone(),
        allowed_claims: active_truth_claim_catalog.allowed_claim_statements(),
        forbidden_claims: active_truth_claim_catalog.forbidden_claim_statements(),
        caveat_refs: unique_strings(
            residual_risks
                .iter()
                .filter(|risk| risk.closure_effect != crate::execution::ClosureEffect::Acceptable)
                .map(|risk| risk.risk_record_id.clone())
                .chain(["remediation-phase-04-risk-publication-overclaim".to_string()]),
        ),
        supporting_refs: vec![
            "remediation-phase-04-criteria-matrix".to_string(),
            "remediation-phase-04-evidence-inventory".to_string(),
            "remediation-phase-04-closure-dossier".to_string(),
            decision.closure_decision_id.clone(),
        ],
        supporting_evidence_refs: unique_strings(
            criteria
                .iter()
                .flat_map(|criterion| criterion.evidence_refs.iter().cloned()),
        ),
        counter_evidence_refs: unique_strings(
            residual_risks
                .iter()
                .filter(|risk| {
                    risk.closure_effect == crate::execution::ClosureEffect::BlocksClosure
                })
                .map(|risk| risk.risk_record_id.clone())
                .chain(phase03_packet_risks.iter().cloned()),
        ),
        publication_risk_refs: vec!["remediation-phase-04-risk-publication-overclaim".to_string()],
    };

    let closure_dossier = crate::execution::ClosureDossier {
        closure_dossier_id: "remediation-phase-04-closure-dossier".to_string(),
        criteria_matrix_ref: criteria_matrix.criteria_matrix_id.clone(),
        inventory_ref: "remediation-phase-04-evidence-inventory".to_string(),
        adversarial_review_ref: "remediation-phase-04-adversarial-review".to_string(),
        claim_boundary_ref: claim_boundary.claim_review_id.clone(),
        risk_refs: residual_risks
            .iter()
            .map(|risk| risk.risk_record_id.clone())
            .collect(),
        recommendation_ref: decision.closure_decision_id.clone(),
    };

    let publication_policy = crate::execution::PublicationPolicyRecord {
        publication_policy_id: decision.publication_policy_ref.clone(),
        claim_catalog: active_truth_claim_catalog.clone(),
        publication_controls: crate::execution::active_truth_publication_controls(),
        allowed_claims: claim_boundary.allowed_claims.clone(),
        required_caveats: crate::execution::active_truth_required_publication_caveats()
            .into_iter()
            .chain([format!(
                "historical_lineage_posture:{:?}",
                decision_posture
            )])
            .collect(),
        forbidden_claims: claim_boundary.forbidden_claims.clone(),
        source_refs: vec![
            criteria_matrix.criteria_matrix_id.clone(),
            closure_dossier.closure_dossier_id.clone(),
            claim_boundary.claim_review_id.clone(),
            decision.closure_decision_id.clone(),
            precursor.decision.closure_decision_id.clone(),
            "notes/ROADMAP.md".to_string(),
            "notes/M7-CLOSURE-OPERATIONS.md".to_string(),
        ],
        audience_note: "Every rendering or quotation must label the Phase 04 decision as historical record-completeness lineage, retain the required caveats, and report the separate current operational decision as NotYet under notes/ROADMAP.md. This bundle must never be relabelled as an M7 proof run, source capture, or independent review."
            .to_string(),
    };

    let evidence_inventory = crate::execution::EvidenceInventoryPacket {
        inventory_packet_id: "remediation-phase-04-evidence-inventory".to_string(),
        northstar_refs: unique_strings(
            criteria
                .iter()
                .flat_map(|criterion| criterion.evidence_refs.iter().cloned()),
        ),
        operator_refs: unique_strings(
            records
                .iter()
                .map(|record| record.metadata.run_id.clone())
                .chain([
                    "operator:system-overview".to_string(),
                    "operator:post-v4-panel".to_string(),
                    "api:/api/northstar/07/closure-review".to_string(),
                    "api:/api/remediation/phase-04/final-closure-rereview".to_string(),
                ]),
        ),
        risk_refs: residual_risks
            .iter()
            .map(|risk| risk.risk_record_id.clone())
            .collect(),
        phase_01_refs: phase01_refs.clone(),
        phase_02_refs: phase02_refs.clone(),
        phase_03_refs: phase03_refs.clone(),
        phase_04_refs: vec![
            criteria_matrix.criteria_matrix_id.clone(),
            "remediation-phase-04-adversarial-review".to_string(),
            claim_boundary.claim_review_id.clone(),
            closure_dossier.closure_dossier_id.clone(),
            publication_policy.publication_policy_id.clone(),
            decision.closure_decision_id.clone(),
        ],
        summary: "Phase 04 rereview inventory preserves the historical Phase 01 through 03 record evidence and its lineage decisions. It is not the source inventory for a current operational M7 proof run."
            .to_string(),
    };

    let adversarial_review = crate::execution::AdversarialReviewRecord {
        adversarial_review_id: "remediation-phase-04-adversarial-review".to_string(),
        scenario_refs: unique_strings(
            phase01
                .shell_first_paths
                .iter()
                .cloned()
                .chain(phase03.run_refs.iter().cloned()),
        ),
        criterion_refs: criteria
            .iter()
            .map(|criterion| criterion.criterion_id.clone())
            .collect(),
        criteria_matrix_ref: criteria_matrix.criteria_matrix_id.clone(),
        failure_refs: unique_strings(
            criteria
                .iter()
                .filter(|criterion| criterion.status != crate::execution::ClosureCriterionStatus::Passed)
                .flat_map(|criterion| criterion.gap_refs.iter().cloned())
                .chain(phase03_packet_risks.iter().cloned()),
        ),
        counter_evidence_refs: unique_strings(
            criteria
                .iter()
                .filter(|criterion| criterion.status == crate::execution::ClosureCriterionStatus::Passed)
                .flat_map(|criterion| criterion.evidence_refs.iter().cloned()),
        ),
        risk_refs: residual_risks
            .iter()
            .map(|risk| risk.risk_record_id.clone())
            .collect(),
        challenge_outcome_refs: vec![
            claim_boundary.claim_review_id.clone(),
            decision.closure_decision_id.clone(),
            precursor.decision.closure_decision_id.clone(),
        ],
        recommendation_ref: decision.closure_decision_id.clone(),
        summary: "Phase 04 adversarial rereview challenges its historical record set and preserves both decisions as explicit lineage; it has no authority to change the current operational NotYet status or to stand in for an M7 independent review."
            .to_string(),
    };

    let store = DurableArtifactStore::bootstrap(workspace.remediation_phase_04_store_root())?;
    for criterion in &criteria {
        criterion.validate().map_err(|error| {
            LocalRuntimeError::Storage(format!("phase04 criterion validation failed: {error}"))
        })?;
    }
    store.persist_closure_criteria_matrix(&criteria_matrix)?;
    store.persist_evidence_inventory_packet(&evidence_inventory)?;
    store.persist_adversarial_review_record(&adversarial_review)?;
    for risk in &residual_risks {
        store.persist_residual_risk_record(risk)?;
    }
    store.persist_closure_dossier(&closure_dossier)?;
    store.persist_claim_boundary_review_packet(&claim_boundary)?;
    store.persist_publication_policy_record(&publication_policy)?;
    store.persist_closure_decision_record(&decision)?;

    Ok(Phase04RereviewBundle {
        criteria,
        criteria_matrix,
        evidence_inventory,
        adversarial_review,
        residual_risks,
        closure_dossier,
        claim_boundary,
        publication_policy,
        decision,
    })
}

fn require_closed_historical_phase04_decision(
    decision: crate::execution::NorthStarClosureDecision,
) -> Result<(), LocalRuntimeError> {
    if decision == crate::execution::NorthStarClosureDecision::Closed {
        Ok(())
    } else {
        Err(LocalRuntimeError::HistoricalPhase04TruthUnavailable { decision })
    }
}

fn northstar07_view_from_phase04_bundle(
    bundle: Phase04RereviewBundle,
) -> NorthStar07ClosureReviewView {
    NorthStar07ClosureReviewView {
        summary: format!(
            "The historical NorthStar 07 record-completeness rereview evaluated {} criteria, recorded {} residual risk(s), and issued one lineage decision: {:?}. The separate operational decision remains NotYet.",
            bundle.criteria.len(),
            bundle.residual_risks.len(),
            bundle.decision.decision
        ),
        review_scope: "historical_record_completeness".to_string(),
        operational_decision: crate::execution::NorthStarClosureDecision::NotYet,
        status_authority_ref: "notes/ROADMAP.md".to_string(),
        operator_truth_surfaces: operator_truth_surface_authority(),
        criteria: bundle.criteria,
        criteria_matrix: bundle.criteria_matrix,
        evidence_inventory: bundle.evidence_inventory,
        adversarial_review: bundle.adversarial_review,
        residual_risks: bundle.residual_risks,
        closure_dossier: bundle.closure_dossier,
        claim_boundary: bundle.claim_boundary,
        publication_policy: bundle.publication_policy,
        decision: bundle.decision,
        is_remediated_current_review: false,
        guardrails: vec![
            "The Phase 04 decision is historical lineage, never the current operational decision."
                .to_string(),
            "Current operational status can change only through the evidence-derived M7 dossier."
                .to_string(),
            "Publication policy must keep Phase 04 and operational M7 claims visibly separate."
                .to_string(),
        ],
    }
}

fn build_northstar_07_closure_review_view(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
) -> Result<NorthStar07ClosureReviewView, LocalRuntimeError> {
    let bundle = build_phase04_rereview_bundle(workspace, records)?;
    require_closed_historical_phase04_decision(bundle.decision.decision)?;
    Ok(northstar07_view_from_phase04_bundle(bundle))
}

fn build_remediation_phase_04_final_closure_rereview_view(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
) -> Result<RemediationPhase04FinalClosureRereviewView, LocalRuntimeError> {
    let bundle = build_phase04_rereview_bundle(workspace, records)?;
    require_closed_historical_phase04_decision(bundle.decision.decision)?;
    let northstar07 = northstar07_view_from_phase04_bundle(bundle.clone());
    let precursor_store = DurableArtifactStore::bootstrap(workspace.northstar_07_store_root())?;
    let superseded_decision = precursor_store
        .load_closure_decision_record(&bundle.decision.supersedes_ref)
        .ok();

    let criteria_refs = bundle
        .criteria
        .iter()
        .map(|item| item.criterion_id.clone())
        .collect::<Vec<_>>();
    let workstream_a_closed = !bundle.criteria.is_empty()
        && !bundle.criteria_matrix.phase_evidence_refs.is_empty()
        && !bundle.criteria_matrix.delta_crosswalk_refs.is_empty()
        && bundle.criteria.iter().all(|criterion| {
            !criterion.evidence_refs.is_empty()
                && !criterion.phase_evidence_refs.is_empty()
                && !criterion.delta_crosswalk_refs.is_empty()
        });
    let workstream_b_closed = !bundle.adversarial_review.counter_evidence_refs.is_empty()
        && !bundle.claim_boundary.allowed_claims.is_empty()
        && !bundle.claim_boundary.forbidden_claims.is_empty()
        && !bundle.claim_boundary.publication_risk_refs.is_empty();
    let workstream_c_closed = !bundle.closure_dossier.closure_dossier_id.is_empty()
        && !bundle.closure_dossier.claim_boundary_ref.is_empty()
        && bundle.publication_policy.validate().is_ok()
        && !bundle.decision.closure_decision_id.is_empty()
        && !bundle.decision.supersedes_ref.is_empty()
        && superseded_decision.is_some();

    let workstreams = vec![
        remediation_workstream(
            "phase-04-workstream-a",
            "Historical Criteria Refresh and Record-Evidence Inventory",
            if workstream_a_closed {
                "closure_grade"
            } else {
                "not_yet"
            },
            format!(
                "{} criterion/criteria, {} phase evidence ref(s), and {} delta crosswalk ref(s) define the historical record-completeness rereview.",
                bundle.criteria.len(),
                bundle.criteria_matrix.phase_evidence_refs.len(),
                bundle.criteria_matrix.delta_crosswalk_refs.len()
            ),
            unique_strings(
                criteria_refs
                    .iter()
                    .cloned()
                    .chain([bundle.criteria_matrix.criteria_matrix_id.clone()])
                    .chain([bundle.evidence_inventory.inventory_packet_id.clone()]),
            ),
            if workstream_a_closed {
                Vec::new()
            } else {
                vec!["gap:phase04-criteria-refresh-incomplete".to_string()]
            },
        ),
        remediation_workstream(
            "phase-04-workstream-b",
            "Historical Adversarial Re-Review and Claim-Boundary Testing",
            if workstream_b_closed {
                "closure_grade"
            } else {
                "not_yet"
            },
            format!(
                "{} counter-evidence ref(s), {} forbidden claim(s), and {} publication-risk ref(s) keep the historical rereview adversarial and publication-safe.",
                bundle.adversarial_review.counter_evidence_refs.len(),
                bundle.claim_boundary.forbidden_claims.len(),
                bundle.claim_boundary.publication_risk_refs.len()
            ),
            unique_strings(
                bundle
                    .adversarial_review
                    .counter_evidence_refs
                    .iter()
                    .cloned()
                    .chain([bundle.adversarial_review.adversarial_review_id.clone()])
                    .chain([bundle.claim_boundary.claim_review_id.clone()]),
            ),
            if workstream_b_closed {
                Vec::new()
            } else {
                vec!["gap:phase04-claim-boundary-rereview-incomplete".to_string()]
            },
        ),
        remediation_workstream(
            "phase-04-workstream-c",
            "Historical Lineage Decision, Publication Policy, and Supersession Protocol",
            if workstream_c_closed {
                "closure_grade"
            } else {
                "not_yet"
            },
            format!(
                "The historical Phase 04 decision {:?} supersedes {} only within the archived record lineage.",
                bundle.decision.decision, bundle.decision.supersedes_ref
            ),
            vec![
                bundle.closure_dossier.closure_dossier_id.clone(),
                bundle.publication_policy.publication_policy_id.clone(),
                bundle.decision.closure_decision_id.clone(),
                bundle.decision.supersedes_ref.clone(),
            ],
            if workstream_c_closed {
                Vec::new()
            } else {
                vec!["gap:phase04-supersession-lineage-incomplete".to_string()]
            },
        ),
    ];

    let phase_status = remediation_phase_status(&workstreams);
    let operator_truth_surfaces = northstar07.operator_truth_surfaces.clone();

    Ok(RemediationPhase04FinalClosureRereviewView {
        summary: format!(
            "Remediation Phase 04 preserves a historical record-completeness rereview that supersedes the precursor NorthStar 07 lineage decision. Record posture: {:?}; operational posture: NotYet.",
            bundle.decision.decision
        ),
        phase_status,
        decision_posture: format!("Historical{:?}", bundle.decision.decision),
        historical_lineage_decision: bundle.decision.decision,
        review_scope: "historical_record_completeness".to_string(),
        operational_decision: crate::execution::NorthStarClosureDecision::NotYet,
        status_authority_ref: "notes/ROADMAP.md".to_string(),
        operator_truth_surfaces,
        criteria_refs,
        criteria_matrix_refs: vec![bundle.criteria_matrix.criteria_matrix_id.clone()],
        evidence_inventory_refs: vec![bundle.evidence_inventory.inventory_packet_id.clone()],
        adversarial_review_refs: vec![bundle.adversarial_review.adversarial_review_id.clone()],
        claim_boundary_refs: vec![bundle.claim_boundary.claim_review_id.clone()],
        closure_dossier_refs: vec![bundle.closure_dossier.closure_dossier_id.clone()],
        publication_policy_refs: vec![bundle.publication_policy.publication_policy_id.clone()],
        final_decision_refs: vec![bundle.decision.closure_decision_id.clone()],
        claim_catalog: bundle.claim_boundary.claim_catalog.clone(),
        publication_controls: bundle.publication_policy.publication_controls.clone(),
        allowed_claims: bundle.claim_boundary.allowed_claims.clone(),
        forbidden_claims: bundle.claim_boundary.forbidden_claims.clone(),
        northstar07,
        workstreams,
        remaining_blockers: vec![
            "No evidence-derived current M7 operational dossier has passed.".to_string(),
            "One new precommitted external M7 proof run must capture the exact same-run M0 through M6 evidence chain from a fresh clean checkout; the historical 2026-07-31 detached run validates only its exact local implementation snapshot and does not validate current post-baseline hardening."
                .to_string(),
            "Every provider named by the frozen M7 scope must have a current live qualification bound to that run."
                .to_string(),
            "An external source custodian must attest the exact non-review source inventory."
                .to_string(),
            "An independent reviewer must sign the final M7 review and recommendation.".to_string(),
        ],
        boundary_statement: "Phase 04 judges only historical record-completeness. Its lineage decision does not establish current operational capability or North Star closure."
            .to_string(),
        next_phase: "M7 evidence-derived operational closure under notes/M7-CLOSURE-OPERATIONS.md."
            .to_string(),
        guardrails: vec![
            "The precursor NorthStar 07 decision must remain loadable as lineage.".to_string(),
            "The Phase 04 decision must always be labelled historical record-completeness."
                .to_string(),
            "The current operational decision remains NotYet unless a new M7 dossier proves otherwise."
                .to_string(),
            "Publication policy must forbid translating lineage status into current capability claims."
                .to_string(),
            "Phase 04 artifacts cannot substitute for current M7 source capture or independent review."
                .to_string(),
        ],
    })
}

fn select_records_for_packet(
    records: &[LocalRunRecord],
    run_ids: &[String],
) -> Vec<LocalRunRecord> {
    if run_ids.is_empty() {
        return records.to_vec();
    }
    let wanted = run_ids.iter().cloned().collect::<BTreeSet<_>>();
    records
        .iter()
        .filter(|record| wanted.contains(&record.metadata.run_id))
        .cloned()
        .collect()
}

fn build_phase_a_launch_truth_view(records: &[LocalRunRecord]) -> PhaseALaunchTruthView {
    let scenario_support = curated_scenarios()
        .iter()
        .map(scenario_support_classification)
        .collect::<Vec<_>>();
    let mut launches = records
        .iter()
        .filter_map(|record| record.metadata.launch_assembly.clone())
        .collect::<Vec<_>>();
    launches.sort_by(|left, right| right.assembly_id.cmp(&left.assembly_id));
    let mut admissions = records
        .iter()
        .filter_map(|record| record.metadata.campaign_admission.clone())
        .collect::<Vec<_>>();
    admissions.sort_by(|left, right| right.admission_id.cmp(&left.admission_id));

    PhaseALaunchTruthView {
        summary: format!(
            "Phase A launch truth currently classifies {} scenario(s), carries {} explicit launch assembly record(s), and preserves {} campaign admission record(s) across the runner.",
            scenario_support.len(),
            launches.len(),
            admissions.len()
        ),
        scenario_support,
        launches,
        admissions,
        guardrails: vec![
            "No shell-backed claim without explicit scenario support, launch assembly, and admission records.".to_string(),
            "Mixed and staged scenarios remain explicitly classified rather than silently treated as live shell truth.".to_string(),
            "The runner may degrade honestly, but it may not fabricate shell-backed success.".to_string(),
        ],
    }
}

fn build_phase_b_factory_review_packet(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
    request: &PhaseBFactoryReviewPacketExportRequest,
    imported: bool,
) -> Result<PhaseBFactoryReviewPacket, LocalRuntimeError> {
    let selected_records = select_records_for_packet(records, &request.run_ids);
    let dossier = build_phase_b_factory_dossier_view(workspace, &selected_records)?;
    let created_at = current_timestamp();
    let title = request
        .title
        .clone()
        .unwrap_or_else(|| "Phase B factory review packet".to_string());
    let validation_refs = unique_strings(
        dossier
            .validation_profiles
            .iter()
            .map(|profile| profile.validation_profile_id.clone())
            .chain(
                dossier
                    .validation_evidence
                    .iter()
                    .map(|evidence| evidence.evidence_id.clone()),
            )
            .chain(
                dossier
                    .validation_records
                    .iter()
                    .map(|record| record.validation_id.clone()),
            ),
    );
    let comparison_refs = unique_strings(
        dossier
            .comparisons
            .iter()
            .map(|comparison| comparison.comparison_id.clone()),
    );
    let activation_refs = unique_strings(
        dossier
            .activations
            .iter()
            .map(|activation| activation.activation_id.clone())
            .chain(
                dossier
                    .active_states
                    .iter()
                    .map(|state| state.state_id.clone()),
            ),
    );
    let rollback_refs = unique_strings(
        dossier
            .activations
            .iter()
            .map(|activation| activation.rollback_handle_ref.clone())
            .chain(
                dossier
                    .rollback_envelopes
                    .iter()
                    .map(|record| record.rollback_id.clone()),
            )
            .chain(dossier.active_states.iter().flat_map(|state| {
                state
                    .rollback_history
                    .iter()
                    .map(|record| record.rollback_id.clone())
            })),
    );
    let governance_refs = unique_strings(
        dossier
            .governance_transitions
            .iter()
            .map(|record| record.transition_id.clone())
            .chain(
                dossier
                    .quarantine_records
                    .iter()
                    .map(|record| record.quarantine_id.clone()),
            ),
    );

    Ok(PhaseBFactoryReviewPacket {
        packet_id: format!("phase-b-packet:{}:{}", sanitize_id(&title), created_at),
        title,
        summary: request.summary.clone().unwrap_or_else(|| {
            format!(
                "Phase B review packet covering {} run(s), {} factory comparison record(s), and {} activation path(s).",
                dossier.run_refs.len(),
                dossier.comparisons.len(),
                dossier.activations.len()
            )
        }),
        created_at,
        source_run_ids: dossier.run_refs,
        incumbent_factory_refs: dossier.incumbent_factory_refs,
        challenger_factory_refs: dossier.challenger_factory_refs,
        validation_refs,
        comparison_refs,
        activation_refs,
        governance_refs,
        rollback_refs,
        claim_boundary: request
            .claim_boundary
            .clone()
            .unwrap_or(dossier.boundary_statement),
        imported,
    })
}

fn build_phase_b_factory_packet_ledger_view(
    packets: &[PhaseBFactoryReviewPacket],
) -> PhaseBFactoryPacketLedgerView {
    PhaseBFactoryPacketLedgerView {
        summary: if packets.is_empty() {
            "No Phase B factory review packets have been exported yet.".to_string()
        } else {
            format!(
                "The Phase B packet ledger carries {} exported or imported factory review packet(s).",
                packets.len()
            )
        },
        packets: packets.to_vec(),
        guardrails: vec![
            "Phase B packets remain single-factory and bounded.".to_string(),
            "No Phase B packet may imply later-factory creation or federation.".to_string(),
        ],
    }
}

fn build_phase_c_replication_review_packet(
    workspace: &LocalRuntimeWorkspace,
    records: &[LocalRunRecord],
    request: &PhaseCReplicationReviewPacketExportRequest,
    imported: bool,
) -> Result<PhaseCReplicationReviewPacket, LocalRuntimeError> {
    let selected_records = select_records_for_packet(records, &request.run_ids);
    let dossier = build_phase_c_replication_dossier_view(workspace, &selected_records)?;
    let created_at = current_timestamp();
    let title = request
        .title
        .clone()
        .unwrap_or_else(|| "Phase C replication review packet".to_string());

    Ok(PhaseCReplicationReviewPacket {
        packet_id: format!("phase-c-packet:{}:{}", sanitize_id(&title), created_at),
        title,
        summary: request.summary.clone().unwrap_or_else(|| {
            format!(
                "Phase C review packet covering {} run(s), {} replication campaign(s), {} proving run(s), and {} decision record(s).",
                dossier.run_refs.len(),
                dossier.campaigns.len(),
                dossier.proving_runs.len(),
                dossier.decisions.len()
            )
        }),
        created_at,
        source_run_ids: dossier.run_refs,
        parent_factory_refs: dossier.parent_factory_refs,
        child_factory_refs: dossier.child_factory_refs,
        campaign_refs: unique_strings(
            dossier
                .campaigns
                .iter()
                .map(|campaign| campaign.replication_campaign_id.clone()),
        ),
        production_refs: unique_strings(
            dossier
                .candidates
                .iter()
                .flat_map(|candidate| candidate.production_trace_refs.iter().cloned())
                .chain(
                    dossier
                        .evidence_packets
                        .iter()
                        .flat_map(|packet| packet.production_refs.iter().cloned()),
                ),
        ),
        proving_refs: unique_strings(
            dossier
                .proving_runs
                .iter()
                .map(|record| record.proving_run_id.clone())
                .chain(
                    dossier
                        .evidence_packets
                        .iter()
                        .flat_map(|packet| packet.proving_refs.iter().cloned()),
                ),
        ),
        observation_refs: unique_strings(
            dossier
                .observation_windows
                .iter()
                .map(|record| record.observation_window_id.clone())
                .chain(
                    dossier
                        .observation_windows
                        .iter()
                        .flat_map(|record| record.observation_event_refs.iter().cloned()),
                ),
        ),
        quarantine_refs: unique_strings(
            dossier
                .quarantine_protocols
                .iter()
                .map(|record| record.protocol_id.clone())
                .chain(
                    dossier
                        .quarantine_protocols
                        .iter()
                        .flat_map(|record| record.trigger_refs.iter().cloned()),
                ),
        ),
        decision_refs: unique_strings(
            dossier
                .decisions
                .iter()
                .map(|decision| decision.decision_id.clone())
                .chain(
                    dossier
                        .decisions
                        .iter()
                        .flat_map(|decision| decision.rollback_refs.iter().cloned()),
                ),
        ),
        disposition_refs: unique_strings(
            dossier
                .dispositions
                .iter()
                .map(|record| record.disposition_id.clone())
                .chain(
                    dossier
                        .dispositions
                        .iter()
                        .flat_map(|record| record.rollback_refs.iter().cloned()),
                ),
        ),
        claim_boundary: request
            .claim_boundary
            .clone()
            .unwrap_or(dossier.boundary_statement),
        imported,
    })
}

