fn build_v3_generation_artifact(
    run_views: &[RunViewModel],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    handoff_packets: &[V2NextLineHandoffPacket],
    request: &V3GenerationArtifactExportRequest,
    exported: bool,
) -> V3GenerationArtifact {
    let selection = select_v3_generation_runs(run_views, &request.run_ids);
    let primary = selection
        .selected_runs
        .first()
        .cloned()
        .unwrap_or_else(|| selection.challenger.clone());
    let title = request
        .title
        .clone()
        .unwrap_or_else(|| "v3 governed generation artifact".to_string());
    let generation_id = format!(
        "generation-artifact:{}:{}",
        sanitize_id(&title),
        sanitize_id(&selection.challenger.summary.run_id)
    );
    let genome_ref = format!("genome-intent:{}", generation_id);
    let phenotype_ref = format!(
        "phenotype-output:{}:{}",
        sanitize_id(&primary.summary.run_id),
        sanitize_id(&primary.summary.root_task_id)
    );
    let package_bundle_ref = format!("package-bundle:{}", generation_id);
    let rollback_refs = unique_strings(
        selection
            .selected_runs
            .iter()
            .flat_map(|view| {
                view.rollback_handle
                    .iter()
                    .map(|handle| handle.rollback_handle_id.clone())
            })
            .chain(selection.selected_runs.iter().flat_map(|view| {
                view.quarantines
                    .iter()
                    .map(|item| item.quarantine_id.clone())
            }))
            .chain([
                format!("incumbent-retention:{}", selection.incumbent.summary.run_id),
                format!("rollback-anchor:{}", selection.incumbent.summary.run_id),
            ]),
    );
    let validation_refs = unique_strings(
        review_packets
            .iter()
            .take(3)
            .map(|packet| packet.packet_id.clone())
            .chain(
                transition_packets
                    .first()
                    .into_iter()
                    .map(|packet| packet.packet_id.clone()),
            )
            .chain(
                handoff_packets
                    .first()
                    .into_iter()
                    .map(|packet| packet.packet_id.clone()),
            )
            .chain(selection.selected_runs.iter().flat_map(view_evidence_refs)),
    );
    let lineage_refs = unique_strings(
        selection
            .selected_runs
            .iter()
            .map(|view| view.summary.run_id.clone())
            .chain([selection.incumbent.summary.run_id.clone()])
            .chain(
                transition_packets
                    .first()
                    .into_iter()
                    .map(|packet| packet.packet_id.clone()),
            )
            .chain(
                handoff_packets
                    .first()
                    .into_iter()
                    .map(|packet| packet.packet_id.clone()),
            ),
    );
    let build_closure = V3BuildClosureRecord {
        build_closure_id: format!("build-closure:{}", generation_id),
        source_refs: unique_strings(
            selection
                .selected_runs
                .iter()
                .flat_map(|view| {
                    std::iter::once(view.summary.bundle_path.clone())
                        .chain(view.summary.output_refs.clone())
                }),
        ),
        service_refs: vec![
            "service:generation-build".to_string(),
            "service:semantic-validation".to_string(),
            "service:review-evidence".to_string(),
            "service:artifact-storage".to_string(),
            "service:approval-release".to_string(),
            "service:package-bundle".to_string(),
        ],
        validation_refs: validation_refs.clone(),
        emitted_outputs: vec![
            phenotype_ref.clone(),
            package_bundle_ref.clone(),
            genome_ref.clone(),
        ],
        summary: "The build closure keeps genome intent, phenotype output, service participation, validation linkage, and package outputs explicit for one v3 candidate generation.".to_string(),
    };
    let package_bundle = V3PackageBundleManifest {
        manifest_id: format!("bundle-manifest:{}", generation_id),
        bundle_ref: package_bundle_ref.clone(),
        manifest_entries: vec![
            format!("bundle-root:{}", primary.summary.bundle_path),
            format!("activation-envelope:{}", generation_id),
            format!("lineage-anchor:{}", selection.incumbent.summary.run_id),
            "bounded-observation-window".to_string(),
        ],
        activation_ready: true,
        summary: "The package bundle manifest records one activation-ready bounded bundle with explicit lineage, validation, and coexistence hooks.".to_string(),
    };
    let activation_envelope = V3ActivationEnvelope {
        activation_id: format!("activation-envelope:{}", generation_id),
        generation_ref: generation_id.clone(),
        coexistence_mode: request
            .coexistence_mode
            .clone()
            .unwrap_or_else(|| "bounded-adopt".to_string()),
        rollback_refs,
        operator_constraints: if request.operator_constraints.is_empty() {
            default_v3_operator_constraints()
        } else {
            request.operator_constraints.clone()
        },
    };
    let compatibility_surface = V3GenerationCompatibilitySurface {
        incumbent_ref: format!(
            "generation:incumbent:{}",
            sanitize_id(&selection.incumbent.summary.run_id)
        ),
        challenger_ref: generation_id.clone(),
        summary: format!(
            "The v3 compatibility surface compares the incumbent `{}` to challenger `{}` while keeping the v2 handoff and bounded activation envelope attached.",
            selection.incumbent.summary.run_id, selection.challenger.summary.run_id
        ),
        compatibility_notes: vec![
            "Genome intent, phenotype output, and package bundle remain distinguishable."
                .to_string(),
            "The challenger stays comparable to the incumbent through explicit lineage refs."
                .to_string(),
            "Activation does not erase rollback symmetry or incumbent retention.".to_string(),
        ],
    };

    V3GenerationArtifact {
        generation_id: generation_id.clone(),
        title,
        summary: request.summary.clone().unwrap_or_else(|| {
            format!(
                "This v3 generation artifact closes one governed candidate generation around {} selected run(s), explicit build closure, one package manifest, and one activation envelope.",
                selection.selected_runs.len()
            )
        }),
        genome_ref,
        phenotype_ref,
        package_bundle_ref,
        validation_refs,
        lineage_refs,
        build_closure,
        package_bundle,
        activation_envelope,
        compatibility_surface,
        created_at: current_timestamp(),
        exported,
    }
}

fn build_v3_self_production_evidence_packet(
    run_views: &[RunViewModel],
    review_packets: &[OperatorReviewPacket],
    transition_packets: &[V2TransitionPacket],
    handoff_packets: &[V2NextLineHandoffPacket],
    artifacts: &[V3GenerationArtifact],
    request: &V3SelfProductionEvidencePacketExportRequest,
    exported: bool,
) -> V3SelfProductionEvidencePacket {
    let artifact = if request.run_ids.is_empty() {
        artifacts.first().cloned().unwrap_or_else(|| {
            build_v3_generation_artifact(
                run_views,
                review_packets,
                transition_packets,
                handoff_packets,
                &default_v3_generation_artifact_export_request(),
                false,
            )
        })
    } else {
        build_v3_generation_artifact(
            run_views,
            review_packets,
            transition_packets,
            handoff_packets,
            &V3GenerationArtifactExportRequest {
                run_ids: request.run_ids.clone(),
                title: request.title.clone(),
                summary: request.summary.clone(),
                coexistence_mode: None,
                operator_constraints: Vec::new(),
            },
            false,
        )
    };
    let adoption = build_v3_generation_comparison_adoption_rollback_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        std::slice::from_ref(&artifact),
    );
    let successor = build_v3_adopted_generation_successor_production_view(
        run_views,
        review_packets,
        transition_packets,
        handoff_packets,
        std::slice::from_ref(&artifact),
    );
    let title = request
        .title
        .clone()
        .unwrap_or_else(|| "v3 self-production evidence packet".to_string());
    let created_at = current_timestamp();
    V3SelfProductionEvidencePacket {
        packet_id: format!("v3-self-production-packet:{}:{}", sanitize_id(&title), created_at),
        title,
        summary: request.summary.clone().unwrap_or_else(|| {
            format!(
                "The v3 evidence packet binds one generation artifact, one adoption decision path, and {} successor-production record(s) into a bounded single-factory claim packet.",
                usize::from(successor.successor_run.is_some())
            )
        }),
        created_at,
        generation_refs: unique_strings(
            [artifact.compatibility_surface.incumbent_ref.clone()]
                .into_iter()
                .chain([artifact.generation_id.clone()])
                .chain(
                    successor
                        .successor_run
                        .iter()
                        .map(|run| run.produced_generation_ref.clone()),
                ),
        ),
        comparison_refs: unique_strings([
            adoption.decision.decision_id.clone(),
            adoption.lineage_record.continuity_id.clone(),
            artifact.compatibility_surface.summary.clone(),
        ]),
        runtime_refs: unique_strings(
            [successor.campaign.campaign_id.clone(), adoption.observation_window.report_id.clone()]
                .into_iter()
                .chain(
                    successor
                        .successor_run
                        .iter()
                        .map(|run| run.run_id.clone()),
                ),
        ),
        governance_refs: unique_strings(
            [adoption.rollback_envelope.envelope_id.clone(), artifact.activation_envelope.activation_id.clone()]
                .into_iter()
                .chain(artifact.activation_envelope.rollback_refs.iter().cloned())
                .chain(
                    handoff_packets
                        .first()
                        .into_iter()
                        .map(|packet| packet.packet_id.clone()),
                ),
        ),
        claim_boundary: request
            .claim_boundary
            .clone()
            .unwrap_or_else(default_v3_claim_boundary),
        exported,
    }
}

