fn select_v3_generation_runs(
    run_views: &[RunViewModel],
    requested_run_ids: &[String],
) -> V3GenerationSelection {
    let sorted = sorted_run_views(run_views);
    let mut selected_runs = if requested_run_ids.is_empty() {
        sorted
            .iter()
            .filter(|view| {
                matches!(
                    view.summary.scenario_id.as_str(),
                    "supervisor-approval-resume-worker-complete"
                        | "supervisor-promote-activate-successor-campaign"
                        | "supervisor-second-cycle-v1-completion"
                        | "supervisor-durable-fixed-interface-continuous-self-hosting-program"
                        | "supervisor-background-quarantine-rollback-control-loop"
                )
            })
            .cloned()
            .collect::<Vec<_>>()
    } else {
        sorted
            .iter()
            .filter(|view| requested_run_ids.contains(&view.summary.run_id))
            .cloned()
            .collect::<Vec<_>>()
    };
    if selected_runs.is_empty() && !sorted.is_empty() {
        selected_runs = sorted.clone();
    }
    let incumbent =
        find_v3_run_by_scenario(&sorted, &["supervisor-approval-resume-worker-complete"])
            .or_else(|| selected_runs.last().cloned())
            .or_else(|| sorted.last().cloned())
            .unwrap_or_else(fallback_v3_run);
    let challenger = find_v3_run_by_scenario(
        &selected_runs,
        &[
            "supervisor-durable-fixed-interface-continuous-self-hosting-program",
            "supervisor-promote-activate-successor-campaign",
        ],
    )
    .or_else(|| {
        find_v3_run_by_scenario(
            &sorted,
            &[
                "supervisor-durable-fixed-interface-continuous-self-hosting-program",
                "supervisor-promote-activate-successor-campaign",
            ],
        )
    })
    .or_else(|| selected_runs.first().cloned())
    .unwrap_or_else(|| incumbent.clone());
    let successor = find_v3_run_by_scenario(
        &sorted,
        &[
            "supervisor-second-cycle-v1-completion",
            "supervisor-promote-activate-successor-campaign",
        ],
    )
    .filter(|view| view.summary.run_id != challenger.summary.run_id);
    V3GenerationSelection {
        selected_runs,
        incumbent,
        challenger,
        successor,
    }
}

fn find_v3_run_by_scenario(pool: &[RunViewModel], scenario_ids: &[&str]) -> Option<RunViewModel> {
    for scenario_id in scenario_ids {
        if let Some(view) = pool
            .iter()
            .find(|view| view.summary.scenario_id == *scenario_id)
            .cloned()
        {
            return Some(view);
        }
    }
    None
}

fn default_v3_generation_artifact_export_request() -> V3GenerationArtifactExportRequest {
    V3GenerationArtifactExportRequest {
        run_ids: Vec::new(),
        title: None,
        summary: None,
        coexistence_mode: None,
        operator_constraints: Vec::new(),
    }
}

fn default_v3_operator_constraints() -> Vec<String> {
    vec![
        "bounded observation window required".to_string(),
        "incumbent retained until observation closes".to_string(),
        "rollback handle must remain live".to_string(),
        "single successor-production attempt maximum".to_string(),
    ]
}

fn default_v3_claim_boundary() -> String {
    "This packet supports one bounded native single-factory self-production claim only. It does not claim later-factory creation, federation, or hosted ecosystem readiness.".to_string()
}

