    let v3_workspace = build_v3_self_production_workspace_view(
        &run_views,
        operator_review_packets,
        v2_transition_packets,
        v2_next_line_handoff_packets,
        v3_generation_artifacts,
        v3_self_production_evidence_packets,
    );
    let v3_gate = build_v3_bounded_single_factory_self_production_gate_view(
        &run_views,
        operator_review_packets,
        v2_transition_packets,
        v2_next_line_handoff_packets,
        v3_generation_artifacts,
        v3_self_production_evidence_packets,
    );
    let bundle_root = workspace.bundle_root(&record.metadata.run_id);
    let snapshots_root = bundle_root.join("snapshots");
    fs::create_dir_all(&snapshots_root)?;

    write_json(bundle_root.join("summary.json"), &view.summary)?;
    write_json(snapshots_root.join("scenario-studio.json"), &studio)?;
    write_json(snapshots_root.join("usecases.json"), &use_cases)?;
