    #[test]
    fn m4_cancel_request_accepts_only_an_opaque_credential() {
        let request: M4CancelJobRequest = serde_json::from_value(serde_json::json!({
            "cancellation_credential": "opaque-caller-secret"
        }))
        .unwrap();
        assert_eq!(request.cancellation_credential, "opaque-caller-secret");

        let caller_tick = serde_json::from_value::<M4CancelJobRequest>(serde_json::json!({
            "cancellation_credential": "opaque-caller-secret",
            "tick": 41
        }));
        assert!(caller_tick.is_err());
    }

    #[test]
    fn m4_empty_mutations_reject_caller_owned_ticks_as_bad_requests() {
        assert!(validate_m4_mutation_request(&Bytes::new()).is_ok());
        assert!(validate_m4_mutation_request(&Bytes::from_static(b"{}")).is_ok());

        let error =
            validate_m4_mutation_request(&Bytes::from_static(br#"{"tick":41}"#)).unwrap_err();
        assert_eq!(error.status, StatusCode::BAD_REQUEST);
    }

    #[test]
    fn m4_job_serialization_exposes_only_the_cancellation_digest() {
        let raw_credential = "caller-held-cancellation-secret";
        let durable_token = crate::worker_runtime::CancellationToken::from_secret(raw_credential);
        let serialized = serde_json::to_string(&durable_token).unwrap();

        assert!(serialized.contains("credential_digest"));
        assert!(!serialized.contains(raw_credential));
    }

    #[test]
    fn m4_worker_errors_retain_their_http_classification() {
        let cases = vec![
            (
                WorkerRuntimeError::InvalidRequest("bad request".to_string()),
                M4RuntimeFailureClass::InvalidRequest,
                StatusCode::BAD_REQUEST,
            ),
            (
                WorkerRuntimeError::CapabilityDenied("denied".to_string()),
                M4RuntimeFailureClass::CapabilityDenied,
                StatusCode::FORBIDDEN,
            ),
            (
                WorkerRuntimeError::NotFound("missing".to_string()),
                M4RuntimeFailureClass::NotFound,
                StatusCode::NOT_FOUND,
            ),
            (
                WorkerRuntimeError::Conflict("already owned".to_string()),
                M4RuntimeFailureClass::Conflict,
                StatusCode::CONFLICT,
            ),
            (
                WorkerRuntimeError::BudgetExceeded("bounded".to_string()),
                M4RuntimeFailureClass::Unprocessable,
                StatusCode::UNPROCESSABLE_ENTITY,
            ),
            (
                WorkerRuntimeError::Io {
                    path: PathBuf::from("/m4-test"),
                    message: "offline".to_string(),
                },
                M4RuntimeFailureClass::Unavailable,
                StatusCode::SERVICE_UNAVAILABLE,
            ),
            (
                WorkerRuntimeError::Integrity("corrupt".to_string()),
                M4RuntimeFailureClass::Integrity,
                StatusCode::INTERNAL_SERVER_ERROR,
            ),
        ];

        for (worker_error, expected_class, expected_status) in cases {
            let local_error = LocalRuntimeError::from(M4RuntimeError::Worker(worker_error));
            assert!(
                matches!(
                    &local_error,
                    LocalRuntimeError::M4Runtime { class, .. } if class == &expected_class
                ),
                "{local_error}"
            );
            assert_eq!(ApiError::from(local_error).status, expected_status);
        }
    }

    #[test]
    fn closure_decision_is_closed_without_failed_blocking_or_caveated_items() {
        let criteria = vec![crate::execution::ClosureCriterionRecord {
            criterion_id: "criterion:closed".to_string(),
            title: "Closed".to_string(),
            status: crate::execution::ClosureCriterionStatus::Passed,
            evidence_refs: vec!["evidence:1".to_string()],
            phase_evidence_refs: vec!["phase:1".to_string()],
            delta_crosswalk_refs: vec!["delta:1".to_string()],
            gap_refs: Vec::new(),
            summary: "criterion passed".to_string(),
        }];
        let residual_risks = vec![crate::execution::ResidualRiskRecord {
            risk_record_id: "risk:acceptable".to_string(),
            risk_class: crate::execution::ResidualRiskClass::Legibility,
            supporting_refs: vec!["support:1".to_string()],
            severity: crate::execution::RiskSeverity::Low,
            closure_effect: crate::execution::ClosureEffect::Acceptable,
            summary: "risk acceptable".to_string(),
        }];

        assert_eq!(
            closure_decision_from_review(&criteria, &residual_risks),
            crate::execution::NorthStarClosureDecision::Closed
        );
    }

