    #[tokio::test]
    async fn inference_provider_upsert_replaces_existing_entry() {
        let workspace = LocalRuntimeWorkspace::bootstrap(
            std::env::temp_dir().join(format!("aiaf-v23-inference-upsert-{}", current_timestamp())),
        )
        .unwrap();
        let service = LocalRuntimeService::new(workspace).await.unwrap();

        let first = inference_provider_for_tests(
            "provider:test",
            InferenceProviderMode::OpenAiResponses,
            true,
        );
        let mut replacement = first.clone();
        replacement.policy_summary = "replacement policy".to_string();
        replacement
            .models
            .push(crate::execution::InferenceProviderModelEntry {
                model_ref: "gpt-5.4".to_string(),
                input_cost_per_million_microunits: 1_250_000,
                output_cost_per_million_microunits: 10_000_000,
                supports_json_schema: true,
                supports_function_tools: true,
            });

        service.upsert_inference_provider(first).await.unwrap();
        let updated = service
            .upsert_inference_provider(replacement.clone())
            .await
            .unwrap();
        let registry = service.inference_provider_registry().await.unwrap();

        assert_eq!(updated.provider, replacement);
        assert_eq!(registry.providers.len(), 1);
        assert_eq!(
            registry.providers[0].provider.policy_summary,
            "replacement policy"
        );
        assert_eq!(registry.providers[0].provider.models.len(), 2);
    }

    #[test]
    fn inference_api_error_mapping_uses_expected_status_codes() {
        assert_eq!(
            ApiError::from(LocalRuntimeError::InvalidInferenceOperation {
                identifier: "turn:test".to_string(),
                reason: "unsupported model".to_string(),
            })
            .status,
            StatusCode::BAD_REQUEST
        );
        assert_eq!(
            ApiError::from(LocalRuntimeError::InferenceExecutionFailed {
                identifier: "turn:test".to_string(),
                reason: "missing provider secret env".to_string(),
            })
            .status,
            StatusCode::INTERNAL_SERVER_ERROR
        );
        assert_eq!(
            ApiError::from(LocalRuntimeError::InferenceProviderNotFound {
                provider_id: "provider:missing".to_string(),
            })
            .status,
            StatusCode::NOT_FOUND
        );
        assert_eq!(
            ApiError::from(LocalRuntimeError::InvalidTurnPackageOperation {
                identifier: "turn-package:test".to_string(),
                reason: "invalid role schema combination".to_string(),
            })
            .status,
            StatusCode::BAD_REQUEST
        );
        assert_eq!(
            ApiError::from(LocalRuntimeError::TurnPackageNotFound {
                turn_package_id: "turn-package:missing".to_string(),
            })
            .status,
            StatusCode::NOT_FOUND
        );
        assert_eq!(
            ApiError::from(LocalRuntimeError::ParsedTurnResultNotFound {
                parsed_result_id: "parsed-turn-result:missing".to_string(),
            })
            .status,
            StatusCode::NOT_FOUND
        );
    }

