    #[test]
    fn north_star_nodes_keep_current_decision_and_maturity_explicit() {
        let nodes = north_star_nodes()
            .into_iter()
            .map(|node| (node.label, (node.band, node.status, node.maturity)))
            .collect::<BTreeMap<_, _>>();

        assert_eq!(
            nodes.get("Observer Console"),
            Some(&(
                "surface".to_string(),
                ConsoleProgressStatus::NotYet,
                CapabilityMaturity::Effectful
            ))
        );
        assert_eq!(
            nodes.get("Wasm-Biotic substrate"),
            Some(&(
                "substrate".to_string(),
                ConsoleProgressStatus::NotYet,
                CapabilityMaturity::Effectful
            ))
        );
        assert_eq!(
            nodes.get("Multi-factory ecosystem"),
            Some(&(
                "ecosystem".to_string(),
                ConsoleProgressStatus::LiveButBounded,
                CapabilityMaturity::Operational
            ))
        );
    }

    #[test]
    fn progress_tracker_preserves_not_yet_and_capability_maturity_truth() {
        let tracker = progress_tracker_items()
            .into_iter()
            .map(|item| (item.area, (item.status, item.maturity)))
            .collect::<BTreeMap<_, _>>();

        assert_eq!(
            tracker.get("Wasm-Biotic substrate"),
            Some(&(ConsoleProgressStatus::NotYet, CapabilityMaturity::Effectful))
        );
        assert_eq!(
            tracker.get("Execution harness"),
            Some(&(ConsoleProgressStatus::NotYet, CapabilityMaturity::Effectful))
        );
        assert_eq!(
            tracker.get("Orchestration"),
            Some(&(ConsoleProgressStatus::NotYet, CapabilityMaturity::Rehearsed))
        );
        assert_eq!(
            tracker.get("Later factory creation"),
            Some(&(
                ConsoleProgressStatus::LiveButBounded,
                CapabilityMaturity::Operational
            ))
        );
        assert_eq!(
            tracker.get("Pre-federation ecosystem contracts"),
            Some(&(ConsoleProgressStatus::NotYet, CapabilityMaturity::Rehearsed))
        );
        assert_eq!(
            tracker.get("Broader native services"),
            Some(&(
                ConsoleProgressStatus::LiveButBounded,
                CapabilityMaturity::Operational
            ))
        );
        assert_eq!(
            tracker.get("Multi-factory ecosystem"),
            Some(&(
                ConsoleProgressStatus::LiveButBounded,
                CapabilityMaturity::Operational
            ))
        );
    }

