    #[tokio::test]
    async fn general_audience_historical_and_future_items_stay_recorded_and_bounded() {
        let workspace = LocalRuntimeWorkspace::bootstrap(
            std::env::temp_dir().join(format!("aiaf-v23-home-roadmap-{}", current_timestamp())),
        )
        .unwrap();
        let service = LocalRuntimeService::new(workspace).await.unwrap();
        service
            .start_run("supervisor-promote-activate-successor-campaign")
            .await
            .unwrap();

        let run_views = service.collect_run_views().await.unwrap();
        let history = build_run_history_view(&run_views);
        let portfolio = build_factory_portfolio_view(&run_views);
        let overview = build_system_overview(&run_views);
        let runbook = service.operator_runbook.read().unwrap().clone();
        let mut planning = build_planning_guidance_view(&run_views, &runbook);
        let factory_01_programs = service.factory_01_program_views().await.unwrap();
        annotate_planning_guidance_with_factory_01(&mut planning, &factory_01_programs);
        let transition = service.v2_transition_workspace().await.unwrap();
        let convergence_transition = service.v2_convergence_transition_workspace().await.unwrap();
        let phase01 = service
            .remediation_phase_01_lifecycle_closure()
            .await
            .unwrap();
        let phase02 = service
            .remediation_phase_02_service_ecology_closure()
            .await
            .unwrap();
        let phase03 = service
            .remediation_phase_03_reproduction_ecosystem_closure()
            .await
            .unwrap();
        let phase04 = match service.remediation_phase_04_final_closure_rereview().await {
            Ok(phase04) => Some(phase04),
            Err(LocalRuntimeError::HistoricalPhase04TruthUnavailable { .. }) => None,
            Err(error) => panic!("unexpected Phase 04 derivation failure: {error}"),
        };

        let history_items = build_general_audience_historical_timeline(
            &history,
            &portfolio,
            &overview.progress_tracker,
            &phase01,
            &phase02,
            &phase03,
            phase04.as_ref(),
        );
        assert!(
            history_items
                .iter()
                .any(|item| item.source_kind == "remediation")
        );
        assert!(
            history_items
                .iter()
                .any(|item| item.source_kind == "progress_tracker")
        );
        assert!(
            history_items
                .iter()
                .any(|item| item.source_kind == "run_history" || item.source_kind == "portfolio")
        );
        let unavailable_phase04 = history_items
            .iter()
            .find(|item| item.milestone_id == "phase-04")
            .expect("historical Phase 04 boundary item should always be explicit");
        assert_eq!(
            unavailable_phase04.source_kind,
            "historical_review_unavailable"
        );
        assert_eq!(
            unavailable_phase04.status_label,
            "historical_review_unavailable:not_yet"
        );
        assert!(unavailable_phase04.evidence_refs.is_empty());

        let roadmap = build_general_audience_future_roadmap(
            &overview.progress_tracker,
            &planning,
            &transition,
            &convergence_transition,
            &phase01,
            &phase02,
            &phase03,
            phase04.as_ref(),
        );
        assert!(!roadmap.is_empty());
        assert!(roadmap.iter().all(|item| matches!(
            item.source_kind.as_str(),
            "progress_tracker" | "planning" | "transition" | "blocker"
        )));
        assert!(roadmap.iter().all(|item| matches!(
            item.status,
            ConsoleProgressStatus::LiveButBounded | ConsoleProgressStatus::NotYet
        )));
        let unavailable_phase04 = roadmap
            .iter()
            .find(|item| item.roadmap_id == "blockers:phase-04-unavailable")
            .expect("missing historical Phase 04 review should remain an explicit blocker");
        assert_eq!(unavailable_phase04.status, ConsoleProgressStatus::NotYet);
        assert!(unavailable_phase04.source_refs.is_empty());
    }

